const kanji_v2 = /* @__PURE__ */ JSON.parse(`[{"key":"k:人","kind":"kanji","level":"N5","character":"人","meaning":"Người, con người","hanviet":"Nhân","onReadings":["ジン","ニン"],"kunReadings":["ひと"],"strokeCount":2,"radicals":[],"components":[],"compounds":[{"compound":"日本人","reading":"にほんじん","meaning":"Người Nhật"},{"compound":"大人","reading":"おとな","meaning":"Người lớn","vocabKey":"v:大人"},{"compound":"一人","reading":"ひとり","meaning":"Một người","vocabKey":"v:一人"}],"lessonIds":[1,5,9,10,11,12,27,28,30,32,41,47],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 人 là chữ tượng hình, vẽ hình người đang bước đi nhìn từ bên cạnh 🚶. Mẹo nhớ: hai nét như hai chân bước — hình ảnh con người đang đi. Hán-Việt: Nhân, như 'nhân loại', 'nhân dân'. Khi làm bộ thủ bên trái viết thành 亻(にんべん), xuất hiện trong rất nhiều kanji liên quan đến con người: 体 (thể), 休 (hưu), 住 (trú).","example":"あの**人**は新しい日本語の先生ですか。 / ano hito wa atarashii nihongo no sensei desu ka. (Người kia có phải giáo viên tiếng Nhật mới không?)","examples":[{"ja":"あの人は新しい日本語の先生ですか。","vi":"Người kia có phải giáo viên tiếng Nhật mới không?","romaji":"ano hito wa atarashii nihongo no sensei desu ka."},{"ja":"大人になる","vi":"Trở thành người lớn","romaji":"Otona ni naru"},{"ja":"隣の人に挨拶する","vi":"Chào người bên cạnh","romaji":"Tonari no hito ni aisatsu suru"},{"ja":"ご主人は何をしていますか","vi":"Chồng chị làm gì?","romaji":"Go shujin wa nani wo shiteimasuka"}]},{"key":"k:男","kind":"kanji","level":"N5","character":"男","meaning":"Nam, đàn ông","hanviet":"Nam","onReadings":["ダン","ナン"],"kunReadings":["おとこ"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"男の子","reading":"おとこのこ","meaning":"Con trai","vocabKey":"v:男の子"},{"compound":"男性","reading":"だんせい","meaning":"Nam giới","vocabKey":"v:男性"}],"lessonIds":[10,41,47],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 田 (ruộng) + 力 (sức mạnh). Mẹo nhớ: người dùng sức 💪 (力) cày ruộng (田) ngày xưa là đàn ông — người ra đồng lao động. Hán-Việt: Nam, như 'nam nữ', 'nam giới'. Âm on ダン (dan) gần với 'đàn' trong 'đàn ông'. Đối lập với 女 (nữ).","example":"**男**の子が遊んでいます。 / otoko no ko ga asonde imasu. (Con trai đang chơi.)","examples":[{"ja":"男の子が遊んでいます。","vi":"Con trai đang chơi.","romaji":"otoko no ko ga asonde imasu."},{"ja":"男性の服","vi":"Quần áo nam","romaji":"Dansei no fuku"},{"ja":"男の子が遊ぶ","vi":"Bé trai chơi","romaji":"Otokonoko ga asobu"},{"ja":"男の人が走る","vi":"Đàn ông chạy","romaji":"Otokonohito ga hashiru"}]},{"key":"k:女","kind":"kanji","level":"N5","character":"女","meaning":"Nữ, phụ nữ","hanviet":"Nữ","onReadings":["ジョ","ニョ"],"kunReadings":["おんな"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"女の子","reading":"おんなのこ","meaning":"Con gái","vocabKey":"v:女の子"},{"compound":"女性","reading":"じょせい","meaning":"Nữ giới","vocabKey":"v:女性"}],"lessonIds":[5,10,47],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 女 là chữ tượng hình, nguồn gốc vẽ hình người phụ nữ đang quỳ gối chắp tay theo phong cách cổ đại 👩. Mẹo nhớ: ba nét uốn cong mềm mại gợi hình dáng nữ tính. Hán-Việt: Nữ, như 'nữ sinh', 'phụ nữ'. Khi làm bộ thủ bên trái (おんなへん), xuất hiện trong 姉 (tỷ/chị), 妹 (muội/em gái), 妻 (thê/vợ), 好 (hảo/thích).","example":"あの**女**の人は先生です。 / ano onna no hito wa sensei desu. (Người phụ nữ kia là giáo viên.)","examples":[{"ja":"あの女の人は先生です。","vi":"Người phụ nữ kia là giáo viên.","romaji":"ano onna no hito wa sensei desu."},{"ja":"彼女は学生だ","vi":"Cô ấy là sinh viên","romaji":"Kanojo wa gakusei da"},{"ja":"女性の声","vi":"Giọng nữ","romaji":"Josei no koe"},{"ja":"女の子が歌う","vi":"Bé gái hát","romaji":"Onnanoko ga utau"}]},{"key":"k:子","kind":"kanji","level":"N5","character":"子","meaning":"Con, trẻ con","hanviet":"Tử","onReadings":["シ","ス"],"kunReadings":["こ"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"子供","reading":"こども","meaning":"Trẻ con","vocabKey":"v:子供"},{"compound":"男の子","reading":"おとこのこ","meaning":"Con trai","vocabKey":"v:男の子"},{"compound":"女の子","reading":"おんなのこ","meaning":"Con gái","vocabKey":"v:女の子"}],"lessonIds":[9,10,19,22,24,27,28,30,31,34,41,42],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 子 là chữ tượng hình, nguồn gốc vẽ hình em bé đang giơ hai tay lên từ trong tã 👶. Mẹo nhớ: nét ngang trên là hai tay giơ, thân dọc là người bé, nét móc dưới là chân quấn tã. Hán-Việt: Tử, như 'tử nữ' (con cái), 'đệ tử'. Khi đứng một mình đọc こ (ko), trong hợp từ thường đọc し (shi). Xuất hiện trong 字 (tự), 学 (học), 好 (hảo).","example":"**子**供たちが公園で遊んでいます。 / kodomo-tachi ga kouen de asonde imasu. (Bọn trẻ đang chơi trong công viên.)","examples":[{"ja":"子供たちが公園で遊んでいます。","vi":"Bọn trẻ đang chơi trong công viên.","romaji":"kodomo-tachi ga kouen de asonde imasu."},{"ja":"息子は大学生だ","vi":"Con trai là sinh viên đại học","romaji":"Musuko wa daigakusei da"},{"ja":"子供が遊ぶ","vi":"Trẻ con chơi","romaji":"Kodomo ga asobu"},{"ja":"子育ては大変だ","vi":"Nuôi con rất vất vả","romaji":"Kosodate wa taihen da"}]},{"key":"k:父","kind":"kanji","level":"N5","character":"父","meaning":"Bố, cha","hanviet":"Phụ","onReadings":["フ"],"kunReadings":["ちち"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"お父さん","reading":"おとうさん","meaning":"Bố (lịch sự)","vocabKey":"v:お父さん"},{"compound":"父親","reading":"ちちおや","meaning":"Người cha","vocabKey":"v:父親"}],"lessonIds":[7,41],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 八 (tám, tách ra) + 乂 (hai nét giao nhau). Mẹo nhớ: hình ảnh bàn tay người cha cầm rìu (乂) giơ cao bảo vệ gia đình, hai nét trên (八) như hai tay dang rộng che chở. Hán-Việt: Phụ, như 'phụ mẫu' (cha mẹ), 'phụ thân'. Âm kun ちち (chichi) là cách gọi cha thân mật. Đối lập với 母 (mẫu/mẹ).","example":"**父**は大阪の会社で働いています。 / chichi wa oosaka no kaisha de hataraite imasu. (Bố tôi đang làm việc ở một công ty tại Osaka.)","examples":[{"ja":"父は大阪の会社で働いています。","vi":"Bố tôi đang làm việc ở một công ty tại Osaka.","romaji":"chichi wa oosaka no kaisha de hataraite imasu."},{"ja":"父親は厳しい","vi":"Bố nghiêm khắc","romaji":"chichioya wa kibishii"},{"ja":"祖父は元気だ","vi":"Ông khỏe mạnh","romaji":"Sofu wa genki da"},{"ja":"父は毎朝新聞を読んでいます。","vi":"Bố tôi mỗi sáng đều đọc báo.","romaji":"chichi wa maiasa shinbun o yonde imasu."}]},{"key":"k:母","kind":"kanji","level":"N5","character":"母","meaning":"Mẹ","hanviet":"Mẫu","onReadings":["ボ"],"kunReadings":["はは"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"お母さん","reading":"おかあさん","meaning":"Mẹ (lịch sự)","vocabKey":"v:お母さん"},{"compound":"母親","reading":"ははおや","meaning":"Người mẹ","vocabKey":"v:母親"}],"lessonIds":[7,24,35,41],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 母 là chữ tượng hình, nguồn gốc vẽ hình người phụ nữ có hai chấm biểu thị ngực — biểu tượng người mẹ cho con bú. Mẹo nhớ: khung ngoài giống chữ 女 (nữ) nhưng thêm hai chấm bên trong, gợi người phụ nữ đang nuôi con 🤱. Hán-Việt: Mẫu, như 'phụ mẫu' (cha mẹ), 'mẫu tử'. Âm kun はは (haha) dùng khi nói về mẹ mình. Đối lập với 父 (phụ/cha).","example":"**母**の料理はおいしいです。 / haha no ryouri wa oishii desu. (Món ăn của mẹ ngon.)","examples":[{"ja":"母の料理はおいしいです。","vi":"Món ăn của mẹ ngon.","romaji":"haha no ryouri wa oishii desu."},{"ja":"母親は優しい","vi":"Mẹ hiền","romaji":"Hahaoya wa yasashii"},{"ja":"祖母の料理","vi":"Món ăn của bà","romaji":"sobo no ryouri"},{"ja":"母に料理を作ってもらいました。","vi":"Nhờ mẹ nấu ăn.","romaji":"haha ni ryouri o tsukutsute moraimashita."}]},{"key":"k:兄","kind":"kanji","level":"N5","character":"兄","meaning":"Anh trai","hanviet":"Huynh","onReadings":["ケイ","キョウ"],"kunReadings":["あに"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"お兄さん","reading":"おにいさん","meaning":"Anh trai (lịch sự)","vocabKey":"v:お兄さん"},{"compound":"兄弟","reading":"きょうだい","meaning":"Anh em","vocabKey":"v:兄弟"}],"lessonIds":[11],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 口 (miệng) + 儿 (chân người). Mẹo nhớ: người có miệng (口) to ở trên — anh trai hay chỉ bảo, ra lệnh cho em; phần chân (儿) bên dưới cho thấy đây là 'người'. Hán-Việt: Huynh, như 'huynh đệ' (anh em). Âm on キョウ (kyou) cũng đọc cho 兄弟 (きょうだい – kyoudai – anh chị em). So sánh với 弟 (đệ/em trai).","example":"**兄**は来年大学を卒業する予定です。 / ani wa rainen daigaku wo sotsugyou suru yotei desu. (Anh trai dự định tốt nghiệp đại học vào năm sau.)","examples":[{"ja":"兄は来年大学を卒業する予定です。","vi":"Anh trai dự định tốt nghiệp đại học vào năm sau.","romaji":"ani wa rainen daigaku wo sotsugyou suru yotei desu."},{"ja":"兄弟が多い","vi":"Nhiều anh chị em","romaji":"kyoudai ga ooi"},{"ja":"兄は東京に住んでいる","vi":"Anh trai sống ở Tokyo","romaji":"ani wa toukyou ni sunde iru"},{"ja":"お兄さんは何歳ですか","vi":"Anh trai bạn bao nhiêu tuổi?","romaji":"O niisan wa nansai de suka"}]},{"key":"k:弟","kind":"kanji","level":"N5","character":"弟","meaning":"Em trai","hanviet":"Đệ","onReadings":["テイ","ダイ"],"kunReadings":["おとうと"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"弟","reading":"おとうと","meaning":"Em trai","vocabKey":"v:弟"},{"compound":"兄弟","reading":"きょうだい","meaning":"Anh em","vocabKey":"v:兄弟"}],"lessonIds":[11],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 丷 (hai chấm/sừng) + 弓 (cung) + 丨 (nét dọc) + ノ (nét phẩy). Mẹo nhớ: em trai còn nhỏ, tập bắn cung (弓) với mũi tên (丨) — hình ảnh cậu em đang luyện tập 🏹. Hán-Việt: Đệ, như 'huynh đệ' (anh em), 'đệ tử' (học trò). Âm on テイ/ダイ (tei/dai), âm kun おとうと (otouto). Đối lập với 兄 (huynh/anh trai).","example":"**弟**は毎日自転車で高校に通っています。 / otouto wa mainichi jitensha de koukou ni kayotte imasu. (Em trai tôi đi xe đạp đến trường cấp ba mỗi ngày.)","examples":[{"ja":"弟は毎日自転車で高校に通っています。","vi":"Em trai tôi đi xe đạp đến trường cấp ba mỗi ngày.","romaji":"otouto wa mainichi jitensha de koukou ni kayotsute imasu."},{"ja":"兄弟が多い","vi":"Nhiều anh chị em","romaji":"kyoudai ga ooi"},{"ja":"弟は中学生です","vi":"Em trai học THCS","romaji":"otouto wa chuugakusei desu"},{"ja":"弟は毎月図書館で本を借りています。","vi":"Em trai tôi mỗi tháng đều mượn sách ở thư viện.","romaji":"otouto wa maitsuki toshokan de hon o karite imasu."}]},{"key":"k:姉","kind":"kanji","level":"N5","character":"姉","meaning":"Chị gái","hanviet":"Tỷ","onReadings":["シ"],"kunReadings":["あね"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"お姉さん","reading":"おねえさん","meaning":"Chị gái (lịch sự)","vocabKey":"v:お姉さん"}],"lessonIds":[11],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 女 (nữ) + 市 (chợ/thành phố). Mẹo nhớ: người phụ nữ (女) lớn tuổi hơn, đã biết đi chợ (市) một mình — đó là chị gái 👩. Hán-Việt: Tỷ, như 'tỷ muội' (chị em gái). Âm kun あね (ane) dùng khi nói về chị mình. Cùng bộ 女: 妹 (muội/em gái), 妻 (thê/vợ). So sánh với 妹 — chị có 市 (đi chợ), em có 未 (chưa đủ lớn).","example":"**姉**は市立病院で看護師として働いています。 / ane wa shiritsu byouin de kangoshi toshite hataraite imasu. (Chị gái tôi đang làm y tá ở bệnh viện thành phố.)","examples":[{"ja":"姉は市立病院で看護師として働いています。","vi":"Chị gái tôi đang làm y tá ở bệnh viện thành phố.","romaji":"ane wa shiritsu byouin de kangoshi toshite hataraite imasu."},{"ja":"姉は先生です","vi":"Chị gái là giáo viên","romaji":"Ane wa sensei de su"},{"ja":"お姉さんはきれいですね","vi":"Chị gái đẹp nhỉ","romaji":"o neesan wa kirei desu ne"},{"ja":"姉は毎日ピアノを弾いています。","vi":"Chị tôi mỗi ngày đều chơi piano.","romaji":"ane wa mainichi piano o hiite imasu."}]},{"key":"k:妹","kind":"kanji","level":"N5","character":"妹","meaning":"Em gái","hanviet":"Muội","onReadings":["マイ"],"kunReadings":["いもうと"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"妹","reading":"いもうと","meaning":"Em gái","vocabKey":"v:妹"},{"compound":"姉妹","reading":"しまい","meaning":"Chị em gái"}],"lessonIds":[11],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 女 (nữ) + 未 (chưa). Mẹo nhớ: người phụ nữ (女) còn 'chưa' (未) lớn — đó là em gái 👧. Chữ 未 trông như cây chưa mọc hết cành, ý là 'chưa trưởng thành'. Hán-Việt: Muội, như 'tỷ muội' (chị em gái). Âm kun いもうと (imouto). So sánh với 姉 (tỷ/chị gái) — chị có 市 (đi chợ/trưởng thành), em có 未 (chưa đủ lớn).","example":"**妹**はピアノが上手です。 / imouto wa piano ga jouzu desu. (Em gái chơi piano giỏi.)","examples":[{"ja":"妹はピアノが上手です。","vi":"Em gái chơi piano giỏi.","romaji":"imouto wa piano ga jouzu desu."},{"ja":"妹と買い物に行く","vi":"Đi mua sắm với em gái","romaji":"imouto to kaimono ni iku"},{"ja":"妹にプレゼントをあげました。","vi":"Tôi đã tặng quà cho em gái.","romaji":"imouto ni purezento o agemashita."},{"ja":"妹は新しいバッグがほしいと言っていました。","vi":"Em gái nói rằng muốn có túi mới.","romaji":"imouto wa atarashii baggu ga hoshii to itsute imashita."}]},{"key":"k:夫","kind":"kanji","level":"N5","character":"夫","meaning":"Chồng","hanviet":"Phu","onReadings":["フ","フウ"],"kunReadings":["おっと"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"夫婦","reading":"ふうふ","meaning":"Vợ chồng","vocabKey":"v:夫婦"},{"compound":"夫人","reading":"ふじん","meaning":"Phu nhân"}],"lessonIds":[9,17,42],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 大 (lớn) + 一 (một nét ngang trên đầu). Mẹo nhớ: chữ 大 (người dang tay) thêm một nét ngang trên đầu như cái trâm cài tóc — ngày xưa đàn ông trưởng thành cài trâm búi tóc, đánh dấu đã đủ tuổi lấy vợ → chồng 👨. Hán-Việt: Phu, như 'phu nhân' (vợ), 'phu thê' (vợ chồng). Đối lập với 妻 (thê/vợ).","example":"**夫**は料理が上手です。 / otto wa ryouri ga jouzu desu. (Chồng tôi nấu ăn giỏi.)","examples":[{"ja":"夫は料理が上手です。","vi":"Chồng tôi nấu ăn giỏi.","romaji":"otto wa ryouri ga jouzu desu."},{"ja":"大丈夫ですか","vi":"Bạn ổn không?","romaji":"daijoubu desu ka"},{"ja":"この靴は丈夫で長持ちします","vi":"Đôi giày này bền lắm","romaji":"kono kutsu wa joubu de nagamochi shimasu"},{"ja":"夫は会社員だ","vi":"Chồng là nhân viên công ty","romaji":"Otto wa kaishain da"}]},{"key":"k:妻","kind":"kanji","level":"N5","character":"妻","meaning":"Vợ","hanviet":"Thê","onReadings":["サイ"],"kunReadings":["つま"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"妻","reading":"つま","meaning":"Vợ","vocabKey":"v:妻"},{"compound":"夫妻","reading":"ふさい","meaning":"Vợ chồng"}],"lessonIds":[9],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 十 (mười/thập) + 彐 (tay vươn lấy) + 女 (nữ). Mẹo nhớ: người phụ nữ (女) giỏi giang, một tay vươn lấy (彐) mười (十) việc nhà — đó là người vợ đảm đang 👩‍🍳. Phần trên gợi hình cây chổi/kim châm, nghề thủ công mà vợ xưa hay làm. Hán-Việt: Thê, như 'phu thê' (vợ chồng), 'thê tử'. Đối lập với 夫 (phu/chồng).","example":"来月、**妻**と北海道へ旅行する予定です。 / raigetsu, tsuma to hokkaidou e ryokou suru yotei desu. (Tháng sau tôi dự định đi du lịch Hokkaido cùng vợ.)","examples":[{"ja":"来月、妻と北海道へ旅行する予定です。","vi":"Tháng sau tôi dự định đi du lịch Hokkaido cùng vợ.","romaji":"raigetsu, tsuma to hokkaidou e ryokou suru yotei desu."},{"ja":"妻と旅行する","vi":"Du lịch với vợ","romaji":"tsuma to ryokou suru"},{"ja":"妻が病気のとき、会社を休みます。","vi":"Khi vợ ốm, tôi xin nghỉ làm.","romaji":"tsuma ga byouki no toki, kaisha o yasumimasu."},{"ja":"妻","vi":"vợ (dùng khi nói về vợ mình)","romaji":"tsuma"}]},{"key":"k:友","kind":"kanji","level":"N5","character":"友","meaning":"Bạn bè","hanviet":"Hữu","onReadings":["ユウ"],"kunReadings":["とも"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"友達","reading":"ともだち","meaning":"Bạn","vocabKey":"v:友達"},{"compound":"親友","reading":"しんゆう","meaning":"Bạn thân"}],"lessonIds":[5],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: ナ (tay phải vươn ra) + 又 (tay phải/lại). Mẹo nhớ: hai bàn tay 🤝 đan vào nhau — hai người nắm tay nhau thành bạn bè. Hán-Việt: Hữu, như 'bạn hữu', 'hữu nghị' (tình bạn). Âm on ユウ (yuu), âm kun とも (tomo) như trong 友達 (ともだち – tomodachi – bạn bè).","example":"**友**達と映画を見ました。 / tomodachi to eiga wo mimashita. (Tôi xem phim với bạn.)","examples":[{"ja":"友達と映画を見ました。","vi":"Tôi xem phim với bạn.","romaji":"tomodachi to eiga wo mimashita."},{"ja":"友達に会う","vi":"Gặp bạn","romaji":"Tomodachi ni au"},{"ja":"学生時代の友人に会う","vi":"Gặp bạn thời sinh viên","romaji":"gakusei jidai no yuujin ni au"},{"ja":"友達に相談する","vi":"Trao đổi với bạn","romaji":"tomodachi ni soudan suru"}]},{"key":"k:体","kind":"kanji","level":"N5","character":"体","meaning":"Cơ thể","hanviet":"Thể","onReadings":["タイ"],"kunReadings":["からだ"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"体重","reading":"たいじゅう","meaning":"Cân nặng"},{"compound":"体力","reading":"たいりょく","meaning":"Thể lực"}],"lessonIds":[16,19,28,42],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 亻 (người) + 本 (gốc, cơ bản). Mẹo nhớ: phần 'gốc' (本) của con người (亻) chính là thân thể — cái cơ bản nhất mà mỗi người có 🏃. Hán-Việt: Thể, như 'thân thể', 'thể dục', 'thể lực'. Âm on タイ (tai) gần với 'thể' trong tiếng Việt. Cùng bộ 亻: 休 (hưu/nghỉ), 住 (trú/ở), 使 (sứ/sử dụng).","example":"**体**に気をつけてください。 / karada ni ki wo tsukete kudasai. (Hãy giữ gìn sức khỏe.)","examples":[{"ja":"体に気をつけてください。","vi":"Hãy giữ gìn sức khỏe.","romaji":"karada ni ki wo tsukete kudasai."},{"ja":"体が弱い","vi":"Cơ thể yếu","romaji":"Karada ga yowai"},{"ja":"体温を測る","vi":"Đo thân nhiệt","romaji":"Taion wo hakaru"},{"ja":"体の状態がよくない","vi":"Tình trạng cơ thể không tốt","romaji":"karada no joutai ga yokunai"}]},{"key":"k:頭","kind":"kanji","level":"N5","character":"頭","meaning":"Đầu","hanviet":"Đầu","onReadings":["トウ","ズ"],"kunReadings":["あたま"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"頭痛","reading":"ずつう","meaning":"Đau đầu","vocabKey":"v:頭痛"}],"lessonIds":[16],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 豆 (đậu) + 頁 (trang/đầu). Mẹo nhớ: bộ 頁 (おおがい) nghĩa gốc là 'đầu/mặt', xuất hiện trong các kanji liên quan đến phần đầu. Phần 豆 (đậu) gợi hình: cái đầu tròn tròn như hạt đậu 🫘 đặt trên cổ. Hán-Việt: Đầu, như 'đầu não'. Âm on トウ (tou) gần với 'đầu'. Cùng bộ 頁: 顔 (nhan/khuôn mặt).","example":"昨日から**頭**が痛いので、病院に行くつもりです。 / kinou kara atama ga itai node, byouin ni iku tsumori desu. (Từ hôm qua tôi bị đau đầu nên định đi bệnh viện.)","examples":[{"ja":"昨日から頭が痛いので、病院に行くつもりです。","vi":"Từ hôm qua tôi bị đau đầu nên định đi bệnh viện.","romaji":"kinou kara atama ga itai node, byouin ni iku tsumori desu."},{"ja":"頭が痛い","vi":"Đau đầu","romaji":"Atama ga itai"},{"ja":"頭痛がする","vi":"Bị đau đầu","romaji":"zutsuu ga suru"},{"ja":"牛が五頭いる","vi":"Có 5 con bò","romaji":"ushi ga gotou iru"}]},{"key":"k:顔","kind":"kanji","level":"N5","character":"顔","meaning":"Khuôn mặt","hanviet":"Nhan","onReadings":["ガン"],"kunReadings":["かお"],"strokeCount":18,"radicals":[],"components":[],"compounds":[{"compound":"顔色","reading":"かおいろ","meaning":"Sắc mặt"},{"compound":"洗顔","reading":"せんがん","meaning":"Rửa mặt"}],"lessonIds":[16],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 彦 (người tài hoa, gồm 立 đứng + 彡 vằn/nét đẹp) + 頁 (đầu/mặt). Mẹo nhớ: bộ 頁 chỉ 'đầu/mặt', phần 彦 có 彡 (ba nét vằn) như nét đẹp trên khuôn mặt — khuôn mặt xinh đẹp có nhiều đường nét 😊. Hán-Việt: Nhan, như 'nhan sắc' (vẻ đẹp khuôn mặt), 'dung nhan'. Cùng bộ 頁: 頭 (đầu).","example":"朝起きたら、まず**顔**を洗って歯を磨きます。 / asa okitara, mazu kao wo aratte ha wo migakimasu. (Mỗi sáng thức dậy, tôi rửa mặt trước rồi đánh răng.)","examples":[{"ja":"朝起きたら、まず顔を洗って歯を磨きます。","vi":"Mỗi sáng thức dậy, tôi rửa mặt trước rồi đánh răng.","romaji":"asa oki tara, mazu kao o aratsute ha o migakimasu."},{"ja":"顔を洗う","vi":"Rửa mặt","romaji":"Kao wo arau"},{"ja":"朝起きて、顔を洗って、朝ごはんを食べます。","vi":"Sáng dậy, rửa mặt, rồi ăn sáng.","romaji":"asa okite, kao o aratsute, asa gohan o tabemasu."},{"ja":"元気なのに、どうしてそんな顔をしているんですか。","vi":"Khỏe mạnh thế mà sao lại làm vẻ mặt như vậy?","romaji":"genki na noni, doushite sonna kao o shite iru n desu ka."}]},{"key":"k:目","kind":"kanji","level":"N5","character":"目","meaning":"Mắt","hanviet":"Mục","onReadings":["モク","ボク"],"kunReadings":["め"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"目的","reading":"もくてき","meaning":"Mục đích","vocabKey":"v:目的"},{"compound":"目標","reading":"もくひょう","meaning":"Mục tiêu"}],"lessonIds":[16,23,30,42,45,49,50],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 目 là chữ tượng hình, nguồn gốc vẽ hình con mắt xoay dọc — khung ngoài là viền mắt, hai nét ngang bên trong là tròng mắt và đồng tử 👁️. Mẹo nhớ: hình chữ nhật đứng có hai vạch ngang ở giữa giống con mắt. Hán-Việt: Mục, như 'mục tiêu' (đích nhắm mắt tới), 'tiết mục'. Là bộ thủ quan trọng, xuất hiện trong 見 (kiến/nhìn), 耳 (nhĩ/tai) có cấu trúc tương tự.","example":"パソコンを長く使ったので、**目**が疲れました。 / pasokon wo nagaku tsukatta node, me ga tsukaremashita. (Vì dùng máy tính lâu nên mắt tôi bị mỏi.)","examples":[{"ja":"パソコンを長く使ったので、目が疲れました。","vi":"Vì dùng máy tính lâu nên mắt tôi bị mỏi.","romaji":"pasokon o nagaku tsukatsuta node, me ga tsukaremashita."},{"ja":"真面目な学生","vi":"Học sinh nghiêm túc","romaji":"Majime na gakusei"},{"ja":"目が大きい","vi":"Mắt to","romaji":"me ga ookii"},{"ja":"好きな科目は何ですか","vi":"Bạn thích môn gì?","romaji":"Suki na kamoku wa nani de suka"}]},{"key":"k:耳","kind":"kanji","level":"N5","character":"耳","meaning":"Tai","hanviet":"Nhĩ","onReadings":["ジ"],"kunReadings":["みみ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"耳鼻科","reading":"じびか","meaning":"Khoa tai mũi họng"}],"lessonIds":[16],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 耳 là chữ tượng hình, nguồn gốc vẽ hình lỗ tai — khung ngoài là vành tai, hai nét ngang bên trong là cấu trúc bên trong tai 👂. Mẹo nhớ: trông giống chữ 目 (mắt) nhưng hai nét ngang chạm ra ngoài khung như vành tai nhô ra. Hán-Việt: Nhĩ, như 'nhĩ mục' (tai mắt). Âm kun みみ (mimi), âm lặp lại dễ nhớ. So sánh với 目 (mục/mắt): mắt khép kín, tai mở rộng ra.","example":"飛行機に乗った後、**耳**が痛くなりました。 / hikouki ni notta ato, mimi ga itaku narimashita. (Sau khi đi máy bay, tai tôi bị đau.)","examples":[{"ja":"飛行機に乗った後、耳が痛くなりました。","vi":"Sau khi đi máy bay, tai tôi bị đau.","romaji":"hikouki ni notsuta nochi, mimi ga itaku narimashita."},{"ja":"耳が痛い","vi":"Đau tai","romaji":"Mimi ga itai"}]},{"key":"k:口","kind":"kanji","level":"N5","character":"口","meaning":"Miệng, lối","hanviet":"Khẩu","onReadings":["コウ","ク"],"kunReadings":["くち"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"入口","reading":"いりぐち","meaning":"Lối vào","vocabKey":"v:入口"},{"compound":"出口","reading":"でぐち","meaning":"Lối ra","vocabKey":"v:出口"},{"compound":"人口","reading":"じんこう","meaning":"Dân số","vocabKey":"v:人口"}],"lessonIds":[16,33,47],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 口 là chữ tượng hình đơn giản nhất — hình vuông mở miệng 👄. Mẹo nhớ: ô vuông trống bên trong giống cái miệng đang há ra. Hán-Việt: Khẩu, như 'nhân khẩu' (số người), 'khẩu ngữ'. Là một trong những bộ thủ phổ biến nhất (くちへん), xuất hiện trong 言 (ngôn/nói), 知 (tri/biết), 味 (vị). Cũng mang nghĩa 'lối vào': 入口 (いりぐち – lối vào), 出口 (でぐち – lối ra).","example":"医者に「大きく**口**を開けてください」と言われました。 / isha ni \\"ookiku kuchi wo akete kudasai\\" to iwaremashita. (Bác sĩ bảo tôi \\"hãy mở miệng to ra\\".)","examples":[{"ja":"医者に「大きく口を開けてください」と言われました。","vi":"Bác sĩ bảo tôi \\"hãy mở miệng to ra\\".","romaji":"isha ni\\" ookiku kuchi o akete kudasai\\" to iwa remashita."},{"ja":"入口はどこ","vi":"Lối vào ở đâu","romaji":"Iriguchi wa doko"},{"ja":"出口に向かう","vi":"Hướng về lối ra","romaji":"Deguchi ni mukau"},{"ja":"東口で待ち合わせする","vi":"Hẹn gặp ở cổng đông","romaji":"Higashiguchi de machiawase suru"}]},{"key":"k:手","kind":"kanji","level":"N5","character":"手","meaning":"Tay","hanviet":"Thủ","onReadings":["シュ"],"kunReadings":["て"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"手紙","reading":"てがみ","meaning":"Thư","vocabKey":"v:手紙"},{"compound":"上手","reading":"じょうず","meaning":"Giỏi"},{"compound":"下手","reading":"へた","meaning":"Dở"}],"lessonIds":[2,3,6,7,9,11,14,28,33,36,41,47],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 手 là chữ tượng hình, nguồn gốc vẽ hình bàn tay với các ngón xòe ra ✋. Mẹo nhớ: ba nét ngang trên là ba ngón tay, nét dọc móc dưới là cổ tay. Hán-Việt: Thủ, như 'thủ công' (làm bằng tay), 'trợ thủ'. Khi làm bộ thủ bên trái viết thành 扌(てへん), xuất hiện trong 持 (trì/cầm), 押 (áp/ấn), 拾 (thập/nhặt). Âm kun て (te) rất phổ biến: 手紙 (てがみ – thư tay).","example":"外から帰ったら、石けんで**手**を洗いましょう。 / soto kara kaettara, sekken de te wo araimashou. (Sau khi từ ngoài về, hãy rửa tay bằng xà phòng.)","examples":[{"ja":"外から帰ったら、石けんで手を洗いましょう。","vi":"Sau khi từ ngoài về, hãy rửa tay bằng xà phòng.","romaji":"soto kara kaetsu tara, sekken de te o arai masho u."},{"ja":"母を手伝う","vi":"Phụ giúp mẹ","romaji":"Haha wo tetsudau"},{"ja":"料理が上手","vi":"Nấu ăn giỏi","romaji":"ryouri ga jouzu"},{"ja":"歌が下手","vi":"Hát dở","romaji":"Uta ga heta"}]},{"key":"k:足","kind":"kanji","level":"N5","character":"足","meaning":"Chân, đủ","hanviet":"Túc","onReadings":["ソク"],"kunReadings":["あし","た"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"足りる","reading":"たりる","meaning":"Đủ","vocabKey":"v:足りる"},{"compound":"不足","reading":"ふそく","meaning":"Thiếu"},{"compound":"遠足","reading":"えんそく","meaning":"Dã ngoại"}],"lessonIds":[16,21],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 口 (miệng/đầu gối) + 龰 (bàn chân bước). Mẹo nhớ: phần trên 口 tượng trưng đầu gối, phần dưới là bàn chân đang bước — toàn bộ chân từ gối đến ngón 🦶. Nghĩa mở rộng: 'đủ' (足りる – tariru) vì có chân rồi thì đủ để đi. Hán-Việt: Túc, như 'mãn túc' (đầy đủ), 'túc hạ' (dưới chân). Khi làm bộ thủ bên trái viết thành 𧾷 (あしへん), xuất hiện trong 走 (tẩu/chạy), 路 (lộ/đường).","example":"昨日たくさん歩いたので、**足**が少し痛いです。 / kinou takusan aruita node, ashi ga sukoshi itai desu. (Hôm qua đi bộ nhiều nên chân tôi hơi đau.)","examples":[{"ja":"昨日たくさん歩いたので、足が少し痛いです。","vi":"Hôm qua đi bộ nhiều nên chân tôi hơi đau.","romaji":"kinou takusan aruita node, ashi ga sukoshi itai desu."},{"ja":"水を足す","vi":"Thêm nước","romaji":"Mizu wo tasu"},{"ja":"時間が足りる","vi":"Đủ thời gian","romaji":"Jikan ga tariru"},{"ja":"お金が足りない","vi":"Không đủ tiền","romaji":"Okane ga tarinai"}]},{"key":"k:心","kind":"kanji","level":"N5","character":"心","meaning":"Trái tim, tâm hồn","hanviet":"Tâm","onReadings":["シン"],"kunReadings":["こころ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"心配","reading":"しんぱい","meaning":"Lo lắng"},{"compound":"安心","reading":"あんしん","meaning":"Yên tâm","vocabKey":"v:安心"},{"compound":"中心","reading":"ちゅうしん","meaning":"Trung tâm","vocabKey":"v:中心"}],"lessonIds":[17,28,39,44,50],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 心 là chữ tượng hình, nguồn gốc vẽ hình trái tim với các mạch máu ❤️. Mẹo nhớ: nét móc ở giữa là trái tim, ba chấm xung quanh là nhịp đập tỏa ra — tim đang đập. Hán-Việt: Tâm, như 'tâm hồn', 'trung tâm', 'yên tâm'. Là bộ thủ cực quan trọng (こころ), xuất hiện ở dưới: 思 (tư/nghĩ), 忘 (vong/quên), 感 (cảm). Khi ở bên trái viết thành 忄(りっしんべん): 忙 (mang/bận).","example":"**心**配しないでください。 / shinpai shinaide kudasai. (Đừng lo lắng.)","examples":[{"ja":"心配しないでください。","vi":"Đừng lo lắng.","romaji":"shinpai shinaide kudasai."},{"ja":"子供を心配する","vi":"Lo lắng cho con","romaji":"Kodomo wo shinpai suru"},{"ja":"結果を聞いて安心する","vi":"Nghe kết quả mà yên tâm","romaji":"Kekka wo kiite anshinsuru"},{"ja":"熱心な先生","vi":"Thầy nhiệt tình","romaji":"Nesshin na sensei"}]},{"key":"k:声","kind":"kanji","level":"N4","character":"声","meaning":"Giọng, tiếng","hanviet":"Thanh","onReadings":["セイ"],"kunReadings":["こえ"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"大声","reading":"おおごえ","meaning":"Giọng to"}],"lessonIds":[27],"topicTags":["body"],"sectionId":1,"sectionName":"CON NGƯỜI & CƠ THỂ","mnemonic":"Bộ/thành phần: 士 (kẻ sĩ) + 尸 (thân người nằm, ở đây biến thể dạng cong). Mẹo nhớ: chữ 声 là dạng giản thể của 聲 — hình ảnh kẻ sĩ (士) gõ nhạc cụ tạo ra tiếng vang 🔔. Phần dưới cong như âm thanh lan tỏa đi xa. Hán-Việt: Thanh, như 'thanh âm' (âm thanh), 'ca thanh' (giọng hát). Âm on セイ (sei) như trong 声優 (せいゆう – diễn viên lồng tiếng).","example":"大きい**声**で話してください。 / ookii koe de hanashite kudasai. (Hãy nói to hơn.)","examples":[{"ja":"大きい声で話してください。","vi":"Hãy nói to hơn.","romaji":"ookii koe de hanashite kudasai."},{"ja":"声が大きい","vi":"Giọng to","romaji":"koe ga ookii"},{"ja":"声が小さくて聞こえません。","vi":"Tiếng nhỏ quá nên không nghe thấy.","romaji":"koe ga chiisakute kikoemasen."},{"ja":"鳥の声が聞こえますか。","vi":"Bạn có nghe thấy tiếng chim không?","romaji":"tori no koe ga kikoemasu ka."}]},{"key":"k:天","kind":"kanji","level":"N5","character":"天","meaning":"Trời","hanviet":"Thiên","onReadings":["テン"],"kunReadings":["あめ","あま"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"天気","reading":"てんき","meaning":"Thời tiết","vocabKey":"v:天気"},{"compound":"天国","reading":"てんごく","meaning":"Thiên đường"}],"lessonIds":[11,12,47],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 一 (trần/nóc) + 大 (người dang tay). Hán-Việt: THIÊN. Mẹo nhớ: Một người đứng dang rộng tay (大), phía trên là vòm trần (一) — đó là bầu 'trời' ☁️. Chỉ 4 nét nhưng mang nghĩa lớn lao. Âm テン (ten) chính là 'thiên'. Liên kết: 天気 (thiên khí = thời tiết), 天国 (thiên quốc = thiên đường). ⚠️ Đừng nhầm 天 với 夫 (phu/chồng) — 天 nét ngang trên dài hơn, 夫 nét ngang dưới dài hơn.","example":"今日は**天**気がいいですね。 / kyou wa tenki ga ii desu ne. (Hôm nay thời tiết đẹp nhỉ.)","examples":[{"ja":"今日は天気がいいですね。","vi":"Hôm nay thời tiết đẹp nhỉ.","romaji":"kyou wa tenki ga ii desu ne."},{"ja":"天気がいい","vi":"Thời tiết đẹp","romaji":"Tenki gaii"},{"ja":"天気予報を見る","vi":"Xem dự báo thời tiết","romaji":"tenki yohou o miru"},{"ja":"天候に恵まれた","vi":"Được thời tiết ưu đãi","romaji":"tenkou ni megumareta"}]},{"key":"k:気","kind":"kanji","level":"N5","character":"気","meaning":"Khí, tinh thần","hanviet":"Khí","onReadings":["キ","ケ"],"kunReadings":["-"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"天気","reading":"てんき","meaning":"Thời tiết","vocabKey":"v:天気"},{"compound":"元気","reading":"げんき","meaning":"Khỏe mạnh","vocabKey":"v:元気"},{"compound":"気持ち","reading":"きもち","meaning":"Tâm trạng","vocabKey":"v:気持ち"},{"compound":"人気","reading":"にんき","meaning":"Nổi tiếng","vocabKey":"v:人気"}],"lessonIds":[8,11,12,17,23,25,26,28,32,33,34,36,38,44,47,50],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 气 (hơi nước bốc lên) + メ (gạch chéo, giản lược từ 米 gạo). Hán-Việt: KHÍ. Mẹo nhớ: Hơi nước (气) bốc lên từ nồi cơm (米) — đó là 'khí', năng lượng, tinh thần 💨. Chữ gốc 氣 có 米, dạng hiện đại rút gọn thành メ. Âm キ (ki) gần 'khí'. Liên kết: 天気 (thời tiết), 元気 (nguyên khí = khỏe), 気持ち (cảm xúc), 人気 (nhân khí = nổi tiếng).","example":"**気**をつけてください。 / ki wo tsukete kudasai. (Hãy cẩn thận.)","examples":[{"ja":"気をつけてください。","vi":"Hãy cẩn thận.","romaji":"ki wo tsukete kudasai."},{"ja":"車に気をつける","vi":"Cẩn thận xe","romaji":"Kuruma ni ki o tsukeru"},{"ja":"風が気持ちいい","vi":"Gió dễ chịu","romaji":"Kaze ga kimochii i"},{"ja":"元気な子供","vi":"Đứa trẻ khỏe mạnh","romaji":"Genki na kodomo"}]},{"key":"k:雨","kind":"kanji","level":"N5","character":"雨","meaning":"Mưa","hanviet":"Vũ","onReadings":["ウ"],"kunReadings":["あめ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"大雨","reading":"おおあめ","meaning":"Mưa to"},{"compound":"雨天","reading":"うてん","meaning":"Ngày mưa"}],"lessonIds":[12],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: Chữ tượng hình — nét ngang trên = bầu trời, nét dọc = cửa sổ nhìn ra, 4 chấm = hạt mưa rơi. Hán-Việt: VŨ. Mẹo nhớ: Nhìn qua cửa sổ thấy hạt mưa rơi từ trời xuống 🌧️ — đó là 'mưa'. 8 nét. Âm ウ (u) gần 'vũ'. Liên kết: 大雨 (mưa to), 雨天 (ngày mưa). 雨 là bộ thủ quan trọng: 雪 (tuyết), 雲 (vân/mây), 電 (điện) đều chứa 雨. ⚠️ 4 chấm bên trong phải viết đúng vị trí.","example":"明日は**雨**が降るそうです。 / ashita wa ame ga furu sou desu. (Nghe nói ngày mai mưa.)","examples":[{"ja":"明日は雨が降るそうです。","vi":"Nghe nói ngày mai mưa.","romaji":"ashita wa ame ga furu sou desu."},{"ja":"雨が降る","vi":"Trời mưa","romaji":"Ame ga furu"},{"ja":"雨で試合は中止になった","vi":"Trận đấu bị hủy vì mưa","romaji":"ame de shiai wa chuushi ni natsuta"},{"ja":"きのうは雨でした。","vi":"Hôm qua trời đã mưa.","romaji":"kinou wa ame deshita."}]},{"key":"k:雪","kind":"kanji","level":"N5","character":"雪","meaning":"Tuyết","hanviet":"Tuyết","onReadings":["セツ"],"kunReadings":["ゆき"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"大雪","reading":"おおゆき","meaning":"Tuyết lớn"}],"lessonIds":[12,40],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 雨 (mưa) + ヨ(彐) (tay quét). Hán-Việt: TUYẾT. Mẹo nhớ: 雨 Mưa rơi xuống gặp lạnh, dùng tay (彐) quét đi — đó là 'tuyết' ❄️, thứ mưa trắng có thể quét được. Âm ゆき (yuki), セツ (setsu) gần 'tuyết'. Liên kết: 大雪 (tuyết lớn). ⚠️ Đừng nhầm 彐 bên dưới với ヨ katakana — 彐 trong 雪 là 'tay vốc/quét'.","example":"**雪**が降っています。 / yuki ga futte imasu. (Tuyết đang rơi.)","examples":[{"ja":"雪が降っています。","vi":"Tuyết đang rơi.","romaji":"yuki ga futsute imasu."},{"ja":"雪が降る","vi":"Tuyết rơi","romaji":"Yuki ga furu"},{"ja":"午後から雪が降るでしょう。","vi":"Chiều chắc sẽ có tuyết.","romaji":"gogo kara yuki ga furu desho u."},{"ja":"雪で学校が休みになりました。","vi":"Trường đã nghỉ vì tuyết.","romaji":"yuki de gakkou ga yasumi ni narimashita."}]},{"key":"k:風","kind":"kanji","level":"N4","character":"風","meaning":"Gió","hanviet":"Phong","onReadings":["フウ","フ"],"kunReadings":["かぜ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"風邪","reading":"かぜ","meaning":"Cảm","vocabKey":"v:風邪"},{"compound":"台風","reading":"たいふう","meaning":"Bão","vocabKey":"v:台風"}],"lessonIds":[32,39],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 几 (ghế/khung) + 虫 (trùng/côn trùng, biến thể). Hán-Việt: PHONG. Mẹo nhớ: 几 Khung cửa mở ra, côn trùng (虫) bay vào theo 'gió' 🌬️. Gió mang theo côn trùng! Âm かぜ (kaze) = gió/cảm, フウ (fuu) gần 'phong'. Liên kết: 風邪 (cảm gió = cảm lạnh), 台風 (đài phong = bão). ⚠️ 風邪 (kaze = cảm) đọc giống 風 (kaze = gió) — gió lạnh gây cảm!","example":"今日は**風**が強いです。 / kyou wa kaze ga tsuyoi desu. (Hôm nay gió mạnh.)","examples":[{"ja":"今日は風が強いです。","vi":"Hôm nay gió mạnh.","romaji":"kyou wa kaze ga tsuyoi desu."},{"ja":"風が強い","vi":"Gió mạnh","romaji":"Kaze ga tsuyoi"},{"ja":"台風が来る","vi":"Bão đến","romaji":"taifuu ga kuru"},{"ja":"風邪をひく","vi":"Bị cảm","romaji":"Kaze wo hiku"}]},{"key":"k:空","kind":"kanji","level":"N5","character":"空","meaning":"Bầu trời, trống rỗng","hanviet":"Không","onReadings":["クウ"],"kunReadings":["そら","あ","から"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"空港","reading":"くうこう","meaning":"Sân bay","vocabKey":"v:空港"},{"compound":"空気","reading":"くうき","meaning":"Không khí","vocabKey":"v:空気"}],"lessonIds":[11,12,27,31,32,44],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 穴 (hang, lỗ — 宀 mái + 八 chia) + 工 (thợ, công). Hán-Việt: KHÔNG. Mẹo nhớ: Thợ (工) đào sâu vào hang (穴) cho đến khi trống 'không' — rồi mở rộng ra thành bầu trời bao la 🌌. Âm そら (sora) = bầu trời, から (kara) = rỗng, クウ (kuu) gần 'không'. Liên kết: 空港 (không cảng = sân bay), 空気 (không khí). ⚠️ Đừng nhầm 空 với 穴 (huyệt/lỗ) — 空 thêm 工 ở dưới.","example":"雨が止んで、**空**がとても青く見えます。 / ame ga yande, sora ga totemo aoku miemasu. (Mưa tạnh rồi nên bầu trời trông rất xanh.)","examples":[{"ja":"雨が止んで、空がとても青く見えます。","vi":"Mưa tạnh rồi nên bầu trời trông rất xanh.","romaji":"ame ga yande, sora ga totemo aoku miemasu."},{"ja":"お腹が空く","vi":"Đói bụng","romaji":"Onaka ga suku"},{"ja":"空が青い","vi":"Trời xanh","romaji":"Sora ga aoi"},{"ja":"田舎の空気はきれいです","vi":"Không khí ở quê trong sạch","romaji":"inaka no kuuki wa kirei desu"}]},{"key":"k:海","kind":"kanji","level":"N5","character":"海","meaning":"Biển","hanviet":"Hải","onReadings":["カイ"],"kunReadings":["うみ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"海外","reading":"かいがい","meaning":"Nước ngoài","vocabKey":"v:海外"},{"compound":"海岸","reading":"かいがん","meaning":"Bờ biển","vocabKey":"v:海岸"}],"lessonIds":[12,35,38],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 氵(水) (nước) + 每 (mỗi — 𠂉 + 母 mẹ). Hán-Việt: HẢI. Mẹo nhớ: 氵 Nước trải rộng khắp mọi nơi (每 = mỗi) — đó là 'biển' cả 🌊. Hoặc: biển như người 母 mẹ chứa đựng tất cả nước. Âm カイ (kai) gần 'hải'. Liên kết: 海外 (hải ngoại = nước ngoài), 海岸 (hải ngạn = bờ biển). ⚠️ Bộ 氵(3 chấm nước) viết trước, 每 viết sau.","example":"夏は**海**に行きます。 / natsu wa umi ni ikimasu. (Mùa hè tôi đi biển.)","examples":[{"ja":"夏は海に行きます。","vi":"Mùa hè tôi đi biển.","romaji":"natsu wa umi ni ikimasu."},{"ja":"海岸を歩く","vi":"Đi dọc bờ biển","romaji":"Kaigan wo aruku"},{"ja":"海で泳ぐ","vi":"Bơi ở biển","romaji":"Umi de oyogu"},{"ja":"海外旅行に行きたい","vi":"Muốn đi du lịch nước ngoài","romaji":"kaigai ryokou ni ikitai"}]},{"key":"k:山","kind":"kanji","level":"N5","character":"山","meaning":"Núi","hanviet":"Sơn","onReadings":["サン"],"kunReadings":["やま"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"富士山","reading":"ふじさん","meaning":"Núi Phú Sĩ"},{"compound":"山登り","reading":"やまのぼり","meaning":"Leo núi","vocabKey":"v:山登り"}],"lessonIds":[8,35],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: Chữ tượng hình — 3 đỉnh núi nhô lên từ mặt đất ⛰️. Hán-Việt: SƠN. Mẹo nhớ: Đỉnh giữa cao nhất, hai đỉnh bên thấp hơn — rõ ràng là hình 'núi'! Chỉ 3 nét, rất dễ viết. Âm やま (yama), サン (san) gần 'sơn'. Liên kết: 富士山 (Phú Sĩ Sơn), 山登り (leo núi). 山 là bộ thủ: 岩 (nham/đá), 島 (đảo), 崖 (nhai/vách) đều chứa 山. ⚠️ Đừng nhầm với 出 (xuất) — 山 có 3 nét dọc, 出 có hình khác.","example":"**山**に登りたいです。 / yama ni noboritai desu. (Tôi muốn leo núi.)","examples":[{"ja":"山に登りたいです。","vi":"Tôi muốn leo núi.","romaji":"yama ni noboritai desu."},{"ja":"山に登る","vi":"Leo núi","romaji":"Yama ni noboru"},{"ja":"この島には火山がある","vi":"Trên đảo này có núi lửa","romaji":"Kono shima ni wa kazan ga aru"},{"ja":"登山が趣味です","vi":"Sở thích là leo núi","romaji":"Tozan ga shumi de su"}]},{"key":"k:川","kind":"kanji","level":"N5","character":"川","meaning":"Sông","hanviet":"Xuyên","onReadings":["セン"],"kunReadings":["かわ"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"川","reading":"かわ","meaning":"Sông","vocabKey":"v:川"}],"lessonIds":[13],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: Chữ tượng hình — 3 nét cong chảy xuống = dòng nước chảy 🏞️. Hán-Việt: XUYÊN. Mẹo nhớ: Ba dòng nước chảy song song — đó là 'sông'. Chỉ 3 nét, dễ nhớ dễ viết. Âm かわ (kawa), セン (sen) gần 'xuyên' (xuyên suốt). Liên kết: Cặp nhớ 山 (núi, 3 đỉnh) ↔ 川 (sông, 3 dòng). ⚠️ Nét giữa thẳng, 2 nét bên hơi cong — khác với katakana ツ (tsu).","example":"夏になると、この**川**で子どもたちが遊びます。 / natsu ni naru to, kono kawa de kodomo-tachi ga asobimasu. (Đến mùa hè thì bọn trẻ chơi ở con sông này.)","examples":[{"ja":"夏になると、この川で子どもたちが遊びます。","vi":"Đến mùa hè thì bọn trẻ chơi ở con sông này.","romaji":"natsu ni naru to, kono kawa de kodomo-tachi ga asobimasu."},{"ja":"川で釣りをする","vi":"Câu cá ở sông","romaji":"Kawa de tsuri wo suru"},{"ja":"川の長さを測る","vi":"Đo chiều dài con sông","romaji":"Kawa no nagasa wo hakaru"},{"ja":"この川で泳げます。","vi":"Có thể bơi ở sông này.","romaji":"kono kawa de oyogemasu."}]},{"key":"k:林","kind":"kanji","level":"N4","character":"林","meaning":"Rừng nhỏ","hanviet":"Lâm","onReadings":["リン"],"kunReadings":["はやし"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"林","reading":"はやし","meaning":"Rừng nhỏ","vocabKey":"v:林"}],"lessonIds":[],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 木 (cây) + 木 (cây) = hai cây cạnh nhau. Hán-Việt: LÂM. Mẹo nhớ: Hai cây 🌲🌲 mọc cạnh nhau = rừng nhỏ, lùm cây. Âm リン (rin) gần 'lâm'. Liên kết: 木 (1 cây) → 林 (2 cây = rừng nhỏ) → 森 (3 cây = rừng rậm). Chuỗi nhớ tuyệt vời! 森林 (sâm lâm = rừng rậm). ⚠️ 林 là 2 chữ 木 ghép ngang, đừng nhầm với 森 có thêm 木 ở trên.","example":"**林**を歩きました。 / hayashi wo arukimashita. (Tôi đã đi bộ trong rừng.)","examples":[{"ja":"林を歩きました。","vi":"Tôi đã đi bộ trong rừng.","romaji":"hayashi wo arukimashita."},{"ja":"林の中を歩く","vi":"Đi bộ trong rừng","romaji":"Hayashi no naka wo aruku"}]},{"key":"k:森","kind":"kanji","level":"N4","character":"森","meaning":"Rừng (rậm)","hanviet":"Sâm","onReadings":["シン"],"kunReadings":["もり"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"森林","reading":"しんりん","meaning":"Rừng"}],"lessonIds":[],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 木 + 木 + 木 = ba cây chồng lên nhau. Hán-Việt: SÂM. Mẹo nhớ: Ba cây 🌲🌲🌲 mọc dày đặc = rừng rậm rạp, um tùm. Âm もり (mori), シン (shin) gần 'sâm'. Liên kết: 木 (1 cây) → 林 (2 cây) → 森 (3 cây) — quy luật tăng dần rất dễ nhớ! 森林 (sâm lâm) = rừng. ⚠️ Viết 木 trên trước (ở giữa), rồi 2 木 ở dưới viết sau.","example":"**森**の中は涼しいです。 / mori no naka wa suzushii desu. (Trong rừng mát.)","examples":[{"ja":"森の中は涼しいです。","vi":"Trong rừng mát.","romaji":"mori no naka wa suzushii desu."},{"ja":"森を歩く","vi":"Đi bộ trong rừng","romaji":"Mori wo aruku"}]},{"key":"k:花","kind":"kanji","level":"N5","character":"花","meaning":"Hoa","hanviet":"Hoa","onReadings":["カ"],"kunReadings":["はな"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"花見","reading":"はなみ","meaning":"Ngắm hoa"},{"compound":"花火","reading":"はなび","meaning":"Pháo hoa","vocabKey":"v:花火"}],"lessonIds":[6,7,12,27,30],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 艹 (cỏ/thực vật) + 化 (biến hóa — 亻 người + 匕 thìa). Hán-Việt: HOA. Mẹo nhớ: Thực vật (艹) biến hóa (化) thành bông 'hoa' tuyệt đẹp 🌸. Âm はな (hana), カ (ka) gần 'hoa'. Liên kết: 花見 (hoa kiến = ngắm hoa anh đào), 花火 (hoa hỏa = pháo hoa). ⚠️ Đừng nhầm bộ 艹 (cỏ, 3 nét) trên đầu với bộ 竹 (trúc, 6 nét).","example":"きれいな**花**が咲いています。 / kireina hana ga saite imasu. (Hoa đẹp đang nở.)","examples":[{"ja":"きれいな花が咲いています。","vi":"Hoa đẹp đang nở.","romaji":"kireina hana ga saite imasu."},{"ja":"花が咲く","vi":"Hoa nở","romaji":"Hana ga saku"},{"ja":"花火を見る","vi":"Xem pháo hoa","romaji":"Hanabi wo miru"},{"ja":"木村さんに花をあげました。","vi":"Tôi tặng hoa cho chị Kimura.","romaji":"kimura san ni hana o agemashita."}]},{"key":"k:草","kind":"kanji","level":"N4","character":"草","meaning":"Cỏ","hanviet":"Thảo","onReadings":["ソウ"],"kunReadings":["くさ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"草花","reading":"くさばな","meaning":"Hoa cỏ"}],"lessonIds":[35],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 艹 (cỏ/thực vật) + 早 (sớm — 日 mặt trời + 十 mười). Hán-Việt: THẢO. Mẹo nhớ: Thực vật (艹) mọc sớm nhất (早) vào buổi sáng — đó là 'cỏ' 🌿, loại cây mọc nhanh và sớm nhất. Âm くさ (kusa), ソウ (sou) gần 'thảo'. Liên kết: 草花 (cỏ hoa = hoa dại). So sánh: 花 (hoa = cây biến hóa đẹp) ↔ 草 (cỏ = cây mọc sớm giản dị).","example":"**草**の上に座りました。 / kusa no ue ni suwarimashita. (Tôi ngồi trên cỏ.)","examples":[{"ja":"草の上に座りました。","vi":"Tôi ngồi trên cỏ.","romaji":"kusa no ue ni suwarimashita."},{"ja":"草の上に座る","vi":"Ngồi trên cỏ","romaji":"Kusa no ue ni suwaru"},{"ja":"草津","vi":"khu nghỉ dưỡng ở tỉnh Gunma","romaji":"kusatsu"}]},{"key":"k:木","kind":"kanji","level":"N5","character":"木","meaning":"Cây, gỗ","hanviet":"Mộc","onReadings":["モク","ボク"],"kunReadings":["き","こ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"木曜日","reading":"もくようび","meaning":"Thứ Năm","vocabKey":"v:木曜日"},{"compound":"大木","reading":"たいぼく","meaning":"Cây lớn"}],"lessonIds":[4,10],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: Chữ tượng hình — thân cây dọc ở giữa, cành vươn ra hai bên, rễ bám đất bên dưới 🌳. Hán-Việt: MỘC. Mẹo nhớ: Hình ảnh rõ ràng của một cây — thân thẳng, cành tỏa, rễ sâu. Chỉ 4 nét. Âm き (ki), モク (moku) gần 'mộc'. Liên kết: 木曜日 (mộc diệu nhật = thứ Năm). 木 là bộ thủ cực phổ biến: 林 (lâm), 森 (sâm), 本 (bản), 休 (hưu), 校 (hiệu) đều chứa 木.","example":"大きい**木**があります。 / ookii ki ga arimasu. (Có cây to.)","examples":[{"ja":"大きい木があります。","vi":"Có cây to.","romaji":"ookii ki ga arimasu."},{"ja":"木曜日に会議がある","vi":"Thứ Năm có họp","romaji":"mokuyoubi ni kaigi ga aru"},{"ja":"木が高い","vi":"Cây cao","romaji":"Ki ga takai"},{"ja":"木村さんに花をあげました。","vi":"Tôi tặng hoa cho chị Kimura.","romaji":"kimura san ni hana o agemashita."}]},{"key":"k:石","kind":"kanji","level":"N4","character":"石","meaning":"Đá","hanviet":"Thạch","onReadings":["セキ","シャク"],"kunReadings":["いし"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"石油","reading":"せきゆ","meaning":"Dầu mỏ","vocabKey":"v:石油"}],"lessonIds":[32,37],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 厂 (vách đá/sườn núi) + 口 (khối vuông). Hán-Việt: THẠCH. Mẹo nhớ: Dưới vách núi (厂) có một khối vuông (口) — đó là tảng 'đá' 🪨. Chỉ 5 nét, dễ viết. Âm いし (ishi), セキ (seki) gần 'thạch'. Liên kết: 石油 (thạch du = dầu mỏ). 石 là bộ thủ: 岩 (nham = đá tảng, 山+石), 砂 (sa = cát). ⚠️ Đừng nhầm 石 với 右 (hữu/phải) — 石 có 厂 (vách), 右 có ナ (tay phải).","example":"**石**の上に座ると、服が汚れてしまいます。 / ishi no ue ni suwaru to, fuku ga yogorete shimaimasu. (Nếu ngồi lên đá thì quần áo sẽ bị bẩn.)","examples":[{"ja":"石の上に座ると、服が汚れてしまいます。","vi":"Nếu ngồi lên đá thì quần áo sẽ bị bẩn.","romaji":"ishi no ue ni suwaru to, fuku ga yogorete shimaimasu."},{"ja":"石を投げる","vi":"Ném đá","romaji":"Ishi wo nageru"},{"ja":"石鹸で洗う","vi":"Rửa bằng xà phòng","romaji":"Sekken de arau"},{"ja":"あの橋は石で作られました。","vi":"Cây cầu kia được làm bằng đá.","romaji":"ano hashi wa ishi de tsukura remashita."}]},{"key":"k:地","kind":"kanji","level":"N5","character":"地","meaning":"Đất, nền","hanviet":"Địa","onReadings":["チ","ジ"],"kunReadings":["-"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"地震","reading":"じしん","meaning":"Động đất","vocabKey":"v:地震"},{"compound":"地下鉄","reading":"ちかてつ","meaning":"Tàu ngầm","vocabKey":"v:地下鉄"},{"compound":"地図","reading":"ちず","meaning":"Bản đồ","vocabKey":"v:地図"}],"lessonIds":[3,5,14,29,30,33,39,40],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 土 (đất) + 也 (cũng, vậy — gợi âm chi/địa). Hán-Việt: ĐỊA. Mẹo nhớ: 土 Đất đai trải rộng khắp nơi, 也 gợi âm 'địa'. Đất là nền tảng cho mọi thứ 🌍. Âm チ (chi) gần 'địa', ジ (ji) dùng trong từ ghép. Liên kết: 地震 (địa chấn = động đất), 地下鉄 (địa hạ thiết = tàu điện ngầm), 地図 (địa đồ = bản đồ). ⚠️ 土 viết trước (bên trái), 也 viết sau (bên phải).","example":"**地**震が起きました。 / jishin ga okimashita. (Động đất xảy ra.)","examples":[{"ja":"地震が起きました。","vi":"Động đất xảy ra.","romaji":"jishin ga okimashita."},{"ja":"地味な色が好き","vi":"Thích màu giản dị","romaji":"Jimi na iro ga suki"},{"ja":"出身地はどこですか","vi":"Quê bạn ở đâu?","romaji":"Shusshinchi wa dokodesuka"},{"ja":"地方に住む","vi":"Sống ở vùng","romaji":"chihou ni sumu"}]},{"key":"k:光","kind":"kanji","level":"N4","character":"光","meaning":"Ánh sáng","hanviet":"Quang","onReadings":["コウ"],"kunReadings":["ひかり","ひか"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"日光","reading":"にっこう","meaning":"Ánh nắng","vocabKey":"v:日光"},{"compound":"観光","reading":"かんこう","meaning":"Tham quan"}],"lessonIds":[35],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: ⺌/小 (tia sáng tỏa ra) + 儿 (người — chân bước). Hán-Việt: QUANG. Mẹo nhớ: Tia lửa (⺌) tỏa sáng phía trên người (儿) — đó là 'ánh sáng' ✨. Hình dung ngọn đuốc trên đầu người, chiếu sáng xung quanh. Âm ひかり (hikari), コウ (kou) gần 'quang'. Liên kết: 日光 (nhật quang = ánh nắng), 観光 (quan quang = tham quan du lịch). ⚠️ 6 nét — phần trên viết tia sáng trước, phần dưới viết chân người sau.","example":"太陽の**光**が明るいです。 / taiyou no hikari ga akarui desu. (Ánh nắng mặt trời sáng.)","examples":[{"ja":"太陽の光が明るいです。","vi":"Ánh nắng mặt trời sáng.","romaji":"taiyou no hikari ga akarui desu."},{"ja":"星が光る","vi":"Sao sáng","romaji":"Hoshi ga hikaru"},{"ja":"光が強すぎる","vi":"Ánh sáng quá mạnh","romaji":"Hikari ga tsuyosu giru"},{"ja":"光熱費を節約する","vi":"Tiết kiệm tiền điện nước","romaji":"kounetsuhi o setsuyaku suru"}]},{"key":"k:鳥","kind":"kanji","level":"N5","character":"鳥","meaning":"Chim","hanviet":"Điểu","onReadings":["チョウ"],"kunReadings":["とり"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"小鳥","reading":"ことり","meaning":"Chim nhỏ"},{"compound":"鳥肉","reading":"とりにく","meaning":"Thịt gà"}],"lessonIds":[27],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: Chữ tượng hình — phần trên = đầu chim có mỏ, giữa = thân và cánh, 灬 (dưới) = lông đuôi xòe ra 🐦. Hán-Việt: ĐIỂU. Mẹo nhớ: Nhìn chữ như chim đứng nghiêng: mỏ nhọn ở trên, thân ở giữa, đuôi lông (灬 = 4 chấm) tỏa ra bên dưới. 11 nét. Âm とり (tori), チョウ (chou) gần 'điểu'. Liên kết: 小鳥 (tiểu điểu = chim nhỏ), 鳥肉 (thịt gà). ⚠️ Đừng nhầm 鳥 (điểu/chim, 11 nét) với 烏 (ô/quạ, 10 nét — thiếu 1 nét ngang vì quạ đen không thấy mắt).","example":"**鳥**が歌っています。 / tori ga utatte imasu. (Chim đang hót.)","examples":[{"ja":"鳥が歌っています。","vi":"Chim đang hót.","romaji":"tori ga utatsute imasu."},{"ja":"鳥が鳴く","vi":"Chim kêu","romaji":"Tori ga naku"},{"ja":"焼き鳥を食べに行く","vi":"Đi ăn gà nướng xiên","romaji":"Yakitori wo tabe ni iku"},{"ja":"鳥の声が聞こえますか。","vi":"Bạn có nghe thấy tiếng chim không?","romaji":"tori no koe ga kikoemasu ka."}]},{"key":"k:魚","kind":"kanji","level":"N5","character":"魚","meaning":"Cá","hanviet":"Ngư","onReadings":["ギョ"],"kunReadings":["さかな","うお"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"金魚","reading":"きんぎょ","meaning":"Cá vàng"},{"compound":"魚屋","reading":"さかなや","meaning":"Tiệm cá"}],"lessonIds":[6],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: Chữ tượng hình — phần trên = đầu cá, 田 (giữa) = thân có vảy, 灬 (dưới) = đuôi/vây 🐟. Hán-Việt: NGƯ. Mẹo nhớ: Nhìn từ trên xuống: đầu cá nhọn → thân vuông có vảy (田) → đuôi vẫy (灬). 11 nét. Âm さかな (sakana) = cá (đời thường), ギョ (gyo) gần 'ngư' (từ ghép). Liên kết: 金魚 (kim ngư = cá vàng), 魚屋 (ngư ốc = tiệm cá). ⚠️ Đừng nhầm 魚 với 鳥 (điểu/chim) — cả hai đều có 灬 nhưng phần trên khác nhau.","example":"**魚**が好きです。 / sakana ga suki desu. (Tôi thích cá.)","examples":[{"ja":"魚が好きです。","vi":"Tôi thích cá.","romaji":"sakana ga suki desu."},{"ja":"魚を釣る","vi":"Câu cá","romaji":"Sakana wo tsuru"},{"ja":"肉は食べますが、魚は食べません。","vi":"Thịt tôi ăn nhưng cá thì không.","romaji":"niku wa tabemasu ga, sakana wa tabemasen."},{"ja":"妹は猫に魚をとられました。","vi":"Em gái bị con mèo lấy mất cá.","romaji":"imouto wa neko ni sakana o tora remashita."}]},{"key":"k:犬","kind":"kanji","level":"N5","character":"犬","meaning":"Chó","hanviet":"Khuyển","onReadings":["ケン"],"kunReadings":["いぬ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"犬","reading":"いぬ","meaning":"Chó","vocabKey":"v:犬"},{"compound":"子犬","reading":"こいぬ","meaning":"Chó con"}],"lessonIds":[10],"topicTags":["weather"],"sectionId":2,"sectionName":"TỰ NHIÊN & THỜI TIẾT","mnemonic":"Bộ/thành phần: 大 (lớn/người dang tay) + 丶 (chấm = tai vểnh). Hán-Việt: KHUYỂN. Mẹo nhớ: Giống chữ 大 (đại/lớn) nhưng thêm một 丶 chấm nhỏ — đó là tai con 'chó' vểnh lên 🐕. Chỉ 4 nét. Âm いぬ (inu), ケン (ken) gần 'khuyển'. Liên kết: 子犬 (chó con). 犬/犭 là bộ thủ: 猫 (miêu/mèo), 狭 (hẹp), 猿 (viên/khỉ). ⚠️ Đừng nhầm 犬 (chó, có chấm) với 大 (lớn, không chấm) — chỉ khác một chấm nhỏ!","example":"**犬**と散歩します。 / inu to sanpo shimasu. (Tôi đi dạo với chó.)","examples":[{"ja":"犬と散歩します。","vi":"Tôi đi dạo với chó.","romaji":"inu to sanpo shimasu."},{"ja":"犬が走る","vi":"Chó chạy","romaji":"Inu ga hashiru"},{"ja":"わたしは犬に靴をかまれました。","vi":"Tôi bị chó cắn hỏng giày.","romaji":"watashi wa inu ni kutsu o kama remashita."},{"ja":"小さい犬","vi":"Con chó nhỏ","romaji":"Chiisai inu"}]},{"key":"k:日","kind":"kanji","level":"N5","character":"日","meaning":"Ngày, mặt trời","hanviet":"Nhật","onReadings":["ニチ","ジツ"],"kunReadings":["ひ","か"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"日曜日","reading":"にちようび","meaning":"Chủ nhật","vocabKey":"v:日曜日"},{"compound":"今日","reading":"きょう","meaning":"Hôm nay","vocabKey":"v:今日"},{"compound":"毎日","reading":"まいにち","meaning":"Mỗi ngày","vocabKey":"v:毎日"}],"lessonIds":[2,4,5,17,18,19,24,26,28,35],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 日 là tượng hình — hình mặt trời (□) với tia sáng (nét ngang giữa). Hán-Việt: NHẬT. Mẹo nhớ: Khung vuông có ánh sáng bên trong — 'nhật' là mặt trời, là ngày ☀️. Chỉ 4 nét. Âm ひ (hi) = ngày/nắng, ニチ (nichi) gần 'nhật'. Liên kết: 日曜日 (Chủ nhật), 今日 (hôm nay), 毎日 (mỗi ngày). ⚠️ 日 là bộ thủ cực phổ biến: 時 (thì), 明 (minh), 早 (tảo), 昼 (trú).","example":"毎**日**勉強しています。 / mainichi benkyou shite imasu. (Tôi học mỗi ngày.)","examples":[{"ja":"毎日勉強しています。","vi":"Tôi học mỗi ngày.","romaji":"mainichi benkyou shite imasu."},{"ja":"昨日映画を見た","vi":"Hôm qua xem phim","romaji":"kinou eiga o mita"},{"ja":"今日は暑い","vi":"Hôm nay nóng","romaji":"kyou wa atsui"},{"ja":"明日学校がある","vi":"Ngày mai có trường","romaji":"ashita gakkou ga aru"}]},{"key":"k:月","kind":"kanji","level":"N5","character":"月","meaning":"Tháng, mặt trăng","hanviet":"Nguyệt","onReadings":["ゲツ","ガツ"],"kunReadings":["つき"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"月曜日","reading":"げつようび","meaning":"Thứ Hai","vocabKey":"v:月曜日"},{"compound":"今月","reading":"こんげつ","meaning":"Tháng này","vocabKey":"v:今月"}],"lessonIds":[4,5,11,23,30,31,36,50],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 月 là tượng hình — hình trăng lưỡi liềm với 2 nét ngang là ánh sáng mờ. Hán-Việt: NGUYỆT. Mẹo nhớ: Trăng khuyết (月) treo trên trời — 'nguyệt' là mặt trăng, đếm tháng 🌙. 4 nét. Âm つき (tsuki) = trăng, ゲツ (getsu) gần 'nguyệt'. Liên kết: 月曜日 (thứ Hai), 今月 (tháng này). ⚠️ 月 trong nhiều kanji là biến thể của 肉 (thịt) — cần phân biệt: 月 đứng bên trái = thịt, đứng một mình = trăng.","example":"今夜は**月**がきれいなので、写真を撮りたいです。 / konya wa tsuki ga kirei na node, shashin wo toritai desu. (Tối nay trăng đẹp nên tôi muốn chụp ảnh.)","examples":[{"ja":"今夜は月がきれいなので、写真を撮りたいです。","vi":"Tối nay trăng đẹp nên tôi muốn chụp ảnh.","romaji":"konya wa tsuki ga kirei na node, shashin wo toritai desu."},{"ja":"先月引っ越した","vi":"Tháng trước chuyển nhà","romaji":"Sengetsu hikkoshita"},{"ja":"今月は3月だ","vi":"Tháng này là tháng 3","romaji":"kongetsu wa 3 tsuki da"},{"ja":"来月日本に行く","vi":"Tháng sau đi Nhật","romaji":"Raigetsu nippon ni iku"}]},{"key":"k:年","kind":"kanji","level":"N5","character":"年","meaning":"Năm","hanviet":"Niên","onReadings":["ネン"],"kunReadings":["とし"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"今年","reading":"ことし","meaning":"Năm nay","vocabKey":"v:今年"},{"compound":"来年","reading":"らいねん","meaning":"Năm sau","vocabKey":"v:来年"},{"compound":"去年","reading":"きょねん","meaning":"Năm ngoái","vocabKey":"v:去年"}],"lessonIds":[5,7,11,36,40,41,46,49,50],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 禾 (lúa, biến thể trên) + 干 (can/chặn). Hán-Việt: NIÊN. Mẹo nhớ: Mỗi mùa lúa (禾) chín là một 'niên' — một năm trôi qua 📅. 6 nét. Âm とし (toshi) = năm/tuổi, ネン (nen) gần 'niên'. Liên kết: 今年 (năm nay), 来年 (năm sau), 去年 (năm ngoái). ⚠️ Đừng nhầm 年 (niên/năm) với 午 (ngọ) — 年 có nhiều nét ngang hơn.","example":"来**年**日本に行きます。 / rainen nihon ni ikimasu. (Năm sau tôi đi Nhật.)","examples":[{"ja":"来年日本に行きます。","vi":"Năm sau tôi đi Nhật.","romaji":"rainen nippon ni ikimasu."},{"ja":"年齢を聞いてもいいですか","vi":"Hỏi tuổi có được không?","romaji":"Nenrei wo kii temoiidesuka"},{"ja":"去年結婚した","vi":"Năm ngoái kết hôn","romaji":"Kyonen kekkon shita"},{"ja":"今年は忙しい","vi":"Năm nay bận","romaji":"Kotoshi wa isogashii"}]},{"key":"k:時","kind":"kanji","level":"N5","character":"時","meaning":"Giờ, lúc","hanviet":"Thì","onReadings":["ジ"],"kunReadings":["とき"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"時間","reading":"じかん","meaning":"Thời gian","vocabKey":"v:時間"},{"compound":"時計","reading":"とけい","meaning":"Đồng hồ","vocabKey":"v:時計"}],"lessonIds":[2,4,6,9,11,15,45],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 日 (ngày) + 寺. Mẹo nhớ: thời gian gắn với nhịp ngày đêm, nên nhớ nghĩa 'giờ/lúc'.","example":"三**時**に会いましょう。 / sanji ni aimashou. (Hẹn gặp lúc 3 giờ.)","examples":[{"ja":"三時に会いましょう。","vi":"Hẹn gặp lúc 3 giờ.","romaji":"sanji ni aimashou."},{"ja":"到着時間を確認する","vi":"Kiểm tra giờ đến","romaji":"touchaku jikan o kakunin suru"},{"ja":"出発時間に遅れないようにする","vi":"Cố gắng không trễ giờ khởi hành","romaji":"shuppatsu jikan ni okurenai you ni suru"},{"ja":"時々映画を見る","vi":"Thỉnh thoảng xem phim","romaji":"Tokidoki eiga wo miru"}]},{"key":"k:分","kind":"kanji","level":"N5","character":"分","meaning":"Phút, chia, hiểu","hanviet":"Phân","onReadings":["ブン","フン"],"kunReadings":["わ","わ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"十分","reading":"じゅっぷん","meaning":"10 phút"},{"compound":"半分","reading":"はんぶん","meaning":"Một nửa"},{"compound":"自分","reading":"じぶん","meaning":"Bản thân","vocabKey":"v:自分"}],"lessonIds":[4,24,26,28,32,34],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 八 (tám/tách ra) + 刀 (dao). Hán-Việt: PHÂN. Mẹo nhớ: Dùng 刀 dao cắt 八 tách ra — 'phân' chia, phân biệt ✂️. 4 nét. Âm わかる (wakaru) = hiểu, わける (wakeru) = chia, フン (fun) = phút. Liên kết: 十分 (10 phút), 半分 (một nửa), 自分 (bản thân). ⚠️ 3 nghĩa khác nhau: フン = phút, ブン = phần/chia, わかる = hiểu biết.","example":"五**分**待ってください。 / gofun matte kudasai. (Xin đợi 5 phút.)","examples":[{"ja":"五分待ってください。","vi":"Xin đợi 5 phút.","romaji":"gofun matsute kudasai."},{"ja":"日本語が分かる","vi":"Hiểu tiếng Nhật","romaji":"Nihongo ga wakaru"},{"ja":"十分な準備","vi":"Chuẩn bị đầy đủ","romaji":"juubun na junbi"},{"ja":"身分証を見せてください","vi":"Xin cho xem giấy tờ tùy thân","romaji":"mibunshou o misete kudasai"}]},{"key":"k:週","kind":"kanji","level":"N5","character":"週","meaning":"Tuần","hanviet":"Chu","onReadings":["シュウ"],"kunReadings":["-"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"今週","reading":"こんしゅう","meaning":"Tuần này","vocabKey":"v:今週"},{"compound":"来週","reading":"らいしゅう","meaning":"Tuần sau","vocabKey":"v:来週"},{"compound":"先週","reading":"せんしゅう","meaning":"Tuần trước","vocabKey":"v:先週"}],"lessonIds":[5,11,13,36,50],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 辶 (shinnyou, di chuyển) + 周 (chu/xung quanh). Hán-Việt: CHU. Mẹo nhớ: Đi (辶) một vòng 周 xung quanh — hết một 'chu' kỳ, một tuần 🔄. 11 nét. Âm シュウ (shuu) gần 'chu'. Liên kết: 今週 (tuần này), 来週 (tuần sau), 先週 (tuần trước). ⚠️ 周 (chu) bên trong = 'xung quanh' — gợi hình chu kỳ lặp lại.","example":"来**週**テストがあります。 / raishuu tesuto ga arimasu. (Tuần sau có thi.)","examples":[{"ja":"来週テストがあります。","vi":"Tuần sau có thi.","romaji":"raishuu tesuto ga arimasu."},{"ja":"先週旅行した","vi":"Tuần trước du lịch","romaji":"senshuu ryokou shita"},{"ja":"今週は忙しい","vi":"Tuần này bận","romaji":"konshuu wa isogashii"},{"ja":"来週テストがある","vi":"Tuần sau có thi","romaji":"raishuu tesuto ga aru"}]},{"key":"k:曜","kind":"kanji","level":"N5","character":"曜","meaning":"Ngày (trong tuần)","hanviet":"Diệu","onReadings":["ヨウ"],"kunReadings":["-"],"strokeCount":18,"radicals":[],"components":[],"compounds":[{"compound":"月曜日","reading":"げつようび","meaning":"Thứ Hai","vocabKey":"v:月曜日"},{"compound":"火曜日","reading":"かようび","meaning":"Thứ Ba","vocabKey":"v:火曜日"}],"lessonIds":[4],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 日 (ngày) + 翟. Mẹo nhớ: các ngày trong tuần đều mang chữ 日 + 曜, nên nhớ nghĩa 'thứ trong tuần'.","example":"何**曜**日が好きですか。 / nanyoubi ga suki desu ka. (Bạn thích thứ mấy?)","examples":[{"ja":"何曜日が好きですか。","vi":"Bạn thích thứ mấy?","romaji":"nani youbi ga suki desu ka."},{"ja":"月曜日から仕事が始まる","vi":"Thứ Hai bắt đầu làm việc","romaji":"getsuyoubi kara shigoto ga hajimaru"},{"ja":"火曜日にテストがある","vi":"Thứ Ba có kiểm tra","romaji":"kayoubi ni tesuto ga aru"},{"ja":"水曜日は休みです","vi":"Thứ Tư được nghỉ","romaji":"suiyoubi wa yasumi desu"}]},{"key":"k:朝","kind":"kanji","level":"N5","character":"朝","meaning":"Buổi sáng","hanviet":"Triêu","onReadings":["チョウ"],"kunReadings":["あさ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"朝ご飯","reading":"あさごはん","meaning":"Bữa sáng"},{"compound":"毎朝","reading":"まいあさ","meaning":"Mỗi sáng","vocabKey":"v:毎朝"},{"compound":"今朝","reading":"けさ","meaning":"Sáng nay","vocabKey":"v:今朝"}],"lessonIds":[4,6],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 十 (mười) + 日 (mặt trời) + 月 (trăng — biến thể). Hán-Việt: TRIÊU. Mẹo nhớ: Mặt trời (日) mọc lên khi trăng (月) còn sót — đó là 'triêu' sáng sớm 🌅. 12 nét. Âm あさ (asa) = buổi sáng, チョウ (chou) gần 'triêu'. Liên kết: 朝ご飯 (bữa sáng), 毎朝 (mỗi sáng), 今朝 (sáng nay). ⚠️ 今朝 đọc けさ (kesa) — cách đọc đặc biệt, không theo quy tắc.","example":"毎**朝**6時に起きます。 / maiasa rokuji ni okimasu. (Mỗi sáng tôi dậy lúc 6 giờ.)","examples":[{"ja":"毎朝6時に起きます。","vi":"Mỗi sáng tôi dậy lúc 6 giờ.","romaji":"maiasa 6ji ni okimasu."},{"ja":"朝起きる","vi":"Dậy buổi sáng","romaji":"Asaokiru"},{"ja":"今朝は寒い","vi":"Sáng nay lạnh","romaji":"Kesa wa samui"},{"ja":"毎朝走る","vi":"Chạy mỗi sáng","romaji":"Maiasa hashiru"}]},{"key":"k:昼","kind":"kanji","level":"N5","character":"昼","meaning":"Buổi trưa","hanviet":"Trú","onReadings":["チュウ"],"kunReadings":["ひる"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"昼ご飯","reading":"ひるごはん","meaning":"Bữa trưa"},{"compound":"昼休み","reading":"ひるやすみ","meaning":"Nghỉ trưa","vocabKey":"v:昼休み"}],"lessonIds":[4,6,27],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 尺 (thước/đo) + 旦 (bình minh — 日 trên 一). Hán-Việt: TRÚ. Mẹo nhớ: Mặt trời (旦 bình minh) lên cao đo được (尺) — giữa 'trú', buổi trưa ☀️. 9 nét. Âm ひる (hiru) = trưa, チュウ (chuu) gần 'trú'. Liên kết: 昼ご飯 (bữa trưa), 昼休み (nghỉ trưa). ⚠️ Chuỗi thời gian trong ngày: 朝 (triêu/sáng) → 昼 (trú/trưa) → 夕 (tịch/chiều) → 夜 (dạ/tối).","example":"**昼**ご飯を食べましょう。 / hirugohan wo tabemashou. (Ăn trưa nào.)","examples":[{"ja":"昼ご飯を食べましょう。","vi":"Ăn trưa nào.","romaji":"hirugohan wo tabemashou."},{"ja":"昼ご飯を食べる","vi":"Ăn trưa","romaji":"Hiru gohan wo taberu"},{"ja":"昼間は暑い","vi":"Ban ngày nóng","romaji":"Hiruma wa atsui"},{"ja":"昼休みに食事する","vi":"Ăn trưa giờ nghỉ","romaji":"Hiruyasumi ni shokuji suru"}]},{"key":"k:夕","kind":"kanji","level":"N4","character":"夕","meaning":"Chiều tối","hanviet":"Tịch","onReadings":["セキ"],"kunReadings":["ゆう"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"夕方","reading":"ゆうがた","meaning":"Buổi chiều tối","vocabKey":"v:夕方"},{"compound":"夕食","reading":"ゆうしょく","meaning":"Bữa tối"}],"lessonIds":[32],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 夕 là tượng hình — hình trăng khuyết mới nhô lúc chạng vạng. Hán-Việt: TỊCH. Mẹo nhớ: Trăng non (夕) mới nhô — trời vừa 'tịch' dương, chiều tối đã đến 🌙. Chỉ 3 nét. Âm ゆう (yuu) = chiều, セキ (seki) gần 'tịch'. Liên kết: 夕方 (chiều tối), 夕食 (bữa tối). ⚠️ Đừng nhầm 夕 (tịch/chiều — 3 nét) với 夜 (dạ/đêm — 8 nét) hay 多 (đa/nhiều — 2 chữ 夕 chồng).","example":"**夕**方に帰ります。 / yuugata ni kaerimasu. (Tôi về lúc chiều tối.)","examples":[{"ja":"夕方に帰ります。","vi":"Tôi về lúc chiều tối.","romaji":"yuugata ni kaerimasu."},{"ja":"夕方に帰る","vi":"Về lúc chiều tối","romaji":"yuugata ni kaeru"},{"ja":"海の夕日を見る","vi":"Ngắm hoàng hôn trên biển","romaji":"umi no yuuhi o miru"},{"ja":"夕方","vi":"chiều tối","romaji":"yuugata"}]},{"key":"k:夜","kind":"kanji","level":"N5","character":"夜","meaning":"Đêm, buổi tối","hanviet":"Dạ","onReadings":["ヤ"],"kunReadings":["よる","よ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"夜中","reading":"よなか","meaning":"Nửa đêm","vocabKey":"v:夜中"},{"compound":"今夜","reading":"こんや","meaning":"Tối nay","vocabKey":"v:今夜"}],"lessonIds":[4,32,35],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 亠 (đầu/mái) + 亻 (người) + 夂 (bước chân) + 丶 (chấm). Hán-Việt: DẠ. Mẹo nhớ: Người (亻) bước chân (夂) về nhà dưới mái (亠) khi trời tối — đó là 'dạ', đêm tối 🌃. 8 nét. Âm よる (yoru) = đêm, ヤ (ya) gần 'dạ'. Liên kết: 夜中 (nửa đêm), 今夜 (tối nay). ⚠️ Đừng nhầm 夜 (dạ/đêm — 8 nét) với 液 (dịch/chất lỏng — có thêm 氵).","example":"**夜**遅くまで勉強しました。 / yoru osoku made benkyou shimashita. (Tôi học đến khuya.)","examples":[{"ja":"夜遅くまで勉強しました。","vi":"Tôi học đến khuya.","romaji":"yoru osoku made benkyou shimashita."},{"ja":"夜遅い","vi":"Tối muộn","romaji":"Yoruosoi"},{"ja":"夜中に目が覚めた","vi":"Tỉnh giấc lúc nửa đêm","romaji":"yachuu ni me ga sameta"},{"ja":"今夜は早く寝よう。","vi":"Tối nay ngủ sớm nhé.","romaji":"konya wa hayaku neyo u."}]},{"key":"k:春","kind":"kanji","level":"N5","character":"春","meaning":"Mùa xuân","hanviet":"Xuân","onReadings":["シュン"],"kunReadings":["はる"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"春休み","reading":"はるやすみ","meaning":"Nghỉ xuân","vocabKey":"v:春休み"}],"lessonIds":[12],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 日 + thành tố cây/cỏ. Mẹo nhớ: nắng ấm làm cây cối bật dậy, nên nhớ nghĩa 'mùa xuân'.","example":"**春**に桜が咲きます。 / haru ni sakura ga sakimasu. (Mùa xuân hoa anh đào nở.)","examples":[{"ja":"春に桜が咲きます。","vi":"Mùa xuân hoa anh đào nở.","romaji":"haru ni sakura ga sakimasu."},{"ja":"春に花が咲く","vi":"Mùa xuân hoa nở","romaji":"Haru ni hana ga saku"},{"ja":"春休みに旅行する","vi":"Nghỉ xuân đi du lịch","romaji":"haruyasumi ni ryokou suru"},{"ja":"春になれば、花が咲きます。","vi":"Nếu đến mùa xuân thì hoa sẽ nở.","romaji":"haru ni nare ba, hana ga sakimasu."}]},{"key":"k:夏","kind":"kanji","level":"N5","character":"夏","meaning":"Mùa hè","hanviet":"Hạ","onReadings":["カ"],"kunReadings":["なつ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"夏休み","reading":"なつやすみ","meaning":"Nghỉ hè","vocabKey":"v:夏休み"}],"lessonIds":[12],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: thành tố đầu + 夂. Mẹo nhớ: hình người đội mũ dưới nắng nóng, nên nhớ nghĩa 'mùa hè'.","example":"日本の**夏**は蒸し暑いので、毎日水をたくさん飲みます。 / nihon no natsu wa mushiatsui node, mainichi mizu wo takusan nomimasu. (Mùa hè ở Nhật oi bức nên mỗi ngày tôi uống nhiều nước.)","examples":[{"ja":"日本の夏は蒸し暑いので、毎日水をたくさん飲みます。","vi":"Mùa hè ở Nhật oi bức nên mỗi ngày tôi uống nhiều nước.","romaji":"nippon no natsu wa mushiatsui node, mainichisui o takusan nomimasu."},{"ja":"夏は暑い","vi":"Mùa hè nóng","romaji":"Natsu wa atsui"},{"ja":"夏休みに海に行く","vi":"Nghỉ hè đi biển","romaji":"Natsuyasumi ni umi ni iku"},{"ja":"夏休みに北海道へ行こうと思っています。","vi":"Tôi đang định hè sẽ đi Hokkaido.","romaji":"natsuyasumi ni hokkaidou e iko u to omotsute imasu."}]},{"key":"k:秋","kind":"kanji","level":"N5","character":"秋","meaning":"Mùa thu","hanviet":"Thu","onReadings":["シュウ"],"kunReadings":["あき"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"秋","reading":"あき","meaning":"Mùa thu","vocabKey":"v:秋"}],"lessonIds":[12],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 禾 (lúa) + 火 (lửa). Mẹo nhớ: mùa gặt vàng như lửa trên cánh đồng, nên nhớ nghĩa 'mùa thu'.","example":"**秋**は涼しくて、散歩するのにちょうどいいです。 / aki wa suzushikute, sanpo suru no ni choudo ii desu. (Mùa thu mát, rất hợp để đi dạo.)","examples":[{"ja":"秋は涼しくて、散歩するのにちょうどいいです。","vi":"Mùa thu mát, rất hợp để đi dạo.","romaji":"aki wa suzushikute, sanpo suru no ni choudo ii desu."},{"ja":"秋は涼しい","vi":"Mùa thu mát","romaji":"Aki wa suzushii"},{"ja":"京都へ行くなら、秋がいちばんきれいです。","vi":"Nếu đi Kyoto thì mùa thu là đẹp nhất.","romaji":"kyouto e iku nara, aki ga ichiban kirei desu."},{"ja":"パソコンなら、秋葉原が安いですよ。","vi":"Máy tính thì Akihabara rẻ lắm.","romaji":"pasokon nara, akihabara ga yasui desu yo."}]},{"key":"k:冬","kind":"kanji","level":"N5","character":"冬","meaning":"Mùa đông","hanviet":"Đông","onReadings":["トウ"],"kunReadings":["ふゆ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"冬休み","reading":"ふゆやすみ","meaning":"Nghỉ đông","vocabKey":"v:冬休み"}],"lessonIds":[12],"topicTags":["time"],"sectionId":3,"sectionName":"THỜI GIAN","mnemonic":"Bộ/thành phần: 夂 + chấm lạnh. Mẹo nhớ: nét rơi xuống gợi khí lạnh, nên nhớ nghĩa 'mùa đông'.","example":"**冬**は寒いので、出かける前にコートを着ます。 / fuyu wa samui node, dekakeru mae ni kooto wo kimasu. (Vì mùa đông lạnh nên tôi mặc áo khoác trước khi ra ngoài.)","examples":[{"ja":"冬は寒いので、出かける前にコートを着ます。","vi":"Vì mùa đông lạnh nên tôi mặc áo khoác trước khi ra ngoài.","romaji":"fuyu wa samui node, dekakeru mae ni kooto wo kimasu."},{"ja":"冬は寒い","vi":"Mùa đông lạnh","romaji":"Fuyu wa samui"},{"ja":"冬休みは短い","vi":"Nghỉ đông ngắn","romaji":"Fuyuyasumi wa mijikai"},{"ja":"冬休み どこか [へ] 行きましたか。","vi":"Nghỉ đông anh/chị có đi đâu không?","romaji":"fuyuyasumi doko ka [ e ] ikimashita ka."}]},{"key":"k:百","kind":"kanji","level":"N5","character":"百","meaning":"Trăm (100)","hanviet":"Bách","onReadings":["ヒャク"],"kunReadings":["-"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"百円","reading":"ひゃくえん","meaning":"100 yên"},{"compound":"三百","reading":"さんびゃく","meaning":"300"}],"lessonIds":[3],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 一 (một) + 白 (trắng). Hán-Việt: BÁCH. Mẹo nhớ: Một (一) trên trắng (白) — 'bách' là trăm, số lớn tròn 💯. 6 nét. Âm ヒャク (hyaku) gần 'bách'. Liên kết: 百円 (100 yên), 三百 (300). ⚠️ Âm biến đổi: 三百 = さんびゃく (sanbyaku), 六百 = ろっぴゃく (roppyaku).","example":"**百**円ショップに行きました。 / hyaku en shoppu ni ikimashita. (Tôi đã đi cửa hàng 100 yên.)","examples":[{"ja":"百円ショップに行きました。","vi":"Tôi đã đi cửa hàng 100 yên.","romaji":"hyaku en shoppu ni ikimashita."},{"ja":"百円ショップ","vi":"Cửa hàng 100 yên","romaji":"Hyakuen shoppu"},{"ja":"インスタントラーメンは安藤百福によって発明されました。","vi":"Mì ăn liền được Andou Momofuku phát minh.","romaji":"insutanto raamen wa andou hyaku fuku niyotte hatsumei sa remashita."},{"ja":"百","vi":"trăm","romaji":"hyaku"}]},{"key":"k:千","kind":"kanji","level":"N5","character":"千","meaning":"Nghìn (1000)","hanviet":"Thiên","onReadings":["セン"],"kunReadings":["ち"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"千円","reading":"せんえん","meaning":"1000 yên"},{"compound":"三千","reading":"さんぜん","meaning":"3000"}],"lessonIds":[3],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 丿 (phẩy) + 十 (mười). Hán-Việt: THIÊN. Mẹo nhớ: Từ mười (十) nhân lên — 'thiên' là nghìn, con số vượt trội. Chỉ 3 nét. Âm セン (sen) gần 'thiên'. Liên kết: 千円 (1000 yên). ⚠️ Âm biến đổi: 三千 = さんぜん (sanzen), 八千 = はっせん (hassen).","example":"**千**円でお願いします。 / sen en de onegai shimasu. (1000 yên nhé.)","examples":[{"ja":"千円でお願いします。","vi":"1000 yên nhé.","romaji":"sen en de onegai shimasu."},{"ja":"千円札","vi":"Tờ 1000 yên","romaji":"Senen satsu"},{"ja":"東京ディズニーランドは千葉県にあります。","vi":"Công viên Tokyo Disneyland ở tỉnh Chiba.","romaji":"toukyou dizuniirando wa chibaken ni arimasu."},{"ja":"財布に千円しかありません。","vi":"Trong ví chỉ có 1000 yên thôi.","romaji":"saifu ni senen shika arimasen."}]},{"key":"k:万","kind":"kanji","level":"N5","character":"万","meaning":"Vạn (10,000)","hanviet":"Vạn","onReadings":["マン","バン"],"kunReadings":["-"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"一万円","reading":"いちまんえん","meaning":"10"}],"lessonIds":[3,22],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 万 là dạng giản lược của 萬 — chỉ còn 3 nét: 一 (ngang) + 𠃌 (nét gấp). Hán-Việt: VẠN. Mẹo nhớ: Chỉ 3 nét mà biểu thị số 10,000 — con số 'vạn' lớn nhưng viết thật đơn giản 💰. Âm マン (man) như trong 一万 (ichiman - mười nghìn). Liên kết: 百 (trăm) → 千 (nghìn) → 万 (vạn) — hệ thống đếm lớn dần. ⚠️ Đừng nhầm với 方 (phương) — 方 có nét ngang rồi xuống, 万 có nét gấp khác hẳn.","example":"一**万**円かかりました。 / ichiman en kakarimashita. (Tốn 10,000 yên.)","examples":[{"ja":"一万円かかりました。","vi":"Tốn 10,000 yên.","romaji":"ichiman en kakarimashita."},{"ja":"一万円","vi":"10.000 yên","romaji":"Ichiman en"},{"ja":"3万円でパソコンが買えますか。","vi":"Với 3 vạn yên có thể mua máy tính không?","romaji":"3 manen de pasokon ga kaemasu ka."},{"ja":"五人で一万円です。","vi":"5 người hết 1 vạn yên.","romaji":"gonin de ichi manen desu."}]},{"key":"k:多","kind":"kanji","level":"N5","character":"多","meaning":"Nhiều","hanviet":"Đa","onReadings":["タ"],"kunReadings":["おお"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"多分","reading":"たぶん","meaning":"Có lẽ"},{"compound":"多い","reading":"おおい","meaning":"Nhiều","vocabKey":"v:多い"}],"lessonIds":[12],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 夕 (chiều tối) + 夕 (chiều tối) — hai lần. Hán-Việt: ĐA. Mẹo nhớ: Hai buổi chiều (夕夕) chồng lên — 'đa' là nhiều, lặp lại nhiều lần ✕️2. 6 nét. Âm おおい (ooi) = nhiều, タ (ta) gần 'đa'. Liên kết: 多分 (có lẽ = đa phần), 多い (nhiều). ⚠️ Cặp đối: 多 (đa/nhiều) ↔ 少 (thiểu/ít).","example":"人が**多**いですね。 / hito ga ooi desu ne. (Đông người nhỉ.)","examples":[{"ja":"人が多いですね。","vi":"Đông người nhỉ.","romaji":"hito ga ooi desu ne."},{"ja":"人が多い","vi":"Người nhiều","romaji":"hito ga ooi"},{"ja":"朝から来客が多い","vi":"Từ sáng có nhiều khách tới","romaji":"asa kara raikyaku ga ooi"},{"ja":"このスマホには便利な機能が多い","vi":"Điện thoại này có nhiều chức năng tiện lợi","romaji":"kono sumaho ni wa benri na kinou ga ooi"}]},{"key":"k:少","kind":"kanji","level":"N5","character":"少","meaning":"Ít, một chút","hanviet":"Thiểu","onReadings":["ショウ"],"kunReadings":["すく","すこ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"少年","reading":"しょうねん","meaning":"Thiếu niên"},{"compound":"少し","reading":"すこし","meaning":"Một chút","vocabKey":"v:少し"}],"lessonIds":[9,12,13,14],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 小 (nhỏ) + 丿 (nét phẩy). Hán-Việt: THIỂU. Mẹo nhớ: Nhỏ (小) bớt thêm chút nữa — 'thiểu' là ít, ít ỏi. 4 nét. Âm すこし (sukoshi) = chút, すくない (sukunai) = ít, ショウ (shou) gần 'thiểu'. Liên kết: 少年 (thiếu niên), 少し (một chút). ⚠️ 少し (sukoshi) dùng rất phổ biến — 'một chút'. Cặp: 多 ↔ 少.","example":"**少**し待ってください。 / sukoshi matte kudasai. (Xin đợi một chút.)","examples":[{"ja":"少し待ってください。","vi":"Xin đợi một chút.","romaji":"sukoshi matsute kudasai."},{"ja":"人が少ない","vi":"Ít người","romaji":"hito ga sukunai"},{"ja":"少し休む","vi":"Nghỉ một chút","romaji":"Sukoshi yasumu"},{"ja":"話す機会が少ない","vi":"Ít cơ hội nói","romaji":"Hanasu kikai ga sukunai"}]},{"key":"k:半","kind":"kanji","level":"N5","character":"半","meaning":"Nửa, phân nửa","hanviet":"Bán","onReadings":["ハン"],"kunReadings":["なか"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"半分","reading":"はんぶん","meaning":"Một nửa"},{"compound":"半年","reading":"はんとし","meaning":"Nửa năm","vocabKey":"v:半年"}],"lessonIds":[4,46],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 丷 (tám/tách) + ngang + dọc. Hán-Việt: BÁN. Mẹo nhớ: Nét dọc (丨) chia đôi phần trên — 'bán' là nửa, phân đôi ½. 5 nét. Âm なかば (nakaba) = nửa chừng, ハン (han) gần 'bán'. Liên kết: 半分 (một nửa), 半年 (nửa năm). ⚠️ Đừng nhầm 半 (bán/nửa) với 牛 (ngưu/bò) — tuy giống nhưng nét khác.","example":"ケーキを**半**分に切ってください。 / keeki wo hanbun ni kitte kudasai. (Hãy cắt bánh làm đôi.)","examples":[{"ja":"ケーキを半分に切ってください。","vi":"Hãy cắt bánh làm đôi.","romaji":"keeki o hanbun ni kitsute kudasai."},{"ja":"6時半に起きます。","vi":"Tôi dậy vào lúc 6 giờ rưỡi.","romaji":"6jihan ni okimasu."},{"ja":"子どもなら、半額です。","vi":"Nếu là trẻ em thì nửa giá.","romaji":"kodomo nara, hangaku desu."},{"ja":"半","vi":"rưỡi, nửa","romaji":"han"}]},{"key":"k:全","kind":"kanji","level":"N5","character":"全","meaning":"Tất cả, toàn bộ","hanviet":"Toàn","onReadings":["ゼン"],"kunReadings":["まった","すべ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"全部","reading":"ぜんぶ","meaning":"Tất cả","vocabKey":"v:全部"},{"compound":"全然","reading":"ぜんぜん","meaning":"Hoàn toàn","vocabKey":"v:全然"},{"compound":"安全","reading":"あんぜん","meaning":"An toàn"}],"lessonIds":[9,11,24,44],"topicTags":["counter"],"sectionId":4,"sectionName":"SỐ ĐẾM & LƯỢNG","mnemonic":"Bộ/thành phần: 入 (vào/nhập — biến thể 亼) + 王 (vua/ngọc). Hán-Việt: TOÀN. Mẹo nhớ: Vua (王) thu nạp (入) tất cả — 'toàn' bộ, đầy đủ, không thiếu gì 👑✅. 6 nét. Âm ゼン (zen) như trong 全部 (zenbu - tất cả), まったく (mattaku) = hoàn toàn. Liên kết: 全部 (toàn bộ), 全然 (hoàn toàn), 安全 (an toàn). ⚠️ Phần trên 亼 là biến thể của 入 (nhập), không phải 人 (nhân) — cách viết hơi khác.","example":"おなかがすいていたので、**全**部食べました。 / onaka ga suite ita node, zenbu tabemashita. (Vì đói nên tôi đã ăn hết.)","examples":[{"ja":"おなかがすいていたので、全部食べました。","vi":"Vì đói nên tôi đã ăn hết.","romaji":"onaka ga suite ita node, zenbu tabemashita."},{"ja":"この道は安全だ","vi":"Con đường này an toàn","romaji":"Kono michi wa anzen da"},{"ja":"全然わからない","vi":"Hoàn toàn không hiểu","romaji":"Zenzen wakaranai"},{"ja":"全部食べた","vi":"Ăn hết tất cả","romaji":"Zenbu tabeta"}]},{"key":"k:行","kind":"kanji","level":"N5","character":"行","meaning":"Đi, thực hiện","hanviet":"Hành","onReadings":["コウ","ギョウ"],"kunReadings":["い","おこな"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"旅行","reading":"りょこう","meaning":"Du lịch","vocabKey":"v:旅行"},{"compound":"銀行","reading":"ぎんこう","meaning":"Ngân hàng","vocabKey":"v:銀行"},{"compound":"行う","reading":"おこなう","meaning":"Tiến hành"}],"lessonIds":[1,4,5,9,11,17,24,26,33,35,37],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 彳 (bước chân trái) + 亍 (bước chân phải), hợp thành hình ngã tư đường. Mẹo nhớ: hai bên trái phải (彳亍) tạo thành đường đi — nơi người ta bước đi, thực hiện hành trình 🚶. Hán-Việt: Hành, như 'hành trình', 'lữ hành', 'ngân hàng'. Nhiều âm on: コウ (kou) cho đi/hàng (旅行), ギョウ (gyou) cho dòng/nghề (行事). Là bộ thủ quan trọng (ぎょうがまえ), xuất hiện trong 街 (nhai/phố), 術 (thuật).","example":"日本に**行**きたいです。 / nihon ni ikitai desu. (Tôi muốn đi Nhật.)","examples":[{"ja":"日本に行きたいです。","vi":"Tôi muốn đi Nhật.","romaji":"nippon ni ikitai desu."},{"ja":"学校に行く","vi":"Đi học","romaji":"gakkou ni iku"},{"ja":"ヨーロッパを旅行する","vi":"Du lịch châu Âu","romaji":"yooroppa o ryokou suru"},{"ja":"飛行機で行く","vi":"Đi bằng máy bay","romaji":"hikouki de iku"}]},{"key":"k:来","kind":"kanji","level":"N5","character":"来","meaning":"Đến","hanviet":"Lai","onReadings":["ライ"],"kunReadings":["く","き"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"来月","reading":"らいげつ","meaning":"Tháng sau","vocabKey":"v:来月"},{"compound":"来年","reading":"らいねん","meaning":"Năm sau","vocabKey":"v:来年"},{"compound":"将来","reading":"しょうらい","meaning":"Tương lai","vocabKey":"v:将来"}],"lessonIds":[5,17,24,28,46,50],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 来 là dạng giản thể của 來, nguồn gốc vẽ hình cây lúa mì chín trĩu bông 🌾. Mẹo nhớ: nét ngang trên là bông lúa, hai nét phẩy là hạt rũ xuống, nét dọc là thân, 木 ở dưới là gốc rễ — lúa mì 'đến' từ phương Tây, nghĩa gốc là lúa mì, sau mượn nghĩa 'đến'. Hán-Việt: Lai, như 'tương lai', 'ngoại lai', 'lai lịch'. ⚠️ Dễ nhầm với 未 (vị/chưa): 来 nét ngang trên ngắn hơn, 未 nét ngang trên dài hơn.","example":"友達が**来**たので、一緒に晩ご飯を作りました。 / tomodachi ga kita node, issho ni bangohan wo tsukurimashita. (Bạn đến nên chúng tôi nấu bữa tối cùng nhau.)","examples":[{"ja":"友達が来たので、一緒に晩ご飯を作りました。","vi":"Bạn đến nên chúng tôi nấu bữa tối cùng nhau.","romaji":"tomodachi ga kita node, issho ni bangohan wo tsukurimashita."},{"ja":"日本に来る","vi":"Đến Nhật","romaji":"Nippon ni kuru"},{"ja":"来週テストがある","vi":"Tuần sau có thi","romaji":"raishuu tesuto ga aru"},{"ja":"来月日本に行く","vi":"Tháng sau đi Nhật","romaji":"Raigetsu nippon ni iku"}]},{"key":"k:帰","kind":"kanji","level":"N5","character":"帰","meaning":"Về, trở về","hanviet":"Quy","onReadings":["キ"],"kunReadings":["かえ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"帰国","reading":"きこく","meaning":"Về nước"},{"compound":"帰り","reading":"かえり","meaning":"Lúc về","vocabKey":"v:帰り"}],"lessonIds":[5,12,20,31,46],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: giản thể của 歸. Phân tích: リ (biến thể của 刂/dao) + 帚 (chổi quét nhà — bao gồm 彐+冖+巾). Mẹo nhớ: cầm dao (リ) và chổi (帚) dọn dẹp nhà cửa — hành động đặc trưng khi trở về nhà 🏠. Hán-Việt: Quy, như 'quy hồi' (trở về), 'quy quốc' (帰国 — về nước), 'hồi quy'. Âm kun かえる (kaeru) thường dùng trong giao tiếp hàng ngày.","example":"仕事が終わったら、まっすぐ家に**帰**ります。 / shigoto ga owattara, massugu ie ni kaerimasu. (Sau khi hết giờ làm, tôi về thẳng nhà.)","examples":[{"ja":"仕事が終わったら、まっすぐ家に帰ります。","vi":"Sau khi hết giờ làm, tôi về thẳng nhà.","romaji":"shigoto ga owatsu tara, massugu ie ni kaerimasu."},{"ja":"家に帰る","vi":"Về nhà","romaji":"Ie ni kaeru"},{"ja":"来年帰国する","vi":"Năm sau về nước","romaji":"Rainen kikoku suru"},{"ja":"お帰りなさい。今日は早かったですね。","vi":"Chào mừng về nhà. Hôm nay về sớm nhỉ.","romaji":"o kaeri nasai. kyou wa hayakatsuta desu ne."}]},{"key":"k:食","kind":"kanji","level":"N5","character":"食","meaning":"Ăn","hanviet":"Thực","onReadings":["ショク"],"kunReadings":["た"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"食事","reading":"しょくじ","meaning":"Bữa ăn","vocabKey":"v:食事"},{"compound":"食堂","reading":"しょくどう","meaning":"Nhà ăn","vocabKey":"v:食堂"},{"compound":"食料品","reading":"しょくりょうひん","meaning":"Thực phẩm"}],"lessonIds":[3,6,8,13,44],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 亼 (nắp vung/mái che) + 良 (tốt lành, biến thể). Mẹo nhớ: phần trên 亼 là nắp vung, phần dưới gợi hình bát cơm đầy — mở vung ra thấy cơm ngon 🍚. Nguồn gốc tượng hình: bình gốm đựng thức ăn có nắp đậy. Hán-Việt: Thực, như 'thực phẩm', 'ẩm thực', 'thực đơn'. Là bộ thủ 飠(しょくへん) khi đứng bên trái: 飲 (ẩm/uống), 飯 (phạn/cơm), 館 (quán).","example":"ご飯を**食**べましょう。 / gohan wo tabemashou. (Ăn cơm nào.)","examples":[{"ja":"ご飯を食べましょう。","vi":"Ăn cơm nào.","romaji":"gohan wo tabemashou."},{"ja":"ご飯を食べる","vi":"Ăn cơm","romaji":"Gohan wo taberu"},{"ja":"友達と食事する","vi":"Ăn cơm với bạn","romaji":"Tomodachi to shokuji suru"},{"ja":"食事をする","vi":"Ăn cơm","romaji":"Shokuji wo suru"}]},{"key":"k:飲","kind":"kanji","level":"N5","character":"飲","meaning":"Uống","hanviet":"Ẩm","onReadings":["イン"],"kunReadings":["の"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"飲み物","reading":"のみもの","meaning":"Đồ uống","vocabKey":"v:飲み物"},{"compound":"飲料","reading":"いんりょう","meaning":"Nước giải khát"}],"lessonIds":[6,9,17,21,25,33],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 飠 (bộ thực — liên quan ăn uống) + 欠 (người há miệng). Mẹo nhớ: bên trái 飠 là đồ ăn uống, bên phải 欠 là người há miệng ra — há miệng (欠) để uống thức uống (飠) 🥤. Hán-Việt: Ẩm, như 'ẩm thực' (ăn uống), 'ẩm liệu' (đồ uống). So sánh: 食 (thực) chỉ ăn — ngậm miệng nhai; 飲 (ẩm) thêm 欠 (há miệng) → há miệng đổ nước vào → uống.","example":"お茶を**飲**みませんか。 / ocha wo nomimasen ka. (Uống trà không?)","examples":[{"ja":"お茶を飲みませんか。","vi":"Uống trà không?","romaji":"ocha wo nomimasen ka."},{"ja":"お茶を飲む","vi":"Uống trà","romaji":"O cha wo nomu"},{"ja":"飲み物を注文する","vi":"Gọi đồ uống","romaji":"nomimono o chuumon suru"},{"ja":"ジュースを飲みます。","vi":"Tôi uống nước hoa quả.","romaji":"juusu o nomimasu."}]},{"key":"k:見","kind":"kanji","level":"N5","character":"見","meaning":"Nhìn, xem","hanviet":"Kiến","onReadings":["ケン"],"kunReadings":["み","み"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"花見","reading":"はなみ","meaning":"Ngắm hoa"},{"compound":"意見","reading":"いけん","meaning":"Ý kiến","vocabKey":"v:意見"},{"compound":"見物","reading":"けんぶつ","meaning":"Tham quan"}],"lessonIds":[3,6,14,21,26,27,31,34,37,39,41,50],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 目 (mắt) + 儿 (chân người). Mẹo nhớ: con mắt (目) mọc trên đôi chân (儿) — đôi mắt biết đi, đi khắp nơi nhìn ngắm 👀. Hán-Việt: Kiến, như 'ý kiến', 'phát kiến', 'kiến thức'. Hai cách đọc: 見る (みる/miru) = chủ động nhìn; 見える (みえる/mieru) = nhìn thấy được (tự nhiên). Là bộ thủ (みる), xuất hiện trong 親 (thân), 覚 (giác/nhớ).","example":"夕食のあとで、家族とテレビを**見**ます。 / yuushoku no ato de, kazoku to terebi wo mimasu. (Sau bữa tối, tôi xem TV cùng gia đình.)","examples":[{"ja":"夕食のあとで、家族とテレビを見ます。","vi":"Sau bữa tối, tôi xem TV cùng gia đình.","romaji":"yuushoku no ato de, kazoku to terebi wo mimasu."},{"ja":"鍵が見つかる","vi":"Chìa khóa được tìm thấy","romaji":"Kagi ga mitsu karu"},{"ja":"富士山が見える","vi":"Nhìn thấy núi Phú Sĩ","romaji":"Fujisan ga mieru"},{"ja":"写真を見せる","vi":"Cho xem ảnh","romaji":"Shashin wo miseru"}]},{"key":"k:聞","kind":"kanji","level":"N5","character":"聞","meaning":"Nghe, hỏi","hanviet":"Văn","onReadings":["ブン","モン"],"kunReadings":["き","き"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"新聞","reading":"しんぶん","meaning":"Báo","vocabKey":"v:新聞"},{"compound":"聞こえる","reading":"きこえる","meaning":"Nghe thấy","vocabKey":"v:聞こえる"}],"lessonIds":[2,6,23,27],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 門 (cổng/cửa) + 耳 (tai). Mẹo nhớ: áp tai (耳) vào khe cửa (門) để nghe ngóng bên trong — lắng nghe lén qua cánh cổng 👂. Hán-Việt: Văn, như 'tân văn' (新聞 — tin tức/báo), 'văn danh' (nghe tiếng). Hai cách đọc: 聞く (きく/kiku) = chủ động nghe/hỏi; 聞こえる (きこえる/kikoeru) = nghe thấy (tự nhiên). So sánh với 問 (vấn/hỏi) = 門+口: dùng miệng hỏi.","example":"勉強する前に、好きな音楽を**聞**きます。 / benkyou suru mae ni, suki na ongaku wo kikimasu. (Trước khi học tôi nghe nhạc mình thích.)","examples":[{"ja":"勉強する前に、好きな音楽を聞きます。","vi":"Trước khi học tôi nghe nhạc mình thích.","romaji":"benkyou suru mae ni, suki na ongaku wo kikimasu."},{"ja":"音楽を聞く","vi":"Nghe nhạc","romaji":"Ongaku wo kiku"},{"ja":"音が聞こえる","vi":"Nghe thấy âm thanh","romaji":"Oto ga kiko eru"},{"ja":"聞き取りのテスト","vi":"Bài kiểm tra nghe hiểu","romaji":"Kiki tori no tesuto"}]},{"key":"k:読","kind":"kanji","level":"N5","character":"読","meaning":"Đọc","hanviet":"Độc","onReadings":["ドク","トク"],"kunReadings":["よ"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"読書","reading":"どくしょ","meaning":"Đọc sách"}],"lessonIds":[6,14],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 言 (lời nói/ngôn) + 売 (bán/mại — phần cho âm đọc). Mẹo nhớ: lời nói (言) được truyền bá (売 gợi ý lan truyền) thành văn bản → đọc 📖. Phần phải 売 gốc từ chữ cổ 𧶠, cho âm トク (toku). Hán-Việt: Độc, như 'độc giả' (người đọc), 'bái độc'. Bộ 言 là bộ thủ ngôn (ごんべん), cũng xuất hiện trong 話 (thoại), 語 (ngữ), 記 (ký).","example":"寝る前に、毎日本を三十分ぐらい**読**みます。 / neru mae ni, mainichi hon wo sanjuppun gurai yomimasu. (Trước khi ngủ, mỗi ngày tôi đọc sách khoảng 30 phút.)","examples":[{"ja":"寝る前に、毎日本を三十分ぐらい読みます。","vi":"Trước khi ngủ, mỗi ngày tôi đọc sách khoảng 30 phút.","romaji":"neru mae ni, mai nippon o san juufun gurai yomimasu."},{"ja":"本を読む","vi":"Đọc sách","romaji":"Hon wo yomu"},{"ja":"読解問題を解く","vi":"Giải bài đọc hiểu","romaji":"Dokkai mondai wo toku"},{"ja":"注意書きをよく読む","vi":"Đọc kỹ bảng cảnh báo","romaji":"chuuigaki o yoku yomu"}]},{"key":"k:書","kind":"kanji","level":"N5","character":"書","meaning":"Viết, sách","hanviet":"Thư","onReadings":["ショ"],"kunReadings":["か"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"辞書","reading":"じしょ","meaning":"Từ điển","vocabKey":"v:辞書"},{"compound":"図書館","reading":"としょかん","meaning":"Thư viện","vocabKey":"v:図書館"},{"compound":"書類","reading":"しょるい","meaning":"Tài liệu","vocabKey":"v:書類"}],"lessonIds":[2,4,6,29,30,34,45],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 聿 (cầm bút viết — 肀 biến thể) + 曰 (nói/viết). Mẹo nhớ: bên trên là tay cầm bút (聿), bên dưới là lời đã nói (曰) — ghi chép lời nói thành văn bản → viết, sách ✍️. Hán-Việt: Thư, như 'thư viện' (図書館), 'thư pháp' (nét chữ đẹp), 'bí thư'. Âm on ショ (sho) trong 辞書 (jisho — từ điển), 教科書 (kyoukasho — sách giáo khoa).","example":"手紙を**書**きました。 / tegami wo kakimashita. (Tôi đã viết thư.)","examples":[{"ja":"手紙を書きました。","vi":"Tôi đã viết thư.","romaji":"tegami wo kakimashita."},{"ja":"手紙を書く","vi":"Viết thư","romaji":"Tegami wo kaku"},{"ja":"辞書で調べる","vi":"Tra từ điển","romaji":"Jisho de shiraberu"},{"ja":"説明書を見ながら組み立てる","vi":"Lắp ráp theo sách hướng dẫn","romaji":"setsumeisho o mi nagara kumitateru"}]},{"key":"k:話","kind":"kanji","level":"N5","character":"話","meaning":"Nói chuyện, câu chuyện","hanviet":"Thoại","onReadings":["ワ"],"kunReadings":["はな","はなし"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"電話","reading":"でんわ","meaning":"Điện thoại","vocabKey":"v:電話"},{"compound":"会話","reading":"かいわ","meaning":"Hội thoại","vocabKey":"v:会話"}],"lessonIds":[3,7,14,20,21,25,28,41,48],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 言 (lời nói/ngôn) + 舌 (cái lưỡi — 千+口). Mẹo nhớ: dùng lời nói (言) phát ra bằng cái lưỡi (舌) → nói chuyện, trao đổi 🗣️. Lưỡi (舌) chuyển động trong miệng tạo ra lời (言) → câu chuyện. Hán-Việt: Thoại, như 'hội thoại', 'điện thoại' (電話), 'đàm thoại'. Liên quan: 語 (ngữ/ngôn ngữ) = 言+吾, 談 (đàm/nói chuyện) = 言+炎.","example":"日本語を**話**します。 / nihongo wo hanashimasu. (Tôi nói tiếng Nhật.)","examples":[{"ja":"日本語を話します。","vi":"Tôi nói tiếng Nhật.","romaji":"nihongo wo hanashimasu."},{"ja":"日本語で話す","vi":"Nói bằng tiếng Nhật","romaji":"Nihongo de hanasu"},{"ja":"動物の世話をする","vi":"Chăm sóc động vật","romaji":"doubutsu no sewa o suru"},{"ja":"友達に電話する","vi":"Gọi điện cho bạn","romaji":"Tomodachi ni denwa suru"}]},{"key":"k:買","kind":"kanji","level":"N5","character":"買","meaning":"Mua","hanviet":"Mãi","onReadings":["バイ"],"kunReadings":["か"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"買い物","reading":"かいもの","meaning":"Mua sắm","vocabKey":"v:買い物"},{"compound":"売買","reading":"ばいばい","meaning":"Mua bán"}],"lessonIds":[6,13],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 罒 (lưới — biến thể của 网) + 貝 (vỏ sò/tiền). Mẹo nhớ: thả lưới (罒) gom tiền (貝) về — giăng lưới bắt hàng bằng tiền → mua 🛒. Xưa dùng vỏ sò (貝) làm tiền tệ. Hán-Việt: Mãi, như 'mãi lực' (sức mua), 'mại mãi' (mua bán). ⚠️ Dễ nhầm với 売 (mại/bán): 買 có 貝 (tiền) ở dưới → bỏ tiền ra → mua; 売 không có 貝 → bán.","example":"駅前の本屋で、日本語の本を**買**いました。 / ekimae no honya de, nihongo no hon wo kaimashita. (Tôi đã mua sách tiếng Nhật ở hiệu sách trước ga.)","examples":[{"ja":"駅前の本屋で、日本語の本を買いました。","vi":"Tôi đã mua sách tiếng Nhật ở hiệu sách trước ga.","romaji":"ekimae no honya de, nihongo no hon wo kaimashita."},{"ja":"本を買う","vi":"Mua sách","romaji":"Hon wo kau"},{"ja":"買い物に行く","vi":"Đi mua sắm","romaji":"Kaimono ni iku"},{"ja":"鉛筆と消しゴムを買いました。","vi":"Tôi đã mua bút chì và tẩy.","romaji":"enpitsu to keshigomu o kaimashita."}]},{"key":"k:売","kind":"kanji","level":"N5","character":"売","meaning":"Bán","hanviet":"Mại","onReadings":["バイ"],"kunReadings":["う"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"売り場","reading":"うりば","meaning":"Quầy bán","vocabKey":"v:売り場"},{"compound":"販売","reading":"はんばい","meaning":"Bán hàng"}],"lessonIds":[3,15,21,25,26,27,28,32,34,35,39,40,47],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 士 + 冗 (thành tố cổ). Mẹo nhớ: liên tưởng người bán đứng quầy trao hàng, nên nhớ nghĩa 'bán'.","example":"この店は花を**売**っています。 / kono mise wa hana wo utte imasu. (Quán này bán hoa.)","examples":[{"ja":"この店は花を売っています。","vi":"Quán này bán hoa.","romaji":"kono mise wa hana o utsute imasu."},{"ja":"本を売る","vi":"Bán sách","romaji":"Hon wo uru"},{"ja":"この本はよく売れる","vi":"Sách này bán chạy","romaji":"Kono hon wa yoku ureru"},{"ja":"食品の売り場は地下にあります","vi":"Quầy thực phẩm ở tầng hầm","romaji":"Shokuhin no uriba wa chika ni arimasu"}]},{"key":"k:作","kind":"kanji","level":"N5","character":"作","meaning":"Làm, tạo ra","hanviet":"Tác","onReadings":["サク","サ"],"kunReadings":["つく"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"作文","reading":"さくぶん","meaning":"Bài luận","vocabKey":"v:作文"},{"compound":"作品","reading":"さくひん","meaning":"Tác phẩm"}],"lessonIds":[15,31,39],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 亻(người/nhân đứng) + 乍 (bỗng nhiên/tạo). Mẹo nhớ: người (亻) bắt tay vào việc (乍) → làm, tạo ra 🔨. Phần 乍 gợi hình dáng dùi đục tác động, người (亻) cầm dụng cụ sáng tạo. Hán-Việt: Tác, như 'tác phẩm' (作品), 'sáng tác', 'tác giả'. Âm on サク (saku) trong 作文 (sakubun — bài luận), サ (sa) trong 作業 (sagyou — công việc).","example":"週末は家でカレーを**作**ります。 / shuumatsu wa ie de karee wo tsukurimasu. (Cuối tuần tôi nấu cà ri ở nhà.)","examples":[{"ja":"週末は家でカレーを作ります。","vi":"Cuối tuần tôi nấu cà ri ở nhà.","romaji":"shuumatsu wa ie de karee wo tsukurimasu."},{"ja":"料理を作る","vi":"Nấu ăn","romaji":"ryouri o tsukuru"},{"ja":"作物がよく育った","vi":"Hoa màu phát triển tốt","romaji":"sakumotsu ga yoku sodatsuta"},{"ja":"IMCは コンピューターソフトを 作って います。","vi":"Công ty IMC sản xuất phần mềm máy tính.","romaji":"imc wa konpyuutaasofuto o tsukutsute imasu."}]},{"key":"k:使","kind":"kanji","level":"N5","character":"使","meaning":"Sử dụng","hanviet":"Sử","onReadings":["シ"],"kunReadings":["つか"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"大使館","reading":"たいしかん","meaning":"Đại sứ quán","vocabKey":"v:大使館"},{"compound":"使い方","reading":"つかいかた","meaning":"Cách sử dụng"}],"lessonIds":[25,33,36],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 亻(người) + 吏 (quan lại — viên chức). Mẹo nhớ: viên quan (吏) sai người (亻) đi làm nhiệm vụ → sử dụng, sai khiến 📋. Quan (吏) dùng quyền điều khiển → sử dụng. Hán-Việt: Sử/Sứ, như 'sử dụng', 'đại sứ' (大使), 'thiên sứ'. Âm シ (shi) trong 大使館 (taishikan — đại sứ quán). Liên quan: 史 (sử/lịch sử), 事 (sự/việc).","example":"パソコンを**使**います。 / pasokon wo tsukaimasu. (Tôi sử dụng máy tính.)","examples":[{"ja":"パソコンを使います。","vi":"Tôi sử dụng máy tính.","romaji":"pasokon wo tsukaimasu."},{"ja":"パソコンを使う","vi":"Sử dụng máy tính","romaji":"Pasokon wo tsukau"},{"ja":"会議室の使用料を払う","vi":"Trả phí sử dụng phòng họp","romaji":"kaigishitsu no shiyouryou o harau"},{"ja":"使用方法を説明する","vi":"Giải thích cách sử dụng","romaji":"shiyou houhou o setsumei suru"}]},{"key":"k:持","kind":"kanji","level":"N5","character":"持","meaning":"Cầm, giữ, có","hanviet":"Trì","onReadings":["ジ"],"kunReadings":["も"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"気持ち","reading":"きもち","meaning":"Tâm trạng","vocabKey":"v:気持ち"},{"compound":"持ち物","reading":"もちもの","meaning":"Đồ mang theo"}],"lessonIds":[14,17,33,36,38],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 扌(tay/thủ) + 寺 (chùa — 土 đất + 寸 tấc). Mẹo nhớ: tay (扌) giữ chặt đồ vật quý trong chùa (寺) → cầm, giữ ✋. Phần 寺 cho âm ジ (ji). Hán-Việt: Trì, như 'duy trì', 'kiên trì', 'bảo trì'. ⚠️ Cực dễ nhầm với 待 (đãi/đợi): 持 có 扌(tay) → dùng tay cầm giữ; 待 có 彳(bước chân) → đứng đợi. Nhớ: tay (扌) = cầm (持), chân (彳) = đợi (待).","example":"荷物が重そうだったので、私が**持**ちました。 / nimotsu ga omosou datta node, watashi ga mochimashita. (Vì hành lý có vẻ nặng nên tôi đã xách giúp.)","examples":[{"ja":"荷物が重そうだったので、私が持ちました。","vi":"Vì hành lý có vẻ nặng nên tôi đã xách giúp.","romaji":"nimotsu ga omosou datsuta node, watashi ga mochimashita."},{"ja":"荷物を持つ","vi":"Mang hành lý","romaji":"Nimotsu wo motsu"},{"ja":"風が気持ちいい","vi":"Gió dễ chịu","romaji":"Kaze ga kimochii i"},{"ja":"気持ちがいい","vi":"Cảm giác tốt","romaji":"Kimochi gaii"}]},{"key":"k:待","kind":"kanji","level":"N5","character":"待","meaning":"Đợi","hanviet":"Đãi","onReadings":["タイ"],"kunReadings":["ま"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"招待","reading":"しょうたい","meaning":"Mời"},{"compound":"期待","reading":"きたい","meaning":"Kỳ vọng"}],"lessonIds":[13,14,37,46],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 彳(bước chân/xích) + 寺 (chùa — 土+寸). Mẹo nhớ: dừng bước chân (彳) trước cổng chùa (寺), kiên nhẫn đợi ⏳. Phần 寺 cho âm タイ (tai). Hán-Việt: Đãi, như 'kỳ đãi' (期待 — kỳ vọng), 'chiêu đãi' (招待 — mời khách), 'đối đãi'. ⚠️ Cực dễ nhầm với 持 (trì/cầm): 待 có 彳(chân) → đứng đợi; 持 có 扌(tay) → cầm giữ. Nhớ: chân (彳) = đợi (待), tay (扌) = cầm (持).","example":"ここで**待**ってください。 / koko de matte kudasai. (Xin đợi ở đây.)","examples":[{"ja":"ここで待ってください。","vi":"Xin đợi ở đây.","romaji":"koko de matsute kudasai."},{"ja":"友達を待つ","vi":"Đợi bạn","romaji":"Tomodachi wo matsu"},{"ja":"結婚式に招待された","vi":"Được mời dự đám cưới","romaji":"kekkonshiki ni shoutai sa reta"},{"ja":"招待状を送る","vi":"Gửi thiệp mời","romaji":"shoutaijou o okuru"}]},{"key":"k:立","kind":"kanji","level":"N5","character":"立","meaning":"Đứng, dựng lên","hanviet":"Lập","onReadings":["リツ"],"kunReadings":["た","た"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"立派","reading":"りっぱ","meaning":"Tuyệt vời"},{"compound":"役に立つ","reading":"やくにたつ","meaning":"Có ích","vocabKey":"v:役に立つ"}],"lessonIds":[21,33,34],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 立 là chữ tượng hình, vẽ người đứng trên mặt đất. Mẹo nhớ: nét ngang trên (一) là đầu, hai chấm (丷) là hai tay dang ra, nét dọc (丨) là thân mình, nét ngang dưới (一) là mặt đất — người đứng thẳng hiên ngang 🧍. Hán-Việt: Lập, như 'thành lập', 'độc lập', 'lập trường'. Là bộ thủ (たつ), xuất hiện trong 音 (âm), 章 (chương), 竜 (long/rồng).","example":"ここに**立**ってください。 / koko ni tatte kudasai. (Hãy đứng ở đây.)","examples":[{"ja":"ここに立ってください。","vi":"Hãy đứng ở đây.","romaji":"koko ni tatsute kudasai."},{"ja":"この本は役に立つ","vi":"Cuốn sách này có ích","romaji":"Kono hon wa yaku ni tatsu"},{"ja":"ここに立ってください","vi":"Hãy đứng ở đây","romaji":"Kokoni tatsutekudasai"},{"ja":"計画を立てる","vi":"Lập kế hoạch","romaji":"Keikaku wo tateru"}]},{"key":"k:座","kind":"kanji","level":"N4","character":"座","meaning":"Ngồi, chỗ ngồi","hanviet":"Tọa","onReadings":["ザ"],"kunReadings":["すわ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"座席","reading":"ざせき","meaning":"Chỗ ngồi"},{"compound":"星座","reading":"せいざ","meaning":"Chòm sao"}],"lessonIds":[32],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 广 (mái nhà/nghiễm) + 坐 (ngồi — hai người 人人 trên đất 土). Mẹo nhớ: dưới mái nhà (广), hai người ngồi xuống đất (坐) → chỗ ngồi, vị trí 💺. Chữ 坐 bên trong gợi hình hai người đối diện ngồi xổm trên đất. Hán-Việt: Tọa, như 'tọa lạc', 'tọa độ', 'tinh tọa' (星座 — chòm sao). Âm on ザ (za) trong 座席 (zaseki — ghế ngồi).","example":"ここに**座**ってください。 / koko ni suwatte kudasai. (Hãy ngồi ở đây.)","examples":[{"ja":"ここに座ってください。","vi":"Hãy ngồi ở đây.","romaji":"koko ni suwatsute kudasai."},{"ja":"椅子に座る","vi":"Ngồi ghế","romaji":"Isu ni suwaru"},{"ja":"よく見えるように、前の席に座りました。","vi":"Để nhìn rõ hơn, tôi đã ngồi ghế phía trước.","romaji":"yoku mieru you ni, mae no seki ni suwarimashita."},{"ja":"医者は患者を椅子に座らせました。","vi":"Bác sĩ đã cho bệnh nhân ngồi vào ghế.","romaji":"isha wa kanja o isu ni suwara semashita."}]},{"key":"k:走","kind":"kanji","level":"N4","character":"走","meaning":"Chạy","hanviet":"Tẩu","onReadings":["ソウ"],"kunReadings":["はし"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"走る","reading":"はしる","meaning":"Chạy","vocabKey":"v:走る"}],"lessonIds":[27],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 土 (đất) + 㐅 (giao nhau) + 龰 (biến thể bàn chân). Mẹo nhớ: phần trên gợi hình đầu và thân, phần dưới là đôi chân đang lao nhanh trên mặt đất — người vung tay chạy 🏃. Nét cuối phẩy mạnh thể hiện tốc độ. Hán-Việt: Tẩu, như 'tẩu thoát' (chạy thoát), 'bôn tẩu' (chạy vạy). Là bộ thủ (そうにょう), xuất hiện trong 起 (khởi), 越 (việt/vượt), 超 (siêu). So với 歩 (bộ/đi bộ): 走 nhanh hơn.","example":"健康のために、毎朝公園で**走**ります。 / kenkou no tame ni, maiasa kouen de hashirimasu. (Vì sức khỏe, mỗi sáng tôi chạy trong công viên.)","examples":[{"ja":"健康のために、毎朝公園で走ります。","vi":"Vì sức khỏe, mỗi sáng tôi chạy trong công viên.","romaji":"kenkou no tame ni, maiasa kouen de hashirimasu."},{"ja":"公園を走る","vi":"Chạy trong công viên","romaji":"kouen o hashiru"},{"ja":"ご馳走様でした。とてもおいしかったです。","vi":"Cảm ơn vì bữa ăn, món ăn rất ngon.","romaji":"gochisousama deshita. totemo oishikatsuta desu."},{"ja":"走りながら音楽を聞くのが好きです。","vi":"Tôi thích vừa chạy bộ vừa nghe nhạc.","romaji":"hashiri nagara ongaku o kiku no ga suki desu."}]},{"key":"k:歩","kind":"kanji","level":"N5","character":"歩","meaning":"Đi bộ","hanviet":"Bộ","onReadings":["ホ"],"kunReadings":["ある"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"散歩","reading":"さんぽ","meaning":"Đi dạo","vocabKey":"v:散歩"},{"compound":"歩道","reading":"ほどう","meaning":"Vỉa hè","vocabKey":"v:歩道"}],"lessonIds":[5,12,13,23,32],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 止 (bàn chân trái/dừng) + 少 (biến thể bàn chân phải). Gốc từ 步. Mẹo nhớ: chân trái (止) bước rồi chân phải (少 biến thể) bước theo — hai bàn chân luân phiên từng bước → đi bộ 🚶. Hán-Việt: Bộ, như 'tản bộ' (散歩 — đi dạo), 'bộ hành', 'tiến bộ'. So với 走 (tẩu/chạy): 歩 chậm rãi từng bước, 走 lao nhanh. Âm on ホ (ho) trong 歩道 (hodou — vỉa hè).","example":"天気がいい日は、駅まで**歩**きます。 / tenki ga ii hi wa, eki made arukimasu. (Những ngày thời tiết đẹp tôi đi bộ tới ga.)","examples":[{"ja":"天気がいい日は、駅まで歩きます。","vi":"Những ngày thời tiết đẹp tôi đi bộ tới ga.","romaji":"tenki ga ii hi wa, eki made arukimasu."},{"ja":"学校まで歩く","vi":"Đi bộ đến trường","romaji":"gakkou made aruku"},{"ja":"公園を散歩する","vi":"Đi dạo trong công viên","romaji":"kouen o sanpo suru"},{"ja":"横断歩道を渡る","vi":"Băng qua vạch qua đường","romaji":"oudan hodou o wataru"}]},{"key":"k:止","kind":"kanji","level":"N5","character":"止","meaning":"Dừng","hanviet":"Chỉ","onReadings":["シ"],"kunReadings":["と","と"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"中止","reading":"ちゅうし","meaning":"Hủy","vocabKey":"v:中止"},{"compound":"禁止","reading":"きんし","meaning":"Cấm"}],"lessonIds":[14,29,33,45],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 止 là chữ tượng hình, vẽ hình bàn chân/dấu chân trên mặt đất. Mẹo nhớ: nét dọc là cẳng chân, ba nét ngang là ngón chân — bàn chân đặt xuống đất, không nhúc nhích → dừng lại 🛑. Hán-Việt: Chỉ, như 'cấm chỉ' (禁止 — cấm), 'trung chỉ' (中止 — ngưng giữa chừng), 'phòng chỉ'. Là bộ thủ rất quan trọng (とめる), xuất hiện trong 歩 (bộ/đi), 正 (chính/đúng), 歳 (tuế/tuổi), 武 (vũ/võ).","example":"車を**止**めてください。 / kuruma wo tomete kudasai. (Hãy dừng xe.)","examples":[{"ja":"車を止めてください。","vi":"Hãy dừng xe.","romaji":"kuruma wo tomete kudasai."},{"ja":"車が止まる","vi":"Xe dừng","romaji":"Kuruma ga tomaru"},{"ja":"車を止める","vi":"Dừng xe","romaji":"Kuruma wo tomeru"},{"ja":"試合を中止する","vi":"Hủy trận đấu","romaji":"shiai o chuushi suru"}]},{"key":"k:送","kind":"kanji","level":"N5","character":"送","meaning":"Gửi","hanviet":"Tống","onReadings":["ソウ"],"kunReadings":["おく"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"放送","reading":"ほうそう","meaning":"Phát sóng"},{"compound":"送り物","reading":"おくりもの","meaning":"Quà tặng"}],"lessonIds":[1,7,20,24,26,33,49,50],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 辶 (chuyển động/đi/sước) + 关 (phần trong — 丷+天 biến thể). Mẹo nhớ: hành động di chuyển (辶) đồ vật đi xa → gửi, tiễn đưa 📦. Phần trong gợi ý gói đồ, phần ngoài 辶 là chuyển đi. Hán-Việt: Tống, như 'phát tống' (gửi đi), 'hộ tống' (đi kèm bảo vệ), 'phóng tống' (放送 — phát sóng). Bộ 辶 (しんにょう) là bộ chuyển động, cũng có trong 近, 遠, 達.","example":"手紙を**送**りました。 / tegami wo okurimashita. (Tôi đã gửi thư.)","examples":[{"ja":"手紙を送りました。","vi":"Tôi đã gửi thư.","romaji":"tegami wo okurimashita."},{"ja":"手紙を送る","vi":"Gửi thư","romaji":"Tegami wo okuru"},{"ja":"送料はいくらですか","vi":"Phí vận chuyển là bao nhiêu?","romaji":"souryou wa ikura desu ka"},{"ja":"招待状を送る","vi":"Gửi thiệp mời","romaji":"shoutaijou o okuru"}]},{"key":"k:届","kind":"kanji","level":"N4","character":"届","meaning":"Đến nơi, giao hàng","hanviet":"Giới","onReadings":["-"],"kunReadings":["とど","とど"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"届ける","reading":"とどける","meaning":"Giao","vocabKey":"v:届ける"},{"compound":"届く","reading":"とどく","meaning":"Tới","vocabKey":"v:届く"}],"lessonIds":[46,48],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 尸 (thân người/thi) + 由 (do/lý do — hình ruộng có lối đi). Mẹo nhớ: người (尸) mang đồ theo con đường (由) giao tận nơi — hàng hóa đi qua đường đi rõ ràng để 'đến nơi' 📬. Hán-Việt: Giới (ít dùng trong tiếng Việt hiện đại). Hai dạng: 届く (とどく/todoku) = hàng tới (tự động); 届ける (とどける/todokeru) = giao/nộp (tha động). Không có âm on thông dụng.","example":"荷物が**届**きました。 / nimotsu ga todokimashita. (Hàng đã đến.)","examples":[{"ja":"荷物が届きました。","vi":"Hàng đã đến.","romaji":"nimotsu ga todokimashita."},{"ja":"荷物が届く","vi":"Hàng đến","romaji":"Nimotsu ga todoku"},{"ja":"届けてください","vi":"Xin hãy giao hàng","romaji":"Todoketekudasai"},{"ja":"届けを出す","vi":"Nộp đơn","romaji":"Todoke wo dasu"}]},{"key":"k:開","kind":"kanji","level":"N5","character":"開","meaning":"Mở","hanviet":"Khai","onReadings":["カイ"],"kunReadings":["あ","あ","ひら"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"開発","reading":"かいはつ","meaning":"Phát triển"},{"compound":"公開","reading":"こうかい","meaning":"Công khai"}],"lessonIds":[8,14,27,29,43,44,49],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 門 (cổng/cửa) + 开 (hai tay đẩy then cửa, biến thể). Mẹo nhớ: hai tay (开) đẩy cánh cổng (門) mở toang ra → mở 🚪. Hình ảnh sống động: then cài (一) được hai tay đẩy lên → cửa bật mở. Hán-Việt: Khai, như 'khai mạc', 'khai phá', 'công khai', 'khai giảng'. Đối lập hoàn toàn với 閉 (bế/đóng): 開 mở ra, 閉 đóng lại.","example":"窓を**開**けてください。 / mado wo akete kudasai. (Hãy mở cửa sổ.)","examples":[{"ja":"窓を開けてください。","vi":"Hãy mở cửa sổ.","romaji":"mado wo akete kudasai."},{"ja":"ドアが開く","vi":"Cửa mở ra","romaji":"Doa ga hiraku"},{"ja":"窓を開ける","vi":"Mở cửa sổ","romaji":"Mado wo akeru"},{"ja":"ドアが開きました。 母がドアを開けました。","vi":"Cửa đã mở ra. Mẹ đã mở cửa.","romaji":"doa ga hirakimashita. haha ga doa o akemashita."}]},{"key":"k:閉","kind":"kanji","level":"N5","character":"閉","meaning":"Đóng","hanviet":"Bế","onReadings":["ヘイ"],"kunReadings":["し","し","と"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"閉店","reading":"へいてん","meaning":"Đóng cửa tiệm"}],"lessonIds":[14,29,31],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 門 (cổng/cửa) + 才 (tài/cây gỗ chắn ngang). Mẹo nhớ: cài thanh gỗ (才) ngang qua cánh cổng (門) → đóng chặt, khóa lại 🔒. Thanh chắn (才) giữ cho cửa không mở được. Hán-Việt: Bế, như 'bế mạc' (閉幕 — kết thúc), 'bế quan tỏa cảng', 'phế bế'. Đối lập hoàn toàn với 開 (khai/mở): 閉 đóng lại, 開 mở ra. Âm on ヘイ (hei) trong 閉店 (heiten — đóng cửa tiệm).","example":"ドアを**閉**めてください。 / doa wo shimete kudasai. (Hãy đóng cửa.)","examples":[{"ja":"ドアを閉めてください。","vi":"Hãy đóng cửa.","romaji":"doa wo shimete kudasai."},{"ja":"ドアを閉める","vi":"Đóng cửa","romaji":"Doa wo shimeru"},{"ja":"目を閉じる","vi":"Nhắm mắt","romaji":"Me wo tojiru"},{"ja":"店は六時に閉まります。 店員が窓を閉めました。","vi":"Cửa hàng đóng lúc sáu giờ. Nhân viên đã đóng cửa sổ.","romaji":"Mise wa rokuji ni shimarimasu. Tenin ga mado wo shimemashita."}]},{"key":"k:入","kind":"kanji","level":"N5","character":"入","meaning":"Vào","hanviet":"Nhập","onReadings":["ニュウ"],"kunReadings":["い","い","はい"],"strokeCount":2,"radicals":[],"components":[],"compounds":[{"compound":"入口","reading":"いりぐち","meaning":"Lối vào","vocabKey":"v:入口"},{"compound":"入学","reading":"にゅうがく","meaning":"Nhập học","vocabKey":"v:入学"}],"lessonIds":[13,16,17,22,31,33,35,37,38,46],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 入 là chữ tượng hình, vẽ hình mũi tên/nêm chỉ vào trong. Mẹo nhớ: hai nét xiên hội tụ vào bên trong, như mũi tên chỉ hướng đi vào → vào ➡️. Nét trái ngắn, nét phải dài, hội tụ ở đỉnh. Hán-Việt: Nhập, như 'nhập học' (入学), 'nhập khẩu', 'xâm nhập'. ⚠️ Cực dễ nhầm với 人 (nhân/người): 入 nét trái ngắn hơn phải → vào; 人 nét trái dài hơn phải → người. Đối lập với 出 (xuất/ra).","example":"部屋に**入**ってください。 / heya ni haitte kudasai. (Hãy vào phòng.)","examples":[{"ja":"部屋に入ってください。","vi":"Hãy vào phòng.","romaji":"heya ni haitsute kudasai."},{"ja":"部屋に入る","vi":"Vào phòng","romaji":"Heya ni hairu"},{"ja":"砂糖を入れる","vi":"Cho đường vào","romaji":"satou o ireru"},{"ja":"大学に入学する","vi":"Nhập học đại học","romaji":"daigaku ni nyuugaku suru"}]},{"key":"k:出","kind":"kanji","level":"N5","character":"出","meaning":"Ra, xuất","hanviet":"Xuất","onReadings":["シュツ"],"kunReadings":["で","だ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"出口","reading":"でぐち","meaning":"Lối ra","vocabKey":"v:出口"},{"compound":"出発","reading":"しゅっぱつ","meaning":"Xuất phát","vocabKey":"v:出発"},{"compound":"出席","reading":"しゅっせき","meaning":"Tham dự"}],"lessonIds":[11,13,15,16,17,22,23,26,30,32,33,37,38,40,46,49],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 屮 (mầm nhú lên) chồng hai lớp liên tiếp. Mẹo nhớ: cây mầm nảy từ mặt đất nhô lên — nhú ra, xuất hiện 🌱. Hai lớp chồng nhau thể hiện sự bùng phát mạnh mẽ ra ngoài. Hán-Việt: Xuất, như 'xuất phát' (出発), 'xuất khẩu', 'sản xuất'. Đối lập với 入 (nhập/vào): 出 hướng ra ngoài, 入 hướng vào trong. Hai cách đọc: 出る (でる/deru) = ra; 出す (だす/dasu) = đưa ra.","example":"毎朝七時に家を**出**て、会社に向かいます。 / maiasa shichiji ni ie wo dete, kaisha ni mukaimasu. (Mỗi sáng 7 giờ tôi ra khỏi nhà và đi đến công ty.)","examples":[{"ja":"毎朝七時に家を出て、会社に向かいます。","vi":"Mỗi sáng 7 giờ tôi ra khỏi nhà và đi đến công ty.","romaji":"maiasa nanaji ni ie o dete, kaisha ni mukaimasu."},{"ja":"昔のことを思い出す","vi":"Nhớ lại chuyện xưa","romaji":"Mukashi nokoto wo omoidasu"},{"ja":"レポートを出す","vi":"Nộp báo cáo","romaji":"repooto o dasu"},{"ja":"家を出る","vi":"Rời nhà","romaji":"Ie wo deru"}]},{"key":"k:動","kind":"kanji","level":"N5","character":"動","meaning":"Chuyển động","hanviet":"Động","onReadings":["ドウ"],"kunReadings":["うご"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"運動","reading":"うんどう","meaning":"Vận động","vocabKey":"v:運動"},{"compound":"動物","reading":"どうぶつ","meaning":"Động vật","vocabKey":"v:動物"},{"compound":"自動","reading":"じどう","meaning":"Tự động"}],"lessonIds":[3,16,18,23,26,27,31,32,36],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 重 (nặng/trọng) + 力 (lực/sức mạnh). Mẹo nhớ: dùng sức (力) đẩy vật nặng (重) cho nó nhúc nhích → chuyển động 💪. Muốn thứ nặng di chuyển thì cần lực! Hán-Việt: Động, như 'vận động' (運動), 'động vật' (動物), 'tự động' (自動), 'hoạt động'. Liên quan: 働 (động/làm việc) = 亻+動 — người chuyển động = lao động.","example":"**動**かないでください。 / ugokanaide kudasai. (Xin đừng cử động.)","examples":[{"ja":"動かないでください。","vi":"Xin đừng cử động.","romaji":"ugokanaide kudasai."},{"ja":"車が動く","vi":"Xe chuyển động","romaji":"Kuruma ga ugoku"},{"ja":"机を動かす","vi":"Di chuyển bàn","romaji":"Tsukue wo ugoka su"},{"ja":"毎朝運動する","vi":"Tập thể dục mỗi sáng","romaji":"maiasa undou suru"}]},{"key":"k:働","kind":"kanji","level":"N5","character":"働","meaning":"Làm việc","hanviet":"Động","onReadings":["ドウ"],"kunReadings":["はたら"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"働く","reading":"はたらく","meaning":"Làm việc","vocabKey":"v:働く"}],"lessonIds":[4,32],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 亻(người/nhân) + 動 (chuyển động — 重+力). Mẹo nhớ: người (亻) chuyển động (動) không ngừng → lao động, làm việc 👷. ⚠️ Đặc biệt: đây là quốc tự (国字/kokuji) — chữ do Nhật tự sáng tạo, không tồn tại trong tiếng Trung! Hán-Việt: Động (mượn từ 動). Chỉ có 1 âm kun: はたらく (hataraku). So với 動: 動 = chuyển động bất kỳ; 働 = con người làm việc cụ thể.","example":"毎日**働**いています。 / mainichi hataraite imasu. (Tôi làm việc mỗi ngày.)","examples":[{"ja":"毎日働いています。","vi":"Tôi làm việc mỗi ngày.","romaji":"mainichi hataraite imasu."},{"ja":"会社で働く","vi":"Làm việc ở công ty","romaji":"Kaisha de hataraku"},{"ja":"共働きの夫婦","vi":"Vợ chồng cùng đi làm","romaji":"tomobataraki no fuufu"},{"ja":"放送局で働きたい","vi":"Muốn làm việc ở đài truyền hình","romaji":"housoukyoku de hatarakitai"}]},{"key":"k:洗","kind":"kanji","level":"N5","character":"洗","meaning":"Rửa","hanviet":"Tẩy","onReadings":["セン"],"kunReadings":["あら"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"洗濯","reading":"せんたく","meaning":"Giặt","vocabKey":"v:洗濯"},{"compound":"洗面所","reading":"せんめんじょ","meaning":"Nhà tắm"}],"lessonIds":[3,10,18,19,44],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 氵(nước/thủy) + 先 (trước/tiên — 𐃏+儿). Mẹo nhớ: dùng nước (氵) rửa sạch trước tiên (先) rồi mới ăn — hãy rửa tay trước! 🚿. 先 vừa gợi nghĩa 'trước' vừa cho âm セン (sen). Hán-Việt: Tẩy, như 'tẩy rửa', 'tẩy trắng'. Bộ 氵(さんずい) là bộ nước, xuất hiện rất nhiều: 海 (hải), 池 (trì), 湖 (hồ), 泳 (vịnh). Âm on セン (sen) trong 洗濯 (sentaku — giặt).","example":"手を**洗**いましょう。 / te wo araimashou. (Hãy rửa tay nào.)","examples":[{"ja":"手を洗いましょう。","vi":"Hãy rửa tay nào.","romaji":"te wo araimashou."},{"ja":"手を洗う","vi":"Rửa tay","romaji":"Te wo arau"},{"ja":"服を洗濯する","vi":"Giặt quần áo","romaji":"Fuku wo sentaku suru"},{"ja":"週末に洗濯をする","vi":"Giặt đồ cuối tuần","romaji":"shuumatsu ni sentaku o suru"}]},{"key":"k:切","kind":"kanji","level":"N5","character":"切","meaning":"Cắt","hanviet":"Thiết","onReadings":["セツ"],"kunReadings":["き"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"大切","reading":"たいせつ","meaning":"Quan trọng"},{"compound":"親切","reading":"しんせつ","meaning":"Tốt bụng"},{"compound":"切符","reading":"きっぷ","meaning":"Vé","vocabKey":"v:切符"}],"lessonIds":[7,8,11,17,33,38,41,42,43],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 七 (bảy) + 刀 (dao). Mẹo nhớ: cầm dao (刀) cắt làm bảy (七) phần → cắt ✂️. Nét nghiêng của 七 gợi nhát cắt xiên. Hán-Việt: Thiết, như 'thân thiết' (親切), 'đại thiết' (大切 — quan trọng), 'khẩn thiết'. Nghĩa mở rộng thú vị: 'cắt' → 'cắt vào lòng' → 'tha thiết, quan trọng'. So sánh: 切る (kiru/cắt) ≠ 着る (kiru/mặc) — cùng âm khác chữ!","example":"紙を**切**ります。 / kami wo kirimasu. (Tôi cắt giấy.)","examples":[{"ja":"紙を切ります。","vi":"Tôi cắt giấy.","romaji":"kami wo kirimasu."},{"ja":"紙を切る","vi":"Cắt giấy","romaji":"Kami wo kiru"},{"ja":"大切な人","vi":"Người quan trọng","romaji":"taisetsu na hito"},{"ja":"親切な人","vi":"Người tốt bụng","romaji":"shinsetsu na hito"}]},{"key":"k:思","kind":"kanji","level":"N5","character":"思","meaning":"Nghĩ","hanviet":"Tư","onReadings":["シ"],"kunReadings":["おも"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"思い出","reading":"おもいで","meaning":"Kỷ niệm"},{"compound":"不思議","reading":"ふしぎ","meaning":"Kỳ lạ"}],"lessonIds":[10,13,15,21,22,27,30],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 田 (ruộng/đầu não) + 心 (trái tim). Mẹo nhớ: phần trên 田 tượng trưng cho bộ não (ô vuông giống não bộ chia thành vùng), phần dưới 心 là trái tim — suy nghĩ bằng cả lý trí (não) và tình cảm (tim) 🤔. Hán-Việt: Tư, như 'tư duy', 'tư tưởng', 'suy tư'. Liên quan cùng bộ 心: 想 (tưởng), 感 (cảm), 念 (niệm), 忘 (vong/quên) — tất cả liên quan tâm trí.","example":"この計画は現実的で、いいと**思**います。 / kono keikaku wa genjitsuteki de, ii to omoimasu. (Tôi nghĩ kế hoạch này thực tế và tốt.)","examples":[{"ja":"この計画は現実的で、いいと思います。","vi":"Tôi nghĩ kế hoạch này thực tế và tốt.","romaji":"kono keikaku wa genjitsuteki de, ii to omoimasu."},{"ja":"昔のことを思い出す","vi":"Nhớ lại chuyện xưa","romaji":"Mukashi nokoto wo omoidasu"},{"ja":"いいと思う","vi":"Nghĩ là tốt","romaji":"ii to omou"},{"ja":"不思議な話","vi":"Câu chuyện bí ẩn","romaji":"Fushigi na hanashi"}]},{"key":"k:知","kind":"kanji","level":"N5","character":"知","meaning":"Biết","hanviet":"Tri","onReadings":["チ"],"kunReadings":["し"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"知識","reading":"ちしき","meaning":"Kiến thức"},{"compound":"知人","reading":"ちじん","meaning":"Người quen"}],"lessonIds":[15,28,30,43,45,47],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 矢 (mũi tên/thỉ) + 口 (miệng). Mẹo nhớ: lời nói (口) nhanh và chính xác như mũi tên (矢) bắn trúng đích — người hiểu biết trả lời nhanh trúng vấn đề 🏹. Hán-Việt: Tri, như 'tri thức', 'tri kỷ' (bạn thân hiểu mình), 'nhận tri'. Âm on チ (chi) trong 知識 (chishiki — kiến thức). Phần 矢 là bộ thủ thỉ (や), cũng xuất hiện trong 短 (đoản/ngắn), 医 (y/bác sĩ).","example":"この人を**知**っていますか。 / kono hito wo shitte imasu ka. (Bạn biết người này không?)","examples":[{"ja":"この人を知っていますか。","vi":"Bạn biết người này không?","romaji":"kono hito o shitsute imasu ka."},{"ja":"住所を知る","vi":"Biết địa chỉ","romaji":"juusho o shiru"},{"ja":"結果を知らせる","vi":"Thông báo kết quả","romaji":"Kekka wo shiraseru"},{"ja":"町で知り合いに会った","vi":"Gặp người quen trong thị trấn","romaji":"Machi de shiriai ni atsuta"}]},{"key":"k:考","kind":"kanji","level":"N5","character":"考","meaning":"Suy nghĩ","hanviet":"Khảo","onReadings":["コウ"],"kunReadings":["かんが"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"考え","reading":"かんがえ","meaning":"Suy nghĩ"},{"compound":"参考","reading":"さんこう","meaning":"Tham khảo"}],"lessonIds":[25],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 耂 (biến thể của 老/già — bỏ 匕) + 丂 (hơi cong/khuất). Mẹo nhớ: phần trên 耂 là biến thể của 老 (già/lão) — người già (耂) kinh nghiệm dày dặn, ngồi trầm ngâm suy nghĩ 🧓. Tuổi tác mang lại sự suy xét chín chắn. Hán-Việt: Khảo, như 'tham khảo' (参考), 'khảo sát', 'tư khảo'. Liên quan: 老 (lão/già) cùng gốc phần trên 耂. Âm kun かんがえる (kangaeru) = suy nghĩ.","example":"よく**考**えてください。 / yoku kangaete kudasai. (Hãy suy nghĩ kỹ.)","examples":[{"ja":"よく考えてください。","vi":"Hãy suy nghĩ kỹ.","romaji":"yoku kangaete kudasai."},{"ja":"よく考える","vi":"Suy nghĩ kỹ","romaji":"Yoku kangaeru"},{"ja":"いくら 考えても、わかりません。","vi":"Cho dù có nghĩ thế nào đi nữa thì cũng không hiểu.","romaji":"ikura kangaete mo, wakarimasen."},{"ja":"考えます","vi":"nghĩ, suy nghĩ","romaji":"kangaemasu"}]},{"key":"k:教","kind":"kanji","level":"N5","character":"教","meaning":"Dạy","hanviet":"Giáo","onReadings":["キョウ"],"kunReadings":["おし","おそ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"教室","reading":"きょうしつ","meaning":"Phòng học","vocabKey":"v:教室"},{"compound":"教育","reading":"きょういく","meaning":"Giáo dục","vocabKey":"v:教育"},{"compound":"教会","reading":"きょうかい","meaning":"Nhà thờ","vocabKey":"v:教会"}],"lessonIds":[1,3,7,14,27,31,35,42],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 孝 (hiếu — 耂 người già + 子 con) + 攵 (tay cầm roi/phộc). Mẹo nhớ: dùng roi (攵) dạy con (子) lòng hiếu thảo với cha mẹ già (耂) → dạy dỗ, giáo dục 👨‍🏫. Hình ảnh giáo dục truyền thống: thầy cầm roi chỉ bảo học trò. Hán-Việt: Giáo, như 'giáo dục' (教育), 'giáo viên', 'tôn giáo' (教会). Hai cách đọc: 教える (おしえる/oshieru) = dạy; 教わる (おそわる/osowaru) = được dạy.","example":"日本語を**教**えてください。 / nihongo wo oshiete kudasai. (Hãy dạy tiếng Nhật cho tôi.)","examples":[{"ja":"日本語を教えてください。","vi":"Hãy dạy tiếng Nhật cho tôi.","romaji":"nihongo wo oshiete kudasai."},{"ja":"日本語を教える","vi":"Dạy tiếng Nhật","romaji":"Nihongo wo oshieru"},{"ja":"教会に行く","vi":"Đi nhà thờ","romaji":"kyoukai ni iku"},{"ja":"教室に入る","vi":"Vào phòng học","romaji":"kyoushitsu ni hairu"}]},{"key":"k:習","kind":"kanji","level":"N5","character":"習","meaning":"Học, luyện tập","hanviet":"Tập","onReadings":["シュウ"],"kunReadings":["なら"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"練習","reading":"れんしゅう","meaning":"Luyện tập","vocabKey":"v:練習"},{"compound":"学習","reading":"がくしゅう","meaning":"Học tập"},{"compound":"習慣","reading":"しゅうかん","meaning":"Thói quen","vocabKey":"v:習慣"}],"lessonIds":[7,19,28,30,38,48],"topicTags":[],"sectionId":5,"sectionName":"ĐỘNG TÁC & HÀNH VI","mnemonic":"Bộ/thành phần: 羽 (đôi cánh chim/vũ) + 白 (trắng/bạch). Mẹo nhớ: chim con (白 — trắng tinh, non nớt) vỗ đôi cánh (羽) tập bay lặp đi lặp lại → luyện tập 🐦. Chim non phải tập vỗ cánh hàng trăm lần mới bay được — giống như học phải luyện tập nhiều. Hán-Việt: Tập, như 'luyện tập' (練習), 'học tập' (学習), 'tập quán' (習慣 — thói quen). Âm on シュウ (shuu), kun なら(う) (narau).","example":"ピアノを**習**っています。 / piano wo naratte imasu. (Tôi đang học piano.)","examples":[{"ja":"ピアノを習っています。","vi":"Tôi đang học piano.","romaji":"piano o naratsute imasu."},{"ja":"ピアノを習う","vi":"Học piano","romaji":"Piano wo narau"},{"ja":"ピアノを練習する","vi":"Luyện tập piano","romaji":"piano o renshuu suru"},{"ja":"授業の前に予習する","vi":"Soạn bài trước giờ học","romaji":"jugyou no mae ni yoshuu suru"}]},{"key":"k:学","kind":"kanji","level":"N5","character":"学","meaning":"Học","hanviet":"Học","onReadings":["ガク"],"kunReadings":["まな"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"学校","reading":"がっこう","meaning":"Trường học","vocabKey":"v:学校"},{"compound":"大学","reading":"だいがく","meaning":"Đại học","vocabKey":"v:大学"},{"compound":"学生","reading":"がくせい","meaning":"Học sinh","vocabKey":"v:学生"}],"lessonIds":[1,5,11,16,25,31,35,38,45,46,47,48,49],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 冖 (nắp/mái che) + ⺊ (bốc) + 子 (con). Hán-Việt: HỌC. Mẹo nhớ: Đứa trẻ (子) dưới mái trường (冖) đang học tập — 'học' là tiếp thu kiến thức 📚. 8 nét. Âm ガク (gaku) như trong 学校 (gakkou - trường học), まなぶ (manabu) = học. Liên kết: 学校 (trường học), 大学 (đại học), 学生 (học sinh). ⚠️ Đừng nhầm với 字 (tự/chữ) — 字 có 宀 (mái) + 子, còn 学 có 冖.","example":"この**学**校は留学生へのサポートが手厚いです。 / kono gakkou wa ryuugakusei e no sapooto ga teatsui desu. (Trường này hỗ trợ du học sinh rất tốt.)","examples":[{"ja":"この学校は留学生へのサポートが手厚いです。","vi":"Trường này hỗ trợ du học sinh rất tốt.","romaji":"kono gakkou wa ryuugakusei e no sapooto ga teatsui desu."},{"ja":"大学に入学する","vi":"Nhập học đại học","romaji":"daigaku ni nyuugaku suru"},{"ja":"日本に留学する","vi":"Du học Nhật","romaji":"nippon ni ryuugaku suru"},{"ja":"工場を見学する","vi":"Tham quan nhà máy","romaji":"koujou o kengaku suru"}]},{"key":"k:校","kind":"kanji","level":"N5","character":"校","meaning":"Trường","hanviet":"Hiệu","onReadings":["コウ"],"kunReadings":["-"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"学校","reading":"がっこう","meaning":"Trường","vocabKey":"v:学校"},{"compound":"高校","reading":"こうこう","meaning":"Trường cấp 3","vocabKey":"v:高校"}],"lessonIds":[5,15,35,38],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 木 (cây/gỗ) + 交 (giao). Hán-Việt: HIỆU. Mẹo nhớ: Nơi có cây (木) to che mát, mọi người giao (交) lưu học tập — trường 'hiệu' 🏫. 10 nét. Âm コウ (kou) gần 'hiệu'. Liên kết: 学校 (trường học), 高校 (trường cấp 3). ⚠️ Bên phải là 交 (giao) — chứ không phải 父 (phụ/cha).","example":"今日は**校**長先生の話を体育館で聞きました。 / kyou wa kouchou sensei no hanashi wo taiikukan de kikimashita. (Hôm nay chúng tôi nghe hiệu trưởng phát biểu ở nhà thi đấu.)","examples":[{"ja":"今日は校長先生の話を体育館で聞きました。","vi":"Hôm nay chúng tôi nghe hiệu trưởng phát biểu ở nhà thi đấu.","romaji":"kyou wa kouchou sensei no hanashi wo taiikukan de kikimashita."},{"ja":"学校に行く","vi":"Đi học","romaji":"gakkou ni iku"},{"ja":"小学校に入る","vi":"Vào tiểu học","romaji":"shougakkou ni hairu"},{"ja":"中学校を卒業する","vi":"Tốt nghiệp THCS","romaji":"chuugakkou o sotsugyou suru"}]},{"key":"k:先","kind":"kanji","level":"N5","character":"先","meaning":"Trước, tiên","hanviet":"Tiên","onReadings":["セン"],"kunReadings":["さき"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"先生","reading":"せんせい","meaning":"Thầy/ cô","vocabKey":"v:先生"},{"compound":"先週","reading":"せんしゅう","meaning":"Tuần trước","vocabKey":"v:先週"}],"lessonIds":[1,5,29,32,34,38],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 𠂉 (biến thể của 土) + 儿 (chân người). Hán-Việt: TIÊN. Mẹo nhớ: Đôi chân (儿) bước đi trước — 'tiên' phong, người đi trước 🚶‍♂️. 6 nét. Âm セン (sen) như trong 先生 (sensei - thầy/cô), さき (saki) = phía trước. Liên kết: 先生 (thầy cô), 先週 (tuần trước). ⚠️ Đừng nhầm với 洗 (tẩy/rửa) — 洗 có thêm 氵 (nước) bên trái.","example":"**先**に行ってください。 / saki ni itte kudasai. (Hãy đi trước.)","examples":[{"ja":"先に行ってください。","vi":"Hãy đi trước.","romaji":"saki ni itsute kudasai."},{"ja":"先輩に聞く","vi":"Hỏi tiền bối","romaji":"Senpai ni kiku"},{"ja":"先週旅行した","vi":"Tuần trước du lịch","romaji":"senshuu ryokou shita"},{"ja":"先月引っ越した","vi":"Tháng trước chuyển nhà","romaji":"Sengetsu hikkoshita"}]},{"key":"k:生","kind":"kanji","level":"N5","character":"生","meaning":"Sống, sinh ra","hanviet":"Sinh","onReadings":["セイ","ショウ"],"kunReadings":["い","う","なま"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"先生","reading":"せんせい","meaning":"Thầy","vocabKey":"v:先生"},{"compound":"学生","reading":"がくせい","meaning":"Học sinh","vocabKey":"v:学生"},{"compound":"生活","reading":"せいかつ","meaning":"Cuộc sống","vocabKey":"v:生活"},{"compound":"生まれる","reading":"うまれる","meaning":"Sinh ra","vocabKey":"v:生まれる"}],"lessonIds":[1,5,8,11,12,16,22,32,37,42,45,47,48],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 生 là chữ tượng hình — hình mầm non mọc lên (丨) từ mặt đất (一). Hán-Việt: SINH. Mẹo nhớ: Mầm cây vươn lên từ đất — 'sinh' ra, sống, tươi mới 🌱. 5 nét. Âm セイ (sei) trong 学生, ショウ (shou), いきる (ikiru) = sống, うまれる (umareru) = sinh ra. Liên kết: 先生 (thầy cô), 学生 (học sinh), 生活 (cuộc sống). ⚠️ Nhiều cách đọc — セイ/ショウ/い/う/なま — cần nhớ theo từ ghép.","example":"東京で**生**まれました。 / toukyou de umaremashita. (Tôi sinh ra ở Tokyo.)","examples":[{"ja":"東京で生まれました。","vi":"Tôi sinh ra ở Tokyo.","romaji":"toukyou de umaremashita."},{"ja":"東京で生まれる","vi":"Sinh ra ở Tokyo","romaji":"toukyou de umareru"},{"ja":"生きることは素晴らしい","vi":"Sống thật tuyệt vời","romaji":"ikiru koto wa subarashii"},{"ja":"一人で生活する","vi":"Sống một mình","romaji":"ichinin de seikatsu suru"}]},{"key":"k:試","kind":"kanji","level":"N5","character":"試","meaning":"Thử, thi","hanviet":"Thí","onReadings":["シ"],"kunReadings":["こころ","ため"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"試験","reading":"しけん","meaning":"Kỳ thi","vocabKey":"v:試験"},{"compound":"試合","reading":"しあい","meaning":"Trận đấu","vocabKey":"v:試合"}],"lessonIds":[4,21,31],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 言 (lời nói) + 式 (thức/kiểu). Hán-Việt: THÍ. Mẹo nhớ: Dùng lời (言) theo khuôn thức (式) để kiểm tra — 'thí' nghiệm, thi cử 📝. 13 nét. Âm シ (shi) như trong 試験 (shiken - kỳ thi), ためす (tamesu) = thử. Liên kết: 試験 (kỳ thi), 試合 (trận đấu). ⚠️ Đi cùng 験 tạo 試験 (shiken) — cặp đôi không tách rời.","example":"来週**試**験があります。 / raishuu shiken ga arimasu. (Tuần sau có thi.)","examples":[{"ja":"来週試験があります。","vi":"Tuần sau có thi.","romaji":"raishuu shiken ga arimasu."},{"ja":"試験を受ける","vi":"Thi","romaji":"Shiken wo ukeru"},{"ja":"試験会場を間違えないでください","vi":"Đừng nhầm địa điểm thi","romaji":"shiken kaijou o machigaenaide kudasai"},{"ja":"試合を見る","vi":"Xem trận đấu","romaji":"Shiai wo miru"}]},{"key":"k:験","kind":"kanji","level":"N5","character":"験","meaning":"Kiểm tra, kinh nghiệm","hanviet":"Nghiệm","onReadings":["ケン"],"kunReadings":["-"],"strokeCount":18,"radicals":[],"components":[],"compounds":[{"compound":"試験","reading":"しけん","meaning":"Kỳ thi","vocabKey":"v:試験"},{"compound":"経験","reading":"けいけん","meaning":"Kinh nghiệm","vocabKey":"v:経験"},{"compound":"実験","reading":"じっけん","meaning":"Thí nghiệm","vocabKey":"v:実験"}],"lessonIds":[4,28,31,47],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 馬 (ngựa) + 㑒 (nghiệm — phần trên). Hán-Việt: NGHIỆM. Mẹo nhớ: Ngựa (馬) phải qua kiểm tra, thử 'nghiệm' trước khi ra trận 🐴✓. 18 nét (nhiều nét nhất nhóm). Âm ケン (ken) gần 'nghiệm'. Liên kết: 試験 (kỳ thi), 経験 (kinh nghiệm), 実験 (thí nghiệm). ⚠️ Bên trái là 馬 (ngựa) — 10 nét, viết cẩn thận.","example":"日本語能力試**験**に合格したので、家族が喜んでくれました。 / nihongo nouryoku shiken ni goukaku shita node, kazoku ga yorokonde kuremashita. (Vì đỗ kỳ thi năng lực tiếng Nhật nên gia đình tôi rất vui.)","examples":[{"ja":"日本語能力試験に合格したので、家族が喜んでくれました。","vi":"Vì đỗ kỳ thi năng lực tiếng Nhật nên gia đình tôi rất vui.","romaji":"nihongo nouryoku shiken ni goukaku shita node, kazoku ga yorokonde kuremashita."},{"ja":"いろいろ経験する","vi":"Trải qua nhiều thứ","romaji":"Iroiro keiken suru"},{"ja":"試験を受ける","vi":"Thi","romaji":"Shiken wo ukeru"},{"ja":"試験会場を間違えないでください","vi":"Đừng nhầm địa điểm thi","romaji":"shiken kaijou o machigaenaide kudasai"}]},{"key":"k:問","kind":"kanji","level":"N4","character":"問","meaning":"Hỏi","hanviet":"Vấn","onReadings":["モン"],"kunReadings":["と"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"問題","reading":"もんだい","meaning":"Vấn đề","vocabKey":"v:問題"},{"compound":"質問","reading":"しつもん","meaning":"Câu hỏi","vocabKey":"v:質問"}],"lessonIds":[34],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 門 (cổng) + 口 (miệng). Hán-Việt: VẤN. Mẹo nhớ: Đứng ở cổng (門) mở miệng (口) hỏi — 'vấn' đề, câu hỏi ❓. 11 nét. Âm モン (mon) như trong 問題 (mondai - vấn đề), とう (tou) = hỏi. Liên kết: 問題 (vấn đề), 質問 (câu hỏi). ⚠️ Đừng nhầm với 聞 (văn/nghe) — 聞 có 耳 (tai) bên trong 門, còn 問 có 口 (miệng).","example":"この**問**題が分からなかったら、授業の後で先生に聞いてください。 / kono mondai ga wakaranakattara, jugyou no ato de sensei ni kiite kudasai. (Nếu không hiểu bài này thì hãy hỏi giáo viên sau giờ học.)","examples":[{"ja":"この問題が分からなかったら、授業の後で先生に聞いてください。","vi":"Nếu không hiểu bài này thì hãy hỏi giáo viên sau giờ học.","romaji":"kono mondai ga wakaranakatsu tara, jugyou no nochi de sensei ni kiite kudasai."},{"ja":"先生に質問する","vi":"Hỏi thầy cô","romaji":"Sensei ni shitsumon suru"},{"ja":"問題を解く","vi":"Giải bài","romaji":"Mondai wo toku"},{"ja":"練習問題をたくさん解く","vi":"Giải nhiều bài tập","romaji":"renshuu mondai o takusan toku"}]},{"key":"k:答","kind":"kanji","level":"N4","character":"答","meaning":"Trả lời","hanviet":"Đáp","onReadings":["トウ"],"kunReadings":["こた"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"答え","reading":"こたえ","meaning":"Đáp án","vocabKey":"v:答え"}],"lessonIds":[39,45],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 竹 (tre) ⺮ + 合 (hợp). Hán-Việt: ĐÁP. Mẹo nhớ: Những thanh tre (⺮) ghép vào nhau cho hợp (合) — tìm ra đáp án, trả lời đúng ✅. 12 nét. Âm トウ (tou), こたえる (kotaeru) = trả lời. Liên kết: 答え (đáp án). Đi cặp với 問: 問答 (vấn đáp). ⚠️ Phần trên là ⺮ (竹 viết tắt), không phải hai chữ 个.","example":"**答**えを書いてください。 / kotae wo kaite kudasai. (Hãy viết đáp án.)","examples":[{"ja":"答えを書いてください。","vi":"Hãy viết đáp án.","romaji":"kotae wo kaite kudasai."},{"ja":"質問に答える","vi":"Trả lời câu hỏi","romaji":"Shitsumon ni kotaeru"},{"ja":"答えを書く","vi":"Viết đáp án","romaji":"Kotae wo kaku"},{"ja":"答えます","vi":"trả lời","romaji":"kotaemasu"}]},{"key":"k:文","kind":"kanji","level":"N5","character":"文","meaning":"Văn, câu, chữ","hanviet":"Văn","onReadings":["ブン","モン"],"kunReadings":["ふみ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"文化","reading":"ぶんか","meaning":"Văn hóa","vocabKey":"v:文化"},{"compound":"文法","reading":"ぶんぽう","meaning":"Ngữ pháp","vocabKey":"v:文法"},{"compound":"作文","reading":"さくぶん","meaning":"Bài luận","vocabKey":"v:作文"}],"lessonIds":[13,31,41,42,47],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 文 là chữ tượng hình — hình hoa văn giao nhau trên áo (亠 + 乂). Hán-Việt: VĂN. Mẹo nhớ: Nét giao nhau tạo hoa 'văn' — từ hoa văn → văn hóa → văn chương → câu văn ✍️. 4 nét. Âm ブン (bun) trong 文法 (bunpou - ngữ pháp), モン (mon) trong 文字 (monji). Liên kết: 文化 (văn hóa), 文法 (ngữ pháp), 作文 (bài luận). ⚠️ Đừng nhầm với 交 (giao) — 交 có 6 nét và thêm phần chân.","example":"**文**法を勉強しています。 / bunpou wo benkyou shite imasu. (Tôi đang học ngữ pháp.)","examples":[{"ja":"文法を勉強しています。","vi":"Tôi đang học ngữ pháp.","romaji":"bunpou wo benkyou shite imasu."},{"ja":"レストランで料理を注文した","vi":"Gọi món ở nhà hàng","romaji":"resutoran de ryouri o chuumon shita"},{"ja":"文法を勉強する","vi":"Học ngữ pháp","romaji":"bunpou o benkyou suru"},{"ja":"文字を書く","vi":"Viết chữ","romaji":"Moji wo kaku"}]},{"key":"k:字","kind":"kanji","level":"N5","character":"字","meaning":"Chữ","hanviet":"Tự","onReadings":["ジ"],"kunReadings":["あざ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"漢字","reading":"かんじ","meaning":"Kanji","vocabKey":"v:漢字"},{"compound":"文字","reading":"もじ","meaning":"Ký tự","vocabKey":"v:文字"},{"compound":"数字","reading":"すうじ","meaning":"Số"}],"lessonIds":[9,48],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + 子 (con). Hán-Việt: TỰ. Mẹo nhớ: Đứa trẻ (子) được dạy chữ dưới mái nhà (宀) — 'tự' là chữ viết ✍️. 6 nét. Âm ジ (ji) như trong 漢字 (kanji - chữ Hán), あざ (aza) = tên đất. Liên kết: 漢字 (kanji), 文字 (moji - ký tự), 数字 (suuji - số). ⚠️ Đừng nhầm với 学 (học) — cả hai có 子 nhưng 字 dùng 宀, 学 dùng 冖.","example":"**字**が上手ですね。 / ji ga jouzu desu ne. (Chữ đẹp nhỉ.)","examples":[{"ja":"字が上手ですね。","vi":"Chữ đẹp nhỉ.","romaji":"ji ga jouzu desu ne."},{"ja":"文字を書く","vi":"Viết chữ","romaji":"Moji wo kaku"},{"ja":"字を書く","vi":"Viết chữ","romaji":"Ji wo kaku"},{"ja":"ミラーさんは 漢字を 読む ことが できます。","vi":"Anh Miller có thể đọc chữ Hán.","romaji":"miraa san wa kanji o yomu koto ga dekimasu."}]},{"key":"k:英","kind":"kanji","level":"N5","character":"英","meaning":"Anh (nước Anh)","hanviet":"Anh","onReadings":["エイ"],"kunReadings":["-"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"英語","reading":"えいご","meaning":"Tiếng Anh","vocabKey":"v:英語"},{"compound":"英国","reading":"えいこく","meaning":"Nước Anh"}],"lessonIds":[2],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 艹 (cỏ/thảo) + 央 (trung ương/giữa). Hán-Việt: ANH. Mẹo nhớ: Bông hoa (艹) đẹp nhất ở trung tâm (央) — 'anh' hoa, tinh hoa, xuất sắc 🌸. 8 nét. Âm エイ (ei) như trong 英語 (eigo - tiếng Anh). Liên kết: 英語 (tiếng Anh), 英国 (nước Anh). ⚠️ 央 cũng xuất hiện trong 映 (ánh/chiếu) — nhưng 映 có 日 thay vì 艹.","example":"**英**語を話せますか。 / eigo wo hanasemasu ka. (Bạn nói được tiếng Anh không?)","examples":[{"ja":"英語を話せますか。","vi":"Bạn nói được tiếng Anh không?","romaji":"eigo wo hanasemasu ka."},{"ja":"英語が話せる","vi":"Nói được tiếng Anh","romaji":"Eigo ga hanaseru"},{"ja":"「ありがとう」は英語で何ですか。……「Thank you」です。","vi":"'Arigatou' tiếng Anh nói thế nào? Tiếng Anh nói là 'Thank you'.","romaji":"\\" arigatou\\" wa eigo de nani desu ka.......\\" thank you\\" desu."},{"ja":"英語がよくわかります。","vi":"Tôi hiểu tiếng Anh tốt.","romaji":"eigo ga yoku wakarimasu."}]},{"key":"k:語","kind":"kanji","level":"N5","character":"語","meaning":"Ngôn ngữ","hanviet":"Ngữ","onReadings":["ゴ"],"kunReadings":["かた"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"日本語","reading":"にほんご","meaning":"Tiếng Nhật","vocabKey":"v:日本語"},{"compound":"英語","reading":"えいご","meaning":"Tiếng Anh","vocabKey":"v:英語"},{"compound":"物語","reading":"ものがたり","meaning":"Câu chuyện"}],"lessonIds":[2,37],"topicTags":["school"],"sectionId":6,"sectionName":"TRƯỜNG HỌC & HỌC TẬP","mnemonic":"Bộ/thành phần: 言 (lời nói) + 吾 (ta). Hán-Việt: NGỮ. Mẹo nhớ: lời nói (言) của 'ta' (吾) hợp lại thành ngôn ngữ, nên nhớ nghĩa 'ngữ/lời' 🗨️. 14 nét. Âm ゴ (go) gặp trong 日本語 (nihongo - tiếng Nhật), 英語 (eigo - tiếng Anh). Âm kun かたる (kataru) = kể, thuật lại. Liên kết: 日本語 (tiếng Nhật), 英語 (tiếng Anh), 物語 (câu chuyện). ⚠️ Dễ nhầm với 話 (thoại): 語 thiên về ngôn ngữ/từ vựng, còn 話 thiên về nói chuyện/câu chuyện.","example":"日本**語**を勉強しています。 / nihongo wo benkyou shite imasu. (Tôi đang học tiếng Nhật.)","examples":[{"ja":"日本語を勉強しています。","vi":"Tôi đang học tiếng Nhật.","romaji":"nihongo wo benkyou shite imasu."},{"ja":"日本語を勉強する","vi":"Học tiếng Nhật","romaji":"nihongo o benkyou suru"},{"ja":"英語が話せる","vi":"Nói được tiếng Anh","romaji":"Eigo ga hanaseru"},{"ja":"外国語を勉強する","vi":"Học ngoại ngữ","romaji":"gaikokugo o benkyou suru"}]},{"key":"k:国","kind":"kanji","level":"N5","character":"国","meaning":"Nước, quốc gia","hanviet":"Quốc","onReadings":["コク"],"kunReadings":["くに"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"外国","reading":"がいこく","meaning":"Nước ngoài","vocabKey":"v:外国"},{"compound":"中国","reading":"ちゅうごく","meaning":"Trung Quốc"},{"compound":"国際","reading":"こくさい","meaning":"Quốc tế","vocabKey":"v:国際"}],"lessonIds":[3,11,20,26,32,42],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 囗 (vây quanh/biên giới) + 玉 (ngọc). Hán-Việt: QUỐC. Mẹo nhớ: Ngọc (玉) quý nằm trong biên giới (囗) — bảo vệ báu vật, đó là 'quốc' gia 🏰. 8 nét. Âm くに (kuni) = nước, コク (koku) gần 'quốc'. Liên kết: 外国 (nước ngoài), 中国 (Trung Quốc), 国際 (quốc tế). ⚠️ 玉 bên trong 囗 là dạng giản lược của chữ xưa.","example":"**国**に帰りたいです。 / kuni ni kaeritai desu. (Tôi muốn về nước.)","examples":[{"ja":"国に帰りたいです。","vi":"Tôi muốn về nước.","romaji":"kuni ni kaeritai desu."},{"ja":"来年帰国する","vi":"Năm sau về nước","romaji":"Rainen kikoku suru"},{"ja":"国に帰る","vi":"Về nước","romaji":"Kuni ni kaeru"},{"ja":"外国に行く","vi":"Đi nước ngoài","romaji":"Gaikoku ni iku"}]},{"key":"k:都","kind":"kanji","level":"N5","character":"都","meaning":"Thủ đô, thành phố","hanviet":"Đô","onReadings":["ト"],"kunReadings":["みやこ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"東京都","reading":"とうきょうと","meaning":"Tokyo"},{"compound":"都会","reading":"とかい","meaning":"Thành phố lớn","vocabKey":"v:都会"}],"lessonIds":[22,31],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 者 (giả/người) + 阝 (ấp/thành phố). Hán-Việt: ĐÔ. Mẹo nhớ: Nơi (阝 ấp) tập trung nhiều 者 người — 'đô' thị, thủ đô 🏙️. 11 nét. Âm みやこ (miyako) = kinh đô, ト (to) gần 'đô'. Liên kết: 東京都 (Tokyo), 都会 (thành phố lớn). ⚠️ 阝 bên phải = ấp/thành phố, bên trái = đồi/gò — vị trí rất quan trọng.","example":"**都**会の生活は忙しいです。 / tokai no seikatsu wa isogashii desu. (Cuộc sống thành phố bận.)","examples":[{"ja":"都会の生活は忙しいです。","vi":"Cuộc sống thành phố bận.","romaji":"tokai no seikatsu wa isogashii desu."},{"ja":"都会に住む","vi":"Sống ở thành phố","romaji":"Tokai ni sumu"},{"ja":"日本の都道府県を覚える","vi":"Học các tỉnh thành của Nhật","romaji":"nippon no todoufuken o oboeru"},{"ja":"京都へ行きます。","vi":"Tôi đi Kyoto.","romaji":"kyouto e ikimasu."}]},{"key":"k:町","kind":"kanji","level":"N5","character":"町","meaning":"Phố, thị trấn","hanviet":"Đinh","onReadings":["チョウ"],"kunReadings":["まち"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"町","reading":"まち","meaning":"Thị trấn","vocabKey":"v:町"}],"lessonIds":[8],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 田 (ruộng) + 丁 (đinh/thẻ). Hán-Việt: ĐINH. Mẹo nhớ: Ruộng (田) chia thành từng 丁 ô vuông — phố xá, 'đinh' trấn 🏠. 7 nét. Âm まち (machi) = thị trấn, チョウ (chou). Liên kết: 町 (thị trấn/phố). ⚠️ Quy mô tăng dần: 村 (thôn) < 町 (phố) < 市 (thành phố) < 都 (đô).","example":"この**町**は静かです。 / kono machi wa shizuka desu. (Thị trấn này yên tĩnh.)","examples":[{"ja":"この町は静かです。","vi":"Thị trấn này yên tĩnh.","romaji":"kono machi wa shizuka desu."},{"ja":"町を歩く","vi":"Đi dạo phố","romaji":"Machi wo aruku"},{"ja":"奈良はどんな町ですか。……古い町です。","vi":"Nara là thành phố như thế nào? Là thành phố cổ kính.","romaji":"nara wa donna machi desu ka....... furui machi desu."},{"ja":"この町に新しい病院ができるそうです。","vi":"Nghe nói thị trấn này sẽ có bệnh viện mới.","romaji":"kono machi ni atarashii byouin ga dekiru sou desu."}]},{"key":"k:村","kind":"kanji","level":"N4","character":"村","meaning":"Làng","hanviet":"Thôn","onReadings":["ソン"],"kunReadings":["むら"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"村","reading":"むら","meaning":"Làng","vocabKey":"v:村"}],"lessonIds":[31,38],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 木 (cây) + 寸 (tấc/đo). Hán-Việt: THÔN. Mẹo nhớ: Cây (木) mọc bên đường, đo (寸) ra vài bước — nơi hẻo lánh, 'thôn' làng 🌳. 7 nét. Âm むら (mura) = làng, ソン (son) gần 'thôn'. Liên kết: 村 (làng). ⚠️ Đừng nhầm 村 (thôn/làng) với 材 (tài/chất liệu) — 村 có 寸, 材 có 才.","example":"小さい**村**に住んでいます。 / chiisai mura ni sunde imasu. (Tôi sống ở một ngôi làng nhỏ.)","examples":[{"ja":"小さい村に住んでいます。","vi":"Tôi sống ở một ngôi làng nhỏ.","romaji":"chiisai mura ni sunde imasu."},{"ja":"小さな村","vi":"Ngôi làng nhỏ","romaji":"Chiisana mura"},{"ja":"木村さんに花をあげました。","vi":"Tôi tặng hoa cho chị Kimura.","romaji":"kimura san ni hana o agemashita."},{"ja":"わたしは 木村さんに 傘を 貸して もらいました。","vi":"Tôi được chị Kimura cho mượn ô.","romaji":"watashi wa kimura san ni kasa o kashite moraimashita."}]},{"key":"k:家","kind":"kanji","level":"N5","character":"家","meaning":"Nhà","hanviet":"Gia","onReadings":["カ","ケ"],"kunReadings":["いえ","や"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"家族","reading":"かぞく","meaning":"Gia đình","vocabKey":"v:家族"},{"compound":"家庭","reading":"かてい","meaning":"Gia đình","vocabKey":"v:家庭"},{"compound":"作家","reading":"さっか","meaning":"Nhà văn"}],"lessonIds":[5,9,15,22,27,28,42],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + 豕 (heo/lợn). Hán-Việt: GIA. Mẹo nhớ: Mái nhà (宀) có nuôi 豕 lợn — xưa nhà nông nuôi lợn dưới sàn, đó là 'gia' đình 🏠🐷. 10 nét. Âm いえ (ie) = nhà, カ (ka) gần 'gia'. Liên kết: 家族 (gia đình), 作家 (nhà văn). ⚠️ 豕 không phải 犬 (khuyển) — 豕 có nét phẩy dài hơn.","example":"**家**に帰りましょう。 / ie ni kaerimashou. (Về nhà thôi.)","examples":[{"ja":"家に帰りましょう。","vi":"Về nhà thôi.","romaji":"ie ni kaerimashou."},{"ja":"家族と住む","vi":"Sống với gia đình","romaji":"Kazoku to sumu"},{"ja":"幸せな家庭を作りたい","vi":"Muốn xây dựng gia đình hạnh phúc","romaji":"Shiawase na katei wo tsukuri tai"},{"ja":"農家で手伝いをする","vi":"Phụ giúp ở nhà nông","romaji":"nouka de tetsudai o suru"}]},{"key":"k:室","kind":"kanji","level":"N5","character":"室","meaning":"Phòng","hanviet":"Thất","onReadings":["シツ"],"kunReadings":["むろ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"教室","reading":"きょうしつ","meaning":"Phòng học","vocabKey":"v:教室"},{"compound":"会議室","reading":"かいぎしつ","meaning":"Phòng họp","vocabKey":"v:会議室"}],"lessonIds":[3,22,27,35,39],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + 至 (đến/tới). Hán-Việt: THẤT. Mẹo nhớ: Đến (至) dưới mái nhà (宀) — vào 'thất', căn phòng bên trong 🚪. 9 nét. Âm むろ (muro) = phòng, シツ (shitsu) gần 'thất'. Liên kết: 教室 (phòng học), 会議室 (phòng hỌp). ⚠️ Đừng nhầm 室 (thất/phòng) với 家 (gia/nhà) — 室 là phòng bên trong, 家 là cả ngôi nhà.","example":"**室**の中は暖かいです。 / shitsu no naka wa atatakai desu. (Trong phòng ấm.)","examples":[{"ja":"室の中は暖かいです。","vi":"Trong phòng ấm.","romaji":"shitsu no naka wa atatakai desu."},{"ja":"教室に入る","vi":"Vào phòng học","romaji":"kyoushitsu ni hairu"},{"ja":"会議室を予約する","vi":"Đặt phòng họp","romaji":"Kaigishitsu wo yoyaku suru"},{"ja":"寝室で寝る","vi":"Ngủ ở phòng ngủ","romaji":"Shinshitsu de neru"}]},{"key":"k:堂","kind":"kanji","level":"N5","character":"堂","meaning":"Sảnh, đền","hanviet":"Đường","onReadings":["ドウ"],"kunReadings":["-"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"食堂","reading":"しょくどう","meaning":"Nhà ăn","vocabKey":"v:食堂"},{"compound":"お堂","reading":"おどう","meaning":"Chùa nhỏ"}],"lessonIds":[3,26],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 尚 (thượng — biến thể) + 土 (đất). Hán-Việt: ĐƯỜNG. Mẹo nhớ: Nền đất (土) xây cao (尚) lên — tòa sảnh lớn, 'đường' đền tráng lệ 🏛️. 11 nét. Âm ドウ (dou) gần 'đường'. Liên kết: 食堂 (nhà ăn), お堂 (chùa nhỏ). ⚠️ Đừng nhầm 堂 (đường/sảnh) với 党 (đảng) — 堂 có 土 ở dưới.","example":"**食堂**で昼ご飯を食べます。 / shokudou de hirugohan wo tabemasu. (Tôi ăn trưa ở nhà ăn.)","examples":[{"ja":"食堂で昼ご飯を食べます。","vi":"Tôi ăn trưa ở nhà ăn.","romaji":"shokudou de hirugohan wo tabemasu."},{"ja":"ここは食堂です。","vi":"Đây là nhà ăn.","romaji":"koko wa shokudou desu."},{"ja":"食堂","vi":"nhà ăn","romaji":"shokudou"},{"ja":"国会議事堂","vi":"tòa nhà quốc hội","romaji":"kokkaigijidou"}]},{"key":"k:店","kind":"kanji","level":"N5","character":"店","meaning":"Tiệm, cửa hàng","hanviet":"Điếm","onReadings":["テン"],"kunReadings":["みせ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"店員","reading":"てんいん","meaning":"Nhân viên cửa hàng","vocabKey":"v:店員"},{"compound":"本屋","reading":"ほんや","meaning":"Tiệm sách"}],"lessonIds":[6,10,31],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 广 (mái nhà/mái hiên) + 占 (chiếm/bói). Hán-Việt: ĐIẾ(M). Mẹo nhớ: Dưới mái hiên (广), 占 chiếm một chỗ bày hàng — 'điếm', tiệm bán hàng 🏪. 8 nét. Âm みせ (mise) = tiệm, テン (ten) gần 'điếm'. Liên kết: 店員 (nhân viên cửa hàng), 喫茶店 (quán trà). ⚠️ Đừng nhầm 店 (điếm/tiệm) với 占 (chiếm/bói) — 店 có thêm 广 mái.","example":"あの**店**はおいしいです。 / ano mise wa oishii desu. (Quán đó ngon.)","examples":[{"ja":"あの店はおいしいです。","vi":"Quán đó ngon.","romaji":"ano mise wa oishii desu."},{"ja":"店員に聞く","vi":"Hỏi nhân viên","romaji":"Ten'in ni kiku"},{"ja":"店に入る","vi":"Vào quán","romaji":"mise ni hairu"},{"ja":"この店は雰囲気がいい","vi":"Quán này có không khí tốt","romaji":"Kono mise wa fun'iki gaii"}]},{"key":"k:病","kind":"kanji","level":"N5","character":"病","meaning":"Bệnh","hanviet":"Bệnh","onReadings":["ビョウ"],"kunReadings":["やまい","や"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"病院","reading":"びょういん","meaning":"Bệnh viện","vocabKey":"v:病院"},{"compound":"病気","reading":"びょうき","meaning":"Bệnh","vocabKey":"v:病気"}],"lessonIds":[1,17],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 疒 (bệnh tật — người nằm giường) + 丙 (bính — gợi âm). Hán-Việt: BỆNH. Mẹo nhớ: Người nằm trên giường (疒) ốm đau — 'bệnh' rồi 🏥. 10 nét. Âm やまい (yamai) = bệnh, ビョウ (byou) gần 'bệnh'. Liên kết: 病院 (bệnh viện), 病気 (bệnh tật). ⚠️ 疒 là bộ thủ cho nhiều kanji sức khỏe: 痛 (đau), 疲 (mệt), 症 (triệu chứng).","example":"**病**院に行きました。 / byouin ni ikimashita. (Tôi đã đi bệnh viện.)","examples":[{"ja":"病院に行きました。","vi":"Tôi đã đi bệnh viện.","romaji":"byouin ni ikimashita."},{"ja":"病気になる","vi":"Bị bệnh","romaji":"byouki ni naru"},{"ja":"病院に行く","vi":"Đi bệnh viện","romaji":"byouin ni iku"},{"ja":"病気で会社を休みました。","vi":"Vì bệnh nên nghỉ làm.","romaji":"byouki de kaisha o yasumimashita."}]},{"key":"k:院","kind":"kanji","level":"N5","character":"院","meaning":"Viện","hanviet":"Viện","onReadings":["イン"],"kunReadings":["-"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"病院","reading":"びょういん","meaning":"Bệnh viện","vocabKey":"v:病院"},{"compound":"大学院","reading":"だいがくいん","meaning":"Cao học","vocabKey":"v:大学院"}],"lessonIds":[1,31,38],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 阝 (gò đồi) + 完 (hoàn/hoàn chỉnh). Hán-Việt: VIỆN. Mẹo nhớ: Nơi (阝) hoàn thiện (完) việc chữa trị — 'viện', bệnh viện 🏨. 10 nét. Âm イン (in) gần 'viện'. Liên kết: 病院 (bệnh viện), 大学院 (cao học). ⚠️ 阝 bên trái = đồi/gò — 院 có tường bao quanh trên đồi.","example":"**病院**はどこですか。 / byouin wa doko desu ka. (Bệnh viện ở đâu?)","examples":[{"ja":"病院はどこですか。","vi":"Bệnh viện ở đâu?","romaji":"byouin wa doko desu ka."},{"ja":"病院に入院する","vi":"Nhập viện","romaji":"byouin ni nyuuin suru"},{"ja":"来週退院する","vi":"Tuần sau xuất viện","romaji":"raishuu taiin suru"},{"ja":"美容院で髪を切る","vi":"Cắt tóc ở tiệm","romaji":"biyouin de kami o kiru"}]},{"key":"k:道","kind":"kanji","level":"N5","character":"道","meaning":"Đường","hanviet":"Đạo","onReadings":["ドウ"],"kunReadings":["みち"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"道具","reading":"どうぐ","meaning":"Dụng cụ","vocabKey":"v:道具"},{"compound":"歩道","reading":"ほどう","meaning":"Vỉa hè","vocabKey":"v:歩道"},{"compound":"柔道","reading":"じゅうどう","meaning":"Judo","vocabKey":"v:柔道"}],"lessonIds":[23,27,32,34,36],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 辶 (shinnyou, di chuyển) + 首 (đầu/cổ). Hán-Việt: ĐẠO. Mẹo nhớ: Ngẩng 首 đầu lên mà 辶 bước đi — con 'đạo' đường, đạo lý 🛤️. 12 nét. Âm みち (michi) = đường, ドウ (dou) gần 'đạo'. Liên kết: 道具 (dụng cụ), 歩道 (vỉa hè), 柔道 (judo). ⚠️ 道 vừa nghĩa 'đường đi' vừa nghĩa 'đạo lý' — 柔道 = con đường mềm dẻo.","example":"この**道**をまっすぐ行ってください。 / kono michi wo massugu itte kudasai. (Hãy đi thẳng con đường này.)","examples":[{"ja":"この道をまっすぐ行ってください。","vi":"Hãy đi thẳng con đường này.","romaji":"kono michi o massugu itsute kudasai."},{"ja":"道具を使う","vi":"Dùng dụng cụ","romaji":"dougu o tsukau"},{"ja":"道を渡る","vi":"Qua đường","romaji":"Michi wo wataru"},{"ja":"片道切符を買った","vi":"Đã mua vé một chiều","romaji":"katamichi kippu o katsuta"}]},{"key":"k:駅","kind":"kanji","level":"N5","character":"駅","meaning":"Ga tàu","hanviet":"Dịch","onReadings":["エキ"],"kunReadings":["-"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"駅前","reading":"えきまえ","meaning":"Trước ga","vocabKey":"v:駅前"},{"compound":"駅員","reading":"えきいん","meaning":"Nhân viên ga","vocabKey":"v:駅員"}],"lessonIds":[5,29,38],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 馬 + 尺. Mẹo nhớ: xưa là trạm đổi ngựa, liên tưởng đến nhà ga hiện đại, nên nhớ nghĩa 'ga'.","example":"**駅**まで歩きます。 / eki made arukimasu. (Tôi đi bộ đến ga.)","examples":[{"ja":"駅まで歩きます。","vi":"Tôi đi bộ đến ga.","romaji":"eki made arukimasu."},{"ja":"駅に着く","vi":"Đến ga","romaji":"Eki ni tsuku"},{"ja":"各駅停車で行く","vi":"Đi bằng tàu chạm","romaji":"Kakuekiteisha de iku"},{"ja":"駅で新聞を買います。","vi":"Tôi mua báo ở ga.","romaji":"eki de shinbun o kaimasu."}]},{"key":"k:車","kind":"kanji","level":"N5","character":"車","meaning":"Xe","hanviet":"Xa","onReadings":["シャ"],"kunReadings":["くるま"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"電車","reading":"でんしゃ","meaning":"Tàu điện","vocabKey":"v:電車"},{"compound":"自動車","reading":"じどうしゃ","meaning":"Ô tô"},{"compound":"自転車","reading":"じてんしゃ","meaning":"Xe đạp","vocabKey":"v:自転車"}],"lessonIds":[2,5,23,24,29,33,36,47],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 車 là tượng hình — hình chiếc xe nhìn từ trên: bánh (nét ngang), trục (nét dọc), thân (khung). Hán-Việt: XA. Mẹo nhớ: Khung xe có bánh và trục — 'xa' là xe cộ 🚗. 7 nét. Âm くるま (kuruma) = xe, シャ (sha) gần 'xa'. Liên kết: 電車 (tàu điện), 自動車 (ô tô), 自転車 (xe đạp). ⚠️ 車 là bộ thủ phổ biến: 転 (chuyển), 軽 (khinh/nhẹ), 輸 (du/vận chuyển).","example":"**車**で行きましょう。 / kuruma de ikimashou. (Đi bằng xe nào.)","examples":[{"ja":"車で行きましょう。","vi":"Đi bằng xe nào.","romaji":"kuruma de ikimashou."},{"ja":"電車に乗る","vi":"Đi tàu điện","romaji":"Densha ni noru"},{"ja":"自転車で通う","vi":"Đi bằng xe đạp","romaji":"jitensha de kayou"},{"ja":"車を運転する","vi":"Lái xe","romaji":"Kuruma wo unten suru"}]},{"key":"k:電","kind":"kanji","level":"N5","character":"電","meaning":"Điện","hanviet":"Điện","onReadings":["デン"],"kunReadings":["-"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"電車","reading":"でんしゃ","meaning":"Tàu điện","vocabKey":"v:電車"},{"compound":"電話","reading":"でんわ","meaning":"Điện thoại","vocabKey":"v:電話"},{"compound":"電気","reading":"でんき","meaning":"Điện"}],"lessonIds":[3,5,7,10,20,23,29,38],"topicTags":[],"sectionId":7,"sectionName":"NƠI CHỐN & DI CHUYỂN","mnemonic":"Bộ/thành phần: 雨 + 日 + thành tố phụ. Mẹo nhớ: hình ảnh tia chớp trong mưa gợi ra điện, nên nhớ nghĩa 'điện'.","example":"**電**気をつけてください。 / denki wo tsukete kudasai. (Hãy bật đèn.)","examples":[{"ja":"電気をつけてください。","vi":"Hãy bật đèn.","romaji":"denki wo tsukete kudasai."},{"ja":"友達に電話する","vi":"Gọi điện cho bạn","romaji":"Tomodachi ni denwa suru"},{"ja":"電池を交換する","vi":"Thay pin","romaji":"denchi o koukan suru"},{"ja":"電車に乗る","vi":"Đi tàu điện","romaji":"Densha ni noru"}]},{"key":"k:会","kind":"kanji","level":"N5","character":"会","meaning":"Hội, gặp","hanviet":"Hội","onReadings":["カイ"],"kunReadings":["あ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"会社","reading":"かいしゃ","meaning":"Công ty","vocabKey":"v:会社"},{"compound":"会議","reading":"かいぎ","meaning":"Cuộc họp","vocabKey":"v:会議"},{"compound":"社会","reading":"しゃかい","meaning":"Xã hội","vocabKey":"v:社会"}],"lessonIds":[1,3,4,6,13,26,28,31,35,39,40,42,49],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 人 (người, ở trên) + 云 (mây). Hán-Việt: HỘI. Mẹo nhớ: Hãy hình dung nhiều 人 người tụ họp dưới đám 云 mây — đó là buổi 'hội' họp, gặp gỡ ☁️👥. Âm カイ (kai) gần 'khai' (khai hội). Liên kết: 会社 (công ty = nơi hội tụ), 社会 (xã hội). ⚠️ Đừng nhầm với 合 (hợp) — 会 có 人 ở trên, 合 có 口 ở dưới.","example":"友達に**会**いたいです。 / tomodachi ni aitai desu. (Tôi muốn gặp bạn.)","examples":[{"ja":"友達に会いたいです。","vi":"Tôi muốn gặp bạn.","romaji":"tomodachi ni aitai desu."},{"ja":"友達に会う","vi":"Gặp bạn","romaji":"Tomodachi ni au"},{"ja":"都会に住む","vi":"Sống ở thành phố","romaji":"Tokai ni sumu"},{"ja":"コンサートの会場はとても広かった","vi":"Hội trường rất rộng","romaji":"konsaato no kaijou wa totemo hirokatsuta"}]},{"key":"k:社","kind":"kanji","level":"N5","character":"社","meaning":"Công ty, xã hội, đền","hanviet":"Xã","onReadings":["シャ"],"kunReadings":["やしろ"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"会社","reading":"かいしゃ","meaning":"Công ty","vocabKey":"v:会社"},{"compound":"社会","reading":"しゃかい","meaning":"Xã hội","vocabKey":"v:社会"},{"compound":"神社","reading":"じんじゃ","meaning":"Đền thần","vocabKey":"v:神社"}],"lessonIds":[1,3,16,18,26,31,35,38,42],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 礻(示) (bàn thờ, thần linh) + 土 (đất). Hán-Việt: XÃ. Mẹo nhớ: Nơi có 礻 bàn thờ trên mảnh 土 đất — đó là đền thần (神社), rồi mở rộng thành cộng đồng, 'xã' hội, công ty ⛩️. Âm シャ (sha) giống 'xã' trong tiếng Việt. Liên kết: 会社 (công ty), 社会 (xã hội), 神社 (đền thần). ⚠️ 礻 (bộ thị, 4 nét) khác với 衤 (bộ y/áo, 5 nét).","example":"**会社**で働いています。 / kaisha de hataraite imasu. (Tôi đang làm việc ở công ty.)","examples":[{"ja":"会社で働いています。","vi":"Tôi đang làm việc ở công ty.","romaji":"kaisha de hataraite imasu."},{"ja":"神社にお参りする","vi":"Đi lễ ở đền","romaji":"Jinja ni o mairi suru"},{"ja":"会社に勤める","vi":"Làm việc ở công ty","romaji":"Kaisha ni tsutomeru"},{"ja":"社長に会う","vi":"Gặp giám đốc","romaji":"shachou ni au"}]},{"key":"k:仕","kind":"kanji","level":"N5","character":"仕","meaning":"Phục vụ","hanviet":"Sĩ","onReadings":["シ","ジ"],"kunReadings":["つか"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"仕事","reading":"しごと","meaning":"Công việc","vocabKey":"v:仕事"},{"compound":"仕方","reading":"しかた","meaning":"Cách"}],"lessonIds":[8],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 亻(人) (người đứng) + 士 (sĩ, chiến binh). Hán-Việt: SĨ. Mẹo nhớ: Một 亻 người làm việc cần mẫn như 士 chiến binh — đó là 'phục vụ'. Hầu như chỉ dùng trong 仕事 (shigoto - công việc) và 仕方 (shikata - cách thức). Âm シ (shi) gần 'sĩ'. ⚠️ Đừng nhầm 士 (sĩ, ngang trên dài) với 土 (thổ/đất, ngang dưới dài).","example":"**仕**事が忙しいです。 / shigoto ga isogashii desu. (Công việc bận.)","examples":[{"ja":"仕事が忙しいです。","vi":"Công việc bận.","romaji":"shigoto ga isogashii desu."},{"ja":"仕事が忙しい","vi":"Công việc bận","romaji":"Shigoto ga isogashii"},{"ja":"電車が遅れたから、仕方がないですね。","vi":"Tàu đến trễ rồi nên cũng không còn cách nào khác.","romaji":"Densha ga okureta kara, shikata ga nai desu ne."},{"ja":"お仕事は何ですか。","vi":"Công việc của bạn là gì?","romaji":"o shigoto wa nani desu ka."}]},{"key":"k:事","kind":"kanji","level":"N5","character":"事","meaning":"Việc, sự","hanviet":"Sự","onReadings":["ジ"],"kunReadings":["こと"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"仕事","reading":"しごと","meaning":"Công việc","vocabKey":"v:仕事"},{"compound":"事故","reading":"じこ","meaning":"Tai nạn","vocabKey":"v:事故"},{"compound":"食事","reading":"しょくじ","meaning":"Bữa ăn","vocabKey":"v:食事"}],"lessonIds":[3,8,9,13,17,26,29,39,40,46],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: Chữ tượng hình cổ — hình bàn tay cầm bút ghi chép sổ sách. Hán-Việt: SỰ. Mẹo nhớ: Hình dung cây bút 🖊️ cắm trên giá, xung quanh là các nét ngang = những 'việc' cần ghi chép, xử lý. Âm ジ (ji) gần 'sự'. Liên kết: 仕事 (công việc), 事故 (sự cố/tai nạn), 食事 (bữa ăn = sự ăn). Chữ 8 nét, thứ tự: ngang → dọc → ngang → ngang → dọc cong.","example":"大切な**事**があります。 / taisetsu na koto ga arimasu. (Có chuyện quan trọng.)","examples":[{"ja":"大切な事があります。","vi":"Có chuyện quan trọng.","romaji":"taisetsu na koto ga arimasu."},{"ja":"友達と食事する","vi":"Ăn cơm với bạn","romaji":"Tomodachi to shokuji suru"},{"ja":"すぐに返事する","vi":"Trả lời ngay","romaji":"Suguni henji suru"},{"ja":"事務所で働く","vi":"Làm việc ở văn phòng","romaji":"Jimusho de hataraku"}]},{"key":"k:物","kind":"kanji","level":"N5","character":"物","meaning":"Vật, đồ","hanviet":"Vật","onReadings":["ブツ","モツ"],"kunReadings":["もの"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"食べ物","reading":"たべもの","meaning":"Đồ ăn","vocabKey":"v:食べ物"},{"compound":"買い物","reading":"かいもの","meaning":"Mua sắm","vocabKey":"v:買い物"},{"compound":"動物","reading":"どうぶつ","meaning":"Động vật","vocabKey":"v:動物"},{"compound":"荷物","reading":"にもつ","meaning":"Hành lý","vocabKey":"v:荷物"}],"lessonIds":[6,7,8,9,10,13,18,20,28,29,31,36,37,44],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 牛 (bò) + 勿 (chớ, đừng — 3 nét phẩy). Hán-Việt: VẬT. Mẹo nhớ: 🐂 Con bò (牛) là tài sản quý nhất thời cổ, đại diện cho 'vật', đồ vật. Phần 勿 gợi âm VẬT (butsu). Âm もの (mono) = đồ vật hàng ngày, ブツ (butsu) dùng trong từ ghép. Liên kết: 動物 (động vật), 食べ物 (đồ ăn), 買い物 (mua sắm), 荷物 (hành lý).","example":"買い**物**に行きます。 / kaimono ni ikimasu. (Tôi đi mua sắm.)","examples":[{"ja":"買い物に行きます。","vi":"Tôi đi mua sắm.","romaji":"kaimono ni ikimasu."},{"ja":"あの建物は何階建てですか","vi":"Tòa nhà đó có bao nhiêu tầng?","romaji":"ano tatemono wa nankaidate desu ka"},{"ja":"動物園に行く","vi":"Đi sở thú","romaji":"doubutsuen ni iku"},{"ja":"動物が好き","vi":"Thích động vật","romaji":"doubutsu ga suki"}]},{"key":"k:金","kind":"kanji","level":"N5","character":"金","meaning":"Tiền, vàng, kim loại","hanviet":"Kim","onReadings":["キン","コン"],"kunReadings":["かね"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"お金","reading":"おかね","meaning":"Tiền","vocabKey":"v:お金"},{"compound":"金曜日","reading":"きんようび","meaning":"Thứ Sáu","vocabKey":"v:金曜日"},{"compound":"金魚","reading":"きんぎょ","meaning":"Cá vàng"}],"lessonIds":[4,7,9,18,33,36,37,50],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 人 (người/mái che) + 王 (vua/ngọc) + 丷 (hai chấm = cục vàng). Hán-Việt: KIM. Mẹo nhớ: Dưới mái che (人), nhà vua (王) cất giấu vàng (丷) — đó là 'kim loại, tiền, vàng' 💰. Âm キン (kin) chính là 'kim'. Liên kết: お金 (tiền), 金曜日 (thứ Sáu = ngày Kim), 金魚 (cá vàng). 金 là bộ thủ quan trọng: 銀, 鉄, 銅 đều chứa 金.","example":"お**金**が足りません。 / okane ga tarimasen. (Không đủ tiền.)","examples":[{"ja":"お金が足りません。","vi":"Không đủ tiền.","romaji":"okane ga tarimasen."},{"ja":"金曜日は早く帰る","vi":"Thứ Sáu về sớm","romaji":"kinyoubi wa hayaku kaeru"},{"ja":"料金はいくらですか","vi":"Phí là bao nhiêu?","romaji":"ryoukin wa ikura desu ka"},{"ja":"税金を払う","vi":"Đóng thuế","romaji":"Zeikin wo harau"}]},{"key":"k:銀","kind":"kanji","level":"N5","character":"銀","meaning":"Bạc","hanviet":"Ngân","onReadings":["ギン"],"kunReadings":["-"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"銀行","reading":"ぎんこう","meaning":"Ngân hàng","vocabKey":"v:銀行"},{"compound":"銀色","reading":"ぎんいろ","meaning":"Màu bạc"}],"lessonIds":[1,4],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 金 (kim loại) + 艮 (cứng, giới hạn — âm ごん/gon). Hán-Việt: NGÂN. Mẹo nhớ: 金 Kim loại có tính 艮 cứng rắn, sáng bóng — đó là bạc (銀) 🪙. Nghĩ: 'ngân' hàng chứa bạc. Âm ギン (gin) gần 'ngân'. Liên kết: 銀行 (ngân hàng), 銀色 (màu bạc). ⚠️ Đừng nhầm 艮 với 良 (lương, tốt) — 艮 thiếu chấm ở trên.","example":"**銀**行でお金を出しました。 / ginkou de okane wo dashimashita. (Tôi rút tiền ở ngân hàng.)","examples":[{"ja":"銀行でお金を出しました。","vi":"Tôi rút tiền ở ngân hàng.","romaji":"ginkou de okane wo dashimashita."},{"ja":"銀行にお金を預ける","vi":"Gửi tiền ở ngân hàng","romaji":"ginkou ni okane o azukeru"},{"ja":"銀行の休みは土曜日と日曜日です。","vi":"Ngân hàng đóng cửa vào thứ bảy và chủ nhật.","romaji":"ginkou no yasumi wa doyoubi to nichiyoubi desu."},{"ja":"銀行からお金を借りました。","vi":"Tôi đã vay tiền từ ngân hàng.","romaji":"ginkou kara okane o karimashita."}]},{"key":"k:力","kind":"kanji","level":"N4","character":"力","meaning":"Sức mạnh, lực","hanviet":"Lực","onReadings":["リョク","リキ"],"kunReadings":["ちから"],"strokeCount":2,"radicals":[],"components":[],"compounds":[{"compound":"努力","reading":"どりょく","meaning":"Nỗ lực"},{"compound":"能力","reading":"のうりょく","meaning":"Năng lực"},{"compound":"体力","reading":"たいりょく","meaning":"Thể lực"}],"lessonIds":[28,35],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: Chữ tượng hình — hình cánh tay gồng cơ bắp 💪. Hán-Việt: LỰC. Mẹo nhớ: Chỉ 2 nét nhưng mạnh mẽ! Hình dung cánh tay đang gồng sức — đó là 'lực', sức mạnh. Âm リョク (ryoku) gần 'lực', リキ (riki) gần 'lịch' (sức lịch). Liên kết: 努力 (nỗ lực), 能力 (năng lực), 体力 (thể lực). 力 là bộ thủ quan trọng: 動 (động), 勉 (miễn), 助 (trợ) đều chứa 力.","example":"**力**が強いですね。 / chikara ga tsuyoi desu ne. (Khỏe nhỉ.)","examples":[{"ja":"力が強いですね。","vi":"Khỏe nhỉ.","romaji":"chikara ga tsuyoi desu ne."},{"ja":"力がある","vi":"Có sức mạnh","romaji":"Chikara ga aru"},{"ja":"日本語能力試験を受けようと思っています。","vi":"Tôi đang định thi năng lực tiếng Nhật.","romaji":"nihongo nouryoku shiken o ukeyo u to omotsute imasu."},{"ja":"日本語能力試験は毎年7月と12月に行われます。","vi":"Kỳ thi năng lực tiếng Nhật được tổ chức vào tháng 7 và tháng 12 hàng năm.","romaji":"nihongo nouryoku shiken wa maitoshi 7 tsuki to 12 tsuki ni okonawa remasu."}]},{"key":"k:世","kind":"kanji","level":"N5","character":"世","meaning":"Đời, thế giới","hanviet":"Thế","onReadings":["セイ","セ"],"kunReadings":["よ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"世界","reading":"せかい","meaning":"Thế giới","vocabKey":"v:世界"},{"compound":"世話","reading":"せわ","meaning":"Chăm sóc"}],"lessonIds":[12,25,36,37,48],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: Ba nét dọc nối bởi nét ngang — tượng trưng 3 thế hệ (ông → cha → con). Hán-Việt: THẾ. Mẹo nhớ: Ba thế hệ 👴👨👦 nối tiếp nhau tạo thành 'thế giới, đời người'. Mỗi thế hệ ~30 năm. Âm セイ (sei) gần 'thế'. Liên kết: 世界 (thế giới), 世話 (chăm sóc). ⚠️ Đừng nhầm với 出 (xuất) — 世 có nét ngang dọc đan xen, 出 có 2 ô vuông chồng lên.","example":"**世**界旅行がしたいです。 / sekai ryokou ga shitai desu. (Tôi muốn du lịch thế giới.)","examples":[{"ja":"世界旅行がしたいです。","vi":"Tôi muốn du lịch thế giới.","romaji":"sekai ryokou ga shitai desu."},{"ja":"動物の世話をする","vi":"Chăm sóc động vật","romaji":"doubutsu no sewa o suru"},{"ja":"世界旅行","vi":"Du lịch thế giới","romaji":"sekai ryokou"},{"ja":"いつもお世話になっています。","vi":"Lúc nào cũng cảm ơn anh/chị đã giúp đỡ.","romaji":"itsumo osewa ni natsute imasu."}]},{"key":"k:運","kind":"kanji","level":"N5","character":"運","meaning":"Vận, mang, vận may","hanviet":"Vận","onReadings":["ウン"],"kunReadings":["はこ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"運動","reading":"うんどう","meaning":"Vận động","vocabKey":"v:運動"},{"compound":"運転","reading":"うんてん","meaning":"Lái xe","vocabKey":"v:運転"},{"compound":"運ぶ","reading":"はこぶ","meaning":"Vận chuyển","vocabKey":"v:運ぶ"}],"lessonIds":[18,26,32,36,38],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 辶 (shinnyou, di chuyển) + 軍 (quân đội — có 車 xe + ワ mũ). Hán-Việt: VẬN. Mẹo nhớ: Cả đoàn 軍 quân đội hành quân di chuyển (辶) — đó là 'vận chuyển' 🚛. Nghĩa mở rộng: vận mệnh = số phận đang chuyển động. Âm ウン (un) gần 'vận'. Liên kết: 運動 (vận động), 運転 (lái xe), 運ぶ (vận chuyển).","example":"毎日**運**動しています。 / mainichi undou shite imasu. (Tôi tập thể dục mỗi ngày.)","examples":[{"ja":"毎日運動しています。","vi":"Tôi tập thể dục mỗi ngày.","romaji":"mainichi undou shite imasu."},{"ja":"荷物を運ぶ","vi":"Vận chuyển hàng","romaji":"Nimotsu wo hakobu"},{"ja":"車を運転する","vi":"Lái xe","romaji":"Kuruma wo unten suru"},{"ja":"毎朝運動する","vi":"Tập thể dục mỗi sáng","romaji":"maiasa undou suru"}]},{"key":"k:転","kind":"kanji","level":"N5","character":"転","meaning":"Chuyển, lăn","hanviet":"Chuyển","onReadings":["テン"],"kunReadings":["ころ","ころ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"運転","reading":"うんてん","meaning":"Lái xe","vocabKey":"v:運転"},{"compound":"自転車","reading":"じてんしゃ","meaning":"Xe đạp","vocabKey":"v:自転車"},{"compound":"転勤","reading":"てんきん","meaning":"Chuyển công tác","vocabKey":"v:転勤"}],"lessonIds":[5,18,25,46],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 車 (xe) + 云 (mây/nói — âm ウン). Hán-Việt: CHUYỂN. Mẹo nhớ: Bánh 車 xe quay tròn như 云 mây cuộn — đó là 'chuyển, lăn, xoay' 🔄. Âm テン (ten) = thiên chuyển. Liên kết: 運転 (lái xe = vận chuyển), 自転車 (xe đạp = xe tự chuyển), 転勤 (chuyển công tác). ⚠️ Đừng nhầm 転 (chuyển) với 伝 (truyền) — 転 có 車, 伝 có 亻.","example":"車を**運転**します。 / kuruma wo unten shimasu. (Tôi lái xe.)","examples":[{"ja":"車を運転します。","vi":"Tôi lái xe.","romaji":"kuruma wo unten shimasu."},{"ja":"道で転んだ","vi":"Ngã trên đường","romaji":"Michi de koron da"},{"ja":"車を運転する","vi":"Lái xe","romaji":"Kuruma wo unten suru"},{"ja":"バスの運転手","vi":"Tài xế xe buýt","romaji":"Basu no untenshu"}]},{"key":"k:色","kind":"kanji","level":"N4","character":"色","meaning":"Màu sắc","hanviet":"Sắc","onReadings":["ショク","シキ"],"kunReadings":["いろ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"色","reading":"いろ","meaning":"Màu","vocabKey":"v:色"},{"compound":"景色","reading":"けしき","meaning":"Cảnh sắc","vocabKey":"v:景色"},{"compound":"顔色","reading":"かおいろ","meaning":"Sắc mặt"}],"lessonIds":[27,28,34,37],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: ⺈ (đao/người cúi) + 巴 (quấn). Hán-Việt: SẮC. Mẹo nhớ: Người cúi mình (⺈) ngắm vải lụa cuộn (巴) đầy màu 'sắc' 🎨. Gốc: sắc đẹp, màu sắc. Chỉ 6 nét. Âm いろ (iro) thường dùng, シキ (shiki) trong từ ghép. Liên kết: 景色 (cảnh sắc), 顔色 (sắc mặt), 茶色 (màu nâu). ⚠️ Phần trên (⺈) viết trước, phần dưới (巴) viết sau.","example":"何**色**が好きですか。 / naniiro ga suki desu ka. (Bạn thích màu gì?)","examples":[{"ja":"何色が好きですか。","vi":"Bạn thích màu gì?","romaji":"nanishoku ga suki desu ka."},{"ja":"黄色い花","vi":"Hoa vàng","romaji":"Kiiroi hana"},{"ja":"茶色い靴を買った","vi":"Mua giày nâu","romaji":"chairoi kutsu o katsuta"},{"ja":"景色がきれいだ","vi":"Phong cảnh đẹp","romaji":"Keshiki gakireida"}]},{"key":"k:音","kind":"kanji","level":"N5","character":"音","meaning":"Âm thanh","hanviet":"Âm","onReadings":["オン","イン"],"kunReadings":["おと","ね"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"音楽","reading":"おんがく","meaning":"Âm nhạc","vocabKey":"v:音楽"},{"compound":"発音","reading":"はつおん","meaning":"Phát âm","vocabKey":"v:発音"}],"lessonIds":[9,23,41,42,48],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 立 (đứng) + 日 (mặt trời/miệng). Hán-Việt: ÂM. Mẹo nhớ: Đứng dậy (立) và mở miệng (日) phát ra 'âm' thanh 🔊. Âm オン (on) chính là 'âm' trong Hán-Việt! Liên kết: 音楽 (âm nhạc), 発音 (phát âm). ⚠️ Đừng nhầm với 意 (ý) — 音 có 立+日, còn 意 thêm 心 (tâm) ở dưới. Thêm 心 vào 音 → 意 (ý = âm thanh trong lòng).","example":"変な**音**が聞こえます。 / hen na oto ga kikoemasu. (Nghe thấy tiếng lạ.)","examples":[{"ja":"変な音が聞こえます。","vi":"Nghe thấy tiếng lạ.","romaji":"hen na oto ga kikoemasu."},{"ja":"発音を練習する","vi":"Luyện phát âm","romaji":"hatsuon o renshuu suru"},{"ja":"音楽を聞く","vi":"Nghe nhạc","romaji":"Ongaku wo kiku"},{"ja":"変な音がする","vi":"Có tiếng lạ","romaji":"Hen na oto ga suru"}]},{"key":"k:味","kind":"kanji","level":"N5","character":"味","meaning":"Vị, hương vị","hanviet":"Vị","onReadings":["ミ"],"kunReadings":["あじ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"味","reading":"あじ","meaning":"Vị","vocabKey":"v:味"},{"compound":"意味","reading":"いみ","meaning":"Ý nghĩa","vocabKey":"v:意味"},{"compound":"趣味","reading":"しゅみ","meaning":"Sở thích","vocabKey":"v:趣味"}],"lessonIds":[18,24,28,34,35,41],"topicTags":[],"sectionId":8,"sectionName":"ĐỜI SỐNG & XÃ HỘI","mnemonic":"Bộ/thành phần: 口 (miệng) + 未 (chưa — cây chưa mọc đủ). Hán-Việt: VỊ. Mẹo nhớ: 口 Miệng nếm thử thứ 未 chưa biết — đó là 'vị', hương vị 👅. Âm ミ (mi) gần 'mị' (hương vị quyến rũ). Liên kết: 意味 (ý vị = ý nghĩa), 趣味 (thú vị = sở thích), 味方 (đồng minh). ⚠️ Đừng nhầm 未 (chưa, ngang trên ngắn) với 末 (cuối, ngang trên dài).","example":"**味**はどうですか。 / aji wa dou desu ka. (Vị thế nào?)","examples":[{"ja":"味はどうですか。","vi":"Vị thế nào?","romaji":"aji wa dou desu ka."},{"ja":"この料理は美味しい","vi":"Món này ngon","romaji":"kono ryouri wa oishii"},{"ja":"地味な色が好き","vi":"Thích màu giản dị","romaji":"Jimi na iro ga suki"},{"ja":"味がいい","vi":"Vị ngon","romaji":"Aji gaii"}]},{"key":"k:大","kind":"kanji","level":"N5","character":"大","meaning":"Lớn","hanviet":"Đại","onReadings":["ダイ","タイ"],"kunReadings":["おお"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"大学","reading":"だいがく","meaning":"Đại học","vocabKey":"v:大学"},{"compound":"大切","reading":"たいせつ","meaning":"Quan trọng"},{"compound":"大変","reading":"たいへん","meaning":"Vất vả"}],"lessonIds":[1,4,8,13,17,21,25,27,31,34,35,36,38,39,40,45],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 大 là chữ tượng hình, vẽ hình người dang rộng hai tay. Mẹo nhớ: người (人) dang hai tay ra hết cỡ chỉ kích thước lớn — càng dang rộng càng lớn 🙆. Hán-Việt: Đại, như 'đại học', 'đại dương', 'vĩ đại'. Đối lập với 小 (tiểu/nhỏ). Là bộ thủ cơ bản, xuất hiện trong 夫 (phu/chồng), 天 (thiên/trời), 太 (thái/quá).","example":"**大**きい木があります。 / ookii ki ga arimasu. (Có cây to.)","examples":[{"ja":"大きい木があります。","vi":"Có cây to.","romaji":"ookii ki ga arimasu."},{"ja":"大きい家","vi":"Ngôi nhà lớn","romaji":"ookii ie"},{"ja":"大丈夫ですか","vi":"Bạn ổn không?","romaji":"daijoubu desu ka"},{"ja":"大切な人","vi":"Người quan trọng","romaji":"taisetsu na hito"}]},{"key":"k:小","kind":"kanji","level":"N5","character":"小","meaning":"Nhỏ","hanviet":"Tiểu","onReadings":["ショウ"],"kunReadings":["ちい","こ","お"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"小学校","reading":"しょうがっこう","meaning":"Tiểu học","vocabKey":"v:小学校"},{"compound":"小説","reading":"しょうせつ","meaning":"Tiểu thuyết","vocabKey":"v:小説"}],"lessonIds":[8,28,38,48],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 小 là chữ tượng hình, vẽ hình vật nhỏ bé bị chia tách. Mẹo nhớ: nét dọc ở giữa là vật thể, hai chấm hai bên là mảnh vụn rơi ra — càng chia nhỏ càng bé. Hán-Việt: Tiểu, như 'tiểu học' (小学校), 'tiểu thuyết'. Đối lập với 大 (đại/lớn). Là bộ thủ (しょう), xuất hiện trong 少 (thiếu/ít), 尖 (tiêm/nhọn). Âm on ショウ (shou).","example":"**小**さい犬がいます。 / chiisai inu ga imasu. (Có con chó nhỏ.)","examples":[{"ja":"小さい犬がいます。","vi":"Có con chó nhỏ.","romaji":"chiisai inu ga imasu."},{"ja":"小さい犬","vi":"Con chó nhỏ","romaji":"Chiisai inu"},{"ja":"小学校に入る","vi":"Vào tiểu học","romaji":"shougakkou ni hairu"},{"ja":"小説を読む","vi":"Đọc tiểu thuyết","romaji":"shousetsu o yomu"}]},{"key":"k:長","kind":"kanji","level":"N5","character":"長","meaning":"Dài, trưởng","hanviet":"Trường","onReadings":["チョウ"],"kunReadings":["なが"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"社長","reading":"しゃちょう","meaning":"Giám đốc","vocabKey":"v:社長"},{"compound":"部長","reading":"ぶちょう","meaning":"Trưởng phòng","vocabKey":"v:部長"}],"lessonIds":[16,18,22,40,47],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 長 là chữ tượng hình, vẽ hình người già tóc dài bay theo gió. Mẹo nhớ: nét nét trên cùng là mái tóc dài, phần dưới là thân người — tóc dài = người sống lâu = trưởng 🧓. Hán-Việt: Trường, như 'giám đốc' (社長 — xã trưởng), 'trưởng phòng' (部長). Nghĩa kép: 'dài' (ながい/nagai) và 'người đứng đầu' (chủ tịch/giám đốc). Đối lập với 短 (đoản/ngắn).","example":"この道は**長**いです。 / kono michi wa nagai desu. (Con đường này dài.)","examples":[{"ja":"この道は長いです。","vi":"Con đường này dài.","romaji":"kono michi wa nagai desu."},{"ja":"髪が長い","vi":"Tóc dài","romaji":"Kami ga nagai"},{"ja":"社長に会う","vi":"Gặp giám đốc","romaji":"shachou ni au"},{"ja":"部長に報告する","vi":"Báo cáo trưởng phòng","romaji":"buchou ni houkoku suru"}]},{"key":"k:短","kind":"kanji","level":"N5","character":"短","meaning":"Ngắn","hanviet":"Đoản","onReadings":["タン"],"kunReadings":["みじか"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"短い","reading":"みじかい","meaning":"Ngắn","vocabKey":"v:短い"},{"compound":"短期","reading":"たんき","meaning":"Ngắn hạn"}],"lessonIds":[16],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 矢 (mũi tên/thỉ) + 豆 (đậu/hạt đậu). Mẹo nhớ: mũi tên (矢) chỉ ngắn bằng hạt đậu (豆) → ngắn, cụt ↔️. Mũi tên ngắn thì không bay xa được. Hán-Việt: Đoản, như 'ngắn hạn' (短期 — tanki), 'đoản văn'. Đối lập với 長 (trường/dài). Phần 矢 cũng xuất hiện trong 知 (tri/biết), 医 (y/bác sĩ). Âm on タン (tan).","example":"髪が**短**いです。 / kami ga mijikai desu. (Tóc ngắn.)","examples":[{"ja":"髪が短いです。","vi":"Tóc ngắn.","romaji":"kami ga mijikai desu."},{"ja":"髪が短い","vi":"Tóc ngắn","romaji":"Kami ga mijikai"},{"ja":"髪を短くしてください。","vi":"Xin hãy cắt tóc ngắn đi cho tôi.","romaji":"kami o mijikaku shite kudasai."},{"ja":"短い","vi":"ngắn","romaji":"mijikai"}]},{"key":"k:高","kind":"kanji","level":"N5","character":"高","meaning":"Cao, đắt","hanviet":"Cao","onReadings":["コウ"],"kunReadings":["たか"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"高校","reading":"こうこう","meaning":"Trường cấp 3","vocabKey":"v:高校"},{"compound":"最高","reading":"さいこう","meaning":"Tuyệt vời nhất"}],"lessonIds":[8,15,16,35,40],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 高 là chữ tượng hình, vẽ hình tòa tháp canh/nhà cao tầng. Mẹo nhớ: phần trên 亠 là mái nhà, phần giữa là cửa sổ (口), phần dưới là nền móng — tòa nhà nhiều tầng vươn lên cao 🏢. Hán-Việt: Cao, như 'cao cấp', 'tối cao' (最高/saikou). Nghĩa kép: 'cao' và 'đắt tiền' (たかい/takai). Đối lập với 低 (đê/thấp). Là bộ thủ (たかい), xuất hiện trong 髪 (phát/tóc).","example":"この建物は**高**いです。 / kono tatemono wa takai desu. (Tòa nhà này cao.)","examples":[{"ja":"この建物は高いです。","vi":"Tòa nhà này cao.","romaji":"kono tatemono wa takai desu."},{"ja":"値段が高い","vi":"Giá đắt","romaji":"Nedan ga takai"},{"ja":"今日の最高気温は三十度です","vi":"Nhiệt độ cao nhất hôm nay là 30 độ","romaji":"kyou no saikou kion wa san juudo desu"},{"ja":"高校に通う","vi":"Đi học THPT","romaji":"koukou ni kayou"}]},{"key":"k:低","kind":"kanji","level":"N5","character":"低","meaning":"Thấp","hanviet":"Đê","onReadings":["テイ"],"kunReadings":["ひく"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"低い","reading":"ひくい","meaning":"Thấp","vocabKey":"v:低い"},{"compound":"最低","reading":"さいてい","meaning":"Tệ nhất"}],"lessonIds":[8],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 亻(người) + 氐 (nền móng/gốc). Mẹo nhớ: người (亻) cúi xuống sát nền (氐) → thấp. Phần 氐 gợi hình người khôm xuống, và cho âm テイ (tei). Hán-Việt: Đê, như 'đê thấp', 'tối đê' (最低/saitei — tệ nhất). Đối lập với 高 (cao): 高 là tòa nhà vươn lên, 低 là người cúi xuống. Âm kun ひくい (hikui).","example":"今日は気温が**低**いです。 / kyou wa kion ga hikui desu. (Hôm nay nhiệt độ thấp.)","examples":[{"ja":"今日は気温が低いです。","vi":"Hôm nay nhiệt độ thấp.","romaji":"kyou wa kion ga hikui desu."},{"ja":"山が低い","vi":"Núi thấp","romaji":"Yama ga hikui"},{"ja":"明日の最低気温は五度です","vi":"Nhiệt độ thấp nhất ngày mai là 5 độ","romaji":"Ashita no saitei kion wa godo de su"},{"ja":"温度を低くします。","vi":"Tôi hạ nhiệt độ xuống.","romaji":"ondo o hikuku shimasu."}]},{"key":"k:強","kind":"kanji","level":"N5","character":"強","meaning":"Mạnh","hanviet":"Cường","onReadings":["キョウ","ゴウ"],"kunReadings":["つよ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"強い","reading":"つよい","meaning":"Mạnh","vocabKey":"v:強い"},{"compound":"勉強","reading":"べんきょう","meaning":"Học","vocabKey":"v:勉強"}],"lessonIds":[4,19],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 弓 (cánh cung) + 厶 (biến thể của 虫 côn trùng — 禾+虫). Mẹo nhớ: cánh cung (弓) căng cứng như con bọ cứng cáp — sức mạnh dẻo dai như côn trùng, mạnh mẽ như cung 🏹. Hán-Việt: Cường, như 'cường đại', 'kiên cường', 'miễn cưỡng' (勉強/benkyou — học). Đối lập với 弱 (nhược/yếu). Âm on キョウ (kyou) và ゴウ (gou — cưỡng độ).","example":"風が**強**いです。 / kaze ga tsuyoi desu. (Gió mạnh.)","examples":[{"ja":"風が強いです。","vi":"Gió mạnh.","romaji":"kaze ga tsuyoi desu."},{"ja":"風が強い","vi":"Gió mạnh","romaji":"Kaze ga tsuyoi"},{"ja":"勉強が大変だ","vi":"Học vất vả","romaji":"benkyou ga taihen da"},{"ja":"外国語を勉強する","vi":"Học ngoại ngữ","romaji":"gaikokugo o benkyou suru"}]},{"key":"k:弱","kind":"kanji","level":"N5","character":"弱","meaning":"Yếu","hanviet":"Nhược","onReadings":["ジャク"],"kunReadings":["よわ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"弱い","reading":"よわい","meaning":"Yếu","vocabKey":"v:弱い"},{"compound":"弱点","reading":"じゃくてん","meaning":"Điểm yếu"}],"lessonIds":[19],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: hai cánh cung 弓弓 với điểm trang trí (冫). Mẹo nhớ: hai cánh cung bị gãy, mất sức căng → yếu đuối 🏹⬇️. Cung gãy thì không bắn được, mất đi sức mạnh. Hán-Việt: Nhược, như 'nhược điểm' (弱点 — điểm yếu), 'nhu nhược'. Đối lập với 強 (cường/mạnh): 強 cung căng cứng, 弱 cung gãy gục. Âm on ジャク (jaku), kun よわい (yowai).","example":"体が**弱**いです。 / karada ga yowai desu. (Cơ thể yếu.)","examples":[{"ja":"体が弱いです。","vi":"Cơ thể yếu.","romaji":"karada ga yowai desu."},{"ja":"体が弱い","vi":"Cơ thể yếu","romaji":"Karada ga yowai"},{"ja":"弱い","vi":"yếu","romaji":"yowai"}]},{"key":"k:明","kind":"kanji","level":"N5","character":"明","meaning":"Sáng, rõ ràng","hanviet":"Minh","onReadings":["メイ","ミョウ"],"kunReadings":["あか","あ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"明日","reading":"あした","meaning":"Ngày mai","vocabKey":"v:明日"},{"compound":"説明","reading":"せつめい","meaning":"Giải thích","vocabKey":"v:説明"},{"compound":"明るい","reading":"あかるい","meaning":"Sáng","vocabKey":"v:明るい"}],"lessonIds":[16,24,34,37,50],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 月 (mặt trăng). Mẹo nhớ: có cả mặt trời (日) lẫn mặt trăng (月) chiếu sáng cùng lúc — mọi thứ sáng rực, không còn bóng tối ☀️🌙. Hán-Việt: Minh, như 'minh bạch', 'văn minh', 'giải thích' (説明/setsumei). Đối lập với 暗 (ám/tối). Nhiều âm: メイ (mei) trong 説明, ミョウ (myou) trong 明日 (đọc は ashita hoặc myounichi).","example":"**明**るい部屋が好きです。 / akarui heya ga suki desu. (Tôi thích phòng sáng.)","examples":[{"ja":"明るい部屋が好きです。","vi":"Tôi thích phòng sáng.","romaji":"akarui heya ga suki desu."},{"ja":"理由を説明する","vi":"Giải thích lý do","romaji":"riyuu o setsumei suru"},{"ja":"部屋が明るい","vi":"Phòng sáng","romaji":"Heya ga akarui"},{"ja":"明日学校がある","vi":"Ngày mai có trường","romaji":"ashita gakkou ga aru"}]},{"key":"k:暗","kind":"kanji","level":"N5","character":"暗","meaning":"Tối","hanviet":"Ám","onReadings":["アン"],"kunReadings":["くら"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"暗い","reading":"くらい","meaning":"Tối","vocabKey":"v:暗い"},{"compound":"暗記","reading":"あんき","meaning":"Thuộc lòng"}],"lessonIds":[16],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 音 (âm thanh). Mẹo nhớ: khi mặt trời (日) lặn, chỉ còn nghe âm thanh (音) mà không thấy gì → tối 🌑. Trong bóng tối chỉ dựa vào tai, không dựa được vào mắt. Hán-Việt: Ám, như 'ám sát' (giết trong bóng tối), 'ám thị' (ngầm chỉ). Nghĩa mở rộng: 暗記 (anki) = học thuộc lòng (nhớ trong tối, không cần sách). Đối lập với 明 (minh/sáng).","example":"この部屋は窓が小さくて、昼でも**暗**いです。 / kono heya wa mado ga chiisakute, hiru demo kurai desu. (Phòng này cửa sổ nhỏ nên ban ngày cũng tối.)","examples":[{"ja":"この部屋は窓が小さくて、昼でも暗いです。","vi":"Phòng này cửa sổ nhỏ nên ban ngày cũng tối.","romaji":"kono heya wa mado ga chiisakute, hiru demo kurai desu."},{"ja":"部屋が暗い","vi":"Phòng tối","romaji":"Heya ga kurai"},{"ja":"暗くて何も見えません。","vi":"Tối quá nên không nhìn thấy gì.","romaji":"kurakute nani mo miemasen."},{"ja":"暗くなれば、寒くなります。","vi":"Nếu trời tối thì sẽ lạnh.","romaji":"kuraku nare ba, samuku narimasu."}]},{"key":"k:重","kind":"kanji","level":"N5","character":"重","meaning":"Nặng, quan trọng","hanviet":"Trọng","onReadings":["ジュウ","チョウ"],"kunReadings":["おも","かさ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"体重","reading":"たいじゅう","meaning":"Cân nặng"},{"compound":"重要","reading":"じゅうよう","meaning":"Quan trọng"}],"lessonIds":[12,40],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 重 là chữ tượng hình, vẽ hình người vác bao nặng trên đầu. Mẹo nhớ: nét ngang trên là bao hàng, phần giữa là thân người còng lưng, nét dưới là mặt đất — gánh nặng đè xuống 🏋️. Hán-Việt: Trọng, như 'trọng lượng' (体重), 'quan trọng' (重要). Nghĩa kép: 'nặng' và 'quan trọng'. Đối lập với 軽 (khinh/nhẹ). Xuất hiện trong 動 (động) = 重+力.","example":"この荷物は**重**いです。 / kono nimotsu wa omoi desu. (Hành lý này nặng.)","examples":[{"ja":"この荷物は重いです。","vi":"Hành lý này nặng.","romaji":"kono nimotsu wa omoi desu."},{"ja":"荷物が重い","vi":"Hành lý nặng","romaji":"Nimotsu ga omoi"},{"ja":"荷物の重さを量る","vi":"Cân trọng lượng hành lý","romaji":"Nimotsu no omosa wo hakaru"},{"ja":"この荷物の重さは10キロです。","vi":"Kiện hàng này nặng 10 ký.","romaji":"kono nimotsu no omosa wa 10kiro desu."}]},{"key":"k:軽","kind":"kanji","level":"N5","character":"軽","meaning":"Nhẹ","hanviet":"Khinh","onReadings":["ケイ"],"kunReadings":["かる"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"軽い","reading":"かるい","meaning":"Nhẹ","vocabKey":"v:軽い"},{"compound":"軽食","reading":"けいしょく","meaning":"Bữa ăn nhẹ"}],"lessonIds":[12],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 車 (xe) + 圣 (biến thể, gợi âm/nhẹ). Mẹo nhớ: chiếc xe (車) chạy nhẹ nhàng, không chở nặng → nhẹ 🚗✨. Phần 圣 cho âm ケイ (kei). Hán-Việt: Khinh, như 'khinh thường' (coi nhẹ), 'khinh suất'. Đối lập với 重 (trọng/nặng): 軽 không gánh nặng, 重 đè xuống. Nghĩa mở rộng: 軽食 (keishoku — bữa ăn nhẹ). Âm kun かるい (karui).","example":"このかばんは**軽**いです。 / kono kaban wa karui desu. (Túi này nhẹ.)","examples":[{"ja":"このかばんは軽いです。","vi":"Túi này nhẹ.","romaji":"kono kaban wa karui desu."},{"ja":"かばんが軽い","vi":"Túi nhẹ","romaji":"Kabanga karui"},{"ja":"この靴は軽くて歩きやすいです。","vi":"Đôi giày này nhẹ nên đi rất dễ.","romaji":"kono kutsu wa karukute aruki yasui desu."}]},{"key":"k:広","kind":"kanji","level":"N5","character":"広","meaning":"Rộng","hanviet":"Quảng","onReadings":["コウ"],"kunReadings":["ひろ","ひろ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"広い","reading":"ひろい","meaning":"Rộng","vocabKey":"v:広い"},{"compound":"広告","reading":"こうこく","meaning":"Quảng cáo","vocabKey":"v:広告"}],"lessonIds":[13],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: giản thể của 廣. 广 (mái nhà/nghiễm) + 厶 (tư, biến thể). Mẹo nhớ: dưới mái nhà (广) không gian trống rộng, không có gì chắn → rộng rãi 🏞️. Hán-Việt: Quảng, như 'quảng cáo' (広告/koukoku), 'quảng đại'. Đối lập với 狭 (hiệp/hẹp). Bộ 广 (まだれ) là mái nhà/vách nghiêng, cũng xuất hiện trong 店 (điếm/cửa hàng), 座 (tọa/chỗ ngồi).","example":"この公園は**広**いです。 / kono kouen wa hiroi desu. (Công viên này rộng.)","examples":[{"ja":"この公園は広いです。","vi":"Công viên này rộng.","romaji":"kono kouen wa hiroi desu."},{"ja":"部屋が広い","vi":"Phòng rộng","romaji":"Heya ga hiroi"},{"ja":"テレビで新しい広告を見ました","vi":"Xem quảng cáo mới trên TV","romaji":"terebi de atarashii koukoku o mimashita"},{"ja":"部屋の広さがちょうどいい","vi":"Độ rộng của phòng vừa vặn","romaji":"heya no hirosa ga choudo ii"}]},{"key":"k:狭","kind":"kanji","level":"N5","character":"狭","meaning":"Hẹp, chật","hanviet":"Hiệp","onReadings":["キョウ"],"kunReadings":["せま"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"狭い","reading":"せまい","meaning":"Hẹp","vocabKey":"v:狭い"}],"lessonIds":[13],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 犭 (chó/khển) + 夹 (kẹp/giữa). Mẹo nhớ: con chó (犭) bị kẹp (夹) giữa hai bức tường → chật hẹp, không xoay xở được 🐕. Phần 夹 cho âm キョウ (kyou). Hán-Việt: Hiệp, như 'hiệp hẹp', 'hiệp tràng' (phường hẹp). Đối lập với 広 (quảng/rộng): 狭 bị kẹp chặt, 広 thêng thêng rộng. Bộ 犭 (けものへん) là bộ chó, cũng trong 犬 (khển/chó), 猫 (miêu/mèo).","example":"一人で住むには、この部屋は少し**狭**いです。 / hitori de sumu ni wa, kono heya wa sukoshi semai desu. (Để ở một mình thì căn phòng này hơi chật.)","examples":[{"ja":"一人で住むには、この部屋は少し狭いです。","vi":"Để ở một mình thì căn phòng này hơi chật.","romaji":"ichinin de sumu ni wa, kono heya wa sukoshi semai desu."},{"ja":"部屋が狭い","vi":"Phòng chật","romaji":"Heya ga semai"},{"ja":"狭い","vi":"chật, hẹp","romaji":"semai"}]},{"key":"k:新","kind":"kanji","level":"N5","character":"新","meaning":"Mới","hanviet":"Tân","onReadings":["シン"],"kunReadings":["あたら","あら"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"新聞","reading":"しんぶん","meaning":"Báo","vocabKey":"v:新聞"},{"compound":"新幹線","reading":"しんかんせん","meaning":"Shinkansen","vocabKey":"v:新幹線"},{"compound":"新しい","reading":"あたらしい","meaning":"Mới","vocabKey":"v:新しい"}],"lessonIds":[2,5,8,31,40],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 亲 (thân/cây non — 立+木) + 斤 (rìu/dao). Mẹo nhớ: dùng rìu (斤) chặt cây (亲 biến thể của 木) — bóc lớp vỏ cũ lộ ra lõi gỗ mới tinh → mới 🌲✨. Hán-Việt: Tân, như 'tân văn' (新聞 — báo/tin mới), 'cách tân', 'tân niên' (年 mới). Đối lập với 古 (cổ/cũ). Bộ 斤 (おのづくり) = rìu, cũng trong 新, 断 (đoạn/cắt), 所 (sở/nơi).","example":"**新**しい車を買いました。 / atarashii kuruma wo kaimashita. (Tôi đã mua xe mới.)","examples":[{"ja":"新しい車を買いました。","vi":"Tôi đã mua xe mới.","romaji":"atarashii kuruma wo kaimashita."},{"ja":"新しい服を買った","vi":"Mua quần áo mới","romaji":"atarashii fuku o katsuta"},{"ja":"新幹線で東京に行く","vi":"Đi Tokyo bằng Shinkansen","romaji":"shinkansen de toukyou ni iku"},{"ja":"新聞を読む","vi":"Đọc báo","romaji":"Shinbun wo yomu"}]},{"key":"k:古","kind":"kanji","level":"N5","character":"古","meaning":"Cũ, xưa","hanviet":"Cổ","onReadings":["コ"],"kunReadings":["ふる"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"古い","reading":"ふるい","meaning":"Cũ","vocabKey":"v:古い"},{"compound":"中古","reading":"ちゅうこ","meaning":"Đồ cũ"}],"lessonIds":[8],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 十 (mười/thập) + 口 (miệng). Mẹo nhớ: mười (十) thế hệ truyền miệng (口) lại câu chuyện → xưa cũ, cổ đại 📜. Những gì qua mười đời kể lại đều là thứ cổ xưa. Hán-Việt: Cổ, như 'cổ đại', 'trung cổ' (中古 — đồ cũ), 'cổ điển'. Đối lập với 新 (tân/mới). Âm on コ (ko), kun ふるい (furui).","example":"この建物は**古**いです。 / kono tatemono wa furui desu. (Tòa nhà này cũ.)","examples":[{"ja":"この建物は古いです。","vi":"Tòa nhà này cũ.","romaji":"kono tatemono wa furui desu."},{"ja":"古い建物","vi":"Tòa nhà cũ","romaji":"Furui tatemono"},{"ja":"奈良はどんな町ですか。……古い町です。","vi":"Nara là thành phố như thế nào? Là thành phố cổ kính.","romaji":"nara wa donna machi desu ka....... furui machi desu."},{"ja":"この地図は古いかもしれません。","vi":"Bản đồ này có thể đã cũ.","romaji":"kono chizu wa furui kamo shiremasen."}]},{"key":"k:白","kind":"kanji","level":"N5","character":"白","meaning":"Trắng","hanviet":"Bạch","onReadings":["ハク","ビャク"],"kunReadings":["しろ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"白い","reading":"しろい","meaning":"Trắng","vocabKey":"v:白い"},{"compound":"白紙","reading":"はくし","meaning":"Giấy trắng"}],"lessonIds":[8,34,41],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 白 là chữ tượng hình, nguồn gốc vẽ hạt quả dẻp/hạt gạo trắng. Mẹo nhớ: hình như tia nắng (一) chiếu vào vật (日 biến thể) — ánh sáng phản chiếu màu trắng tinh khiết ⬜️. Hán-Việt: Bạch, như 'minh bạch', 'bạch kim', 'trắng bạch' (白紙/hakushi — giấy trắng). Là bộ thủ (しろ), xuất hiện trong 百 (bách/trăm), 的 (đích/mục tiêu). Đối lập với 黒 (hắc/đen).","example":"**白**い花が咲いています。 / shiroi hana ga saite imasu. (Hoa trắng đang nở.)","examples":[{"ja":"白い花が咲いています。","vi":"Hoa trắng đang nở.","romaji":"shiroi hana ga saite imasu."},{"ja":"映画が面白い","vi":"Phim thú vị","romaji":"Eiga ga omoshiroi"},{"ja":"白い花がきれい","vi":"Hoa trắng đẹp","romaji":"Shiroi hana gakirei"},{"ja":"白い雲","vi":"Mây trắng","romaji":"Shiroi kumo"}]},{"key":"k:黒","kind":"kanji","level":"N5","character":"黒","meaning":"Đen","hanviet":"Hắc","onReadings":["コク"],"kunReadings":["くろ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"黒い","reading":"くろい","meaning":"Đen","vocabKey":"v:黒い"},{"compound":"黒板","reading":"こくばん","meaning":"Bảng đen","vocabKey":"v:黒板"}],"lessonIds":[8,34,35],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 里 (lý/làng — 田+土) + 灬 (lửa — 4 chấm lửa). Mẹo nhớ: lửa (灬) đốt cháy mọi thứ trong làng (里) thành than đen → đen 🔥⬛. Muội khói bám đen sì mọi nơi. Hán-Việt: Hắc, như 'hắc ám' (tối đen), 'hắc bảng' (黒板/kokuban — bảng đen). Đối lập với 白 (bạch/trắng). Bộ 灬 (れっか/れんが) là lửa, cũng ở dưới: 煎 (tiên/chiên), 照 (chiếu/sáng).","example":"**黒**い猫がいます。 / kuroi neko ga imasu. (Có con mèo đen.)","examples":[{"ja":"黒い猫がいます。","vi":"Có con mèo đen.","romaji":"kuroi neko ga imasu."},{"ja":"黒い猫が好き","vi":"Thích mèo đen","romaji":"Kuroi neko ga suki"},{"ja":"黒板に書く","vi":"Viết lên bảng","romaji":"Kokuban ni kaku"},{"ja":"黒い猫","vi":"Mèo đen","romaji":"Kuroi neko"}]},{"key":"k:赤","kind":"kanji","level":"N5","character":"赤","meaning":"Đỏ","hanviet":"Xích","onReadings":["セキ"],"kunReadings":["あか"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"赤い","reading":"あかい","meaning":"Đỏ","vocabKey":"v:赤い"},{"compound":"赤ちゃん","reading":"あかちゃん","meaning":"Em bé","vocabKey":"v:赤ちゃん"}],"lessonIds":[8,34,38],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 大 (lớn) + 火 (lửa, biến thể ở dưới). Mẹo nhớ: ngọn lửa (火) lớn (大) bùng cháy → màu đỏ rực 🔥. Đám cháy lớn toả sắc đỏ. Hán-Việt: Xích, như 'xích đạo' (vùng đỏ dưới xích đạo), 'xích lạp' (trần truồng). Nghĩa mở rộng: 赤ちゃん (akachan — em bé, vì da đỏ hồng). Âm on セキ (seki), kun あかい (akai). Là bộ thủ, xuất hiện trong 赫 (hách/rực rỡ).","example":"信号が**赤**の間は、道路を渡ってはいけません。 / shingou ga aka no aida wa, douro wo watatte wa ikemasen. (Khi đèn đỏ thì không được băng qua đường.)","examples":[{"ja":"信号が赤の間は、道路を渡ってはいけません。","vi":"Khi đèn đỏ thì không được băng qua đường.","romaji":"shingou ga aka no ma wa, douro o watatsute wa ikemasen."},{"ja":"赤い靴を履く","vi":"Mang giày đỏ","romaji":"Akaikutsu wo haku"},{"ja":"赤ちゃんが泣く","vi":"Em bé khóc","romaji":"Akachan ga naku"},{"ja":"赤い花が咲いている","vi":"Hoa đỏ đang nở","romaji":"Akai hana ga saiteiru"}]},{"key":"k:青","kind":"kanji","level":"N5","character":"青","meaning":"Xanh (lam/ lục)","hanviet":"Thanh","onReadings":["セイ"],"kunReadings":["あお"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"青い","reading":"あおい","meaning":"Xanh","vocabKey":"v:青い"},{"compound":"青年","reading":"せいねん","meaning":"Thanh niên"}],"lessonIds":[8,34],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 青 (sinh/mọc lên, biến thể bên trên) + 月 (mặt trăng). Mẹo nhớ: cây cỏ mọc lên (生 biến thể) dưới ánh trăng (月) → màu xanh tươi tốt của cây cỏ, màu xanh của bầu trời 💙. Hán-Việt: Thanh, như 'thanh niên' (青年), 'thanh xuân', 'thanh thiên' (bầu trời xanh). Trong tiếng Nhật 青 bao gồm cả xanh lam và xanh lục (đèn xanh giao thông gọi là 青信号). Âm on セイ (sei).","example":"台風のあとで、空が**青**く澄んでいます。 / taifuu no ato de, sora ga aoku sunde imasu. (Sau bão, bầu trời trong xanh.)","examples":[{"ja":"台風のあとで、空が青く澄んでいます。","vi":"Sau bão, bầu trời trong xanh.","romaji":"taifuu no ato de, sora ga aoku sunde imasu."},{"ja":"青い空がきれい","vi":"Trời xanh đẹp","romaji":"Aoi sora gakirei"},{"ja":"空が青い","vi":"Trời xanh","romaji":"Sora ga aoi"},{"ja":"青","vi":"màu xanh (danh từ)","romaji":"ao"}]},{"key":"k:早","kind":"kanji","level":"N5","character":"早","meaning":"Sớm","hanviet":"Tảo","onReadings":["ソウ"],"kunReadings":["はや"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"早い","reading":"はやい","meaning":"Sớm","vocabKey":"v:早い"},{"compound":"早朝","reading":"そうちょう","meaning":"Sáng sớm"}],"lessonIds":[9,12],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 十 (mười). Mẹo nhớ: mặt trời (日) vừa nhô lên đường chân trời (十 như giá đỡ nâng mặt trời) → buổi sáng sớm 🌅. Mặt trời mới mọc là lúc sớm nhất trong ngày. Hán-Việt: Tảo, như 'tảo triêu' (早朝 — sáng sớm), 'tảo thục'. ⚠️ Dễ nhầm với 草 (thảo/cỏ) có bộ 艸 ở trên: 早 không có 艸 = sớm; 草 có 艸 = cỏ. Âm kun はやい (hayai).","example":"**早**く起きます。 / hayaku okimasu. (Tôi dậy sớm.)","examples":[{"ja":"早く起きます。","vi":"Tôi dậy sớm.","romaji":"hayaku okimasu."},{"ja":"朝早い","vi":"Sáng sớm","romaji":"Asahayai"},{"ja":"早く起きる","vi":"Dậy sớm","romaji":"Hayaku okiru"},{"ja":"きょうは早く帰ります。……どうしてですか。子どもの誕生日ですから。","vi":"Hôm nay tôi sẽ về sớm. Tại sao? Vì hôm nay là sinh nhật con tôi.","romaji":"kyou wa hayaku kaerimasu....... doushite desu ka. kodomo no tanjoubi desu kara."}]},{"key":"k:遅","kind":"kanji","level":"N5","character":"遅","meaning":"Muộn, chậm","hanviet":"Trì","onReadings":["チ"],"kunReadings":["おそ","おく"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"遅い","reading":"おそい","meaning":"Chậm","vocabKey":"v:遅い"},{"compound":"遅刻","reading":"ちこく","meaning":"Đi trễ"}],"lessonIds":[12,26,32],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 辶 (chuyển động/sước) + 尸 (thân người) + 牛 (trâu, biến thể). Mẹo nhớ: di chuyển (辶) chậm chạp như trâu (牛) kéo thân (尸) lê thê → muộn, chậm 🐂. Ai đi chậm như trâu thì sẽ muộn giờ. Hán-Việt: Trì, như 'trì hoãn', 'trì trệ'. Nghĩa mở rộng: 遅刻 (chikoku — đi trễ). Âm kun おそい (osoi) = chậm, おくれる (okureru) = muộn.","example":"**遅**くなってすみません。 / osoku natte sumimasen. (Xin lỗi vì đến trễ.)","examples":[{"ja":"遅くなってすみません。","vi":"Xin lỗi vì đến trễ.","romaji":"osoku natsute sumimasen."},{"ja":"授業に遅刻する","vi":"Đi học trễ","romaji":"jugyou ni chikoku suru"},{"ja":"電車が遅い","vi":"Tàu chậm","romaji":"Densha ga osoi"},{"ja":"約束時間に遅れないでください","vi":"Đừng trễ giờ hẹn","romaji":"Yakusoku jikan ni okure naidekudasai"}]},{"key":"k:近","kind":"kanji","level":"N5","character":"近","meaning":"Gần","hanviet":"Cận","onReadings":["キン"],"kunReadings":["ちか"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"近く","reading":"ちかく","meaning":"Gần đây","vocabKey":"v:近く"},{"compound":"最近","reading":"さいきん","meaning":"Gần đây","vocabKey":"v:最近"}],"lessonIds":[10,12,21,35],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 辶 (di chuyển/sước) + 斤 (rìu). Mẹo nhớ: chỉ cần đi (辶) một quãng ngắn như tầm ném rìu (斤) là tới → gần 📍. Rìu ném không xa, vậy nên gần. Hán-Việt: Cận, như 'phụ cận' (gần đây), 'cận thị' (mắt nhìn gần), 'gần đây' (最近/saikin). Đối lập với 遠 (viễn/xa). Bộ 辶 (しんにょう) chỉ chuyển động, cũng trong 送, 遠, 達.","example":"このアパートは駅が**近**くて、とても便利です。 / kono apaato wa eki ga chikakute, totemo benri desu. (Căn hộ này gần ga nên rất tiện.)","examples":[{"ja":"このアパートは駅が近くて、とても便利です。","vi":"Căn hộ này gần ga nên rất tiện.","romaji":"kono apaato wa eki ga chikakute, totemo benri desu."},{"ja":"駅が近い","vi":"Ga gần","romaji":"Eki ga chikai"},{"ja":"近所の人と話す","vi":"Nói chuyện với hàng xóm","romaji":"Kinjo no hito to hanasu"},{"ja":"最近忙しい","vi":"Gần đây bận","romaji":"Saikin'isogashi i"}]},{"key":"k:遠","kind":"kanji","level":"N5","character":"遠","meaning":"Xa","hanviet":"Viễn","onReadings":["エン"],"kunReadings":["とお"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"遠い","reading":"とおい","meaning":"Xa","vocabKey":"v:遠い"},{"compound":"遠足","reading":"えんそく","meaning":"Dã ngoại"}],"lessonIds":[12,36],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 辶 (di chuyển) + 袁. Mẹo nhớ: phải đi một quãng đường dài mới đến, nên nhớ nghĩa 'xa'.","example":"新しい学校は前の学校より**遠**いです。 / atarashii gakkou wa mae no gakkou yori tooi desu. (Trường mới xa hơn trường cũ.)","examples":[{"ja":"新しい学校は前の学校より遠いです。","vi":"Trường mới xa hơn trường cũ.","romaji":"atarashii gakkou wa mae no gakkou yori tooi desu."},{"ja":"学校が遠い","vi":"Trường xa","romaji":"gakkou ga tooi"},{"ja":"遠くに山が見える","vi":"Xa xa thấy núi","romaji":"tooku ni yama ga mieru"},{"ja":"遠慮なく食べてください。","vi":"Cứ tự nhiên ăn nhé.","romaji":"Enryo naku tabete kudasai."}]},{"key":"k:正","kind":"kanji","level":"N5","character":"正","meaning":"Đúng, chính","hanviet":"Chính","onReadings":["セイ","ショウ"],"kunReadings":["ただ","まさ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"正しい","reading":"ただしい","meaning":"Đúng","vocabKey":"v:正しい"},{"compound":"正月","reading":"しょうがつ","meaning":"Tết","vocabKey":"v:正月"},{"compound":"正確","reading":"せいかく","meaning":"Chính xác"}],"lessonIds":[23,35],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 一 (một/đường kẻ) + 止 (dừng/bàn chân). Mẹo nhớ: bàn chân (止) dừng đúng trên vạch kẻ (一) — đi thẳng, không lệch → đúng, chính xác ✅. Người đi đúng đường là người chính trực. Hán-Việt: Chính, như 'chính xác' (正確), 'chính nghĩa', 'chính nguyệt' (正月/Tết). Nhiều âm: セイ (sei) trong 正確, ショウ (shou) trong 正月. Liên quan: 政 (chính/chính trị), 証 (chứng).","example":"**正**しい答えはどれですか。 / tadashii kotae wa dore desu ka. (Đáp án đúng là đáp án nào?)","examples":[{"ja":"正しい答えはどれですか。","vi":"Đáp án đúng là đáp án nào?","romaji":"tadashii kotae wa dore desu ka."},{"ja":"答えが正しい","vi":"Đáp án đúng","romaji":"Kotae ga tadashii"},{"ja":"正確な時間","vi":"Thời gian chính xác","romaji":"Seikaku na jikan"},{"ja":"正月に家族で初詣に行きます","vi":"Dịp Tết đi lễ đầu năm","romaji":"shougatsu ni kazoku de hatsumoude ni ikimasu"}]},{"key":"k:悪","kind":"kanji","level":"N5","character":"悪","meaning":"Xấu, ác","hanviet":"Ác","onReadings":["アク"],"kunReadings":["わる"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"悪い","reading":"わるい","meaning":"Xấu","vocabKey":"v:悪い"},{"compound":"悪天候","reading":"あくてんこう","meaning":"Thời tiết xấu"}],"lessonIds":[8,19,26,38,44],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 亜 (nhị/hạng hai — biến thể) + 心 (trái tim). Mẹo nhớ: trái tim (心) hạng hai (亜 — không bằng hạng nhất) → xấu, tồi tệ, ác độc 💔. Tâm hồn không sáng trong thì là ác. Hán-Việt: Ác, như 'ác nhân' (người xấu), 'ác nghệp', 'ác thiên hậu' (悪天候 — thời tiết xấu). Âm on アク (aku), kun わるい (warui). Liên quan: 亜 (á châu) cũng đọc ア (a).","example":"天気が**悪**いです。 / tenki ga warui desu. (Thời tiết xấu.)","examples":[{"ja":"天気が悪いです。","vi":"Thời tiết xấu.","romaji":"tenki ga warui desu."},{"ja":"天気が悪い","vi":"Thời tiết xấu","romaji":"Tenki ga warui"},{"ja":"体の調子が悪いんですが、どうすればいいですか。","vi":"Tôi không khỏe, nên làm gì?","romaji":"karada no choushi ga warui n desu ga, dou sure ba ii desu ka."},{"ja":"電車の中で本を読むのは目に悪いです。","vi":"Đọc sách trên tàu điện thì hại mắt.","romaji":"densha no naka de hon o yomu no wa me ni warui desu."}]},{"key":"k:楽","kind":"kanji","level":"N5","character":"楽","meaning":"Vui, nhạc, dễ dàng","hanviet":"Lạc","onReadings":["ガク","ラク"],"kunReadings":["たの"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"音楽","reading":"おんがく","meaning":"Âm nhạc","vocabKey":"v:音楽"},{"compound":"楽しい","reading":"たのしい","meaning":"Vui","vocabKey":"v:楽しい"},{"compound":"楽","reading":"らく","meaning":"Thoải mái"}],"lessonIds":[8,9,42,43,45,48],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 白 (trắng/vỏ) + 木 (cây) + 冫冫 (trang trí nhạc cụ — chuông trên dây). Mẹo nhớ: cây (木) treo chuông nhỏ (冫) làm nhạc cụ → âm nhạc mang lại niềm vui 🎵. Hán-Việt: Lạc, như 'âm nhạc' (音楽/ongaku), 'an lạc' (thoải mái), 'lạc quan'. Ba nghĩa: nhạc (ガク/gaku), vui (たのしい/tanoshii), dễ dàng (ラク/raku). Một chữ nhiều nghĩa nhất ở N4!","example":"旅行は**楽**しかったです。 / ryokou wa tanoshikatta desu. (Chuyến du lịch vui.)","examples":[{"ja":"旅行は楽しかったです。","vi":"Chuyến du lịch vui.","romaji":"ryokou wa tanoshikatsuta desu."},{"ja":"旅行が楽しい","vi":"Du lịch vui","romaji":"ryokou ga tanoshii"},{"ja":"楽な仕事","vi":"Việc nhẹ nhàng","romaji":"Raku na shigoto"},{"ja":"音楽を聞く","vi":"Nghe nhạc","romaji":"Ongaku wo kiku"}]},{"key":"k:好","kind":"kanji","level":"N5","character":"好","meaning":"Thích","hanviet":"Hiếu","onReadings":["コウ"],"kunReadings":["す","この"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"好き","reading":"すき","meaning":"Thích"},{"compound":"大好き","reading":"だいすき","meaning":"Rất thích"}],"lessonIds":[9,27],"topicTags":[],"sectionId":9,"sectionName":"TÍNH CHẤT & TRẠNG THÁI","mnemonic":"Bộ/thành phần: 女 (nữ/phụ nữ) + 子 (con/tử). Mẹo nhớ: hình ảnh người mẹ (女) ôm con (子) — tình yêu giữa mẹ và con là điều ai cũng thích, ai cũng yêu ❤️. Hán-Việt: Hiếu/Hảo, như 'hảo cảm' (cảm tình tốt), 'đại hảo' (大好き/daisuki — rất thích). Âm on コウ (kou) ít dùng, gần như luôn dùng kun: すき (suki) = thích, このむ (konomu) = ưa chuộng. Kanji đơn giản mà đầy ý nghĩa!","example":"音楽が**好**きです。 / ongaku ga suki desu. (Tôi thích nhạc.)","examples":[{"ja":"音楽が好きです。","vi":"Tôi thích nhạc.","romaji":"ongaku ga suki desu."},{"ja":"音楽が好き","vi":"Thích nhạc","romaji":"Ongaku ga suki"},{"ja":"国内旅行が好きです","vi":"Thích du lịch trong nước","romaji":"kokunai ryokou ga suki desu"},{"ja":"わたしはイタリア料理が好きです。","vi":"Tôi thích món ăn Ý.","romaji":"watashi wa itaria ryouri ga suki desu."}]},{"key":"k:上","kind":"kanji","level":"N5","character":"上","meaning":"Trên","hanviet":"Thượng","onReadings":["ジョウ"],"kunReadings":["うえ","あ","のぼ"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"上手","reading":"じょうず","meaning":"Giỏi"},{"compound":"以上","reading":"いじょう","meaning":"Trên","vocabKey":"v:以上"},{"compound":"上がる","reading":"あがる","meaning":"Lên","vocabKey":"v:上がる"}],"lessonIds":[7,8,9,10,12,17,35,36,38,40,41,43,44,45,49],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: Chữ chỉ sự — nét ngang (一) là mặt phẳng, nét dọc chỉ lên phía 'trên' ⬆️. Hán-Việt: THƯỢNG. Mẹo nhớ: Nét dọc vươn LÊN TRÊN mặt phẳng — đó là 'thượng/trên'. Chỉ 3 nét, đối xứng với 下 (hạ/dưới). Âm うえ (ue), ジョウ (jou) gần 'thượng'. Liên kết: 上手 (thượng thủ = giỏi), 以上 (dĩ thượng = trên). ⚠️ Cặp nhớ: 上 (trên, nét chỉ lên) ↔ 下 (dưới, nét chỉ xuống).","example":"机の**上**に本があります。 / tsukue no ue ni hon ga arimasu. (Trên bàn có sách.)","examples":[{"ja":"机の上に本があります。","vi":"Trên bàn có sách.","romaji":"tsukue no ue ni hon ga arimasu."},{"ja":"階段を上がる","vi":"Đi lên cầu thang","romaji":"Kaidan wo agaru"},{"ja":"手を上げる","vi":"Giơ tay","romaji":"Te wo ageru"},{"ja":"どうぞ召し上がってください","vi":"Xin mời dùng","romaji":"douzo meshiagatsute kudasai"}]},{"key":"k:下","kind":"kanji","level":"N5","character":"下","meaning":"Dưới","hanviet":"Hạ","onReadings":["カ","ゲ"],"kunReadings":["した","さ","くだ"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"下手","reading":"へた","meaning":"Dở"},{"compound":"地下鉄","reading":"ちかてつ","meaning":"Tàu ngầm","vocabKey":"v:地下鉄"},{"compound":"下さい","reading":"ください","meaning":"Xin hãy"}],"lessonIds":[3,5,9,10,17,30,40,41,43,48],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: Chữ chỉ sự — nét ngang (一) là mặt phẳng, nét dọc chỉ xuống phía 'dưới' ⬇️. Hán-Việt: HẠ. Mẹo nhớ: Nét dọc rũ XUỐNG DƯỚI mặt phẳng — đó là 'hạ/dưới'. Chỉ 3 nét. Âm した (shita), カ (ka) gần 'hạ'. Liên kết: 下手 (hạ thủ = dở), 地下鉄 (địa hạ thiết = tàu điện ngầm), 下さい (kudasai = xin hãy). ⚠️ Cặp nhớ: 上 (trên) ↔ 下 (dưới) — nét phụ ngược hướng nhau.","example":"机の**下**に猫がいます。 / tsukue no shita ni neko ga imasu. (Dưới bàn có mèo.)","examples":[{"ja":"机の下に猫がいます。","vi":"Dưới bàn có mèo.","romaji":"tsukue no shita ni neko ga imasu."},{"ja":"気温が下がる","vi":"Nhiệt độ giảm","romaji":"Kion ga sagaru"},{"ja":"お金を下ろす","vi":"Rút tiền","romaji":"Okane wo orosu"},{"ja":"坂を下る","vi":"Đi xuống dốc","romaji":"Saka wo kudaru"}]},{"key":"k:中","kind":"kanji","level":"N5","character":"中","meaning":"Trong, giữa","hanviet":"Trung","onReadings":["チュウ"],"kunReadings":["なか"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"中国","reading":"ちゅうごく","meaning":"Trung Quốc"},{"compound":"中心","reading":"ちゅうしん","meaning":"Trung tâm","vocabKey":"v:中心"},{"compound":"一日中","reading":"いちにちじゅう","meaning":"Cả ngày"}],"lessonIds":[10,30,33,37,38,41,45],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 口 (khung/hộp) + 丨 (nét dọc xuyên giữa). Hán-Việt: TRUNG. Mẹo nhớ: Nét dọc (丨) xuyên qua chính giữa khung 口 — đó là 'trong, giữa' 🎯. Chỉ 4 nét, rất dễ nhớ. Âm なか (naka), チュウ (chuu) gần 'trung'. Liên kết: 中国 (trung quốc), 中心 (trung tâm), 一日中 (cả ngày). ⚠️ Đừng nhầm 中 với 申 (thân/xin) — 中 có 1 nét ngang, 申 có 2 nét ngang.","example":"箱の**中**に何がありますか。 / hako no naka ni nani ga arimasu ka. (Trong hộp có gì?)","examples":[{"ja":"箱の中に何がありますか。","vi":"Trong hộp có gì?","romaji":"hako no naka ni nani ga arimasu ka."},{"ja":"試合を中止する","vi":"Hủy trận đấu","romaji":"shiai o chuushi suru"},{"ja":"途中で雨が降った","vi":"Giữa đường trời mưa","romaji":"tochuu de ame ga futsuta"},{"ja":"夜中に目が覚めた","vi":"Tỉnh giấc lúc nửa đêm","romaji":"yachuu ni me ga sameta"}]},{"key":"k:外","kind":"kanji","level":"N5","character":"外","meaning":"Ngoài","hanviet":"Ngoại","onReadings":["ガイ","ゲ"],"kunReadings":["そと","ほか","はず"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"外国","reading":"がいこく","meaning":"Nước ngoài","vocabKey":"v:外国"},{"compound":"外出","reading":"がいしゅつ","meaning":"Ra ngoài"}],"lessonIds":[10,11,29,33,35],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 夕 (chiều tối/trăng lưỡi liềm) + 卜 (bói/nét phẩy). Hán-Việt: NGOẠI. Mẹo nhớ: Buổi 夕 chiều tối ra ngoài xem 卜 bói — phải ra 'ngoài' mới xem được trăng sao 🌙. Âm そと (soto), ガイ (gai) gần 'ngoại'. Liên kết: 外国 (ngoại quốc = nước ngoài), 外出 (ngoại xuất = ra ngoài). ⚠️ Cặp nhớ: 内 (nội/trong, có 人 người bên trong) ↔ 外 (ngoại/ngoài, có 夕 chiều đi ra).","example":"**外**は寒いです。 / soto wa samui desu. (Bên ngoài lạnh.)","examples":[{"ja":"外は寒いです。","vi":"Bên ngoài lạnh.","romaji":"soto wa samui desu."},{"ja":"外国に行く","vi":"Đi nước ngoài","romaji":"Gaikoku ni iku"},{"ja":"郊外に引っ越したい","vi":"Muốn chuyển về ngoại ô","romaji":"kougai ni hikkoshitai"},{"ja":"外に出る","vi":"Ra ngoài","romaji":"Soto ni deru"}]},{"key":"k:右","kind":"kanji","level":"N5","character":"右","meaning":"Bên phải","hanviet":"Hữu","onReadings":["ウ","ユウ"],"kunReadings":["みぎ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"右","reading":"みぎ","meaning":"Bên phải","vocabKey":"v:右"},{"compound":"右手","reading":"みぎて","meaning":"Tay phải"}],"lessonIds":[10],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: ナ (tay phải đưa ra) + 口 (miệng). Hán-Việt: HỮU. Mẹo nhớ: Tay phải (ナ) cầm đồ ăn đưa vào 口 miệng — đa số người thuận tay 'phải' 👉. Âm みぎ (migi), ウ (u) gần 'hữu'. Liên kết: 右手 (tay phải). ⚠️ Phân biệt bằng phần dưới: 右 có 口 (miệng, ăn bằng tay phải) ↔ 左 có 工 (thợ, tay trái cầm công cụ). Nét đầu: 右 viết ノ trước, 左 viết 一 trước.","example":"**右**に曲がってください。 / migi ni magatte kudasai. (Hãy rẽ phải.)","examples":[{"ja":"右に曲がってください。","vi":"Hãy rẽ phải.","romaji":"migi ni magatsute kudasai."},{"ja":"右に曲がる","vi":"Rẽ phải","romaji":"Migi ni magaru"},{"ja":"交差点を右へ曲がります。","vi":"Rẽ phải ở ngã tư.","romaji":"kousaten o migi e magarimasu."}]},{"key":"k:左","kind":"kanji","level":"N5","character":"左","meaning":"Bên trái","hanviet":"Tả","onReadings":["サ"],"kunReadings":["ひだり"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"左","reading":"ひだり","meaning":"Bên trái","vocabKey":"v:左"},{"compound":"左手","reading":"ひだりて","meaning":"Tay trái"}],"lessonIds":[10],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 一ノ (tay trái đưa ra) + 工 (thợ/dụng cụ). Hán-Việt: TẢ. Mẹo nhớ: Tay trái cầm 工 dụng cụ/thước kẻ để đo — thợ dùng tay 'trái' giữ thước 📐. Âm ひだり (hidari), サ (sa) gần 'tả'. Liên kết: 左手 (tay trái). ⚠️ Nét đầu: 左 viết 一 (ngang) trước ↔ 右 viết ノ (phẩy) trước. Phần dưới: 左 có 工 (công cụ) ↔ 右 có 口 (miệng).","example":"**左**に曲がってください。 / hidari ni magatte kudasai. (Hãy rẽ trái.)","examples":[{"ja":"左に曲がってください。","vi":"Hãy rẽ trái.","romaji":"hidari ni magatsute kudasai."},{"ja":"左に曲がる","vi":"Rẽ trái","romaji":"Hidari ni magaru"}]},{"key":"k:前","kind":"kanji","level":"N5","character":"前","meaning":"Trước, phía trước","hanviet":"Tiền","onReadings":["ゼン"],"kunReadings":["まえ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"名前","reading":"なまえ","meaning":"Tên","vocabKey":"v:名前"},{"compound":"午前","reading":"ごぜん","meaning":"Buổi sáng","vocabKey":"v:午前"},{"compound":"以前","reading":"いぜん","meaning":"Trước đây","vocabKey":"v:以前"}],"lessonIds":[4,10,14,29,38],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 月 (thịt/thuyền) + 刂 (đao) + 丷+一 (phần trên). Hán-Việt: TIỀN. Mẹo nhớ: Dùng 刂 dao cắt 月 thịt phía 'trước' mặt — thức ăn bày ra trước mặt 🍖. Âm まえ (mae), ゼン (zen) gần 'tiền'. 9 nét. Liên kết: 名前 (danh tiền = tên), 午前 (ngọ tiền = buổi sáng), 以前 (dĩ tiền = trước đây). ⚠️ Cặp nhớ: 前 (tiền/trước) ↔ 後 (hậu/sau).","example":"駅の**前**にバス停があります。 / eki no mae ni basutei ga arimasu. (Trước ga có trạm xe buýt.)","examples":[{"ja":"駅の前にバス停があります。","vi":"Trước ga có trạm xe buýt.","romaji":"eki no mae ni basutei ga arimasu."},{"ja":"以前ここに住んでいた","vi":"Trước đây sống ở đây","romaji":"Izen kokoni sun deita"},{"ja":"午前中に届く","vi":"Giao trong buổi sáng","romaji":"gozenchuu ni todoku"},{"ja":"駅の手前で降りる","vi":"Xuống trước ga","romaji":"Eki no temae de oriru"}]},{"key":"k:後","kind":"kanji","level":"N5","character":"後","meaning":"Sau, phía sau","hanviet":"Hậu","onReadings":["ゴ","コウ"],"kunReadings":["あと","うし","のち"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"午後","reading":"ごご","meaning":"Buổi chiều","vocabKey":"v:午後"},{"compound":"後ろ","reading":"うしろ","meaning":"Phía sau","vocabKey":"v:後ろ"},{"compound":"最後","reading":"さいご","meaning":"Cuối cùng","vocabKey":"v:最後"}],"lessonIds":[4,10,27,37],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 彳 (bước đi chậm) + 幺 (sợi nhỏ/rối) + 夂 (bước chân kéo lê). Hán-Việt: HẬU. Mẹo nhớ: 彳 Bước đi chậm vì bị 幺 sợi rối quấn chân, chân 夂 kéo lê phía 'sau' 🐌. Người đi sau cùng! Âm あと (ato) = sau, うしろ (ushiro) = phía sau, ゴ (go) gần 'hậu'. Li kết: 午後 (ngọ hậu = chiều), 後ろ (phía sau), 最後 (tối hậu = cuối cùng). ⚠️ 前 (trước) ↔ 後 (sau) — luôn đi cặp.","example":"学校の**後**で遊びます。 / gakkou no ato de asobimasu. (Sau giờ học tôi chơi.)","examples":[{"ja":"学校の後で遊びます。","vi":"Sau giờ học tôi chơi.","romaji":"gakkou no nochi de asobimasu."},{"ja":"後輩に教える","vi":"Dạy hậu bối","romaji":"kouhai ni oshieru"},{"ja":"明後日出発する","vi":"Ngày kia xuất phát","romaji":"myougonichi shuppatsu suru"},{"ja":"以後気をつける","vi":"Từ nay cẩn thận","romaji":"Igo ki wo tsukeru"}]},{"key":"k:北","kind":"kanji","level":"N5","character":"北","meaning":"Phía Bắc","hanviet":"Bắc","onReadings":["ホク"],"kunReadings":["きた"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"北海道","reading":"ほっかいどう","meaning":"Hokkaido"}],"lessonIds":[32],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: Hai người quay lưng lại nhau (丬 + 匕). Hán-Việt: BẮC. Mẹo nhớ: Hai người đứng quay lưng vào nhau — lạnh lẽo, cô đơn ❄️ — phía 'bắc' lạnh nhất! Âm きた (kita), ホク (hoku) gần 'bắc'. 5 nét. Liên kết: 北海道 (Bắc Hải Đạo = Hokkaido). ⚠️ Nhớ 4 hướng: 東 (đông) 西 (tây) 南 (nam) 北 (bắc). Đừng nhầm 北 với 比 (tỉ/so sánh) — 北 có 匕 quay phải, 比 có 2 匕 cùng hướng.","example":"**北**の方は寒いです。 / kita no hou wa samui desu. (Phía bắc lạnh.)","examples":[{"ja":"北の方は寒いです。","vi":"Phía bắc lạnh.","romaji":"kitanokata wa samui desu."},{"ja":"北口の近くにコンビニがある","vi":"Gần cổng bắc có cửa hàng tiện lợi","romaji":"Kitaguchi no chikaku ni konbini ga aru"},{"ja":"ぜひ 北海道へ 行きたいです。","vi":"Tôi nhất định muốn đi Hokkaido.","romaji":"zehi hokkaidou e ikitai desu."},{"ja":"北海道は 寒かったでしょう？……いいえ、そんなに 寒くなかったです。","vi":"Hokkaido chắc lạnh lắm nhỉ? Không, không lạnh lắm đâu.","romaji":"hokkaidou wa samukatsuta desho u?...... iie, sonnani samukunakatsuta desu."}]},{"key":"k:南","kind":"kanji","level":"N5","character":"南","meaning":"Phía Nam","hanviet":"Nam","onReadings":["ナン"],"kunReadings":["みなみ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"南","reading":"みなみ","meaning":"Phía nam","vocabKey":"v:南"},{"compound":"東南","reading":"とうなん","meaning":"Đông nam"}],"lessonIds":[32],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 十 (mười) + 冂 (khung) + 𢆉 (cây cỏ/ấm). Hán-Việt: NAM. Mẹo nhớ: Phía 'nam' ấm áp 🌴 — hình dung căn nhà (冂) hướng nam có cây cỏ tươi tốt bên trong. Âm みなみ (minami), ナン (nan) gần 'nam'. 9 nét. Liên kết: 東南 (đông nam). ⚠️ Nhớ cặp: 北 (bắc, lạnh, 2 người quay lưng) ↔ 南 (nam, ấm, nhà có cây xanh).","example":"**南**の方は暖かいです。 / minami no hou wa atatakai desu. (Phía nam ấm.)","examples":[{"ja":"南の方は暖かいです。","vi":"Phía nam ấm.","romaji":"minami no hou wa atatakai desu."},{"ja":"南口から出てください","vi":"Hãy đi ra cổng nam","romaji":"minamiguchi kara dete kudasai"},{"ja":"南","vi":"nam","romaji":"minami"}]},{"key":"k:東","kind":"kanji","level":"N5","character":"東","meaning":"Phía Đông","hanviet":"Đông","onReadings":["トウ"],"kunReadings":["ひがし"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"東京","reading":"とうきょう","meaning":"Tokyo"},{"compound":"東口","reading":"ひがしぐち","meaning":"Cửa phía đông","vocabKey":"v:東口"}],"lessonIds":[10,32],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 木 (cây) + 日 (mặt trời) xuyên qua giữa. Hán-Việt: ĐÔNG. Mẹo nhớ: 日 Mặt trời mọc đằng sau 木 cây — hướng mặt trời mọc = phía 'đông' 🌅. Hình dung nhìn về đông thấy mặt trời sau hàng cây. Âm ひがし (higashi), トウ (tou) gần 'đông'. 8 nét. Liên kết: 東京 (đông kinh = Tokyo = kinh đô phía đông), 東口 (cửa đông). ⚠️ Đừng nhầm 東 với 束 (thúc/bó) — 東 có 日 ở giữa, 束 có 口 ở giữa.","example":"**東**京は大きい町です。 / toukyou wa ookii machi desu. (Tokyo là thành phố lớn.)","examples":[{"ja":"東京は大きい町です。","vi":"Tokyo là thành phố lớn.","romaji":"toukyou wa ookii machi desu."},{"ja":"東口で待ち合わせする","vi":"Hẹn gặp ở cổng đông","romaji":"Higashiguchi de machiawase suru"},{"ja":"東京から大阪まで3時間かかります。","vi":"Từ Tokyo đến Osaka mất 3 tiếng.","romaji":"toukyou kara oosaka made 3jikan kakarimasu."},{"ja":"東京ディズニーランドは千葉県にあります。","vi":"Công viên Tokyo Disneyland ở tỉnh Chiba.","romaji":"toukyou dizuniirando wa chibaken ni arimasu."}]},{"key":"k:西","kind":"kanji","level":"N5","character":"西","meaning":"Phía Tây","hanviet":"Tây","onReadings":["セイ","サイ"],"kunReadings":["にし"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"西口","reading":"にしぐち","meaning":"Cửa phía tây","vocabKey":"v:西口"},{"compound":"西洋","reading":"せいよう","meaning":"Phương Tây"}],"lessonIds":[29,32],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: Chữ tượng hình gốc — hình tổ chim, chim về tổ khi mặt trời lặn. Hán-Việt: TÂY. Mẹo nhớ: Chim bay về tổ (nét cong bên trong) khi mặt trời lặn ở phía 'tây' 🌇. 6 nét. Âm にし (nishi), セイ (sei) gần 'tây'. Liên kết: 西口 (cửa tây), 西洋 (tây dương = phương Tây). ⚠️ Nhớ 4 hướng theo cặp: 東↔西 (đông↔tây), 南↔北 (nam↔bắc).","example":"**西**口で待っています。 / nishiguchi de matte imasu. (Tôi đợi ở cửa phía tây.)","examples":[{"ja":"西口で待っています。","vi":"Tôi đợi ở cửa phía tây.","romaji":"nishiguchi de matsute imasu."},{"ja":"西口にタクシー乗り場がある","vi":"Có bãi taxi ở cổng tây","romaji":"Nishiguchi ni takushii noriba ga aru"},{"ja":"西","vi":"hướng tây","romaji":"nishi"}]},{"key":"k:内","kind":"kanji","level":"N5","character":"内","meaning":"Trong, nội","hanviet":"Nội","onReadings":["ナイ"],"kunReadings":["うち"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"国内","reading":"こくない","meaning":"Trong nước"},{"compound":"案内","reading":"あんない","meaning":"Hướng dẫn","vocabKey":"v:案内"}],"lessonIds":[9,24,30,50],"topicTags":["place"],"sectionId":10,"sectionName":"VỊ TRÍ & PHƯƠNG HƯỚNG","mnemonic":"Bộ/thành phần: 冂 (khung/vùng bao quanh) + 人 (người). Hán-Việt: NỘI. Mẹo nhớ: 人 Người đứng bên trong 冂 khung — đó là 'nội', bên trong 🏠. Chỉ 4 nét. Âm うち (uchi), ナイ (nai) gần 'nội'. Liên kết: 国内 (quốc nội = trong nước), 案内 (án nội = hướng dẫn). ⚠️ Cặp nhớ: 内 (nội, 人 ở BÊN TRONG 冂) ↔ 外 (ngoại, 夕 ở BÊN NGOÀI). Đừng nhầm 内 với 肉 (nhục/thịt) — 肉 thêm 2 nét trong.","example":"**内**側に入ってください。 / uchigawa ni haitte kudasai. (Hãy vào bên trong.)","examples":[{"ja":"内側に入ってください。","vi":"Hãy vào bên trong.","romaji":"uchigawa ni haitsute kudasai."},{"ja":"係員が会場まで案内してくれた","vi":"Nhân viên dẫn đến hội trường","romaji":"kakariin ga kaijou made annai shite kureta"},{"ja":"案内板を見れば分かります","vi":"Xem bảng hướng dẫn là hiểu","romaji":"Annaiban wo mireba waka rimasu"},{"ja":"駅員が道を案内してくれました","vi":"Nhân viên ga chỉ đường","romaji":"Ekiin ga michi wo annai shitekuremashita"}]},{"key":"k:起","kind":"kanji","level":"N5","character":"起","meaning":"Thức dậy, xảy ra, dựng lên","hanviet":"Khởi","onReadings":["キ"],"kunReadings":["お","お"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"起きる","reading":"おきる","meaning":"Thức dậy","vocabKey":"v:起きる"},{"compound":"起こる","reading":"おこる","meaning":"Xảy ra"}],"lessonIds":[4,33,44],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 走 (chạy) + 巳 (rắn/tỵ). Hán-Việt: KHỞI. Mẹo nhớ: Con 巳 rắn nằm cuộn, bất ngờ 走 chạy vọt dậy — đó là 'khởi' dậy, thức dậy, xảy ra 🐍⬆️. Âm おきる (okiru) = thức dậy, おこる (okoru) = xảy ra, キ (ki) gần 'khởi'. Liên kết: 起きる (thức dậy), 起こる (xảy ra). ⚠️ Phần 走 viết trước (7 nét), 巳 viết sau.","example":"毎朝6時に**起**きます。 / maiasa rokuji ni okimasu. (Mỗi sáng tôi thức dậy lúc 6 giờ)","examples":[{"ja":"毎朝6時に起きます。","vi":"Mỗi sáng tôi thức dậy lúc 6 giờ","romaji":"maiasa 6ji ni okimasu."},{"ja":"朝6時に起こしてください","vi":"Hãy đánh thức tôi lúc 6 giờ sáng","romaji":"asa 6ji ni okoshite kudasai"},{"ja":"朝6時に起きる","vi":"Dậy lúc 6 giờ sáng","romaji":"asa 6ji ni okiru"},{"ja":"弟は六時に起きます。 母が弟を起こします。","vi":"Em trai dậy lúc sáu giờ. Mẹ đánh em trai dậy.","romaji":"otouto wa rokuji ni okimasu. haha ga otouto o okoshimasu."}]},{"key":"k:受","kind":"kanji","level":"N5","character":"受","meaning":"Nhận, thi, chịu","hanviet":"Thụ","onReadings":["ジュ"],"kunReadings":["う"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"受ける","reading":"うける","meaning":"Nhận/ thi","vocabKey":"v:受ける"},{"compound":"受付","reading":"うけつけ","meaning":"Quầy tiếp nhận","vocabKey":"v:受付"}],"lessonIds":[3,31,49],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 爪(爫) (tay với xuống) + 冂 (khung) + 又 (tay đỡ). Hán-Việt: THỤ. Mẹo nhớ: Tay trên (爪) đưa xuống, tay dưới (又) đón lấy — đó là 'thụ', nhận lấy 🤲! Âm うける (ukeru) = nhận, ジュ (ju) gần 'thụ'. 8 nét. Liên kết: 受ける (nhận/thi), 受付 (quầy tiếp nhận). ⚠️ Đừng nhầm 受 (nhận — tay đón) với 授 (trao — có thêm 扌 tay chủ động đưa).","example":"来週試験を**受**けます。 / raishuu shiken wo ukemasu. (Tuần sau tôi đi thi)","examples":[{"ja":"来週試験を受けます。","vi":"Tuần sau tôi đi thi","romaji":"raishuu shiken wo ukemasu."},{"ja":"荷物を受け取る","vi":"Nhận hàng","romaji":"Nimotsu wo uketoru"},{"ja":"試験を受ける","vi":"Thi","romaji":"Shiken wo ukeru"},{"ja":"受付は一階にあります","vi":"Quầy tiếp nhận ở tầng 1","romaji":"uketsuke wa ichikai ni arimasu"}]},{"key":"k:終","kind":"kanji","level":"N5","character":"終","meaning":"Kết thúc, hết","hanviet":"Chung","onReadings":["シュウ"],"kunReadings":["お","お"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"終わる","reading":"おわる","meaning":"Kết thúc","vocabKey":"v:終わる"},{"compound":"最終","reading":"さいしゅう","meaning":"Cuối cùng"}],"lessonIds":[4,20,35],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 糸(糹) (sợi tơ) + 冬 (mùa đông). Hán-Việt: CHUNG. Mẹo nhớ: Cuộn 糸 sợi tơ dệt đến 冬 mùa đông thì hết — đó là 'chung', kết thúc 🧵❄️. Cuối năm là đông, cuối sợi là hết. Âm おわる (owaru), シュウ (shuu) gần 'chung'. Liên kết: 終わる (kết thúc), 最終 (tối chung = cuối cùng). ⚠️ Cặp nhớ: 始 (thủy/bắt đầu) ↔ 終 (chung/kết thúc).","example":"授業が**終**わりました。 / jugyou ga owarimashita. (Tiết học đã kết thúc)","examples":[{"ja":"授業が終わりました。","vi":"Tiết học đã kết thúc","romaji":"jugyou ga owarimashita."},{"ja":"授業が終わる","vi":"Tiết học kết thúc","romaji":"jugyou ga owaru"},{"ja":"申し込みは昨日で終了しました","vi":"Đăng ký đã kết thúc vào hôm qua","romaji":"moushikomi wa kinou de shuuryou shimashita"},{"ja":"コンサートが 終わってから、レストランで 食事を しました。","vi":"Sau khi buổi hòa nhạc kết thúc, tôi đã dùng bữa ở nhà hàng.","romaji":"konsaato ga owatsute kara, resutoran de shokuji o shimashita."}]},{"key":"k:集","kind":"kanji","level":"N5","character":"集","meaning":"Tập hợp, thu thập","hanviet":"Tập","onReadings":["シュウ"],"kunReadings":["あつ","あつ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"集める","reading":"あつめる","meaning":"Thu thập","vocabKey":"v:集める"},{"compound":"集合","reading":"しゅうごう","meaning":"Tập hợp"}],"lessonIds":[1,18,24,33,41,47,49],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 隹 (chim ngắn đuôi) + 木 (cây). Hán-Việt: TẬP. Mẹo nhớ: Bầy 隹 chim đậu tụ họp trên 木 cây 🌳🐦 — đó là 'tập' hợp, tụ tập. Âm あつまる (atsumaru), シュウ (shuu) gần 'tập'. Liên kết: 集める (thu thập), 集合 (tập hợp). ⚠️ 隹 (chim ngắn đuôi) khác 鳥 (điểu/chim dài đuôi) — 隹 thường làm thành phần trong kanji khác.","example":"駅前に**集**まってください。 / ekimae ni atsumatte kudasai. (Hãy tập trung trước ga)","examples":[{"ja":"駅前に集まってください。","vi":"Hãy tập trung trước ga","romaji":"ekimae ni atsumatsute kudasai."},{"ja":"人が集まる","vi":"Người ta tập hợp","romaji":"hito ga atsumaru"},{"ja":"切手を集める","vi":"Sưu tập tem","romaji":"Kitte wo atsumeru"},{"ja":"学生が教室に集まりました。 先生がプリントを集めました。","vi":"Học sinh đã tập hợp trong lớp. Thầy giáo đã thu lại phiếu.","romaji":"gakusei ga kyoushitsu ni atsumarimashita. sensei ga purinto o atsumemashita."}]},{"key":"k:乗","kind":"kanji","level":"N5","character":"乗","meaning":"Lên xe, cưỡi","hanviet":"Thừa","onReadings":["ジョウ"],"kunReadings":["の","の"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"乗る","reading":"のる","meaning":"Lên xe","vocabKey":"v:乗る"},{"compound":"乗り物","reading":"のりもの","meaning":"Phương tiện","vocabKey":"v:乗り物"}],"lessonIds":[10,16,36],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: Phần trên là nét đan chéo (chân gác) + 木 (cây/chiến xa). Hán-Việt: THỪ(A). Mẹo nhớ: Người gác chân lên cây (木) để leo lên — đó là 'thừa', lên xe, cưỡi 🚌. 9 nét. Âm のる (noru) = lên xe, ジョウ (jou) gần 'thừa'. Liên kết: 乗る (lên xe), 乗り物 (phương tiện giao thông). ⚠️ Đừng nhầm 乗 với 店 (tiệm) — 乗 có nét đan chéo ở trên, 店 có 广 mái.","example":"バスに**乗**って学校に行きます。 / basu ni notte gakkou ni ikimasu. (Tôi đi xe buýt đến trường)","examples":[{"ja":"バスに乗って学校に行きます。","vi":"Tôi đi xe buýt đến trường","romaji":"basu ni notsute gakkou ni ikimasu."},{"ja":"バスに乗る","vi":"Lên xe buýt","romaji":"Basu ni noru"},{"ja":"ここで乗り換える","vi":"Chuyển ở đây","romaji":"Kokode norikaeru"},{"ja":"車に乗せる","vi":"Cho lên xe","romaji":"Kuruma ni noseru"}]},{"key":"k:始","kind":"kanji","level":"N5","character":"始","meaning":"Bắt đầu","hanviet":"Thủy","onReadings":["シ"],"kunReadings":["はじ","はじ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"始まる","reading":"はじまる","meaning":"Bắt đầu (tự)","vocabKey":"v:始まる"},{"compound":"始める","reading":"はじめる","meaning":"Bắt đầu (tha)","vocabKey":"v:始める"}],"lessonIds":[14,20,33],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 女 (nữ, phụ nữ) + 台 (đài/bệ, âm ダイ). Hán-Việt: THỦY. Mẹo nhớ: 女 Người mẹ (女) mang thai là 台 nền tảng 'bắt đầu' sự sống mới 👶. Khởi nguồn, khởi đầu. Âm はじまる (hajimaru), シ (shi) gần 'thủy'. Liên kết: 始まる (bắt đầu tự động), 始める (bắt đầu chủ động). ⚠️ Cặp nhớ: 始 (đầu) ↔ 終 (chung/cuối). Đừng nhầm 始 với 姉 (tỷ/chị gái) — 始 có 台, 姉 có 市.","example":"会議は9時に**始**まります。 / kaigi wa kuji ni hajimarimasu. (Cuộc họp bắt đầu lúc 9 giờ)","examples":[{"ja":"会議は9時に始まります。","vi":"Cuộc họp bắt đầu lúc 9 giờ","romaji":"kaigi wa 9ji ni hajimarimasu."},{"ja":"授業が始まる","vi":"Tiết học bắt đầu","romaji":"jugyou ga hajimaru"},{"ja":"仕事を始める","vi":"Bắt đầu làm việc","romaji":"Shigoto wo hajimeru"},{"ja":"年始に初詣に行く","vi":"Đầu năm đi lễ chùa đầu năm","romaji":"nenshi ni hatsumoude ni iku"}]},{"key":"k:引","kind":"kanji","level":"N5","character":"引","meaning":"Kéo, dẫn","hanviet":"Dẫn","onReadings":["イン"],"kunReadings":["ひ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"引く","reading":"ひく","meaning":"Kéo","vocabKey":"v:引く"},{"compound":"引っ越す","reading":"ひっこす","meaning":"Chuyển nhà","vocabKey":"v:引っ越す"}],"lessonIds":[23,30,33],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 弓 (cung) + 丨 (nét dọc/dây cung). Hán-Việt: DẪN. Mẹo nhớ: Kéo dây (丨) cái 弓 cung lại — đó là 'kéo, dẫn' 🏹! Chỉ 4 nét, đơn giản. Âm ひく (hiku) = kéo, イン (in) gần 'dẫn'. Liên kết: 引く (kéo), 引っ越す (kéo đồ chuyển nhà). ⚠️ 引く nhiều nghĩa: kéo cửa, tra từ điển, bị cảm (風邪を引く). Đừng nhầm 弓 (cung — 3 nét) với 弔 (điếu — 4 nét).","example":"ドアを**引**いてください。 / doa wo hiite kudasai. (Hãy kéo cửa)","examples":[{"ja":"ドアを引いてください。","vi":"Hãy kéo cửa","romaji":"doa wo hiite kudasai."},{"ja":"ドアを引く","vi":"Kéo cửa","romaji":"Doa wo hiku"},{"ja":"東京に引っ越す","vi":"Chuyển đến Tokyo","romaji":"toukyou ni hikkosu"},{"ja":"引き出しを開ける","vi":"Mở ngăn kéo","romaji":"Hikidashi wo akeru"}]},{"key":"k:着","kind":"kanji","level":"N5","character":"着","meaning":"Đến nơi, mặc (quần áo)","hanviet":"Trước","onReadings":["チャク"],"kunReadings":["き","つ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"着く","reading":"つく","meaning":"Đến nơi","vocabKey":"v:着く"},{"compound":"着る","reading":"きる","meaning":"Mặc","vocabKey":"v:着る"}],"lessonIds":[17,20,22,25,40],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 羊 (cừ — biến thể âm) + 目 (mắt). Hán-Việt: TRƯỚC. Mẹo nhớ: 目 Mắt nhìn thấy con 羊 cừ đã 'đến nơi' 🐑👀 — hoặc: mặc áo lông cừ cho đến khi nhìn thấy. Hai nghĩa: 着く (tsuku = đến), 着る (kiru = mặc). Âm チャク (chaku) gần 'trước'. Liên kết: 到着 (đã đến). ⚠️ 着 có 2 cách đọc: つく (tsuku = đến nơi) và きる (kiru = mặc đồ) — tùy ngữ cảnh.","example":"空港に**着**いたら電話します。 / kuukou ni tsuitara denwa shimasu. (Khi đến sân bay tôi sẽ gọi điện)","examples":[{"ja":"空港に着いたら電話します。","vi":"Khi đến sân bay tôi sẽ gọi điện","romaji":"kuukou ni tsuitara denwa shimasu."},{"ja":"駅に着く","vi":"Đến ga","romaji":"Eki ni tsuku"},{"ja":"シャツを着る","vi":"Mặc áo sơ mi","romaji":"Shatsu wo kiru"},{"ja":"服を着替える","vi":"Thay đồ","romaji":"Fuku wo kigaeru"}]},{"key":"k:発","kind":"kanji","level":"N4","character":"発","meaning":"Xuất phát, phát ra","hanviet":"Phát","onReadings":["ハツ","ホツ"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"出発","reading":"しゅっぱつ","meaning":"Xuất phát","vocabKey":"v:出発"},{"compound":"発表","reading":"はっぴょう","meaning":"Phát biểu","vocabKey":"v:発表"}],"lessonIds":[31,37,40,41,47,49],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 癶 (hai chân bước) + nét ngang và chấm. Hán-Việt: PHÁT. Mẹo nhớ: Hai bàn chân (癶) sẵn sàng bước ra, 'phát' đi xuất phát 🚀! Âm ハツ (hatsu) gần 'phát'. 9 nét. Liên kết: 出発 (xuất phát), 発表 (phát biểu), 発音 (phát âm). ⚠️ Dạng giản lược của 發 — chỉ dùng dạng 発 trong tiếng Nhật hiện đại.","example":"飛行機は8時に**出発**します。 / hikouki wa hachiji ni shuppatsu shimasu. (Máy bay xuất phát lúc 8 giờ)","examples":[{"ja":"飛行機は8時に出発します。","vi":"Máy bay xuất phát lúc 8 giờ","romaji":"hikouki wa 8ji ni shuppatsu shimasu."},{"ja":"朝早く出発する","vi":"Xuất phát sớm","romaji":"Asahayaku shuppatsu suru"},{"ja":"新しいカフェを発見した","vi":"Phát hiện quán cà phê mới","romaji":"Atarashii kafe wo hakken shita"},{"ja":"発表をする","vi":"Trình bày","romaji":"happyou o suru"}]},{"key":"k:払","kind":"kanji","level":"N5","character":"払","meaning":"Trả tiền, phủi","hanviet":"Phất","onReadings":["—"],"kunReadings":["はら"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"払う","reading":"はらう","meaning":"Trả tiền","vocabKey":"v:払う"},{"compound":"支払い","reading":"しはらい","meaning":"Thanh toán"}],"lessonIds":[17],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 扌(手) (tay) + 厶 (phẩy trái/quẹt). Hán-Việt: PHẤT. Mẹo nhớ: Dùng 扌 tay quẹt (厶) bụi đi, phủi sạch — mở rộng: 'trả tiền' (phất tiền đi!) 💸. Hành động của tay. 5 nét. Âm はらう (harau). Liên kết: 払う (trả tiền), 支払い (thanh toán). ⚠️ Bộ 扌 (tay) ở bên trái cho biết đây là hành động của tay.","example":"カードで**払**ってもいいですか。 / kaado de harattemo ii desu ka. (Trả bằng thẻ có được không?)","examples":[{"ja":"カードで払ってもいいですか。","vi":"Trả bằng thẻ có được không?","romaji":"kaado de haratsute mo ii desu ka."},{"ja":"お金を払う","vi":"Trả tiền","romaji":"Okane wo harau"},{"ja":"お支払いは現金のみでございます。","vi":"Thanh toán chỉ bằng tiền mặt ạ.","romaji":"o shiharai wa genkin nomi de gozaimasu."},{"ja":"払います","vi":"trả tiền","romaji":"haraimasu"}]},{"key":"k:写","kind":"kanji","level":"N5","character":"写","meaning":"Chụp, sao chép","hanviet":"Tả","onReadings":["シャ"],"kunReadings":["うつ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"写真","reading":"しゃしん","meaning":"Ảnh","vocabKey":"v:写真"},{"compound":"写す","reading":"うつす","meaning":"Sao chép","vocabKey":"v:写す"}],"lessonIds":[6,15,29,35,37,45],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 冂 (mái che) + 与 (cho, và). Hán-Việt: TẢ. Mẹo nhớ: Dưới 冂 mái nhà (phòng tối), 与 đưa ra bản sao — đó là 'tả', sao chép, chụp lại 📸. 5 nét, giản lược của 寫. Âm うつす (utsusu), シャ (sha) gần 'tả'. Liên kết: 写真 (tả chân = ảnh chụp), 写す (sao chép). ⚠️ Đừng nhầm 写 với 与 (đơn độc) — 写 có 冂 mái che ở trên.","example":"ここで**写**真を撮ってもいいですか。 / koko de shashin wo tottemo ii desu ka. (Chụp ảnh ở đây có được không?)","examples":[{"ja":"ここで写真を撮ってもいいですか。","vi":"Chụp ảnh ở đây có được không?","romaji":"koko de shashin o totsute mo ii desu ka."},{"ja":"写真を写す","vi":"Chụp ảnh","romaji":"Shashin wo utsusu"},{"ja":"写真を撮る","vi":"Chụp ảnh","romaji":"Shashin wo toru"},{"ja":"机の上に写真があります。","vi":"Ở trên bàn có bức ảnh.","romaji":"tsukue no ue ni shashin ga arimasu."}]},{"key":"k:合","kind":"kanji","level":"N5","character":"合","meaning":"Hợp, gặp, phù hợp","hanviet":"Hợp","onReadings":["ゴウ","ガッ"],"kunReadings":["あ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"場合","reading":"ばあい","meaning":"Trường hợp"},{"compound":"試合","reading":"しあい","meaning":"Trận đấu","vocabKey":"v:試合"},{"compound":"合う","reading":"あう","meaning":"Hợp","vocabKey":"v:合う"}],"lessonIds":[6,14,16,17,19,21,22,26,27,28,29,31,32,33,34,36,37,39,40,41,43,46,47,48],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 亼 (nắp/mái hội tụ) + 口 (miệng). Hán-Việt: HỢP. Mẹo nhớ: Mái che (亼) đậy khít 口 miệng bình — hai phần vừa khít = 'hợp', phù hợp 🧩! Âm あう (au) = hợp, ゴウ (gou) = gặp. 6 nét. Liên kết: 場合 (trường hợp), 試合 (thi đấu), 合う (hợp/vừa). ⚠️ Đừng nhầm 会 (hội — người gặp nhau) với 合 (hợp — vật khớp nhau).","example":"このサイズは私に**合**います。 / kono saizu wa watashi ni aimasu. (Size này vừa với tôi)","examples":[{"ja":"このサイズは私に合います。","vi":"Size này vừa với tôi","romaji":"kono saizu wa watashi ni aimasu."},{"ja":"サイズが合う","vi":"Size vừa","romaji":"Saizu ga au"},{"ja":"電車に間に合う","vi":"Kịp tàu","romaji":"Densha ni maniau"},{"ja":"試験に合格する","vi":"Đậu kỳ thi","romaji":"shiken ni goukaku suru"}]},{"key":"k:進","kind":"kanji","level":"N4","character":"進","meaning":"Tiến lên, tiến bộ","hanviet":"Tiến","onReadings":["シン"],"kunReadings":["すす","すす"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"進む","reading":"すすむ","meaning":"Tiến lên","vocabKey":"v:進む"},{"compound":"進学","reading":"しんがく","meaning":"Lên cấp học trên"}],"lessonIds":[49],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 辶 (shinnyou, di chuyển) + 隹 (chim ngắn đuôi). Hán-Việt: TIẾN. Mẹo nhớ: Con 隹 chim bay 辶 về phía trước — 'tiến' lên, tiến bộ 🐦➡️. Âm すすむ (susumu), シン (shin) gần 'tiến'. 11 nét. Liên kết: 進む (tiến lên), 進学 (tiến học = lên cấp). ⚠️ 隹 (chim ngắn đuôi) xuất hiện trong nhiều kanji: 集 (tập), 難 (nan), 雑 (tạp).","example":"まっすぐ**進**んでください。 / massugu susunde kudasai. (Hãy đi thẳng)","examples":[{"ja":"まっすぐ進んでください。","vi":"Hãy đi thẳng","romaji":"massugu susunde kudasai."},{"ja":"前に進む","vi":"Tiến về phía trước","romaji":"Mae ni susumu"},{"ja":"進行方向の右側に座る","vi":"Ngồi phía bên phải theo hướng chạy","romaji":"shinkou houkou no migigawa ni suwaru"},{"ja":"予定のとおりに進めましょう。","vi":"Hãy tiến hành đúng theo kế hoạch.","romaji":"yotei no toori ni susume masho u."}]},{"key":"k:変","kind":"kanji","level":"N5","character":"変","meaning":"Thay đổi, kỳ lạ","hanviet":"Biến","onReadings":["ヘン"],"kunReadings":["か","か"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"変わる","reading":"かわる","meaning":"Thay đổi","vocabKey":"v:変わる"},{"compound":"大変","reading":"たいへん","meaning":"Vất vả"},{"compound":"変","reading":"へん","meaning":"Lạ"}],"lessonIds":[4,13,23,35,43,50],"topicTags":[],"sectionId":11,"sectionName":"HÀNH ĐỘNG & ĐỘNG TÁC","mnemonic":"Bộ/thành phần: 亦 (cũng/vậy — nghĩch) + 夂 (bước chân xuống). Hán-Việt: BIẾN. Mẹo nhớ: Bước chân (夂) thay đổi (亦 nghịch) hướng đi — đó là 'biến', thay đổi, kỳ lạ. 9 nét. Âm かわる (kawaru) = thay đổi, ヘン (hen) gần 'biến'. Liên kết: 変わる (biến/thay đổi), 大変 (đại biến = vất vả), 変 (hen = lạ). ⚠️ đọc へん (hen) nghĩa 'lạ đời', đọc かわる (kawaru) nghĩa 'thay đổi' — khác nhau tùy ngữ cảnh.","example":"最近、天気が**変**わりやすいです。 / saikin, tenki ga kawariyasui desu. (Gần đây thời tiết hay thay đổi)","examples":[{"ja":"最近、天気が変わりやすいです。","vi":"Gần đây thời tiết hay thay đổi","romaji":"saikin, tenki ga kawariyasui desu."},{"ja":"天気が変わる","vi":"Thời tiết thay đổi","romaji":"Tenki ga kawaru"},{"ja":"予定を変える","vi":"Thay đổi dự định","romaji":"Yotei wo kaeru"},{"ja":"予定を変更してもいいですか","vi":"Có thể thay đổi kế hoạch?","romaji":"yotei o henkou shite mo ii desu ka"}]},{"key":"k:意","kind":"kanji","level":"N5","character":"意","meaning":"Ý, ý nghĩa, ý kiến","hanviet":"Ý","onReadings":["イ"],"kunReadings":["—"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"意味","reading":"いみ","meaning":"Ý nghĩa","vocabKey":"v:意味"},{"compound":"意見","reading":"いけん","meaning":"Ý kiến","vocabKey":"v:意見"},{"compound":"注意","reading":"ちゅうい","meaning":"Chú ý","vocabKey":"v:注意"}],"lessonIds":[21,24,33,37,50],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 音 (âm) + 心 (tâm/tim). Hán-Việt: Ý. Mẹo nhớ: Âm thanh (音) phát ra từ trái tim (心) — đó là 'ý' nghĩ, tâm tư 💭. 13 nét. Âm イ (i) như trong 意味 (imi - ý nghĩa), 注意 (chuui - chú ý). Liên kết: 意味 (ý nghĩa), 意見 (ý kiến), 注意 (chú ý). ⚠️ Phần trên là 音 (âm — 立 + 日), phần dưới là 心 (tâm).","example":"この言葉の**意**味がわかりません。 / kono kotoba no imi ga wakarimasen. (Tôi không hiểu nghĩa của từ này)","examples":[{"ja":"この言葉の意味がわかりません。","vi":"Tôi không hiểu nghĩa của từ này","romaji":"kono kotoba no imi ga wakarimasen."},{"ja":"健康に注意する","vi":"Chú ý sức khỏe","romaji":"kenkou ni chuui suru"},{"ja":"パーティーの料理を用意しました","vi":"Chuẩn bị đồ ăn tiệc","romaji":"paateii no ryouri o youi shimashita"},{"ja":"数学が得意です","vi":"Giỏi toán","romaji":"suugaku ga tokui desu"}]},{"key":"k:決","kind":"kanji","level":"N4","character":"決","meaning":"Quyết định","hanviet":"Quyết","onReadings":["ケツ"],"kunReadings":["き","き"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"決める","reading":"きめる","meaning":"Quyết định","vocabKey":"v:決める"},{"compound":"決まる","reading":"きまる","meaning":"Được quyết định","vocabKey":"v:決まる"}],"lessonIds":[30],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 氵(nước) + 夬 (quải/quyết). Hán-Việt: QUYẾT. Mẹo nhớ: Dòng nước (氵) chảy qua khe hở (夬) — một khi đã 'quyết' thì không quay lại 🌊. 7 nét. Âm ケツ (ketsu), きめる (kimeru) = quyết định. Liên kết: 決める (quyết định), 決まる (được quyết định). ⚠️ Bên phải 夬 cũng xuất hiện trong 快 (khoái) — nhưng 快 có 忄(tim), 決 có 氵(nước).","example":"旅行の日を**決**めましょう。 / ryokou no hi wo kimemashou. (Hãy quyết định ngày đi du lịch)","examples":[{"ja":"旅行の日を決めましょう。","vi":"Hãy quyết định ngày đi du lịch","romaji":"ryokou no hi wo kimemashou."},{"ja":"日程が決まる","vi":"Lịch trình được quyết định","romaji":"Nittei ga kimaru"},{"ja":"場所を決める","vi":"Quyết định địa điểm","romaji":"Basho wo kimeru"},{"ja":"旅行の日が決まりました。 私たちが行き先を決めました。","vi":"Ngày đi du lịch đã được quyết định. Chúng tôi đã quyết định điểm đến.","romaji":"ryokou no hi ga kimarimashita. watashitachi ga ikisaki o kimemashita."}]},{"key":"k:度","kind":"kanji","level":"N5","character":"度","meaning":"Mức độ, lần, nhiệt độ","hanviet":"Độ","onReadings":["ド"],"kunReadings":["たび"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"温度","reading":"おんど","meaning":"Nhiệt độ","vocabKey":"v:温度"},{"compound":"今度","reading":"こんど","meaning":"Lần này","vocabKey":"v:今度"},{"compound":"一度","reading":"いちど","meaning":"Một lần","vocabKey":"v:一度"}],"lessonIds":[9,19,26,41],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 广 (mái nhà/rộng) + 廿 (hai mươi) + 又 (tay/lại). Hán-Việt: ĐỘ. Mẹo nhớ: Dưới mái (广), đo đếm (又) nhiều lần (廿) — 'độ' đo, mức độ, lần 📏. 9 nét. Âm ド (do) trong 温度 (ondo - nhiệt độ), たび (tabi) = lần. Liên kết: 温度 (nhiệt độ), 今度 (lần này), 一度 (một lần). ⚠️ Nhiều nghĩa: mức ĐỘ, số LẦN, và NHIỆT ĐỘ — tuỳ ngữ cảnh.","example":"一**度**日本に行ってみたいです。 / ichido nihon ni itte mitai desu. (Tôi muốn thử đi Nhật một lần)","examples":[{"ja":"一度日本に行ってみたいです。","vi":"Tôi muốn thử đi Nhật một lần","romaji":"ichido nippon ni itsute mitai desu."},{"ja":"今度一緒に行こう","vi":"Lần sau cùng đi nhé","romaji":"Kondo issho ni iko u"},{"ja":"部屋の温度を下げる","vi":"Giảm nhiệt độ phòng","romaji":"Heya no ondo wo sageru"},{"ja":"湿度が高くて暑い","vi":"Độ ẩm cao nên nóng","romaji":"Shitsudo ga takakute atsui"}]},{"key":"k:予","kind":"kanji","level":"N5","character":"予","meaning":"Dự, trước","hanviet":"Dự","onReadings":["ヨ"],"kunReadings":["—"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"予定","reading":"よてい","meaning":"Dự định","vocabKey":"v:予定"},{"compound":"予約","reading":"よやく","meaning":"Đặt trước"},{"compound":"予習","reading":"よしゅう","meaning":"Chuẩn bị bài","vocabKey":"v:予習"}],"lessonIds":[18,30,47],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: マ (biến thể tay chỉ) + 了 (biến thể hoàn thành). Hán-Việt: DỰ. Mẹo nhớ: Tay chỉ (マ) về phía trước (了) — 'dự' định, chuẩn bị trước 👉📅. 4 nét. Âm ヨ (yo) như trong 予定 (yotei - dự định), 予約 (yoyaku - đặt trước). Liên kết: 予定 (dự định), 予約 (đặt trước), 予習 (chuẩn bị bài). ⚠️ Chỉ 4 nét nhưng nhiều từ quan trọng — 予定 và 予約 rất hay dùng.","example":"明日の**予**定を教えてください。 / ashita no yotei wo oshiete kudasai. (Hãy cho tôi biết dự định ngày mai)","examples":[{"ja":"明日の予定を教えてください。","vi":"Hãy cho tôi biết dự định ngày mai","romaji":"ashita no yotei wo oshiete kudasai."},{"ja":"ホテルを予約する","vi":"Đặt khách sạn","romaji":"Hoteru wo yoyaku suru"},{"ja":"授業の前に予習する","vi":"Soạn bài trước giờ học","romaji":"jugyou no mae ni yoshuu suru"},{"ja":"天気予報を見る","vi":"Xem dự báo thời tiết","romaji":"tenki yohou o miru"}]},{"key":"k:理","kind":"kanji","level":"N5","character":"理","meaning":"Lý, lẽ, đạo lý","hanviet":"Lý","onReadings":["リ"],"kunReadings":["—"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"理由","reading":"りゆう","meaning":"Lý do","vocabKey":"v:理由"},{"compound":"料理","reading":"りょうり","meaning":"Nấu ăn","vocabKey":"v:料理"},{"compound":"理解","reading":"りかい","meaning":"Hiểu","vocabKey":"v:理解"}],"lessonIds":[9,19,20,32,41,43,45],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 王 (ngọc/vua) + 里 (làng/dặm). Hán-Việt: LÝ. Mẹo nhớ: Mài ngọc (王) thành từng lớp như ruộng trong làng (里) — tìm ra 'lý' lẽ, đạo lý 💎. 11 nét. Âm リ (ri) như trong 理由 (riyuu - lý do), 料理 (ryouri - nấu ăn). Liên kết: 理由 (lý do), 料理 (nấu ăn), 理解 (hiểu). ⚠️ 王 bên trái thực ra là bộ 玉 (ngọc) viết tắt.","example":"遅れた**理**由を説明してください。 / okureta riyuu wo setsumei shite kudasai. (Hãy giải thích lý do đến trễ)","examples":[{"ja":"遅れた理由を説明してください。","vi":"Hãy giải thích lý do đến trễ","romaji":"okureta riyuu wo setsumei shite kudasai."},{"ja":"車を修理する","vi":"Sửa xe","romaji":"kuruma o shuuri suru"},{"ja":"毎日料理する","vi":"Nấu ăn mỗi ngày","romaji":"mainichi ryouri suru"},{"ja":"無理なお願い","vi":"Yêu cầu vô lý","romaji":"Muri nao negai"}]},{"key":"k:特","kind":"kanji","level":"N5","character":"特","meaning":"Đặc biệt","hanviet":"Đặc","onReadings":["トク"],"kunReadings":["—"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"特に","reading":"とくに","meaning":"Đặc biệt","vocabKey":"v:特に"},{"compound":"特別","reading":"とくべつ","meaning":"Đặc biệt"}],"lessonIds":[5,15,18,36],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 牛 (bò) + 寺 (chùa/trì). Hán-Việt: ĐẶC. Mẹo nhớ: Con bò (牛) ở chùa (寺) — thật 'đặc' biệt, hiếm thấy 🐂⛩️. 10 nét. Âm トク (toku) trong 特に (tokuni - đặc biệt), 特別 (tokubetsu - đặc biệt). Liên kết: 特に (đặc biệt), 特別 (đặc biệt). ⚠️ Đừng nhầm 牛 (bò 4 nét) với 午 (ngọ 4 nét) — 牛 có nét dọc xuyên ngang trên.","example":"**特**に好きな食べ物は何ですか。 / tokuni sukina tabemono wa nan desu ka. (Bạn đặc biệt thích món ăn nào?)","examples":[{"ja":"特に好きな食べ物は何ですか。","vi":"Bạn đặc biệt thích món ăn nào?","romaji":"tokuni suki na tabemono wa nani desu ka."},{"ja":"特別な日","vi":"Ngày đặc biệt","romaji":"tokubetsu na hi"},{"ja":"特急は速い","vi":"Tàu tốc hành nhanh","romaji":"tokkyuu wa hayai"},{"ja":"特に好きな食べ物","vi":"Đồ ăn đặc biệt thích","romaji":"Toku ni suki na tabemono"}]},{"key":"k:別","kind":"kanji","level":"N5","character":"別","meaning":"Chia, khác, riêng biệt","hanviet":"Biệt","onReadings":["ベツ"],"kunReadings":["わか"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"別れる","reading":"わかれる","meaning":"Chia tay","vocabKey":"v:別れる"},{"compound":"特別","reading":"とくべつ","meaning":"Đặc biệt"},{"compound":"別に","reading":"べつに","meaning":"Không đặc biệt"}],"lessonIds":[13,36,44,47],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 口 (miệng) + 力 (lực) + 刂 (dao đứng). Hán-Việt: BIỆT. Mẹo nhớ: Dùng sức (力) và dao (刂) để tách — 'biệt' ly, chia tay, khác biệt ✂️. 7 nét. Âm ベツ (betsu), わかれる (wakareru) = chia tay. Liên kết: 別れる (chia tay), 特別 (đặc biệt), 別に (không đặc biệt). ⚠️ Bên phải là 刂 (dao) — nhiều chữ có 刂 đều mang nghĩa cắt/chia.","example":"友達と駅で**別**れました。 / tomodachi to eki de wakaremashita. (Tôi đã chia tay bạn ở ga)","examples":[{"ja":"友達と駅で別れました。","vi":"Tôi đã chia tay bạn ở ga","romaji":"tomodachi to eki de wakaremashita."},{"ja":"彼女と別れる","vi":"Chia tay bạn gái","romaji":"Kanojo to wakareru"},{"ja":"特別な日","vi":"Ngày đặc biệt","romaji":"tokubetsu na hi"},{"ja":"性別を書く","vi":"Ghi giới tính","romaji":"Seibetsu wo kaku"}]},{"key":"k:必","kind":"kanji","level":"N4","character":"必","meaning":"Tất yếu, nhất định","hanviet":"Tất","onReadings":["ヒツ"],"kunReadings":["かなら"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"必要","reading":"ひつよう","meaning":"Cần thiết"},{"compound":"必ず","reading":"かならず","meaning":"Nhất định","vocabKey":"v:必ず"}],"lessonIds":[35,36,40],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 心 (tim) + 丿 (phiệt ngang). Hán-Việt: TẤT. Mẹo nhớ: Trái tim (心) bị nét xuyên qua — điều 'tất' yếu, nhất định phải có ❤️‍🔥. 5 nét. Âm ヒツ (hitsu) trong 必要 (hitsuyou - cần thiết), かならず (kanarazu) = nhất định. Liên kết: 必要 (cần thiết), 必ず (nhất định). ⚠️ Thứ tự nét: giữa → trái → trái → phải → phải (khác 心).","example":"パスポートは**必**要ですか。 / pasupooto wa hitsuyou desu ka. (Hộ chiếu có cần thiết không?)","examples":[{"ja":"パスポートは必要ですか。","vi":"Hộ chiếu có cần thiết không?","romaji":"pasupooto wa hitsuyou desu ka."},{"ja":"必要な書類","vi":"Tài liệu cần thiết","romaji":"hitsuyou na shorui"},{"ja":"必ず来てください","vi":"Nhất định phải đến nhé","romaji":"kanarazu kite kudasai"},{"ja":"何が必要か、メモしてください。","vi":"Hãy ghi chú xem cần gì.","romaji":"nani ga hitsuyou ka, memo shite kudasai."}]},{"key":"k:不","kind":"kanji","level":"N5","character":"不","meaning":"Bất, không","hanviet":"Bất","onReadings":["フ","ブ"],"kunReadings":["—"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"不便","reading":"ふべん","meaning":"Bất tiện"},{"compound":"不安","reading":"ふあん","meaning":"Bất an","vocabKey":"v:不安"},{"compound":"不思議","reading":"ふしぎ","meaning":"Kỳ lạ"}],"lessonIds":[21,27],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 不 là chữ chỉ sự — nét ngang (一) bị chặn bởi nét dọc và phiệt. Hán-Việt: BẤT. Mẹo nhớ: Hoa nở nhưng bị chặn, không nở được — 'bất' là không, phủ định ❌. 4 nét. Âm フ (fu) trong 不便 (fuben - bất tiện), ブ (bu) trong 不気味 (bukimi). Liên kết: 不便 (bất tiện), 不安 (bất an), 不思議 (kỳ lạ). ⚠️ Tiền tố phủ định mạnh — đứng trước từ để phủ nhận: 不 + 安 = bất an.","example":"この場所は少し**不**便です。 / kono basho wa sukoshi fuben desu. (Nơi này hơi bất tiện)","examples":[{"ja":"この場所は少し不便です。","vi":"Nơi này hơi bất tiện","romaji":"kono basho wa sukoshi fuben desu."},{"ja":"不便な場所","vi":"Nơi bất tiện","romaji":"Fuben na basho"},{"ja":"不思議な話","vi":"Câu chuyện bí ẩn","romaji":"Fushigi na hanashi"},{"ja":"給料に不満がある","vi":"Bất mãn với lương","romaji":"kyuuryou ni fuman ga aru"}]},{"key":"k:方","kind":"kanji","level":"N5","character":"方","meaning":"Phương hướng, cách, người (kính ngữ)","hanviet":"Phương","onReadings":["ホウ"],"kunReadings":["かた"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"方法","reading":"ほうほう","meaning":"Phương pháp"},{"compound":"読み方","reading":"よみかた","meaning":"Cách đọc","vocabKey":"v:読み方"},{"compound":"夕方","reading":"ゆうがた","meaning":"Chiều tối","vocabKey":"v:夕方"}],"lessonIds":[1,14,29,31,32],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 方 là chữ tượng hình — hình cái cày chỉ phương hướng. Hán-Việt: PHƯƠNG. Mẹo nhớ: Cái cày chỉ hướng ra ruộng — 'phương' hướng, cách thức 🧭. 4 nét. Âm ホウ (hou) trong 方法 (houhou - phương pháp), かた (kata) = cách/người. Liên kết: 方法 (phương pháp), 読み方 (cách đọc), 夕方 (chiều tối). ⚠️ Đừng nhầm với 万 (vạn) — 方 có nét ngang + nét gãy, 万 khác cấu trúc.","example":"**使**い**方**がわかりません。 / tsukaikata ga wakarimasen. (Tôi không hiểu cách sử dụng)","examples":[{"ja":"使い方がわかりません。","vi":"Tôi không hiểu cách sử dụng","romaji":"tsukaikata ga wakarimasen."},{"ja":"あの方はだれですか","vi":"Người kia là ai?","romaji":"ano hou wa dare desu ka"},{"ja":"夕方に帰る","vi":"Về lúc chiều tối","romaji":"yuugata ni kaeru"},{"ja":"地方に住む","vi":"Sống ở vùng","romaji":"chihou ni sumu"}]},{"key":"k:法","kind":"kanji","level":"N4","character":"法","meaning":"Pháp luật, phương pháp","hanviet":"Pháp","onReadings":["ホウ"],"kunReadings":["—"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"方法","reading":"ほうほう","meaning":"Phương pháp"},{"compound":"文法","reading":"ぶんぽう","meaning":"Ngữ pháp","vocabKey":"v:文法"},{"compound":"法律","reading":"ほうりつ","meaning":"Pháp luật","vocabKey":"v:法律"}],"lessonIds":[41,42],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 氵(nước) + 去 (đi/bỏ). Hán-Việt: PHÁP. Mẹo nhớ: Nước (氵) chảy đi (去) theo luật tự nhiên — 'pháp' luật, phương pháp, quy tắc ⚖️. 8 nét. Âm ホウ (hou) trong 方法 (houhou - phương pháp), 文法 (bunpou - ngữ pháp). Liên kết: 方法 (phương pháp), 文法 (ngữ pháp), 法律 (pháp luật). ⚠️ Cặp đôi 方法: 方 (phương) + 法 (pháp) — cả hai đều đọc hou.","example":"日本の**法**律を守らなければなりません。 / nihon no houritsu wo mamoranakereba narimasen. (Phải tuân thủ pháp luật Nhật Bản)","examples":[{"ja":"日本の法律を守らなければなりません。","vi":"Phải tuân thủ pháp luật Nhật Bản","romaji":"nippon no houritsu o mamora nakere ba narimasen."},{"ja":"文法を勉強する","vi":"Học ngữ pháp","romaji":"bunpou o benkyou suru"},{"ja":"法律を守る","vi":"Tuân thủ pháp luật","romaji":"houritsu o mamoru"},{"ja":"使用方法を説明する","vi":"Giải thích cách sử dụng","romaji":"shiyou houhou o setsumei suru"}]},{"key":"k:以","kind":"kanji","level":"N4","character":"以","meaning":"Từ, bằng, dĩ","hanviet":"Dĩ","onReadings":["イ"],"kunReadings":["—"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"以上","reading":"いじょう","meaning":"Trở lên","vocabKey":"v:以上"},{"compound":"以下","reading":"いか","meaning":"Trở xuống","vocabKey":"v:以下"},{"compound":"以前","reading":"いぜん","meaning":"Trước đây","vocabKey":"v:以前"}],"lessonIds":[40,45],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 人 (người — biến thể) + 丶 (chấm) + 㠯 (dạng cổ). Hán-Việt: DĨ. Mẹo nhớ: Người (人 biến thể) dùng cái gì đó (丶) làm mốc — 'dĩ' là từ đó trở đi, lấy làm chuẩn 📍. 5 nét. Âm イ (i) như trong 以上 (ijou - trở lên), 以下 (ika - trở xuống). Liên kết: 以上 (trở lên), 以下 (trở xuống), 以前 (trước đây). ⚠️ 以上/以下/以前/以後 — bộ tứ quan trọng, đều bắt đầu bằng 以.","example":"18歳**以**上の方が参加できます。 / juuhassai ijou no kata ga sanka dekimasu. (Người từ 18 tuổi trở lên có thể tham gia)","examples":[{"ja":"18歳以上の方が参加できます。","vi":"Người từ 18 tuổi trở lên có thể tham gia","romaji":"18sai ijou no hou ga sanka dekimasu."},{"ja":"以前ここに住んでいた","vi":"Trước đây sống ở đây","romaji":"Izen kokoni sun deita"},{"ja":"以後気をつける","vi":"Từ nay cẩn thận","romaji":"Igo ki wo tsukeru"},{"ja":"18歳以上の方のみ入場できます","vi":"Chỉ người từ 18 tuổi trở lên","romaji":"18sai ijou no hou nomi nyuujou dekimasu"}]},{"key":"k:質","kind":"kanji","level":"N4","character":"質","meaning":"Chất, phẩm chất, hỏi","hanviet":"Chất","onReadings":["シツ"],"kunReadings":["—"],"strokeCount":15,"radicals":[],"components":[],"compounds":[{"compound":"質問","reading":"しつもん","meaning":"Câu hỏi","vocabKey":"v:質問"},{"compound":"品質","reading":"ひんしつ","meaning":"Chất lượng"}],"lessonIds":[34],"topicTags":[],"sectionId":12,"sectionName":"KHÁI NIỆM TRỪU TƯỢNG","mnemonic":"Bộ/thành phần: 斤 (rìu) × 2 + 貝 (vỏ sò/tiền). Hán-Việt: CHẤT. Mẹo nhớ: Hai lần rìu (斤斤) chẻ vỏ sò (貝) để xem 'chất' lượng bên trong 💰🔍. 15 nét. Âm シツ (shitsu) trong 質問 (shitsumon - câu hỏi), 品質 (hinshitsu - chất lượng). Liên kết: 質問 (câu hỏi), 品質 (chất lượng). ⚠️ 質問 vừa là 'chất vấn' vừa là 'câu hỏi' — nghĩa VN khác tùy ngữ cảnh.","example":"**質**問があります。 / shitsumon ga arimasu. (Tôi có câu hỏi)","examples":[{"ja":"質問があります。","vi":"Tôi có câu hỏi","romaji":"shitsumon ga arimasu."},{"ja":"先生に質問する","vi":"Hỏi thầy cô","romaji":"Sensei ni shitsumon suru"},{"ja":"質問をする","vi":"Đặt câu hỏi","romaji":"Shitsumon wo suru"},{"ja":"水の性質を学ぶ","vi":"Học tính chất của nước","romaji":"Mizu no seishitsu wo manabu"}]},{"key":"k:映","kind":"kanji","level":"N5","character":"映","meaning":"Chiếu, phản ánh","hanviet":"Ánh","onReadings":["エイ"],"kunReadings":["うつ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"映画","reading":"えいが","meaning":"Phim","vocabKey":"v:映画"},{"compound":"映る","reading":"うつる","meaning":"Phản chiếu"}],"lessonIds":[4,31],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 央 (trung ương). Hán-Việt: ÁNH. Mẹo nhớ: Mặt trời (日) chiếu vào trung tâm (央) — 'ánh' sáng phản chiếu, chiếu phim 🌞🎥. 9 nét. Âm エイ (ei) như trong 映画 (eiga - phim), うつる (utsuru) = phản chiếu. Liên kết: 映画 (phim), 映る (phản chiếu). ⚠️ Cùng bộ 央 với 英 (anh) — nhưng 英 có 艹 (cỏ), 映 có 日 (mặt trời).","example":"昨日**映**画を見に行きました。 / kinou eiga wo mi ni ikimashita. (Hôm qua tôi đi xem phim)","examples":[{"ja":"昨日映画を見に行きました。","vi":"Hôm qua tôi đi xem phim","romaji":"kinou eiga wo mi ni ikimashita."},{"ja":"映画館で映画を見る","vi":"Xem phim ở rạp","romaji":"Eigakan de eiga wo miru"},{"ja":"映画を見る","vi":"Xem phim","romaji":"Eiga wo miru"},{"ja":"この映画はおもしろいですね。","vi":"Phim này hay nhỉ.","romaji":"kono eiga wa omoshiroi desu ne."}]},{"key":"k:屋","kind":"kanji","level":"N5","character":"屋","meaning":"Nhà, tiệm, mái","hanviet":"Ốc","onReadings":["オク"],"kunReadings":["や"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"部屋","reading":"へや","meaning":"Phòng","vocabKey":"v:部屋"},{"compound":"本屋","reading":"ほんや","meaning":"Tiệm sách"},{"compound":"屋上","reading":"おくじょう","meaning":"Sân thượng","vocabKey":"v:屋上"}],"lessonIds":[3,10,15,23,35,39],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 尸 (thân/xác) + 至 (đến). Hán-Việt: ỐC. Mẹo nhớ: Dưới mái che (尸) là nơi người ta đến (至) trú ngụ — 'ốc' là nhà, tiệm 🏠. 9 nét. Âm オク (oku), や (ya) như trong 本屋 (honya - tiệm sách). Liên kết: 部屋 (phòng), 本屋 (tiệm sách), 屋上 (sân thượng). ⚠️ 尸 là mái che, không phải 'xác chết' — nhiều kanji dùng 尸 đều liên quan nhà/che.","example":"駅の近くに花**屋**があります。 / eki no chikaku ni hanaya ga arimasu. (Gần ga có tiệm hoa)","examples":[{"ja":"駅の近くに花屋があります。","vi":"Gần ga có tiệm hoa","romaji":"eki no chikaku ni hanaya ga arimasu."},{"ja":"部屋を掃除する","vi":"Dọn phòng","romaji":"heya o souji suru"},{"ja":"屋上で洗濯物を干す","vi":"Phơi đồ trên sân thượng","romaji":"okujou de sentakubutsu o hosu"},{"ja":"屋根を修理する","vi":"Sửa mái nhà","romaji":"yane o shuuri suru"}]},{"key":"k:館","kind":"kanji","level":"N5","character":"館","meaning":"Quán, tòa nhà lớn","hanviet":"Quán","onReadings":["カン"],"kunReadings":["—"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"図書館","reading":"としょかん","meaning":"Thư viện","vocabKey":"v:図書館"},{"compound":"映画館","reading":"えいがかん","meaning":"Rạp phim","vocabKey":"v:映画館"},{"compound":"大使館","reading":"たいしかん","meaning":"Đại sứ quán","vocabKey":"v:大使館"}],"lessonIds":[4,25,28,31,49],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 飠 (ăn) + 官 (quan). Hán-Việt: QUÁN. Mẹo nhớ: Nơi có đồ ăn (飠) cho quan (官) đến ở — 'quán' là tòa nhà lớn 🏛️. 16 nét. Âm カン (kan) như trong 図書館 (toshokan - thư viện). Liên kết: 図書館 (thư viện), 映画館 (rạp phim), 大使館 (đại sứ quán). ⚠️ Nhiều nét (16) — ghi nhớ: bên trái 飠 (ăn), bên phải 官 (quan).","example":"**図書館**で本を借りました。 / toshokan de hon wo karimashita. (Tôi đã mượn sách ở thư viện)","examples":[{"ja":"図書館で本を借りました。","vi":"Tôi đã mượn sách ở thư viện","romaji":"toshokan de hon wo karimashita."},{"ja":"美術館で絵を見る","vi":"Xem tranh ở bảo tàng","romaji":"Bijutsukan de e wo miru"},{"ja":"映画館で映画を見る","vi":"Xem phim ở rạp","romaji":"Eigakan de eiga wo miru"},{"ja":"図書館で本を借りる","vi":"Mượn sách ở thư viện","romaji":"Toshokan de hon wo kariru"}]},{"key":"k:区","kind":"kanji","level":"N4","character":"区","meaning":"Quận, khu vực","hanviet":"Khu","onReadings":["ク"],"kunReadings":["—"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"区","reading":"く","meaning":"Quận"},{"compound":"地区","reading":"ちく","meaning":"Khu vực"}],"lessonIds":[],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 匚 (khung) + 㐅 (bên trong). Hán-Việt: KHU. Mẹo nhớ: Khung bao (匚) chia vùng bên trong — 'khu' vực, quận 🗺️. 4 nét (dạng giản lược). Âm ク (ku) như trong 東京の区 (ku của Tokyo). Liên kết: 区 (quận), 地区 (khu vực). ⚠️ Tokyo có 23 区 (ku) — khác với 県 (ken/tỉnh).","example":"東京には23の**区**があります。 / toukyou ni wa nijuusan no ku ga arimasu. (Tokyo có 23 quận)","examples":[{"ja":"東京には23の区があります。","vi":"Tokyo có 23 quận","romaji":"toukyou ni wa 23 no ku ga arimasu."},{"ja":"区役所で住民票をもらう","vi":"Lấy giấy cư trú ở ủy ban quận","romaji":"kuyakusho de juuminhyou o morau"}]},{"key":"k:県","kind":"kanji","level":"N5","character":"県","meaning":"Tỉnh","hanviet":"Huyện","onReadings":["ケン"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"県","reading":"けん","meaning":"Tỉnh","vocabKey":"v:県"},{"compound":"県庁","reading":"けんちょう","meaning":"Tòa tỉnh"}],"lessonIds":[10],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: biến thể của 縣 (huyện) — phần trên + 小 (nhỏ) + 目 (mắt). Hán-Việt: HUYỆN. Mẹo nhớ: Mắt (目) nhìn xuống vùng nhỏ (小) — 'huyện' là tỉnh, đơn vị hành chính 🏯. 9 nét. Âm ケン (ken) như trong 沖縄県 (Okinawa-ken). Liên kết: 県 (tỉnh), 県庁 (tòa tỉnh). ⚠️ Nhật Bản có 47 都道府県 — hầu hết là 県 (ken), riêng Tokyo là 都.","example":"沖縄**県**に行ったことがありますか。 / okinawa-ken ni itta koto ga arimasu ka. (Bạn đã từng đi tỉnh Okinawa chưa?)","examples":[{"ja":"沖縄県に行ったことがありますか。","vi":"Bạn đã từng đi tỉnh Okinawa chưa?","romaji":"okinawaken ni itsuta koto ga arimasu ka."},{"ja":"日本の都道府県を覚える","vi":"Học các tỉnh thành của Nhật","romaji":"nippon no todoufuken o oboeru"},{"ja":"東京ディズニーランドは千葉県にあります。","vi":"Công viên Tokyo Disneyland ở tỉnh Chiba.","romaji":"toukyou dizuniirando wa chibaken ni arimasu."},{"ja":"県","vi":"tỉnh","romaji":"ken"}]},{"key":"k:市","kind":"kanji","level":"N5","character":"市","meaning":"Thành phố, chợ","hanviet":"Thị","onReadings":["シ"],"kunReadings":["いち"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"市","reading":"し","meaning":"Thành phố"},{"compound":"市場","reading":"いちば","meaning":"Chợ"},{"compound":"市民","reading":"しみん","meaning":"Thị dân"}],"lessonIds":[13],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 亠 (đủ đầu) + 巾 (khăn). Hán-Việt: THỊ. Mẹo nhớ: Khăn (巾) trải ra dưới mái (亠) — nơi buôn bán, 'thị' trường, chợ 🏪. 5 nét. Âm シ (shi) như trong 市場 (ichiba - chợ), いち (ichi) = chợ. Liên kết: 市 (thành phố), 市場 (chợ), 市民 (thị dân). ⚠️ 市 vừa là 'thành phố' (シ/shi) vừa là 'chợ' (いち/ichi) — 2 nghĩa khác nhau.","example":"この**市**は人口が多いです。 / kono shi wa jinkou ga ooi desu. (Thành phố này đông dân)","examples":[{"ja":"この市は人口が多いです。","vi":"Thành phố này đông dân","romaji":"kono shi wa jinkou ga ooi desu."},{"ja":"市役所で住所変更の手続きをする","vi":"Làm thủ tục đổi địa chỉ ở tòa thị chính","romaji":"shiyakusho de juusho henkou no tetsuzuki o suru"},{"ja":"あした 市役所へ 行く 用事が あります。","vi":"Ngày mai tôi có việc bận phải đi đến Ủy ban hành chính thành phố.","romaji":"ashita shiyakusho e iku youji ga arimasu."},{"ja":"市役所","vi":"văn phòng hành chính thành phố, ủy ban nhân dân thành phố","romaji":"shiyakusho"}]},{"key":"k:場","kind":"kanji","level":"N5","character":"場","meaning":"Nơi, trường, bãi","hanviet":"Trường","onReadings":["ジョウ"],"kunReadings":["ば"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"場所","reading":"ばしょ","meaning":"Địa điểm","vocabKey":"v:場所"},{"compound":"場合","reading":"ばあい","meaning":"Trường hợp"},{"compound":"駐車場","reading":"ちゅうしゃじょう","meaning":"Bãi đỗ xe","vocabKey":"v:駐車場"}],"lessonIds":[3,10,23,26,35,38,39],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 土 (đất) + 易 (dương/dễ — biến thể 昜). Hán-Việt: TRƯỜNG. Mẹo nhớ: Mảnh đất (土) rộng mở (昜 = mặt trời mọc) — 'trường' là nơi, bãi, địa điểm 🏗️. 12 nét. Âm ジョウ (jou), ば (ba) như trong 場所 (basho - địa điểm). Liên kết: 場所 (địa điểm), 場合 (trường hợp), 駐車場 (bãi đỗ xe). ⚠️ 場所 (địa điểm) và 場合 (trường hợp) đều dùng 場 nhưng nghĩa rất khác.","example":"待ち合わせの**場**所はどこですか。 / machiawase no basho wa doko desu ka. (Nơi hẹn gặp là ở đâu?)","examples":[{"ja":"待ち合わせの場所はどこですか。","vi":"Nơi hẹn gặp là ở đâu?","romaji":"machiawase no basho wa doko desu ka."},{"ja":"静かな場所","vi":"Nơi yên tĩnh","romaji":"Shizuka na basho"},{"ja":"コンサートの会場はとても広かった","vi":"Hội trường rất rộng","romaji":"konsaato no kaijou wa totemo hirokatsuta"},{"ja":"父は自動車工場で働いています","vi":"Bố làm ở nhà máy xe hơi","romaji":"chichi wa jidousha koujou de hataraite imasu"}]},{"key":"k:京","kind":"kanji","level":"N5","character":"京","meaning":"Kinh đô, thủ đô","hanviet":"Kinh","onReadings":["キョウ","ケイ"],"kunReadings":["—"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"東京","reading":"とうきょう","meaning":"Tokyo"},{"compound":"京都","reading":"きょうと","meaning":"Kyoto"}],"lessonIds":[10],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 亠 (đầu) + 口 (miệng) + 小 (nhỏ). Hán-Việt: KINH. Mẹo nhớ: Lầu cao (亠) với cổng (口) và người (小) tấp nập — 'kinh' đô, thủ đô 🏯. 8 nét. Âm キョウ (kyou) trong 東京 (toukyou - Tokyo), ケイ (kei). Liên kết: 東京 (Tokyo), 京都 (Kyoto). ⚠️ 東京 = 'đông kinh', 京都 = 'kinh đô' — cả hai đều có 京.","example":"**京**都はとてもきれいな町です。 / kyouto wa totemo kireina machi desu. (Kyoto là thành phố rất đẹp)","examples":[{"ja":"京都はとてもきれいな町です。","vi":"Kyoto là thành phố rất đẹp","romaji":"kyouto wa totemo kireina machi desu."},{"ja":"東京から大阪まで3時間かかります。","vi":"Từ Tokyo đến Osaka mất 3 tiếng.","romaji":"toukyou kara oosaka made 3jikan kakarimasu."},{"ja":"京都へ行きます。","vi":"Tôi đi Kyoto.","romaji":"kyouto e ikimasu."},{"ja":"いっしょに京都へ行きませんか。","vi":"Anh/Chị có đi Kyoto cùng với tôi không?","romaji":"issho ni kyouto e ikimasen ka."}]},{"key":"k:建","kind":"kanji","level":"N4","character":"建","meaning":"Xây dựng","hanviet":"Kiến","onReadings":["ケン"],"kunReadings":["た","た"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"建てる","reading":"たてる","meaning":"Xây dựng","vocabKey":"v:建てる"},{"compound":"建物","reading":"たてもの","meaning":"Tòa nhà","vocabKey":"v:建物"}],"lessonIds":[27],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 廴 (sách/đi vòng) + 聿 (bút). Hán-Việt: KIẾN. Mẹo nhớ: Cầm bút (聿) vẽ thiết kế rồi thi công (廴) — 'kiến' tạo, xây dựng 🏗️. 9 nét. Âm ケン (ken), たてる (tateru) = xây dựng. Liên kết: 建てる (xây dựng), 建物 (tòa nhà). ⚠️ 廴 (sách) là bộ thường gặp trong kanji liên quan di chuyển/xây dựng.","example":"新しい家を**建**てたいです。 / atarashii ie wo tatetai desu. (Tôi muốn xây nhà mới)","examples":[{"ja":"新しい家を建てたいです。","vi":"Tôi muốn xây nhà mới","romaji":"atarashii ie wo tatetai desu."},{"ja":"家を建てる","vi":"Xây nhà","romaji":"Ie wo tateru"},{"ja":"あの建物は何階建てですか","vi":"Tòa nhà đó có bao nhiêu tầng?","romaji":"ano tatemono wa nankaidate desu ka"},{"ja":"新しいビルの建設が始まった","vi":"Bắt đầu xây tòa nhà mới","romaji":"atarashii biru no kensetsu ga hajimatsuta"}]},{"key":"k:公","kind":"kanji","level":"N5","character":"公","meaning":"Công cộng","hanviet":"Công","onReadings":["コウ"],"kunReadings":["おおやけ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"公園","reading":"こうえん","meaning":"Công viên","vocabKey":"v:公園"},{"compound":"公共","reading":"こうきょう","meaning":"Công cộng"}],"lessonIds":[10,27],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 八 (tám/chia) + 厶 (riêng tư). Hán-Việt: CÔNG. Mẹo nhớ: Chia (八) cái riêng tư (厶) ra cho mọi người — 'công' cộng, công khai 🏞️. 4 nét. Âm コウ (kou), おおやけ (ooyake) = công cộng. Liên kết: 公園 (công viên), 公共 (công cộng). ⚠️ 公 đối lập với 私 (tư) — công/tư là cặp đối nghĩa.","example":"日曜日に**公**園で遊びます。 / nichiyoubi ni kouen de asobimasu. (Chủ nhật tôi chơi ở công viên)","examples":[{"ja":"日曜日に公園で遊びます。","vi":"Chủ nhật tôi chơi ở công viên","romaji":"nichiyoubi ni kouen de asobimasu."},{"ja":"公園を散歩する","vi":"Đi dạo ở công viên","romaji":"kouen o sanpo suru"},{"ja":"公園を散歩します。","vi":"Đi dạo trong công viên.","romaji":"kouen o sanpo shimasu."},{"ja":"来月、近くに大きい公園ができます。","vi":"Tháng sau, công viên lớn sẽ hoàn thành gần đây.","romaji":"raigetsu, chikaku ni ookii kouen ga dekimasu."}]},{"key":"k:図","kind":"kanji","level":"N5","character":"図","meaning":"Bản đồ, sơ đồ","hanviet":"Đồ","onReadings":["ズ","ト"],"kunReadings":["はか"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"図書館","reading":"としょかん","meaning":"Thư viện","vocabKey":"v:図書館"},{"compound":"地図","reading":"ちず","meaning":"Bản đồ","vocabKey":"v:地図"}],"lessonIds":[4,14,34],"topicTags":[],"sectionId":13,"sectionName":"NƠI CHỐN & KIẾN TRÚC","mnemonic":"Bộ/thành phần: 囗 (khung bao) + phần trong (giản lược của 圖). Hán-Việt: ĐỒ. Mẹo nhớ: Khung (囗) bao quanh bản vẽ bên trong — 'đồ' là bản đồ, sơ đồ 🗺️. 7 nét. Âm ズ (zu) trong 地図 (chizu - bản đồ), ト (to) trong 図書館 (toshokan). Liên kết: 図書館 (thư viện), 地図 (bản đồ). ⚠️ 図 là dạng giản lược của 圖 — 囗 bao quanh nội dung.","example":"地**図**を見て場所を探しました。 / chizu wo mite basho wo sagashimashita. (Tôi xem bản đồ tìm địa điểm)","examples":[{"ja":"地図を見て場所を探しました。","vi":"Tôi xem bản đồ tìm địa điểm","romaji":"chizu wo mite basho wo sagashimashita."},{"ja":"地図を見る","vi":"Xem bản đồ","romaji":"Chizu wo miru"},{"ja":"図書館で本を借りる","vi":"Mượn sách ở thư viện","romaji":"Toshokan de hon wo kariru"},{"ja":"駅の方面図を見る","vi":"Xem bản đồ tuyến ở ga","romaji":"eki no houmenzu o miru"}]},{"key":"k:員","kind":"kanji","level":"N5","character":"員","meaning":"Nhân viên, thành viên","hanviet":"Viên","onReadings":["イン"],"kunReadings":["—"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"会社員","reading":"かいしゃいん","meaning":"Nhân viên","vocabKey":"v:会社員"},{"compound":"店員","reading":"てんいん","meaning":"Nhân viên cửa hàng","vocabKey":"v:店員"},{"compound":"駅員","reading":"えきいん","meaning":"Nhân viên ga","vocabKey":"v:駅員"}],"lessonIds":[1,29,45],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 口 (miệng/mở) + 貝 (vỏ sò/tiền). Hán-Việt: VIÊN. Mẹo nhớ: Miệng (口) nói và đếm tiền (貝) — nhân 'viên' làm việc 👨‍💼. 10 nét. Âm イン (in) gần 'viên'. Liên kết: 会社員 (nhân viên), 店員 (nhân viên cửa hàng). ⚠️ 貝 (bối/vỏ sò) là bộ thủ liên quan tiền bạc: 買 (mua), 売 (bán), 貸 (cho vay).","example":"兄は銀行**員**です。 / ani wa ginkouin desu. (Anh trai tôi là nhân viên ngân hàng)","examples":[{"ja":"兄は銀行員です。","vi":"Anh trai tôi là nhân viên ngân hàng","romaji":"ani wa ginkouin desu."},{"ja":"店員に聞く","vi":"Hỏi nhân viên","romaji":"Ten'in ni kiku"},{"ja":"社員が多い","vi":"Nhiều nhân viên","romaji":"shain ga ooi"},{"ja":"図書館の会員になる","vi":"Trở thành hội viên thư viện","romaji":"Toshokan no kaiin ni naru"}]},{"key":"k:親","kind":"kanji","level":"N5","character":"親","meaning":"Bố mẹ, thân thiết","hanviet":"Thân","onReadings":["シン"],"kunReadings":["おや","した"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"両親","reading":"りょうしん","meaning":"Bố mẹ","vocabKey":"v:両親"},{"compound":"親切","reading":"しんせつ","meaning":"Tốt bụng"},{"compound":"親友","reading":"しんゆう","meaning":"Bạn thân"}],"lessonIds":[8,11,34,41,48],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 立 (đứng) + 木 (cây) + 見 (nhìn). Hán-Việt: THÂN. Mẹo nhớ: Đứng (立) trên cây (木) nhìn (見) con — bố mẹ lo lắng theo dõi, đó là 'thân' 👪. 16 nét. Âm おや (oya) = bố mẹ, したしい (shitashii) = thân thiết, シン (shin) gần 'thân'. Liên kết: 両親 (bố mẹ), 親切 (tốt bụng), 親友 (bạn thân). ⚠️ 2 nghĩa khác nhau: おや (bố mẹ) vs したしい (thân thiết).","example":"**両親**に会いに国へ帰ります。 / ryoushin ni ai ni kuni e kaerimasu. (Tôi về nước để gặp bố mẹ)","examples":[{"ja":"両親に会いに国へ帰ります。","vi":"Tôi về nước để gặp bố mẹ","romaji":"ryoushin ni ai ni kuni e kaerimasu."},{"ja":"親切な人","vi":"Người tốt bụng","romaji":"shinsetsu na hito"},{"ja":"両親に会う","vi":"Gặp bố mẹ","romaji":"ryoushin ni au"},{"ja":"父親は厳しい","vi":"Bố nghiêm khắc","romaji":"chichioya wa kibishii"}]},{"key":"k:族","kind":"kanji","level":"N5","character":"族","meaning":"Tộc, gia tộc, nhóm","hanviet":"Tộc","onReadings":["ゾク"],"kunReadings":["—"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"家族","reading":"かぞく","meaning":"Gia đình","vocabKey":"v:家族"},{"compound":"民族","reading":"みんぞく","meaning":"Dân tộc"}],"lessonIds":[5,15],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 方 (phương/hướng) + 矢 (mũi tên). Hán-Việt: TỘC. Mẹo nhớ: Mũi 矢 tên bay theo cùng 方 hướng — nhóm người cùng đi, 'tộc' giống 🏹👨‍👩‍👧‍👦. 11 nét. Âm ゾク (zoku) gần 'tộc'. Liên kết: 家族 (gia đình), 民族 (dân tộc). ⚠️ Đừng nhầm 族 (tộc) với 旅 (lữ) — 族 có 矢 (tên), 旅 có 方 (phương).","example":"**家族**は4人です。 / kazoku wa yonin desu. (Gia đình tôi có 4 người)","examples":[{"ja":"家族は4人です。","vi":"Gia đình tôi có 4 người","romaji":"kazoku wa 4nin desu."},{"ja":"家族と住む","vi":"Sống với gia đình","romaji":"Kazoku to sumu"},{"ja":"家族と日本へ来ました。","vi":"Tôi đã đến Nhật Bản cùng với gia đình.","romaji":"kazoku to nippon e kimashita."},{"ja":"ご家族","vi":"Gia đình (của người khác)","romaji":"go kazoku"}]},{"key":"k:主","kind":"kanji","level":"N5","character":"主","meaning":"Chủ, chính","hanviet":"Chủ","onReadings":["シュ"],"kunReadings":["ぬし","おも"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"主人","reading":"しゅじん","meaning":"Chủ nhà/ chồng"},{"compound":"主に","reading":"おもに","meaning":"Chủ yếu"}],"lessonIds":[9,27],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 丶 (chấm/ngọn lửa) + 王 (vua). Hán-Việt: CHỦ. Mẹo nhớ: Ngọn nến (丶) trên bàn thờ vua (王) — người làm 'chủ' 👑. 5 nét. Âm ぬし (nushi) = chủ, おも (omo) = chính, シュ (shu) gần 'chủ'. Liên kết: 主人 (chủ nhà/chồng), 主に (chủ yếu). ⚠️ Đừng nhầm 主 (chủ — 5 nét, có chấm) với 王 (vương — 4 nét).","example":"**主**人は会社員です。 / shujin wa kaishain desu. (Chồng tôi là nhân viên công ty)","examples":[{"ja":"主人は会社員です。","vi":"Chồng tôi là nhân viên công ty","romaji":"shujin wa kaishain desu."},{"ja":"ご主人は何をしていますか","vi":"Chồng chị làm gì?","romaji":"Go shujin wa nani wo shiteimasuka"},{"ja":"専業主婦として家事をしている","vi":"Làm nội trợ toàn thời gian","romaji":"sengyou shufu toshite kaji o shite iru"},{"ja":"カリナさんは 学生で、マリアさんは 主婦です。","vi":"Chị Karina là sinh viên, còn chị Maria là nội trợ.","romaji":"karina san wa gakusei de, maria san wa shufu desu."}]},{"key":"k:私","kind":"kanji","level":"N5","character":"私","meaning":"Tôi, riêng tư","hanviet":"Tư","onReadings":["シ"],"kunReadings":["わたし","わたくし"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"私","reading":"わたし","meaning":"Tôi","vocabKey":"v:私"},{"compound":"私立","reading":"しりつ","meaning":"Tư lập"}],"lessonIds":[1,22,50],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 禾 (lúa) + 厶 (riêng tư). Hán-Việt: TƯ. Mẹo nhớ: Giấu lúa (禾) riêng (厶) cho mình — đó là 'tư', tôi, riêng tư 🌾. 7 nét. Âm わたし (watashi) = tôi, シ (shi) gần 'tư'. Liên kết: 私 (tôi), 私立 (tư lập). ⚠️ わたし là cách nói phổ biến nhất cho 'tôi' — lịch sự nhưng không quá trang trọng.","example":"**私**は日本語を勉強しています。 / watashi wa nihongo wo benkyou shite imasu. (Tôi đang học tiếng Nhật)","examples":[{"ja":"私は日本語を勉強しています。","vi":"Tôi đang học tiếng Nhật","romaji":"watashi wa nihongo wo benkyou shite imasu."},{"ja":"私は学生です","vi":"Tôi là sinh viên","romaji":"Watashi wa gakusei desu"},{"ja":"私たちは日本語を勉強する","vi":"Chúng tôi học tiếng Nhật","romaji":"watashitachi wa nihongo o benkyou suru"},{"ja":"私もベトナム人です。","vi":"Tôi cũng là người Việt Nam.","romaji":"watashi mo betonamujin desu."}]},{"key":"k:代","kind":"kanji","level":"N4","character":"代","meaning":"Thay thế, thời đại, giá tiền","hanviet":"Đại","onReadings":["ダイ","タイ"],"kunReadings":["か","よ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"時代","reading":"じだい","meaning":"Thời đại"},{"compound":"代わりに","reading":"かわりに","meaning":"Thay vì"}],"lessonIds":[39],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 亻 (người) + 弋 (bắn/mũi nhọn). Hán-Việt: ĐẠI. Mẹo nhớ: Người (亻) thay thế canh gác (弋) — 'đại' diện, thay thế 🔄. 5 nét. Âm かわる (kawaru) = thay, ダイ (dai) gần 'đại'. Liên kết: 時代 (thời đại), 代わりに (thay vì). ⚠️ Nhiều nghĩa: thay thế, thời đại, giá (代金 = tiền). Đừng nhầm 代 với 伐 (phạt).","example":"電話の**代**わりにメールを送りました。 / denwa no kawari ni meeru wo okurimashita. (Thay vì gọi điện, tôi đã gửi email)","examples":[{"ja":"電話の代わりにメールを送りました。","vi":"Thay vì gọi điện, tôi đã gửi email","romaji":"denwa no kawari ni meeru wo okurimashita."},{"ja":"季節が代わる","vi":"Mùa thay đổi","romaji":"Kisetsu ga kawaru"},{"ja":"代","vi":"phí, tiền ~","romaji":"dai"},{"ja":"来月から電気代が上がるそうです","vi":"Nghe nói từ tháng sau tiền điện sẽ tăng.","romaji":"Raigetsu kara denkidai ga agaru sou desu"}]},{"key":"k:業","kind":"kanji","level":"N5","character":"業","meaning":"Nghiệp, công việc","hanviet":"Nghiệp","onReadings":["ギョウ","ゴウ"],"kunReadings":["わざ"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"授業","reading":"じゅぎょう","meaning":"Tiết học","vocabKey":"v:授業"},{"compound":"卒業","reading":"そつぎょう","meaning":"Tốt nghiệp","vocabKey":"v:卒業"},{"compound":"産業","reading":"さんぎょう","meaning":"Công nghiệp"}],"lessonIds":[17,30,31,46,48],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 业 (trên) + phần dưới phức tạp. Hán-Việt: NGHIỆP. Mẹo nhớ: Chữ phức tạp 13 nét — nghiệp lớn, công việc lớn 💼. Âm わざ (waza) = kỹ năng, ギョウ (gyou) gần 'nghiệp'. Liên kết: 授業 (tiết học), 卒業 (tốt nghiệp), 産業 (công nghiệp). ⚠️ 授業 (jugyou) = tiết học, 卒業 (sotsugyou) = tốt nghiệp — phân biệt qua chữ ghép.","example":"来年大学を**卒業**します。 / rainen daigaku wo sotsugyou shimasu. (Năm sau tôi tốt nghiệp đại học)","examples":[{"ja":"来年大学を卒業します。","vi":"Năm sau tôi tốt nghiệp đại học","romaji":"rainen daigaku wo sotsugyou shimasu."},{"ja":"大学を卒業する","vi":"Tốt nghiệp đại học","romaji":"daigaku o sotsugyou suru"},{"ja":"専業主婦として家事をしている","vi":"Làm nội trợ toàn thời gian","romaji":"sengyou shufu toshite kaji o shite iru"},{"ja":"授業が始まる","vi":"Tiết học bắt đầu","romaji":"jugyou ga hajimaru"}]},{"key":"k:産","kind":"kanji","level":"N5","character":"産","meaning":"Sản xuất, sinh sản","hanviet":"Sản","onReadings":["サン"],"kunReadings":["う"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"生産","reading":"せいさん","meaning":"Sản xuất"},{"compound":"お土産","reading":"おみやげ","meaning":"Quà lưu niệm","vocabKey":"v:お土産"}],"lessonIds":[2,37],"topicTags":[],"sectionId":14,"sectionName":"CON NGƯỜI & XÃ HỘI","mnemonic":"Bộ/thành phần: 产 (trên — biến thể) + 生 (sinh/sống). Hán-Việt: SẢN. Mẹo nhớ: Sinh (生) ra sản phẩm — 'sản' xuất, sản sinh 🏭. 11 nét. Âm うむ (umu) = sinh, サン (san) gần 'sản'. Liên kết: 生産 (sản xuất), お土産 (quà lưu niệm). ⚠️ お土産 (omiyage) đọc đặc biệt — nghĩa gốc: sản vật (産) của vùng đất (土).","example":"お土**産**を買って帰りました。 / omiyage wo katte kaerimashita. (Tôi đã mua quà lưu niệm mang về)","examples":[{"ja":"お土産を買って帰りました。","vi":"Tôi đã mua quà lưu niệm mang về","romaji":"o miyage o katsute kaerimashita."},{"ja":"車を生産する","vi":"Sản xuất xe","romaji":"Kuruma wo seisan suru"},{"ja":"お土産を買う","vi":"Mua quà lưu niệm","romaji":"O miyage wo kau"},{"ja":"お土産","vi":"Quà tặng","romaji":"o miyage"}]},{"key":"k:歌","kind":"kanji","level":"N5","character":"歌","meaning":"Bài hát, hát","hanviet":"Ca","onReadings":["カ"],"kunReadings":["うた"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"歌う","reading":"うたう","meaning":"Hát","vocabKey":"v:歌う"},{"compound":"歌手","reading":"かしゅ","meaning":"Ca sĩ","vocabKey":"v:歌手"}],"lessonIds":[9,18,28,31,42,48],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 哥 (anh/ca — gợi âm) + 欠 (há miệng/ngáp). Hán-Việt: CA. Mẹo nhớ: Anh (哥) há miệng (欠) mà hát — 'ca' hát 🎤! 14 nét. Âm うたう (utau) = hát, カ (ka) gần 'ca'. Liên kết: 歌う (hát), 歌手 (ca sĩ). ⚠️ 哥 gồm 2 chữ 可 xếp chồng — nhớ hình dạng để viết đúng.","example":"彼女は**歌**が上手です。 / kanojo wa uta ga jouzu desu. (Cô ấy hát giỏi)","examples":[{"ja":"彼女は歌が上手です。","vi":"Cô ấy hát giỏi","romaji":"kanojo wa uta ga jouzu desu."},{"ja":"歌を歌う","vi":"Hát bài hát","romaji":"Uta wo utau"},{"ja":"私は歌は下手です。","vi":"Tôi hát dở lắm.","romaji":"watashi wa uta wa heta desu."},{"ja":"彼女はピアノは上手ですが、歌は下手です。","vi":"Cô ấy đàn piano giỏi nhưng hát thì dở.","romaji":"kanojo wa piano wa jouzu desu ga, uta wa heta desu."}]},{"key":"k:画","kind":"kanji","level":"N5","character":"画","meaning":"Hình vẽ, kế hoạch","hanviet":"Họa","onReadings":["ガ","カク"],"kunReadings":["—"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"映画","reading":"えいが","meaning":"Phim","vocabKey":"v:映画"},{"compound":"計画","reading":"けいかく","meaning":"Kế hoạch","vocabKey":"v:計画"},{"compound":"漫画","reading":"まんが","meaning":"Truyện tranh","vocabKey":"v:漫画"}],"lessonIds":[4,31],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 一 (nét ngang) + 由 (do/lý do) + 凵 (khung). Hán-Việt: HỌA. Mẹo nhớ: Đặt khung (凵) quanh bức tranh, thêm nét (一) hoàn thiện — đó là 'họa', vẽ tranh 🖼️. 8 nét. Âm ガ (ga) trong 映画, カク (kaku) trong 計画. Liên kết: 映画 (phim), 計画 (kế hoạch), 漫画 (manga). ⚠️ 2 cách đọc khác nghĩa: ガ = tranh/vẽ, カク = hoạch/kế hoạch.","example":"夏休みの**計画**を友達と一緒に立てました。 / natsuyasumi no keikaku wo tomodachi to issho ni tatemashita. (Tôi đã lập kế hoạch nghỉ hè cùng bạn.)","examples":[{"ja":"夏休みの計画を友達と一緒に立てました。","vi":"Tôi đã lập kế hoạch nghỉ hè cùng bạn.","romaji":"natsuyasumi no keikaku wo tomodachi to issho ni tatemashita."},{"ja":"旅行の日程を計画しています","vi":"Lên kế hoạch lịch trình","romaji":"ryokou no nittei o keikaku shite imasu"},{"ja":"映画館で映画を見る","vi":"Xem phim ở rạp","romaji":"Eigakan de eiga wo miru"},{"ja":"夏休みの計画を立てました","vi":"Lập kế hoạch nghỉ hè","romaji":"Natsuyasumi no keikaku wo tatemashita"}]},{"key":"k:回","kind":"kanji","level":"N5","character":"回","meaning":"Lần, vòng, xoay","hanviet":"Hồi","onReadings":["カイ"],"kunReadings":["まわ","まわ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"一回","reading":"いっかい","meaning":"Một lần","vocabKey":"v:一回"},{"compound":"回る","reading":"まわる","meaning":"Xoay"}],"lessonIds":[11,19,23,45],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 囗 (vây quanh) + 口 (miệng/ô vuông nhỏ). Hán-Việt: HỒI. Mẹo nhớ: Ô nhỏ (口) xoay bên trong ô lớn (囗) — quay vòng tròn, 'hồi' = lần, vòng xoay 🔄. 6 nét. Âm まわる (mawaru) = xoay, カイ (kai) gần 'hồi'. Liên kết: 一回 (một lần), 回る (quay). ⚠️ Đừng nhầm 回 (hồi/lần) với 因 (nhân/nguyên nhân) — 回 có 口 bên trong, 因 có 大.","example":"週に三**回**日本語を勉強します。 / shuu ni sankai nihongo wo benkyou shimasu. (Tôi học tiếng Nhật 3 lần một tuần)","examples":[{"ja":"週に三回日本語を勉強します。","vi":"Tôi học tiếng Nhật 3 lần một tuần","romaji":"shuu ni sankai nihongo wo benkyou shimasu."},{"ja":"ハンドルを回す","vi":"Xoay tay lái","romaji":"Handoru wo mawasu"},{"ja":"週に三回運動する","vi":"Tập 3 lần","romaji":"shuu ni sankai undou suru"},{"ja":"1か月に2回映画を見ます。","vi":"Một tháng tôi xem phim 2 lần.","romaji":"1kagetsu ni 2kai eiga o mimasu."}]},{"key":"k:漢","kind":"kanji","level":"N5","character":"漢","meaning":"Hán, Trung Quốc","hanviet":"Hán","onReadings":["カン"],"kunReadings":["—"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"漢字","reading":"かんじ","meaning":"Chữ Hán","vocabKey":"v:漢字"},{"compound":"漢文","reading":"かんぶん","meaning":"Văn Hán"}],"lessonIds":[9],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 氵 (nước) + 廿 (hai mươi) + 口 (miệng) + 夫 (phu/chồng). Hán-Việt: HÁN. Mẹo nhớ: Sông Hán (氵 nước) — nơi người Trung Hoa (漢人) định cư, chữ Hán (漢字) cũng từ đó mà ra 🏯. 13 nét. Âm カン (kan) gần 'hán'. Liên kết: 漢字 (kanji/chữ Hán), 漢文 (Hán văn). ⚠️ Chữ phức tạp 13 nét, nhớ qua từ ghép 漢字 là cách tốt nhất.","example":"毎日**漢**字を練習しています。 / mainichi kanji wo renshuu shite imasu. (Tôi luyện tập Kanji mỗi ngày)","examples":[{"ja":"毎日漢字を練習しています。","vi":"Tôi luyện tập Kanji mỗi ngày","romaji":"mainichi kanji wo renshuu shite imasu."},{"ja":"ミラーさんは 漢字を 読む ことが できます。","vi":"Anh Miller có thể đọc chữ Hán.","romaji":"miraa san wa kanji o yomu koto ga dekimasu."},{"ja":"この漢字の読み方を教えていただけませんか。","vi":"Bạn có thể dạy tôi cách đọc chữ kanji này được không?","romaji":"kono kanji no yomikata o oshiete ita dake masen ka."},{"ja":"漢字は難しいですが、好きです。","vi":"Chữ Hán khó nhưng tôi thích.","romaji":"kanji wa muzukashii desu ga, suki desu."}]},{"key":"k:急","kind":"kanji","level":"N5","character":"急","meaning":"Vội, cấp bách","hanviet":"Cấp","onReadings":["キュウ"],"kunReadings":["いそ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"急ぐ","reading":"いそぐ","meaning":"Vội","vocabKey":"v:急ぐ"},{"compound":"急に","reading":"きゅうに","meaning":"Đột nhiên","vocabKey":"v:急に"},{"compound":"急行","reading":"きゅうこう","meaning":"Tàu nhanh","vocabKey":"v:急行"}],"lessonIds":[5,6,14,43,45,47],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: phần trên (tay nắm vội vã) + 心 (tâm/tim). Hán-Việt: CẤP. Mẹo nhớ: Tim (心) đập rộn ràng, tay vội vã nắm — 'cấp' bách, gấp gáp 💓! 9 nét. Âm いそぐ (isogu) = vội, キュウ (kyuu) gần 'cấp'. Liên kết: 急ぐ (vội), 急に (đột nhiên), 急行 (tàu tốc hành). ⚠️ Phần dưới là 心 (tâm) — cấp bách bắt nguồn từ trái tim lo lắng.","example":"**急**いで駅に行きました。 / isoide eki ni ikimashita. (Tôi vội vàng đi đến ga)","examples":[{"ja":"急いで駅に行きました。","vi":"Tôi vội vàng đi đến ga","romaji":"isoide eki ni ikimashita."},{"ja":"急いで行く","vi":"Đi vội","romaji":"Isoi de iku"},{"ja":"急な坂道を自転車で登るのは大変","vi":"Leo dốc đứng bằng xe đạp rất vất vả","romaji":"kyuu na sakamichi o jitensha de noboru no wa taihen"},{"ja":"急行に乗る","vi":"Lên tàu nhanh","romaji":"kyuukou ni noru"}]},{"key":"k:牛","kind":"kanji","level":"N5","character":"牛","meaning":"Con bò","hanviet":"Ngưu","onReadings":["ギュウ"],"kunReadings":["うし"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"牛肉","reading":"ぎゅうにく","meaning":"Thịt bò","vocabKey":"v:牛肉"},{"compound":"牛乳","reading":"ぎゅうにゅう","meaning":"Sữa bò","vocabKey":"v:牛乳"}],"lessonIds":[6,12,13,32],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 牛 là tượng hình — hình đầu bò với 2 sừng (nét ngang trên), mặt (nét dọc), thân (nét ngang dưới). Hán-Việt: NGƯU. Mẹo nhớ: Nhìn 牛 thấy đầu bò có sừng nhọn — 'ngưu' là bò 🐄! Chỉ 4 nét. Âm うし (ushi) = bò, ギュウ (gyuu) gần 'ngưu'. Liên kết: 牛肉 (thịt bò), 牛乳 (sữa bò). ⚠️ Đừng nhầm 牛 (bò — sừng nhô lên) với 午 (ngọ — nét ngang không nhô).","example":"焼き肉では、**牛**肉より鶏肉のほうが好きです。 / yakiniku de wa, gyuuniku yori toriniku no hou ga suki desu. (Khi ăn đồ nướng, tôi thích thịt gà hơn thịt bò.)","examples":[{"ja":"焼き肉では、牛肉より鶏肉のほうが好きです。","vi":"Khi ăn đồ nướng, tôi thích thịt gà hơn thịt bò.","romaji":"yakiniku de wa, gyuuniku yori keiniku no hou ga suki desu."},{"ja":"牛が草を食べる","vi":"Bò ăn cỏ","romaji":"Ushi ga kusa wo taberu"},{"ja":"牛肉が高い","vi":"Thịt bò đắt","romaji":"gyuuniku ga takai"},{"ja":"牛乳を飲む","vi":"Uống sữa","romaji":"gyuunyuu o nomu"}]},{"key":"k:去","kind":"kanji","level":"N5","character":"去","meaning":"Qua, đi, quá khứ","hanviet":"Khứ","onReadings":["キョ","コ"],"kunReadings":["さ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"去年","reading":"きょねん","meaning":"Năm ngoái","vocabKey":"v:去年"},{"compound":"過去","reading":"かこ","meaning":"Quá khứ","vocabKey":"v:過去"}],"lessonIds":[5],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 土 (đất) + 厶 (riêng tư/đi). Hán-Việt: KHỨ. Mẹo nhớ: Rời khỏi mảnh 土 đất, đi (厶) xa — 'khứ' đã qua, đã đi rồi 👋. Chỉ 5 nét. Âm さる (saru) = rời đi, キョ (kyo) gần 'khứ'. Liên kết: 去年 (năm ngoái), 過去 (quá khứ). ⚠️ Đừng nhầm 去 (khứ/đi — 5 nét) với 法 (pháp) hay 台 (đài).","example":"**去**年日本に行きました。 / kyonen nihon ni ikimashita. (Năm ngoái tôi đã đi Nhật)","examples":[{"ja":"去年日本に行きました。","vi":"Năm ngoái tôi đã đi Nhật","romaji":"kyonen nippon ni ikimashita."},{"ja":"去年結婚した","vi":"Năm ngoái kết hôn","romaji":"Kyonen kekkon shita"},{"ja":"過去を振り返る","vi":"Nhìn lại quá khứ","romaji":"Kako wo furikaeru"},{"ja":"あの映画は去年作られました。","vi":"Bộ phim đó được làm năm ngoái.","romaji":"ano eiga wa kyonen tsukura remashita."}]},{"key":"k:元","kind":"kanji","level":"N5","character":"元","meaning":"Gốc, nguyên, khỏe","hanviet":"Nguyên","onReadings":["ゲン","ガン"],"kunReadings":["もと"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"元気","reading":"げんき","meaning":"Khỏe mạnh","vocabKey":"v:元気"},{"compound":"元","reading":"もと","meaning":"Gốc"}],"lessonIds":[8,25,30,32,50],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 二 (hai nét ngang) + 儿 (chân người). Hán-Việt: NGUYÊN. Mẹo nhớ: Người đứng (儿) vững trên nền (二) — khỏe mạnh, 'nguyên' vẹn từ gốc 💪. Chỉ 4 nét. Âm もと (moto) = gốc, ゲン (gen) gần 'nguyên'. Liên kết: 元気 (khỏe mạnh), 元 (gốc). ⚠️ Đừng nhầm 元 (nguyên — 4 nét) với 兄 (huynh — có 口), hay 先 (tiên — có thêm nét).","example":"最近忙しかったですが、今日はだいぶ**元**気になりました。 / saikin isogashikatta desu ga, kyou wa daibu genki ni narimashita. (Dạo gần đây khá bận, nhưng hôm nay tôi đã khỏe hơn nhiều.)","examples":[{"ja":"最近忙しかったですが、今日はだいぶ元気になりました。","vi":"Dạo gần đây khá bận, nhưng hôm nay tôi đã khỏe hơn nhiều.","romaji":"saikin isogashikatsuta desu ga, kyou wa daibu genki ni narimashita."},{"ja":"元気な子供","vi":"Đứa trẻ khỏe mạnh","romaji":"Genki na kodomo"},{"ja":"お元気ですか。お久しぶりです。","vi":"Bạn có khỏe không? Lâu rồi không gặp.","romaji":"Ogenki desu ka. Ohisashiburi desu."},{"ja":"地元の友達に会った","vi":"Gặp bạn ở quê nhà","romaji":"Jimoto no tomodachi ni atsuta"}]},{"key":"k:言","kind":"kanji","level":"N5","character":"言","meaning":"Nói, lời nói","hanviet":"Ngôn","onReadings":["ゲン","ゴン"],"kunReadings":["い","こと"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"言葉","reading":"ことば","meaning":"Từ ngữ"},{"compound":"言う","reading":"いう","meaning":"Nói","vocabKey":"v:言う"}],"lessonIds":[2,7,13,21,30,37,42],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 言 là bộ thủ — miệng (口) phát ra âm thanh, các nét ngang là sóng âm. Hán-Việt: NGÔN. Mẹo nhớ: Miệng (口) mở ra, âm thanh (nét ngang) lan tỏa — 'ngôn' là lời nói 🗣️. 7 nét. Âm いう (iu) = nói, ゲン (gen) gần 'ngôn'. Liên kết: 言葉 (từ ngữ), 言う (nói). ⚠️ 言 là bộ thủ rất phổ biến: 話 (thoại), 語 (ngữ), 読 (đọc), 記 (ký).","example":"日本語で何と**言**いますか。 / nihongo de nan to iimasu ka. (Nói bằng tiếng Nhật thế nào?)","examples":[{"ja":"日本語で何と言いますか。","vi":"Nói bằng tiếng Nhật thế nào?","romaji":"nihongo de nani to iimasu ka."},{"ja":"名前を言う","vi":"Nói tên","romaji":"Namae wo iu"},{"ja":"最後に結論を言う","vi":"Nói kết luận ở cuối","romaji":"Saigo ni ketsuron wo iu"},{"ja":"すみませんが、もう一度言ってください。","vi":"Xin lỗi, nói lại một lần nữa.","romaji":"sumimasen ga, mouichido itsute kudasai."}]},{"key":"k:今","kind":"kanji","level":"N5","character":"今","meaning":"Bây giờ, hiện tại","hanviet":"Kim","onReadings":["コン","キン"],"kunReadings":["いま"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"今日","reading":"きょう","meaning":"Hôm nay","vocabKey":"v:今日"},{"compound":"今年","reading":"ことし","meaning":"Năm nay","vocabKey":"v:今年"},{"compound":"今度","reading":"こんど","meaning":"Lần này","vocabKey":"v:今度"}],"lessonIds":[4,5,9,26,29,32,43,46],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 亼 (nắp/mái) + phần dưới. Hán-Việt: KIM. Mẹo nhớ: Dưới mái che (亼), khoảnh khắc hiện tại — 'kim' là bây giờ, ngay lúc này ⏰. Chỉ 4 nét. Âm いま (ima) = bây giờ, コン (kon) gần 'kim'. Liên kết: 今日 (hôm nay), 今年 (năm nay), 今度 (lần này). ⚠️ Đừng nhầm 今 (kim/bây giờ) với 令 (lệnh) — 今 có nét phẩy, 令 có 丨 và 丶.","example":"**今**何時ですか。 / ima nanji desu ka. (Bây giờ mấy giờ?)","examples":[{"ja":"今何時ですか。","vi":"Bây giờ mấy giờ?","romaji":"ima nanji desu ka."},{"ja":"今朝は寒い","vi":"Sáng nay lạnh","romaji":"Kesa wa samui"},{"ja":"今晩何をする","vi":"Tối nay làm gì","romaji":"Konban nani wo suru"},{"ja":"今日は暑い","vi":"Hôm nay nóng","romaji":"kyou wa atsui"}]},{"key":"k:紙","kind":"kanji","level":"N5","character":"紙","meaning":"Giấy","hanviet":"Chỉ","onReadings":["シ"],"kunReadings":["かみ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"紙","reading":"かみ","meaning":"Giấy","vocabKey":"v:紙"},{"compound":"手紙","reading":"てがみ","meaning":"Thư","vocabKey":"v:手紙"}],"lessonIds":[6,7],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 糹 (sợi tơ) + 氏 (thị/họ — gợi âm). Hán-Việt: CHỈ. Mẹo nhớ: Sợi tơ (糹) được ép thành tấm — đó là 'chỉ', tờ giấy 📄. 10 nét. Âm かみ (kami) = giấy, シ (shi) gần 'chỉ'. Liên kết: 紙 (giấy), 手紙 (thư = tay + giấy). ⚠️ 手紙 nghĩa 'thư' trong tiếng Nhật, không phải 'giấy vệ sinh'. Đừng nhầm 紙 với 氏 (thị).","example":"**紙**に名前を書いてください。 / kami ni namae wo kaite kudasai. (Hãy viết tên lên giấy)","examples":[{"ja":"紙に名前を書いてください。","vi":"Hãy viết tên lên giấy","romaji":"kami ni namae wo kaite kudasai."},{"ja":"紙に書く","vi":"Viết lên giấy","romaji":"Kami ni kaku"},{"ja":"手紙を書く","vi":"Viết thư","romaji":"Tegami wo kaku"},{"ja":"紙の裏も使う","vi":"Dùng cả mặt sau giấy","romaji":"Kami no ura mo tsukau"}]},{"key":"k:茶","kind":"kanji","level":"N5","character":"茶","meaning":"Trà","hanviet":"Trà","onReadings":["チャ","サ"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"お茶","reading":"おちゃ","meaning":"Trà","vocabKey":"v:お茶"},{"compound":"茶色","reading":"ちゃいろ","meaning":"Màu nâu","vocabKey":"v:茶色"},{"compound":"喫茶店","reading":"きっさてん","meaning":"Quán cà phê","vocabKey":"v:喫茶店"}],"lessonIds":[6,10,19,34],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 艹 (cỏ/thực vật) + 人 (người) + 木 (cây). Hán-Việt: TRÀ. Mẹo nhớ: Cây cỏ (艹) mà người (人) hái lá từ cây (木) để pha — đó là 'trà' 🍵! 9 nét. Âm チャ (cha) gần 'trà'. Liên kết: お茶 (trà), 茶色 (màu nâu = màu trà), 喫茶店 (quán trà). ⚠️ 茶色 (chairo) = màu nâu, không phải 'màu trà' theo nghĩa đen.","example":"お**茶**を飲みませんか。 / ocha wo nomimasen ka. (Uống trà không?)","examples":[{"ja":"お茶を飲みませんか。","vi":"Uống trà không?","romaji":"ocha wo nomimasen ka."},{"ja":"茶色い靴を買った","vi":"Mua giày nâu","romaji":"chairoi kutsu o katsuta"},{"ja":"茶碗にご飯を入れる","vi":"Xới cơm vào bát","romaji":"Chawan ni gohan wo ireru"},{"ja":"お茶を飲む","vi":"Uống trà","romaji":"O cha wo nomu"}]},{"key":"k:注","kind":"kanji","level":"N5","character":"注","meaning":"Chú ý, rót, đặt hàng","hanviet":"Chú","onReadings":["チュウ"],"kunReadings":["そそ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"注意","reading":"ちゅうい","meaning":"Chú ý","vocabKey":"v:注意"},{"compound":"注文","reading":"ちゅうもん","meaning":"Đặt hàng","vocabKey":"v:注文"}],"lessonIds":[13,33,37],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 氵 (nước) + 主 (chủ). Hán-Việt: CHÚ. Mẹo nhớ: Nước (氵) rót vào chỗ 主 chính — 'chú' ý, tập trung, rót nước 🫗. 8 nét. Âm そそぐ (sosogu) = rót, チュウ (chuu) gần 'chú'. Liên kết: 注意 (chú ý), 注文 (đặt hàng/chú văn). ⚠️ 注文 (chuumon) = đặt hàng, 注意 (chuui) = chú ý — cùng bộ 注 nhưng nghĩa khác.","example":"飲み物を**注**文しましょう。 / nomimono wo chuumon shimashou. (Hãy gọi đồ uống)","examples":[{"ja":"飲み物を注文しましょう。","vi":"Hãy gọi đồ uống","romaji":"nomimono wo chuumon shimashou."},{"ja":"健康に注意する","vi":"Chú ý sức khỏe","romaji":"kenkou ni chuui suru"},{"ja":"レストランで料理を注文した","vi":"Gọi món ở nhà hàng","romaji":"resutoran de ryouri o chuumon shita"},{"ja":"注射をする","vi":"Tiêm","romaji":"chuusha o suru"}]},{"key":"k:番","kind":"kanji","level":"N5","character":"番","meaning":"Số, phiên, lượt","hanviet":"Phiên","onReadings":["バン"],"kunReadings":["—"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"番号","reading":"ばんごう","meaning":"Số","vocabKey":"v:番号"},{"compound":"一番","reading":"いちばん","meaning":"Nhất/ số 1"},{"compound":"番組","reading":"ばんぐみ","meaning":"Chương trình","vocabKey":"v:番組"}],"lessonIds":[5,28,29,30,45,46],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 釆 (phân biệt/chọn lọc) + 田 (ruộng). Hán-Việt: PHIÊN. Mẹo nhớ: Chia ruộng (田) theo thứ tự lượt phiên — 'phiên' là số thứ tự, lượt 🔢. 12 nét. Âm バン (ban) gần 'phiên'. Liên kết: 番号 (số), 一番 (nhất/số 1), 番組 (chương trình). ⚠️ 一番 (ichiban) = 'nhất', 'giỏi nhất' — rất phổ biến trong giao tiếp.","example":"電話**番**号を教えてください。 / denwa bangou wo oshiete kudasai. (Hãy cho tôi biết số điện thoại)","examples":[{"ja":"電話番号を教えてください。","vi":"Hãy cho tôi biết số điện thoại","romaji":"denwa bangou wo oshiete kudasai."},{"ja":"交番で道を聞く","vi":"Hỏi đường ở đồn cảnh sát","romaji":"kouban de michi o kiku"},{"ja":"テレビ番組","vi":"Chương trình TV","romaji":"Terebi bangumi"},{"ja":"電話番号を教えてください","vi":"Cho tôi số điện thoại","romaji":"denwa bangou o oshiete kudasai"}]},{"key":"k:飯","kind":"kanji","level":"N4","character":"飯","meaning":"Cơm, bữa ăn","hanviet":"Phạn","onReadings":["ハン"],"kunReadings":["めし"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"ご飯","reading":"ごはん","meaning":"Cơm","vocabKey":"v:ご飯"},{"compound":"朝ご飯","reading":"あさごはん","meaning":"Bữa sáng"},{"compound":"夕飯","reading":"ゆうはん","meaning":"Bữa tối"}],"lessonIds":[35],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 飠 (thức ăn) + 反 (phản — gợi âm). Hán-Việt: PHẠN. Mẹo nhớ: Thức ăn (飠) chính yếu, 反 gợi âm 'phạn' — cơm, bữa ăn hàng ngày 🍚. 12 nét. Âm めし (meshi) = cơm, ハン (han) gần 'phạn'. Liên kết: ご飯 (cơm), 朝ご飯 (bữa sáng), 夕飯 (bữa tối). ⚠️ ご飯 (gohan) vừa nghĩa 'cơm' vừa nghĩa 'bữa ăn' tùy ngữ cảnh.","example":"ご**飯**を食べましたか。 / gohan wo tabemashita ka. (Bạn ăn cơm chưa?)","examples":[{"ja":"ご飯を食べましたか。","vi":"Bạn ăn cơm chưa?","romaji":"gohan wo tabemashita ka."},{"ja":"ご飯を食べる","vi":"Ăn cơm","romaji":"Gohan wo taberu"},{"ja":"昼ご飯を食べる","vi":"Ăn trưa","romaji":"Hiru gohan wo tabe ru"},{"ja":"炊飯器","vi":"nồi cơm điện","romaji":"suihanki"}]},{"key":"k:服","kind":"kanji","level":"N5","character":"服","meaning":"Quần áo","hanviet":"Phục","onReadings":["フク"],"kunReadings":["—"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"服","reading":"ふく","meaning":"Quần áo","vocabKey":"v:服"},{"compound":"洋服","reading":"ようふく","meaning":"Quần áo phương Tây"},{"compound":"制服","reading":"せいふく","meaning":"Đồng phục"}],"lessonIds":[15],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 月 (thịt/thân thể, biến thể) + phần phải (又 tay nắm vải). Hán-Việt: PHỤC. Mẹo nhớ: Tay (又) khoác vải lên thân (月) — mặc 'phục', quần áo 👔. 8 nét. Âm フク (fuku) gần 'phục'. Liên kết: 服 (quần áo), 洋服 (trang phục phương Tây), 制服 (đồng phục). ⚠️ 月 trong 服 là biến thể của 肉 (thịt/thân), không phải 'mặt trăng'.","example":"新しい**服**を買いたいです。 / atarashii fuku wo kaitai desu. (Tôi muốn mua quần áo mới)","examples":[{"ja":"新しい服を買いたいです。","vi":"Tôi muốn mua quần áo mới","romaji":"atarashii fuku wo kaitai desu."},{"ja":"新しい服を買う","vi":"Mua quần áo mới","romaji":"Atarashii fuku wo kau"},{"ja":"風邪を引かないように、暖かい服を着てください。","vi":"Để không bị cảm, hãy mặc áo ấm.","romaji":"kaze o hikanai you ni, atatakai fuku o kite kudasai."},{"ja":"私は子どもに服を汚されました。","vi":"Tôi bị con làm bẩn quần áo.","romaji":"watashi wa kodomo ni fuku o yogosa remashita."}]},{"key":"k:勉","kind":"kanji","level":"N5","character":"勉","meaning":"Cố gắng, siêng năng","hanviet":"Miễn","onReadings":["ベン"],"kunReadings":["—"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"勉強","reading":"べんきょう","meaning":"Học tập","vocabKey":"v:勉強"}],"lessonIds":[4],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 免 (miễn/thoát) + 力 (lực/sức). Hán-Việt: MIỄN. Mẹo nhớ: Dùng sức (力) cố gắng vượt qua (免) khó khăn — đó là 'miễn' cưỡng cố gắng, siêng năng 📚💪. 10 nét. Âm ベン (ben) gần 'miễn'. Liên kết: 勉強 (học tập = cố gắng + mạnh). ⚠️ 勉強 (benkyou) rất phổ biến — nhớ cặp: 勉 (cố gắng) + 強 (mạnh) = học tập.","example":"毎日三時間**勉**強しています。 / mainichi sanjikan benkyou shite imasu. (Tôi học 3 tiếng mỗi ngày)","examples":[{"ja":"毎日三時間勉強しています。","vi":"Tôi học 3 tiếng mỗi ngày","romaji":"mainichi sanjikan benkyou shite imasu."},{"ja":"勉強が大変だ","vi":"Học vất vả","romaji":"benkyou ga taihen da"},{"ja":"外国語を勉強する","vi":"Học ngoại ngữ","romaji":"gaikokugo o benkyou suru"},{"ja":"勉強方法を変える","vi":"Thay đổi phương pháp học","romaji":"benkyou houhou o kaeru"}]},{"key":"k:旅","kind":"kanji","level":"N5","character":"旅","meaning":"Du lịch, lữ hành","hanviet":"Lữ","onReadings":["リョ"],"kunReadings":["たび"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"旅行","reading":"りょこう","meaning":"Du lịch","vocabKey":"v:旅行"},{"compound":"旅館","reading":"りょかん","meaning":"Nhà trọ Nhật","vocabKey":"v:旅館"}],"lessonIds":[9,35,49],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 方 (phương hướng) + phần trái (cờ/biểu tượng hành trình). Hán-Việt: LỮ. Mẹo nhớ: Cầm cờ lên 方 đường — đi 'lữ' hành, du lịch khám phá 🧳! 10 nét. Âm たび (tabi) = chuyến đi, リョ (ryo) gần 'lữ'. Liên kết: 旅行 (du lịch), 旅館 (nhà trọ kiểu Nhật). ⚠️ Đừng nhầm 旅 (lữ) với 族 (tộc) — 旅 có 方, 族 có 矢.","example":"来月**旅**行に行く予定です。 / raigetsu ryokou ni iku yotei desu. (Tháng sau tôi dự định đi du lịch)","examples":[{"ja":"来月旅行に行く予定です。","vi":"Tháng sau tôi dự định đi du lịch","romaji":"raigetsu ryokou ni iku yotei desu."},{"ja":"ヨーロッパを旅行する","vi":"Du lịch châu Âu","romaji":"yooroppa o ryokou suru"},{"ja":"旅行に行く","vi":"Đi du lịch","romaji":"ryokou ni iku"},{"ja":"旅行の準備をする","vi":"Chuẩn bị cho chuyến du lịch","romaji":"ryokou no junbi o suru"}]},{"key":"k:料","kind":"kanji","level":"N5","character":"料","meaning":"Phí, nguyên liệu","hanviet":"Liệu","onReadings":["リョウ"],"kunReadings":["—"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"料理","reading":"りょうり","meaning":"Nấu ăn","vocabKey":"v:料理"},{"compound":"料金","reading":"りょうきん","meaning":"Phí","vocabKey":"v:料金"},{"compound":"材料","reading":"ざいりょう","meaning":"Nguyên liệu","vocabKey":"v:材料"}],"lessonIds":[9,15,28,33,34,37,42],"topicTags":[],"sectionId":15,"sectionName":"ĐỜI SỐNG HÀNG NGÀY","mnemonic":"Bộ/thành phần: 米 (gạo) + 斗 (đấu/đong lường). Hán-Việt: LIỆU. Mẹo nhớ: Dùng 斗 đấu đong 米 gạo — đo lường nguyên 'liệu' 🌾⚖️. 10 nét. Âm リョウ (ryou) gần 'liệu'. Liên kết: 料理 (nấu ăn), 料金 (phí), 材料 (nguyên liệu). ⚠️ 料理 (ryouri) = nấu ăn/món ăn — một trong những từ N4 phổ biến nhất.","example":"**料**理を作るのが好きです。 / ryouri wo tsukuru no ga suki desu. (Tôi thích nấu ăn)","examples":[{"ja":"料理を作るのが好きです。","vi":"Tôi thích nấu ăn","romaji":"ryouri wo tsukuru no ga suki desu."},{"ja":"毎日料理する","vi":"Nấu ăn mỗi ngày","romaji":"mainichi ryouri suru"},{"ja":"料理を作る","vi":"Nấu ăn","romaji":"ryouri o tsukuru"},{"ja":"材料を買う","vi":"Mua nguyên liệu","romaji":"zairyou o kau"}]},{"key":"k:性","kind":"kanji","level":"N4","character":"性","meaning":"Tính, giới tính, bản chất","hanviet":"Tính","onReadings":["セイ","ショウ"],"kunReadings":["—"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"男性","reading":"だんせい","meaning":"Nam giới","vocabKey":"v:男性"},{"compound":"女性","reading":"じょせい","meaning":"Nữ giới","vocabKey":"v:女性"},{"compound":"性格","reading":"せいかく","meaning":"Tính cách","vocabKey":"v:性格"}],"lessonIds":[47],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 忄(tâm) + 生 (sinh). Hán-Việt: TÍNH. Mẹo nhớ: Tâm (忄) của con người khi sinh (生) ra — bản 'tính', tính cách 💫. 8 nét. Âm セイ (sei) trong 性格 (seikaku - tính cách), ショウ (shou). Liên kết: 男性 (nam giới), 女性 (nữ giới), 性格 (tính cách). ⚠️ 忄 là biến thể của 心 khi đứng bên trái — nhiều kanji cảm xúc dùng 忄.","example":"彼の**性**格は明るいです。 / kare no seikaku wa akarui desu. (Tính cách anh ấy vui vẻ)","examples":[{"ja":"彼の性格は明るいです。","vi":"Tính cách anh ấy vui vẻ","romaji":"kare no seikaku wa akarui desu."},{"ja":"男性の服","vi":"Quần áo nam","romaji":"Dansei no fuku"},{"ja":"女性の声","vi":"Giọng nữ","romaji":"Josei no koe"},{"ja":"性別を書く","vi":"Ghi giới tính","romaji":"Seibetsu wo kaku"}]},{"key":"k:成","kind":"kanji","level":"N4","character":"成","meaning":"Thành, hoàn thành","hanviet":"Thành","onReadings":["セイ"],"kunReadings":["な"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"成功","reading":"せいこう","meaning":"Thành công"},{"compound":"賛成","reading":"さんせい","meaning":"Tán thành","vocabKey":"v:賛成"}],"lessonIds":[32,47],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 戊 (mậu/vũ khí) biến thể. Hán-Việt: THÀNH. Mẹo nhớ: Cầm vũ khí (戈 biến thể) hoàn 'thành' sứ mệnh — thành công, hoàn thành ✅. 6 nét. Âm セイ (sei) trong 成功 (seikou - thành công), なる (naru) = trở thành. Liên kết: 成功 (thành công), 贊成 (tán thành). ⚠️ Đừng nhầm với 戒 (giới/cảnh giác) — 成 không có nét ngang ở giữa.","example":"試験に**成**功しました。 / shiken ni seikou shimashita. (Đã thành công trong kỳ thi.)","examples":[{"ja":"試験に成功しました。","vi":"Đã thành công trong kỳ thi.","romaji":"shiken ni seikou shimashita."},{"ja":"意見に賛成する","vi":"Tán thành ý kiến","romaji":"Iken ni sansei suru"},{"ja":"事業に成功する","vi":"Thành công trong kinh doanh","romaji":"jigyou ni seikou suru"},{"ja":"成績が上がった","vi":"Điểm tăng lên","romaji":"seiseki ga agatsuta"}]},{"key":"k:説","kind":"kanji","level":"N5","character":"説","meaning":"Giải thích, thuyết","hanviet":"Thuyết","onReadings":["セツ"],"kunReadings":["と"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"説明","reading":"せつめい","meaning":"Giải thích","vocabKey":"v:説明"},{"compound":"小説","reading":"しょうせつ","meaning":"Tiểu thuyết","vocabKey":"v:小説"}],"lessonIds":[24,28,34,50],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 言 (lời) + 兑 (đoài/vui). Hán-Việt: THUYẾT. Mẹo nhớ: Dùng lời (言) vui vẻ (兑) để giải thích — 'thuyết' trình, giải thuyết 🗣️. 14 nét. Âm セツ (setsu) trong 説明 (setsumei - giải thích), とく (toku). Liên kết: 説明 (giải thích), 小説 (tiểu thuyết). ⚠️ Cặp đôi 説明: 説 (thuyết) + 明 (minh) — giải thích rõ ràng.","example":"もう一度**説**明してください。 / mou ichido setsumei shite kudasai. (Hãy giải thích lại một lần nữa)","examples":[{"ja":"もう一度説明してください。","vi":"Hãy giải thích lại một lần nữa","romaji":"mou ichido setsumei shite kudasai."},{"ja":"理由を説明する","vi":"Giải thích lý do","romaji":"riyuu o setsumei suru"},{"ja":"説明書を見ながら組み立てる","vi":"Lắp ráp theo sách hướng dẫn","romaji":"setsumeisho o mi nagara kumitateru"},{"ja":"取扱説明書をよく読んでください","vi":"Hãy đọc kỹ hướng dẫn sử dụng","romaji":"Toriatsukaisetsumeisho wo yoku yonde kudasai"}]},{"key":"k:工","kind":"kanji","level":"N4","character":"工","meaning":"Thợ, công, chế tạo","hanviet":"Công","onReadings":["コウ","ク"],"kunReadings":["—"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"工場","reading":"こうじょう","meaning":"Nhà máy","vocabKey":"v:工場"},{"compound":"工事","reading":"こうじ","meaning":"Công trình","vocabKey":"v:工事"}],"lessonIds":[38],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 工 là chữ tượng hình — hình cái thước thợ (ngang-dọc-ngang). Hán-Việt: CÔNG. Mẹo nhớ: Thanh ngang trên dưới nối bằng cột dọc — dụng cụ của thợ 'công' ⚒️. 3 nét. Âm コウ (kou) trong 工場 (koujou - nhà máy). Liên kết: 工場 (nhà máy), 工事 (công trình). ⚠️ Đừng nhầm với 土 (thổ/đất) — 工 nét ngang trên dài, 土 nét ngang dưới dài.","example":"**工**場で働いています。 / koujou de hataraite imasu. (Tôi đang làm việc ở nhà máy)","examples":[{"ja":"工場で働いています。","vi":"Tôi đang làm việc ở nhà máy","romaji":"koujou de hataraite imasu."},{"ja":"父は自動車工場で働いています","vi":"Bố làm ở nhà máy xe hơi","romaji":"chichi wa jidousha koujou de hataraite imasu"},{"ja":"道路の工事をしている","vi":"Đang thi công đường","romaji":"douro no kouji o shite iru"},{"ja":"工事は来月再開される","vi":"Công trình sẽ được tiếp tục tháng sau","romaji":"kouji wa raigetsu saikai sa reru"}]},{"key":"k:交","kind":"kanji","level":"N5","character":"交","meaning":"Giao, trao đổi","hanviet":"Giao","onReadings":["コウ"],"kunReadings":["まじ","か"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"交通","reading":"こうつう","meaning":"Giao thông","vocabKey":"v:交通"},{"compound":"交換","reading":"こうかん","meaning":"Trao đổi"}],"lessonIds":[21,23,29,30,35],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 亠 (đầu) + 乂 (giao nhau). Hán-Việt: GIAO. Mẹo nhớ: Hai nét giao (乂) nhau phía dưới — 'giao' thông, trao đổi, giao lưu 🤝. 6 nét. Âm コウ (kou) trong 交通 (koutsuu - giao thông). Liên kết: 交通 (giao thông), 交換 (trao đổi). ⚠️ Đừng nhầm với 文 (văn 4 nét) — 交 có thêm phần chân (6 nét).","example":"**交**通が便利な所に住みたいです。 / koutsuu ga benri na tokoro ni sumitai desu. (Tôi muốn sống ở nơi giao thông thuận tiện)","examples":[{"ja":"交通が便利な所に住みたいです。","vi":"Tôi muốn sống ở nơi giao thông thuận tiện","romaji":"koutsuu ga benri na tokoro ni sumitai desu."},{"ja":"電話番号を交換する","vi":"Trao đổi số điện thoại","romaji":"denwa bangou o koukan suru"},{"ja":"交差点を右に曲がる","vi":"Rẽ phải ở ngã tư","romaji":"kousaten o migi ni magaru"},{"ja":"交番で道を聞く","vi":"Hỏi đường ở đồn cảnh sát","romaji":"kouban de michi o kiku"}]},{"key":"k:計","kind":"kanji","level":"N5","character":"計","meaning":"Kế hoạch, đếm, đo","hanviet":"Kế","onReadings":["ケイ"],"kunReadings":["はか"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"計画","reading":"けいかく","meaning":"Kế hoạch","vocabKey":"v:計画"},{"compound":"時計","reading":"とけい","meaning":"Đồng hồ","vocabKey":"v:時計"},{"compound":"合計","reading":"ごうけい","meaning":"Tổng cộng"}],"lessonIds":[2,42,45],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 言 (lời) + 十 (mười). Hán-Việt: KẾ. Mẹo nhớ: Đếm (十) bằng lời nói (言) — 'kế' hoạch, tính toán 🧮. 9 nét. Âm ケイ (kei) trong 計画 (keikaku - kế hoạch), はかる (hakaru) = đo/tính. Liên kết: 計画 (kế hoạch), 時計 (đồng hồ), 合計 (tổng cộng). ⚠️ 時計 đọc とけい (tokei) — chữ 計 đọc けい ở đây.","example":"旅行の**計**画を立てました。 / ryokou no keikaku wo tatemashita. (Tôi đã lập kế hoạch du lịch)","examples":[{"ja":"旅行の計画を立てました。","vi":"Tôi đã lập kế hoạch du lịch","romaji":"ryokou no keikaku wo tatemashita."},{"ja":"旅行の日程を計画しています","vi":"Lên kế hoạch lịch trình","romaji":"ryokou no nittei o keikaku shite imasu"},{"ja":"温度計で熱を測る","vi":"Đo sốt bằng nhiệt kế","romaji":"Ondokei de netsu wo hakaru"},{"ja":"夏休みの計画を立てました","vi":"Lập kế hoạch nghỉ hè","romaji":"Natsuyasumi no keikaku wo tatemashita"}]},{"key":"k:研","kind":"kanji","level":"N5","character":"研","meaning":"Nghiên cứu, mài","hanviet":"Nghiên","onReadings":["ケン"],"kunReadings":["と"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"研究","reading":"けんきゅう","meaning":"Nghiên cứu","vocabKey":"v:研究"},{"compound":"研究室","reading":"けんきゅうしつ","meaning":"Phòng nghiên cứu"}],"lessonIds":[1,15],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 石 (đá) + 开 (khai/mở). Hán-Việt: NGHIÊN. Mẹo nhớ: Mài đá (石) cho mở (开) ra — 'nghiên' cứu, tìm hiểu sâu 🔬. 9 nét. Âm ケン (ken) trong 研究 (kenkyuu - nghiên cứu). Liên kết: 研究 (nghiên cứu), 研究室 (phòng nghiên cứu). ⚠️ 石 đứng bên trái — nhiều kanji về đá/khoáng đều có 石.","example":"大学で日本文化を**研**究しています。 / daigaku de nihon bunka wo kenkyuu shite imasu. (Tôi đang nghiên cứu văn hóa Nhật ở đại học)","examples":[{"ja":"大学で日本文化を研究しています。","vi":"Tôi đang nghiên cứu văn hóa Nhật ở đại học","romaji":"daigaku de nippon bunka o kenkyuu shite imasu."},{"ja":"歴史を研究する","vi":"Nghiên cứu lịch sử","romaji":"rekishi o kenkyuu suru"},{"ja":"研究を続ける","vi":"Tiếp tục nghiên cứu","romaji":"kenkyuu o tsuzukeru"},{"ja":"大学で研究者になった","vi":"Trở thành nhà nghiên cứu ở đại học","romaji":"daigaku de kenkyuusha ni natsuta"}]},{"key":"k:忘","kind":"kanji","level":"N5","character":"忘","meaning":"Quên","hanviet":"Vong","onReadings":["ボウ"],"kunReadings":["わす"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"忘れる","reading":"わすれる","meaning":"Quên","vocabKey":"v:忘れる"},{"compound":"忘れ物","reading":"わすれもの","meaning":"Đồ bỏ quên","vocabKey":"v:忘れ物"}],"lessonIds":[17,29,40],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 亡 (vong/mất) + 心 (tâm). Hán-Việt: VONG. Mẹo nhớ: Tâm (心) bị mất (亡) — 'vong' là quên, quên mất 🤦. 7 nét. Âm ボウ (bou), わすれる (wasureru) = quên. Liên kết: 忘れる (quên), 忘れ物 (đồ bỏ quên). ⚠️ 亡 (mất) + 心 (tim) = quên — tâm đã mất thì quên thôi.","example":"傘を**忘**れてしまいました。 / kasa wo wasurete shimaimashita. (Tôi đã lỡ quên ô mất rồi)","examples":[{"ja":"傘を忘れてしまいました。","vi":"Tôi đã lỡ quên ô mất rồi","romaji":"kasa wo wasurete shimaimashita."},{"ja":"約束を忘れる","vi":"Quên lời hẹn","romaji":"Yakusoku wo wasureru"},{"ja":"約束事を忘れない","vi":"Không quên những điều đã hứa","romaji":"Yakusokugoto wo wasure nai"},{"ja":"忘れ物をしたとき、誰に聞いたらいいですか。","vi":"Khi quên đồ, tôi nên hỏi ai?","romaji":"wasuremono o shita toki, dare ni kii tara ii desu ka."}]},{"key":"k:有","kind":"kanji","level":"N5","character":"有","meaning":"Có, tồn tại","hanviet":"Hữu","onReadings":["ユウ"],"kunReadings":["あ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"有名","reading":"ゆうめい","meaning":"Nổi tiếng"},{"compound":"有る","reading":"ある","meaning":"Có"}],"lessonIds":[8],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: ナ (tay biến thể) + 月 (thịt/tháng). Hán-Việt: HỮu. Mẹo nhớ: Tay (ナ) cầm miếng thịt (月) — 'hữu' là có, sở hữu 🤲. 6 nét. Âm ユウ (yuu) trong 有名 (yuumei - nổi tiếng), ある (aru) = có. Liên kết: 有名 (nổi tiếng), 有る (có). ⚠️ 有 đối lập với 無 (vô/không có) — hữu/vô là cặp đối nghĩa.","example":"この店は**有**名です。 / kono mise wa yuumei desu. (Cửa hàng này nổi tiếng)","examples":[{"ja":"この店は有名です。","vi":"Cửa hàng này nổi tiếng","romaji":"kono mise wa yuumei desu."},{"ja":"有名な人","vi":"Người nổi tiếng","romaji":"yuumei na hito"},{"ja":"この条件は有利です","vi":"Điều kiện này có lợi","romaji":"kono jouken wa yuuri desu"},{"ja":"お土産なら、このお菓子が有名です。","vi":"Quà lưu niệm thì loại bánh này nổi tiếng.","romaji":"o miyage nara, kono okashi ga yuumei desu."}]},{"key":"k:用","kind":"kanji","level":"N5","character":"用","meaning":"Dùng, việc","hanviet":"Dụng","onReadings":["ヨウ"],"kunReadings":["もち"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"用意","reading":"ようい","meaning":"Chuẩn bị","vocabKey":"v:用意"},{"compound":"用事","reading":"ようじ","meaning":"Việc cần làm","vocabKey":"v:用事"},{"compound":"利用","reading":"りよう","meaning":"Sử dụng"}],"lessonIds":[9,33,36,50],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 用 là chữ tượng hình — hình cái hàng rào (冂) có gỗ (丨) dùng làm khung. Hán-Việt: DỤNG. Mẹo nhớ: Khung gỗ dùng được nhiều việc — 'dụng' cụ, sử dụng 🔧. 5 nét. Âm ヨウ (you) trong 用意 (youi - chuẩn bị). Liên kết: 用意 (chuẩn bị), 用事 (việc cần làm), 利用 (sử dụng). ⚠️ Đừng nhầm với 月 (nguyệt) — 用 có nét dọc xuyên qua.","example":"明日**用**事があります。 / ashita youji ga arimasu. (Ngày mai tôi có việc)","examples":[{"ja":"明日用事があります。","vi":"Ngày mai tôi có việc","romaji":"ashita youji ga arimasu."},{"ja":"図書館を利用する","vi":"Sử dụng thư viện","romaji":"toshokan o riyou suru"},{"ja":"パーティーの料理を用意しました","vi":"Chuẩn bị đồ ăn tiệc","romaji":"paateii no ryouri o youi shimashita"},{"ja":"明日の授業の用意をした","vi":"Chuẩn bị cho tiết học ngày mai","romaji":"ashita no jugyou no youi o shita"}]},{"key":"k:両","kind":"kanji","level":"N5","character":"両","meaning":"Cả hai","hanviet":"Lưỡng","onReadings":["リョウ"],"kunReadings":["—"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"両方","reading":"りょうほう","meaning":"Cả hai phía"},{"compound":"両親","reading":"りょうしん","meaning":"Bố mẹ","vocabKey":"v:両親"}],"lessonIds":[11],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 一 (nhất) + 冂 (khung) + 山 (sơn biến thể). Hán-Việt: LƯỢNG. Mẹo nhớ: Hai ngọn núi (山) đăng đối trong khung (冂) — 'lượng' là cả hai, đôi bên ⚖️. 6 nét. Âm リョウ (ryou) trong 両方 (ryouhou - cả hai phía), 両親 (ryoushin - bố mẹ). Liên kết: 両方 (cả hai phía), 両親 (bố mẹ). ⚠️ 両親 = lượng thân = bố + mẹ — cách nói trang trọng.","example":"**両**方とも好きです。 / ryouhou tomo suki desu. (Tôi thích cả hai)","examples":[{"ja":"両方とも好きです。","vi":"Tôi thích cả hai","romaji":"ryouhou tomo suki desu."},{"ja":"両親に会う","vi":"Gặp bố mẹ","romaji":"ryoushin ni au"},{"ja":"両親","vi":"bố mẹ","romaji":"ryoushin"}]},{"key":"k:留","kind":"kanji","level":"N5","character":"留","meaning":"Lưu, giữ lại","hanviet":"Lưu","onReadings":["リュウ","ル"],"kunReadings":["と"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"留学","reading":"りゅうがく","meaning":"Du học","vocabKey":"v:留学"},{"compound":"留守","reading":"るす","meaning":"Vắng nhà","vocabKey":"v:留守"}],"lessonIds":[11,16,25,46],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 卯 (mão — biến thể) + 刀 (dao) + 田 (ruộng). Hán-Việt: LƯU. Mẹo nhớ: Dao (刀) cắm xuống ruộng (田) — đánh dấu 'lưu' lại, giữ chỗ 📌. 10 nét. Âm リュウ (ryuu) trong 留学 (ryuugaku - du học), ル (ru) trong 留守 (rusu - vắng nhà). Liên kết: 留学 (du học), 留守 (vắng nhà). ⚠️ 留学 = lưu học = du học — ở lại để học.","example":"日本に**留**学したいです。 / nihon ni ryuugaku shitai desu. (Tôi muốn du học Nhật)","examples":[{"ja":"日本に留学したいです。","vi":"Tôi muốn du học Nhật","romaji":"nippon ni ryuugaku shitai desu."},{"ja":"日本に留学する","vi":"Du học Nhật","romaji":"nippon ni ryuugaku suru"},{"ja":"次の停留所で降ります","vi":"Tôi sẽ xuống ở trạm tiếp theo","romaji":"tsugi no teiryuujo de orimasu"},{"ja":"昼間はいつも留守です","vi":"Ban ngày lúc nào cũng vắng nhà","romaji":"Hiruma wa itsumo rusu de su"}]},{"key":"k:練","kind":"kanji","level":"N5","character":"練","meaning":"Luyện, rèn","hanviet":"Luyện","onReadings":["レン"],"kunReadings":["ね"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"練習","reading":"れんしゅう","meaning":"Luyện tập","vocabKey":"v:練習"},{"compound":"訓練","reading":"くんれん","meaning":"Huấn luyện"}],"lessonIds":[19],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 糹(tơ) + 柬 (giản/chọn lọc). Hán-Việt: LUYỆN. Mẹo nhớ: Kéo tơ (糹) chọn lọc (柬) nhiều lần — 'luyện' tập, rèn luyện 💪. 14 nét. Âm レン (ren) trong 練習 (renshuu - luyện tập), ねる (neru). Liên kết: 練習 (luyện tập), 訓練 (huấn luyện). ⚠️ 糹 bên trái — nhiều kanji liên quan sợi/vải đều có 糹.","example":"毎日ピアノを**練**習しています。 / mainichi piano wo renshuu shite imasu. (Tôi luyện tập piano mỗi ngày)","examples":[{"ja":"毎日ピアノを練習しています。","vi":"Tôi luyện tập piano mỗi ngày","romaji":"mainichi piano wo renshuu shite imasu."},{"ja":"ピアノを練習する","vi":"Luyện tập piano","romaji":"piano o renshuu suru"},{"ja":"友達と会話練習をする","vi":"Luyện hội thoại với bạn","romaji":"tomodachi to kaiwa renshuu o suru"},{"ja":"練習問題をたくさん解く","vi":"Giải nhiều bài tập","romaji":"renshuu mondai o takusan toku"}]},{"key":"k:若","kind":"kanji","level":"N5","character":"若","meaning":"Trẻ","hanviet":"Nhược","onReadings":["ジャク"],"kunReadings":["わか"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"若い","reading":"わかい","meaning":"Trẻ","vocabKey":"v:若い"},{"compound":"若者","reading":"わかもの","meaning":"Người trẻ"}],"lessonIds":[16],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 艹 (cỏ) + 右 (phải — biến thể). Hán-Việt: NHƯỢC. Mẹo nhớ: Cỏ (艹) non mới mọc — 'nhược' là trẻ, non nớt 🌿. 8 nét. Âm ジャク (jaku), わかい (wakai) = trẻ. Liên kết: 若い (trẻ), 若者 (người trẻ). ⚠️ Đừng nhầm với 苦 (khổ/đắng) — 若 có 右, 苦 có 古.","example":"日本の**若**者は忙しいです。 / nihon no wakamono wa isogashii desu. (Giới trẻ Nhật Bản rất bận)","examples":[{"ja":"日本の若者は忙しいです。","vi":"Giới trẻ Nhật Bản rất bận","romaji":"nippon no wakamono wa isogashii desu."},{"ja":"若い人","vi":"Người trẻ","romaji":"wakai hito"},{"ja":"まだ若いのに、悩みが多そうですね。","vi":"Còn trẻ thế mà có vẻ nhiều nỗi lo nhỉ.","romaji":"mada wakai noni, nayami ga oosou desu ne."},{"ja":"若い","vi":"trẻ","romaji":"wakai"}]},{"key":"k:住","kind":"kanji","level":"N5","character":"住","meaning":"Ở, cư trú","hanviet":"Trú","onReadings":["ジュウ"],"kunReadings":["す"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"住む","reading":"すむ","meaning":"Sống","vocabKey":"v:住む"},{"compound":"住所","reading":"じゅうしょ","meaning":"Địa chỉ","vocabKey":"v:住所"}],"lessonIds":[14,15],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 亻(người) + 主 (chủ). Hán-Việt: TRÚ. Mẹo nhớ: Người (亻) làm chủ (主) nơi mình ở — 'trú' ngụ, cư trú 🏠. 7 nét. Âm ジュウ (juu), すむ (sumu) = sống/ở. Liên kết: 住む (sống), 住所 (địa chỉ). ⚠️ Đừng nhầm với 往 (vãng/đi) — 住 có 主 (chủ), 往 có 王.","example":"東京に**住**んでいます。 / toukyou ni sunde imasu. (Tôi đang sống ở Tokyo)","examples":[{"ja":"東京に住んでいます。","vi":"Tôi đang sống ở Tokyo","romaji":"toukyou ni sunde imasu."},{"ja":"東京に住む","vi":"Sống ở Tokyo","romaji":"toukyou ni sumu"},{"ja":"住所を書く","vi":"Viết địa chỉ","romaji":"juusho o kaku"},{"ja":"住民票を提出する","vi":"Nộp giấy cư trú","romaji":"juuminhyou o teishutsu suru"}]},{"key":"k:台","kind":"kanji","level":"N5","character":"台","meaning":"Đài, bệ, đếm máy/ xe","hanviet":"Đài","onReadings":["ダイ","タイ"],"kunReadings":["—"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"台風","reading":"たいふう","meaning":"Bão","vocabKey":"v:台風"},{"compound":"台所","reading":"だいどころ","meaning":"Nhà bếp","vocabKey":"v:台所"}],"lessonIds":[11,27,39],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 厶 (tư) + 口 (miệng). Hán-Việt: ĐÀI. Mẹo nhớ: Cái bệ (口 = khung vuông) nâng lên (厶) — 'đài' là bệ, hay đếm máy/xe 🖥️. 5 nét. Âm ダイ (dai) trong 台所 (daidokoro - nhà bếp), タイ (tai) trong 台風 (taifuu - bão). Liên kết: 台風 (bão), 台所 (nhà bếp). ⚠️ 台 vừa là bệ/đài vừa là bộ đếm xe (一台の車).","example":"**台**所で料理を作ります。 / daidokoro de ryouri wo tsukurimasu. (Tôi nấu ăn ở nhà bếp)","examples":[{"ja":"台所で料理を作ります。","vi":"Tôi nấu ăn ở nhà bếp","romaji":"daidokoro de ryouri wo tsukurimasu."},{"ja":"台風が来る","vi":"Bão đến","romaji":"taifuu ga kuru"},{"ja":"車が二台ある","vi":"Có 2 chiếc xe","romaji":"Kuruma ga nidai aru"},{"ja":"台所で料理する","vi":"Nấu ăn ở bếp","romaji":"daidokoro de ryouri suru"}]},{"key":"k:便","kind":"kanji","level":"N5","character":"便","meaning":"Tiện, thư","hanviet":"Tiện","onReadings":["ベン","ビン"],"kunReadings":["たよ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"便利","reading":"べんり","meaning":"Tiện lợi"},{"compound":"郵便","reading":"ゆうびん","meaning":"Bưu điện"}],"lessonIds":[4,8,11,21,40,46],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 亻(người) + 更 (canh/thay đổi). Hán-Việt: TIỆN. Mẹo nhớ: Người (亻) thay đổi (更) cách làm cho dễ hơn — 'tiện' lợi, thuận tiện 👌. 9 nét. Âm ベン (ben) trong 便利 (benri - tiện lợi), ビン (bin) trong 郵便 (yuubin - bưu điện). Liên kết: 便利 (tiện lợi), 郵便 (bưu điện). ⚠️ 不便 (bất tiện) — 不 + 便, cặp đối nghĩa.","example":"駅の近くは**便**利です。 / eki no chikaku wa benri desu. (Gần ga rất tiện lợi)","examples":[{"ja":"駅の近くは便利です。","vi":"Gần ga rất tiện lợi","romaji":"eki no chikaku wa benri desu."},{"ja":"不便な場所","vi":"Nơi bất tiện","romaji":"Fuben na basho"},{"ja":"便利な道具","vi":"Công cụ tiện lợi","romaji":"benri na dougu"},{"ja":"郵便局に行く","vi":"Đi bưu điện","romaji":"yuubinkyoku ni iku"}]},{"key":"k:費","kind":"kanji","level":"N4","character":"費","meaning":"Phí, chi phí","hanviet":"Phí","onReadings":["ヒ"],"kunReadings":["つい"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"費用","reading":"ひよう","meaning":"Chi phí","vocabKey":"v:費用"},{"compound":"交通費","reading":"こうつうひ","meaning":"Tiền đi lại"},{"compound":"生活費","reading":"せいかつひ","meaning":"Sinh hoạt phí","vocabKey":"v:生活費"}],"lessonIds":[],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 弗 (phất/không) + 貝 (tiền/vỏ sò). Hán-Việt: PHÍ. Mẹo nhớ: Tiền (貝) cứ bay mất (弗) — chi 'phí', tốn kém 💸. 12 nét. Âm ヒ (hi) trong 費用 (hiyou - chi phí). Liên kết: 費用 (chi phí), 交通費 (tiền đi lại), 生活費 (sinh hoạt phí). ⚠️ 弗 trên + 貝 dưới — tiền cứ thoát đi = phí.","example":"**生活費**が高いです。 / seikatsuhi ga takai desu. (Chi phí sinh hoạt cao)","examples":[{"ja":"生活費が高いです。","vi":"Chi phí sinh hoạt cao","romaji":"seikatsuhi ga takai desu."},{"ja":"旅行の費用はいくらかかりましたか","vi":"Chi phí du lịch tốn bao nhiêu?","romaji":"ryokou no hiyou wa ikura kakarimashita ka"},{"ja":"会費を毎月払う","vi":"Trả hội phí mỗi tháng","romaji":"Kaihi wo maitsuki harau"},{"ja":"値段には消費税が含まれています","vi":"Giá đã bao gồm thuế tiêu dùng","romaji":"nedan ni wa shouhi zei ga fukuma rete imasu"}]},{"key":"k:反","kind":"kanji","level":"N4","character":"反","meaning":"Phản, ngược","hanviet":"Phản","onReadings":["ハン"],"kunReadings":["そ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"反対","reading":"はんたい","meaning":"Phản đối","vocabKey":"v:反対"},{"compound":"反省","reading":"はんせい","meaning":"Phản tỉnh"}],"lessonIds":[33,47],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 厂 (triệt/vách) + 又 (tay/lại). Hán-Việt: PHẢN. Mẹo nhớ: Tay (又) đẩy ngược vách (厂) — 'phản' đối, ngược lại 🔄. 4 nét. Âm ハン (han) trong 反対 (hantai - phản đối), そる (soru) = cong ngược. Liên kết: 反対 (phản đối), 反省 (phản tỉnh). ⚠️ 反 là gốc của nhiều kanji: 飯 (cơm), 返 (trả lại), 板 (tấm ván).","example":"彼の意見に**反**対です。 / kare no iken ni hantai desu. (Tôi phản đối ý kiến anh ấy)","examples":[{"ja":"彼の意見に反対です。","vi":"Tôi phản đối ý kiến anh ấy","romaji":"kare no iken ni hantai desu."},{"ja":"計画に反対する","vi":"Phản đối kế hoạch","romaji":"Keikaku ni hantai suru"},{"ja":"その意見には反対です","vi":"Tôi phản đối ý kiến đó","romaji":"Sono iken ni wa hantai de su"},{"ja":"駐車違反","vi":"đỗ xe sai quy định","romaji":"chuushaihan"}]},{"key":"k:階","kind":"kanji","level":"N5","character":"階","meaning":"Tầng, bậc","hanviet":"Giai","onReadings":["カイ"],"kunReadings":["—"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"一階","reading":"いっかい","meaning":"Tầng 1"},{"compound":"階段","reading":"かいだん","meaning":"Cầu thang","vocabKey":"v:階段"}],"lessonIds":[3],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 阝(gò đất) + 皆 (giai/mọi người). Hán-Việt: GIAI. Mẹo nhớ: Gò đất (阝) mà mọi người (皆) bước lên — bậc thang, 'giai' tầng 🪜. 12 nét. Âm カイ (kai) trong 一階 (ikkai - tầng 1), 階段 (kaidan - cầu thang). Liên kết: 一階 (tầng 1), 階段 (cầu thang). ⚠️ 阝 bên trái = gò đất (khác với 阝 bên phải = thành phố).","example":"教室は二**階**にあります。 / kyoushitsu wa nikai ni arimasu. (Phòng học ở tầng 2)","examples":[{"ja":"教室は二階にあります。","vi":"Phòng học ở tầng 2","romaji":"kyoushitsu wa nikai ni arimasu."},{"ja":"三階に住んでいる","vi":"Sống ở tầng 3","romaji":"Sankai ni sun deiru"},{"ja":"階段を上る","vi":"Đi lên cầu thang","romaji":"Kaidan wo noboru"},{"ja":"安全のために、エレベーターじゃなくて階段にします。","vi":"Để an toàn, tôi chọn đi cầu thang chứ không đi thang máy.","romaji":"anzen no tame ni, erebeetaa ja nakute kaidan ni shimasu."}]},{"key":"k:界","kind":"kanji","level":"N5","character":"界","meaning":"Giới, thế giới","hanviet":"Giới","onReadings":["カイ"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"世界","reading":"せかい","meaning":"Thế giới","vocabKey":"v:世界"},{"compound":"業界","reading":"ぎょうかい","meaning":"Ngành"}],"lessonIds":[12,37],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 田 (ruộng) + 介 (giới thiệu/ở giữa). Hán-Việt: GIỚI. Mẹo nhớ: Ranh giới (介) của ruộng (田) — 'giới' hạn, thế giới 🌍. 9 nét. Âm カイ (kai) trong 世界 (sekai - thế giới). Liên kết: 世界 (thế giới), 業界 (ngành). ⚠️ 世界 = thế giới — cặp chữ rất phổ biến.","example":"**世界**中を旅行したいです。 / sekaijuu wo ryokou shitai desu. (Tôi muốn du lịch khắp thế giới)","examples":[{"ja":"世界中を旅行したいです。","vi":"Tôi muốn du lịch khắp thế giới","romaji":"sekaijuu wo ryokou shitai desu."},{"ja":"世界旅行","vi":"Du lịch thế giới","romaji":"sekai ryokou"},{"ja":"世界中のニュースを見る","vi":"Xem tin tức khắp thế giới","romaji":"sekaijuu no nyuusu o miru"},{"ja":"この歌は世界中で歌われています。","vi":"Bài hát này được hát trên khắp thế giới.","romaji":"kono uta wa sekaijuu de utawa rete imasu."}]},{"key":"k:薬","kind":"kanji","level":"N5","character":"薬","meaning":"Thuốc, dược","hanviet":"Dược","onReadings":["ヤク"],"kunReadings":["くすり"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"薬","reading":"くすり","meaning":"Thuốc","vocabKey":"v:薬"},{"compound":"薬局","reading":"やっきょく","meaning":"Hiệu thuốc"}],"lessonIds":[17],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 艹 (cỏ) + 楽 (lạc/vui — biến thể). Hán-Việt: DƯỢC. Mẹo nhớ: Cỏ (艹) làm cho vui khoẻ (楽) — thảo 'dược', thuốc từ thảo mộc 💊. 16 nét. Âm ヤク (yaku), くすり (kusuri) = thuốc. Liên kết: 薬 (thuốc), 薬局 (hiệu thuốc). ⚠️ Đừng nhầm với 楽 (lạc/vui 13 nét) — 薬 có thêm 艹 trên đầu.","example":"**薬**を飲んで早く寝てください。 / kusuri wo nonde hayaku nete kudasai. (Hãy uống thuốc rồi ngủ sớm)","examples":[{"ja":"薬を飲んで早く寝てください。","vi":"Hãy uống thuốc rồi ngủ sớm","romaji":"kusuri wo nonde hayaku nete kudasai."},{"ja":"薬を飲む","vi":"Uống thuốc","romaji":"Kusuri wo nomu"},{"ja":"薬を飲まなければなりません。","vi":"Phải uống thuốc.","romaji":"kusuri o noma nakere ba narimasen."},{"ja":"この薬はいつ飲んだらいいですか。","vi":"Tôi nên uống thuốc này khi nào?","romaji":"kono kusuri wa itsu non dara ii desu ka."}]},{"key":"k:約","kind":"kanji","level":"N5","character":"約","meaning":"Ước, hẹn, khoảng","hanviet":"Ước","onReadings":["ヤク"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"約束","reading":"やくそく","meaning":"Lời hẹn","vocabKey":"v:約束"},{"compound":"予約","reading":"よやく","meaning":"Đặt trước"}],"lessonIds":[9,18,47],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 糹(tơ) + 勺 (thược/múc). Hán-Việt: ƯỚC. Mẹo nhớ: Sợi tơ (糹) buộc giao kèo bằng gáo (勺) — 'ước' hẹn, cam kết 🤝. 9 nét. Âm ヤク (yaku) trong 約束 (yakusoku - lời hẹn), 予約 (yoyaku - đặt trước). Liên kết: 約束 (lời hẹn), 予約 (đặt trước). ⚠️ 予約 = dự ước = đặt trước — rất hay dùng (nhà hàng, khách sạn).","example":"友達と**約**束があります。 / tomodachi to yakusoku ga arimasu. (Tôi có hẹn với bạn)","examples":[{"ja":"友達と約束があります。","vi":"Tôi có hẹn với bạn","romaji":"tomodachi to yakusoku ga arimasu."},{"ja":"ホテルを予約する","vi":"Đặt khách sạn","romaji":"Hoteru wo yoyaku suru"},{"ja":"友達と約束する","vi":"Hẹn với bạn","romaji":"Tomodachi to yakusoku suru"},{"ja":"約束を守る","vi":"Giữ lời hứa","romaji":"Yakusoku wo mamoru"}]},{"key":"k:医","kind":"kanji","level":"N5","character":"医","meaning":"Y tế, bác sĩ","hanviet":"Y","onReadings":["イ"],"kunReadings":["—"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"医者","reading":"いしゃ","meaning":"Bác sĩ","vocabKey":"v:医者"},{"compound":"医学","reading":"いがく","meaning":"Y học","vocabKey":"v:医学"}],"lessonIds":[1,15,47,49],"topicTags":[],"sectionId":16,"sectionName":"TỔNG HỢP BỔ TÚC","mnemonic":"Bộ/thành phần: 匚 (khung/hộp) + 矢 (mũi tên). Hán-Việt: Y. Mẹo nhớ: Mũi tên (矢) trong hộp (匚) — dụng cụ của thầy 'y', bác sĩ chữa bệnh 🏥. 7 nét. Âm イ (i) trong 医者 (isha - bác sĩ), 医学 (igaku - y học). Liên kết: 医者 (bác sĩ), 医学 (y học). ⚠️ 医 là dạng giản lược — nguyên bản là 醫 (rất phức tạp).","example":"**医**者に行ったほうがいいですよ。 / isha ni itta hou ga ii desu yo. (Bạn nên đi bác sĩ đấy)","examples":[{"ja":"医者に行ったほうがいいですよ。","vi":"Bạn nên đi bác sĩ đấy","romaji":"isha ni itsuta hou ga ii desu yo."},{"ja":"医者に見てもらう","vi":"Khám bác sĩ","romaji":"Isha ni mite morau"},{"ja":"歯医者に行く","vi":"Đi nha sĩ","romaji":"Haisha ni iku"},{"ja":"医者に甘いものを食べないように言われました。","vi":"Bác sĩ dặn tôi không ăn đồ ngọt.","romaji":"isha ni amai mono o tabenai you ni iwa remashita."}]},{"key":"k:貸","kind":"kanji","level":"N4","character":"貸","meaning":"Cho mượn","hanviet":"Thải","onReadings":["タイ"],"kunReadings":["か"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"貸す","reading":"かす","meaning":"Cho mượn","vocabKey":"v:貸す"}],"lessonIds":[7,9],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 代 (đại/thay thế) + 貝 (tiền/vỏ sò). Hán-Việt: THẢI (cho mượn). Mẹo nhớ: Thay (代) tiền (貝) cho ai — 'thải' là cho mượn, cho vay 💰. 12 nét. Âm タイ (tai), かす (kasu) = cho mượn. Liên kết: 貸す (cho mượn). Đi cặp với 借 (tá/mượn): 貸 = cho mượn, 借 = đi mượn. ⚠️ 貸す (cho mượn) vs 借りる (đi mượn) — dễ nhầm!","example":"友達にペンを**貸**しました。 / tomodachi ni pen wo kashimashita. (Tôi đã cho bạn mượn bút.)","examples":[{"ja":"友達にペンを貸しました。","vi":"Tôi đã cho bạn mượn bút.","romaji":"tomodachi ni pen wo kashimashita."},{"ja":"本を貸す","vi":"Cho mượn sách","romaji":"Hon wo kasu"},{"ja":"イーさんに本を貸しました。","vi":"Tôi cho chị Lee mượn sách.","romaji":"ii san ni hon o kashimashita."},{"ja":"辞書を 貸して ください。","vi":"Hãy cho tôi mượn cuốn từ điển.","romaji":"jisho o kashite kudasai."}]},{"key":"k:借","kind":"kanji","level":"N4","character":"借","meaning":"Đi mượn","hanviet":"Tá","onReadings":["シャク"],"kunReadings":["か"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"借りる","reading":"かりる","meaning":"Mượn","vocabKey":"v:借りる"},{"compound":"借金","reading":"しゃっきん","meaning":"Tiền nợ"}],"lessonIds":[7],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 亻(người) + 昔 (tích/xưa). Hán-Việt: TÁ. Mẹo nhớ: Người (亻) ngày xưa (昔) mượn đồ — 'tá' là đi mượn, vay mượn 🤲. 10 nét. Âm シャク (shaku), かりる (kariru) = mượn. Liên kết: 借りる (mượn), 借金 (shakkin - tiền nợ). ⚠️ 借りる (mượn) vs 貸す (cho mượn) — cặp đôi hay dùng.","example":"図書館で本を**借**りました。 / toshokan de hon wo karimashita. (Tôi đã mượn sách ở thư viện.)","examples":[{"ja":"図書館で本を借りました。","vi":"Tôi đã mượn sách ở thư viện.","romaji":"toshokan de hon wo karimashita."},{"ja":"本を借りる","vi":"Mượn sách","romaji":"Hon wo kariru"},{"ja":"銀行からお金を借りました。","vi":"Tôi đã vay tiền từ ngân hàng.","romaji":"ginkou kara okane o karimashita."},{"ja":"図書館で本を借りるとき、カードが要ります。","vi":"Khi mượn sách ở thư viện thì cần phải có thẻ.","romaji":"toshokan de hon o kariru toki, kaado ga irimasu."}]},{"key":"k:暑","kind":"kanji","level":"N4","character":"暑","meaning":"Khí hậu nóng bức","hanviet":"Thử","onReadings":["ショ"],"kunReadings":["あつ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"暑い","reading":"あつい","meaning":"Nóng (thời tiết)","vocabKey":"v:暑い"}],"lessonIds":[8],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 者 (giả/người). Hán-Việt: THỬ. Mẹo nhớ: Mặt trời (日) chiếu nóng lên người (者) — 'thử' là nóng bức ☀️🥵. 12 nét. Âm ショ (sho), あつい (atsui) = nóng (thời tiết). Liên kết: 暑い (nóng). ⚠️ 暑い (atsui-nóng thời tiết) vs 熱い (atsui-nóng khi chạm) vs 厚い (atsui-dày) — 3 chữ đọc giống!","example":"今年の夏はとても**暑**いです。 / kotoshi no natsu wa totemo atsui desu. (Mùa hè năm nay rất nóng.)","examples":[{"ja":"今年の夏はとても暑いです。","vi":"Mùa hè năm nay rất nóng.","romaji":"kotoshi no natsu wa totemo atsui desu."},{"ja":"夏は暑い","vi":"Mùa hè nóng","romaji":"Natsu wa atsui"},{"ja":"暑いですから、窓を開けてください。","vi":"Vì nóng nên hãy mở cửa sổ.","romaji":"atsui desu kara, mado o akete kudasai."},{"ja":"きのうは暑かったです。","vi":"Hôm qua trời đã nóng.","romaji":"kinou wa atsukatsuta desu."}]},{"key":"k:寒","kind":"kanji","level":"N4","character":"寒","meaning":"Khí hậu giá rét","hanviet":"Hàn","onReadings":["カン"],"kunReadings":["さむ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"寒い","reading":"さむい","meaning":"Lạnh (thời tiết)","vocabKey":"v:寒い"}],"lessonIds":[8],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + biến thể + ⺀ (băng). Hán-Việt: HÀN. Mẹo nhớ: Dưới mái nhà (宀) mà vẫn thấy băng (⺀) — 'hàn' là giá rét, lạnh lẽo 🥶. 12 nét. Âm カン (kan), さむい (samui) = lạnh (thời tiết). Liên kết: 寒い (lạnh). ⚠️ 寒い (samui-lạnh thời tiết) vs 冷たい (tsumetai-lạnh khi chạm) — khác nghĩa!","example":"冬は**寒**いです。 / fuyu wa samui desu. (Mùa đông thì lạnh.)","examples":[{"ja":"冬は寒いです。","vi":"Mùa đông thì lạnh.","romaji":"fuyu wa samui desu."},{"ja":"冬は寒い","vi":"Mùa đông lạnh","romaji":"Fuyu wa samui"},{"ja":"ペキンはとても寒いです。","vi":"Bắc Kinh rất lạnh.","romaji":"pekin wa totemo samui desu."},{"ja":"シャンハイはあまり寒くないです。","vi":"Thượng Hải không lạnh lắm.","romaji":"shanhai wa amari samukunai desu."}]},{"key":"k:同","kind":"kanji","level":"N4","character":"同","meaning":"Giống hệt nhau","hanviet":"Đồng","onReadings":["ドウ"],"kunReadings":["おな"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"同じ","reading":"おなじ","meaning":"Giống nhau","vocabKey":"v:同じ"},{"compound":"同時","reading":"どうじ","meaning":"Đồng thời"}],"lessonIds":[21,33],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 冂 (khung) + 一 (nhất) + 口 (miệng). Hán-Việt: ĐỒNG. Mẹo nhớ: Một (一) miệng (口) trong khung (冂) — tất cả cùng nói 'đồng' ý, giống nhau 🤝. 6 nét. Âm ドウ (dou) trong 同じ (onaji - giống nhau), 同時 (douji - đồng thời). Liên kết: 同じ (giống nhau), 同時 (đồng thời). ⚠️ 同じ đọc おなじ (onaji) — đọc đặc biệt, cần nhớ.","example":"私も彼と**同**じ意見です。 / watashi mo kare to onaji iken desu. (Tôi cũng có cùng ý kiến với anh ấy.)","examples":[{"ja":"私も彼と同じ意見です。","vi":"Tôi cũng có cùng ý kiến với anh ấy.","romaji":"watashi mo kare to onaji iken desu."},{"ja":"毎日同じ物を食べるのはいやです。","vi":"Ăn cùng một thứ mỗi ngày thì chán.","romaji":"mainichi onaji mono o taberu no wa iya desu."},{"ja":"同じ","vi":"giống","romaji":"onaji"}]},{"key":"k:題","kind":"kanji","level":"N4","character":"題","meaning":"Chủ đề, sự xem xét","hanviet":"Đề","onReadings":["ダイ"],"kunReadings":["-"],"strokeCount":18,"radicals":[],"components":[],"compounds":[{"compound":"問題","reading":"もんだい","meaning":"Vấn đề/ câu hỏi","vocabKey":"v:問題"},{"compound":"宿題","reading":"しゅくだい","meaning":"Bài tập về nhà","vocabKey":"v:宿題"}],"lessonIds":[6,33],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 是 (thị/đúng) + 頁 (đầu/trang). Hán-Việt: ĐỀ. Mẹo nhớ: Trang (頁) viết điều đúng (是) — chủ 'đề', vấn đề 📋. 18 nét (nhiều nét). Âm ダイ (dai) trong 問題 (mondai - vấn đề), 宿題 (shukudai - bài tập). Liên kết: 問題 (vấn đề), 宿題 (bài tập về nhà). ⚠️ 問題 = vấn đề — cặp chữ cực kỳ phổ biến trong JLPT.","example":"明日までに宿**題**を出してください。 / ashita made ni shukudai wo dashite kudasai. (Hãy nộp bài tập về nhà trước ngày mai.)","examples":[{"ja":"明日までに宿題を出してください。","vi":"Hãy nộp bài tập về nhà trước ngày mai.","romaji":"ashita made ni shukudai wo dashite kudasai."},{"ja":"問題を解く","vi":"Giải bài","romaji":"Mondai wo toku"},{"ja":"宿題をする","vi":"Làm bài tập","romaji":"Shukudai wo suru"},{"ja":"練習問題をたくさん解く","vi":"Giải nhiều bài tập","romaji":"renshuu mondai o takusan toku"}]},{"key":"k:品","kind":"kanji","level":"N4","character":"品","meaning":"Vật phẩm, chất lượng","hanviet":"Phẩm","onReadings":["ヒン"],"kunReadings":["しな"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"品物","reading":"しなもの","meaning":"Hàng hóa","vocabKey":"v:品物"},{"compound":"作品","reading":"さくひん","meaning":"Tác phẩm"}],"lessonIds":[15,28,47],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 口 (miệng) × 3. Hán-Việt: PHẨM. Mẹo nhớ: Ba miệng (口口口) xếp chồng — đánh giá 'phẩm' chất, chất lượng bằng lời 📦. 9 nét. Âm ヒン (hin), しな (shina) = đồ vật/phẩm chất. Liên kết: 品物 (hàng hóa), 作品 (tác phẩm). ⚠️ 品 có 3 chữ 口 — khác với 回 (2 口), 囗 (1 口).","example":"この店はいい**品**物が多いです。 / kono mise wa ii shinamono ga ooi desu. (Cửa hàng này có nhiều hàng hóa tốt.)","examples":[{"ja":"この店はいい品物が多いです。","vi":"Cửa hàng này có nhiều hàng hóa tốt.","romaji":"kono mise wa ii shinamono ga ooi desu."},{"ja":"上品な言葉遣い","vi":"Lời nói thanh lịch","romaji":"jouhin na kotobazukai"},{"ja":"品物を選ぶ","vi":"Chọn hàng hóa","romaji":"Shinamono wo erabu"},{"ja":"この製品は日本製です","vi":"Sản phẩm này của Nhật","romaji":"kono seihin wa nipponsei desu"}]},{"key":"k:肉","kind":"kanji","level":"N5","character":"肉","meaning":"Thịt động vật","hanviet":"Nhục","onReadings":["ニク"],"kunReadings":["-"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"牛肉","reading":"ぎゅうにく","meaning":"Thịt bò","vocabKey":"v:牛肉"},{"compound":"豚肉","reading":"ぶたにく","meaning":"Thịt heo","vocabKey":"v:豚肉"},{"compound":"鶏肉","reading":"とりにく","meaning":"Thịt gà","vocabKey":"v:鶏肉"}],"lessonIds":[6,12],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 肉 là chữ tượng hình — hình miếng thịt có xương. Hán-Việt: NHỤC. Mẹo nhớ: Miếng thịt cắt ra thấy đường vân — 'nhục' là thịt 🥩. 6 nét. Âm ニク (niku) trong 牛肉 (gyuuniku - thịt bò), 豚肉 (butaniku - thịt heo). Liên kết: 牛肉 (thịt bò), 豚肉 (thịt heo), 鶏肉 (thịt gà). ⚠️ Bộ 月 (にくづき) thực ra là 肉 viết tắt — nhiều kanji cơ thể dùng 月.","example":"牛**肉**を1キロ買いました。 / gyuuniku wo ichi kiro kaimashita. (Tôi đã mua 1 kg thịt bò.)","examples":[{"ja":"牛肉を1キロ買いました。","vi":"Tôi đã mua 1 kg thịt bò.","romaji":"gyuuniku o 1kiro kaimashita."},{"ja":"肉を焼く","vi":"Nướng thịt","romaji":"Niku wo yaku"},{"ja":"牛肉が高い","vi":"Thịt bò đắt","romaji":"gyuuniku ga takai"},{"ja":"豚肉を買う","vi":"Mua thịt heo","romaji":"Butaniku wo kau"}]},{"key":"k:洋","kind":"kanji","level":"N4","character":"洋","meaning":"Biển lớn, phương Tây","hanviet":"Dương","onReadings":["ヨウ"],"kunReadings":["-"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"洋服","reading":"ようふく","meaning":"Quần áo kiểu Tây"},{"compound":"洋室","reading":"ようしつ","meaning":"Phòng kiểu Tây"}],"lessonIds":[44],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 氵(nước) + 羊 (dê/dương). Hán-Việt: DƯƠNG. Mẹo nhớ: Nước (氵) mênh mông như biển lớn có dê (羊) — 'dương' là đại dương, Tây dương 🌊. 9 nét. Âm ヨウ (you) trong 洋服 (youfuku - quần áo kiểu Tây). Liên kết: 洋服 (quần áo Tây), 洋室 (phòng kiểu Tây). ⚠️ 洋 (Tây) đối lập 和 (Nhật): 洋食/和食, 洋室/和室.","example":"新しい**洋**服を買いたいです。 / atarashii youfuku wo kaitai desu. (Tôi muốn mua quần áo kiểu Tây mới.)","examples":[{"ja":"新しい洋服を買いたいです。","vi":"Tôi muốn mua quần áo kiểu Tây mới.","romaji":"atarashii youfuku wo kaitai desu."},{"ja":"部屋は和室にしますか、洋室にしますか。","vi":"Bạn chọn phòng kiểu Nhật hay kiểu Tây?","romaji":"heya wa washitsu ni shimasu ka, youshitsu ni shimasu ka."},{"ja":"今日は洋食より和食の気分です","vi":"Hôm nay tôi thấy muốn ăn món Nhật hơn món Tây.","romaji":"Kyou wa youshoku yori washoku no kibun desu"}]},{"key":"k:池","kind":"kanji","level":"N4","character":"池","meaning":"Cái ao","hanviet":"Trì","onReadings":["チ"],"kunReadings":["いけ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"池","reading":"いけ","meaning":"Cái ao","vocabKey":"v:池"},{"compound":"電池","reading":"でんち","meaning":"Pin","vocabKey":"v:電池"}],"lessonIds":[10,30],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 氵(nước) + 也 (dã/cũng). Hán-Việt: TRÌ. Mẹo nhớ: Chỗ nước (氵) tụ lại (也) — 'trì' là ao, hồ nhỏ 🏞️. 6 nét. Âm チ (chi), いけ (ike) = ao. Liên kết: 池 (ao), 電池 (denchi - pin). ⚠️ 電池 = điện trì = pin — 池 không chỉ nghĩa ao mà còn dùng trong 'pin'.","example":"公園に大きな**池**があります。 / kouen ni ookina ike ga arimasu. (Trong công viên có một cái ao lớn.)","examples":[{"ja":"公園に大きな池があります。","vi":"Trong công viên có một cái ao lớn.","romaji":"kouen ni ookina ike ga arimasu."},{"ja":"池に魚がいる","vi":"Có cá trong ao","romaji":"Ike ni sakana gairu"},{"ja":"電池を交換する","vi":"Thay pin","romaji":"denchi o koukan suru"},{"ja":"電池","vi":"pin","romaji":"denchi"}]},{"key":"k:門","kind":"kanji","level":"N5","character":"門","meaning":"Cổng lớn","hanviet":"Môn","onReadings":["モン"],"kunReadings":["かど"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"門","reading":"もん","meaning":"Cổng","vocabKey":"v:門"},{"compound":"専門","reading":"せんもん","meaning":"Chuyên môn","vocabKey":"v:専門"}],"lessonIds":[15],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 門 là chữ tượng hình — hình hai cánh cổng mở. Hán-Việt: MÔN. Mẹo nhớ: Hai cánh cửa đối xứng — 'môn' là cổng, chuyên môn 🚪. 8 nét. Âm モン (mon) trong 門 (cổng), 専門 (senmon - chuyên môn), かど (kado). Liên kết: 門 (cổng), 専門 (chuyên môn). ⚠️ 門 là bộ thủ — nhiều kanji có 門: 問 (vấn), 聞 (nghe), 間 (gian), 開 (mở).","example":"学校の**門**の前で待っています。 / gakkou no mon no mae de matte imasu. (Tôi đang đợi trước cổng trường.)","examples":[{"ja":"学校の門の前で待っています。","vi":"Tôi đang đợi trước cổng trường.","romaji":"gakkou no mon no mae de matsute imasu."},{"ja":"専門学校でデザインを学ぶ","vi":"Học thiết kế ở trường chuyên môn","romaji":"senmon gakkou de dezain o manabu"},{"ja":"門を開ける","vi":"Mở cổng","romaji":"Mon wo akeru"},{"ja":"日本語教育が専門です","vi":"Chuyên môn là giáo dục tiếng Nhật","romaji":"nihongo kyouiku ga senmon desu"}]},{"key":"k:所","kind":"kanji","level":"N4","character":"所","meaning":"Nơi chốn","hanviet":"Sở","onReadings":["ショ"],"kunReadings":["ところ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"場所","reading":"ばしょ","meaning":"Địa điểm","vocabKey":"v:場所"},{"compound":"住所","reading":"じゅうしょ","meaning":"Địa chỉ","vocabKey":"v:住所"},{"compound":"台所","reading":"だいどころ","meaning":"Nhà bếp","vocabKey":"v:台所"}],"lessonIds":[3,8,13,14,26,27,30,35,46],"topicTags":[],"sectionId":17,"sectionName":"N4 TRỌNG ĐIỂM (CÒN THIẾU)","mnemonic":"Bộ/thành phần: 戸 (cửa/hộ) + 斤 (rìu). Hán-Việt: SỞ. Mẹo nhớ: Dùng rìu (斤) đóng cửa (戸) xây nơi ở — 'sở' là nơi chốn, chỗ 📍. 8 nét. Âm ショ (sho) trong 場所 (basho - địa điểm), ところ (tokoro) = nơi. Liên kết: 場所 (địa điểm), 住所 (địa chỉ), 台所 (nhà bếp). ⚠️ Đọc ところ (tokoro) rất phổ biến — cần nhớ cách đọc kun này.","example":"ここはとても静かな**所**です。 / koko wa totemo shizuka na tokoro desu. (Đây là một nơi rất yên tĩnh.)","examples":[{"ja":"ここはとても静かな所です。","vi":"Đây là một nơi rất yên tĩnh.","romaji":"koko wa totemo shizuka na tokoro desu."},{"ja":"近所の人と話す","vi":"Nói chuyện với hàng xóm","romaji":"Kinjo no hito to hanasu"},{"ja":"静かな場所","vi":"Nơi yên tĩnh","romaji":"Shizuka na basho"},{"ja":"住所を書く","vi":"Viết địa chỉ","romaji":"juusho o kaku"}]},{"key":"k:円","kind":"kanji","level":"N5","character":"円","meaning":"Tiền Yên, hình tròn","hanviet":"Viên","onReadings":["エン"],"kunReadings":["まる"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"百円","reading":"ひゃくえん","meaning":"100 Yên"}],"lessonIds":[3],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 円 là chữ tượng hình — hình đồng xu tròn trong khung. Hán-Việt: VIÊN (tròn). Mẹo nhớ: Hình tròn ⭕ — 'viên' vừa là hình tròn, vừa là đơn vị tiền Yên 💴. 4 nét. Âm エン (en) trong 百円 (hyakuen - 100 yên), まるい (marui) = tròn. Liên kết: 百円 (100 yên). ⚠️ 円 (en) = Yên Nhật — đồng tiền Nhật Bản.","example":"このりんごは百**円**です。 / kono ringo wa hyaku en desu. (Quả táo này giá 100 yên.)","examples":[{"ja":"このりんごは百円です。","vi":"Quả táo này giá 100 yên.","romaji":"kono ringo wa hyaku en desu."},{"ja":"もし １億円あったら、いろいろな国を旅行したいです。","vi":"Nếu có 100 triệu yên, tôi muốn đi du lịch nhiều nước.","romaji":"moshi ichi okuen atsu tara, iroiro na kuni o ryokou shitai desu."},{"ja":"財布に千円しかありません。","vi":"Trong ví chỉ có 1000 yên thôi.","romaji":"saifu ni senen shika arimasen."},{"ja":"3万円でパソコンが買えますか。","vi":"Với 3 vạn yên có thể mua máy tính không?","romaji":"3 manen de pasokon ga kaemasu ka."}]},{"key":"k:火","kind":"kanji","level":"N5","character":"火","meaning":"Lửa","hanviet":"Hỏa","onReadings":["カ"],"kunReadings":["ひ"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"火曜日","reading":"かようび","meaning":"Thứ Ba","vocabKey":"v:火曜日"},{"compound":"花火","reading":"はなび","meaning":"Pháo hoa","vocabKey":"v:花火"}],"lessonIds":[4,27,34,39,43],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 火 là chữ tượng hình — hình ngọn lửa bốc cháy. Hán-Việt: HỎe. Mẹo nhớ: Ngọn lửa với tia lửa bắn hai bên — 'hỏa' là lửa 🔥. 4 nét. Âm カ (ka) trong 火曜日 (kayoubi - thứ Ba), ひ (hi) = lửa. Liên kết: 火曜日 (thứ Ba), 花火 (hanabi - pháo hoa). ⚠️ 火 là bộ thủ — biến thể: 灬 (4 nét lửa ở dưới) trong 熱, 点.","example":"きれいな花**火**を見ました。 / kireina hanabi wo mimashita. (Tôi đã xem pháo hoa rất đẹp.)","examples":[{"ja":"きれいな花火を見ました。","vi":"Tôi đã xem pháo hoa rất đẹp.","romaji":"kireina hanabi wo mimashita."},{"ja":"火曜日にテストがある","vi":"Thứ Ba có kiểm tra","romaji":"kayoubi ni tesuto ga aru"},{"ja":"この島には火山がある","vi":"Trên đảo này có núi lửa","romaji":"Kono shima ni wa kazan ga aru"},{"ja":"花火を見る","vi":"Xem pháo hoa","romaji":"Hanabi wo miru"}]},{"key":"k:水","kind":"kanji","level":"N5","character":"水","meaning":"Nước","hanviet":"Thủy","onReadings":["スイ"],"kunReadings":["みず"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"水曜日","reading":"すいようび","meaning":"Thứ Tư","vocabKey":"v:水曜日"},{"compound":"水道","reading":"すいどう","meaning":"Nước máy","vocabKey":"v:水道"}],"lessonIds":[4,6,32,36],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 水 là chữ tượng hình — hình dòng nước chảy. Hán-Việt: THỦY. Mẹo nhớ: Dòng nước chảy giữa hai bờ — 'thủy' là nước 💧. 4 nét. Âm スイ (sui) trong 水曜日 (suiyoubi - thứ Tư), みず (mizu) = nước. Liên kết: 水曜日 (thứ Tư), 水道 (suidou - nước máy). ⚠️ 水 là bộ thủ — biến thể: 氵(3 giọt nước bên trái) trong 海, 池, 洋.","example":"冷たい**水**を飲みます。 / tsumetai mizu wo nomimasu. (Tôi uống nước lạnh.)","examples":[{"ja":"冷たい水を飲みます。","vi":"Tôi uống nước lạnh.","romaji":"tsumetai mizu wo nomimasu."},{"ja":"水曜日は休みです","vi":"Thứ Tư được nghỉ","romaji":"suiyoubi wa yasumi desu"},{"ja":"大雨で洪水が起きた","vi":"Mưa lớn gây lũ lụt","romaji":"ooame de kouzui ga okita"},{"ja":"水を飲む","vi":"Uống nước","romaji":"Mizu wo nomu"}]},{"key":"k:土","kind":"kanji","level":"N5","character":"土","meaning":"Đất đai","hanviet":"Thổ","onReadings":["ド","ト"],"kunReadings":["つち"],"strokeCount":3,"radicals":[],"components":[],"compounds":[{"compound":"土曜日","reading":"どようび","meaning":"Thứ Bảy","vocabKey":"v:土曜日"},{"compound":"お土産","reading":"おみやげ","meaning":"Quà lưu niệm","vocabKey":"v:お土産"}],"lessonIds":[2,4,28],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 十 (thập) + 一 (nhất). Hán-Việt: THỔ. Mẹo nhớ: Cái cây (十) mọc trên mặt đất (一) — 'thổ' là đất 🌍. 3 nét. Âm ド (do) trong 土曜日 (doyoubi - thứ Bảy), つち (tsuchi) = đất. Liên kết: 土曜日 (thứ Bảy), お土産 (omiyage - quà lưu niệm). ⚠️ 土 là bộ thủ — xuất hiện trong 地 (đất), 場 (nơi).","example":"日本のお土**産**を買いました。 / nihon no omiyage wo kaimashita. (Tôi đã mua quà lưu niệm Nhật Bản.)","examples":[{"ja":"日本のお土産を買いました。","vi":"Tôi đã mua quà lưu niệm Nhật Bản.","romaji":"nippon no o miyage o kaimashita."},{"ja":"土日は家でゆっくりする","vi":"Nghỉ ngơi ở nhà vào cuối tuần","romaji":"Donichi wa ie de yukkurisuru"},{"ja":"土曜日に買い物に行く","vi":"Thứ Bảy đi mua sắm","romaji":"doyoubi ni kaimono ni iku"},{"ja":"お土産を買う","vi":"Mua quà lưu niệm","romaji":"O miyage wo kau"}]},{"key":"k:午","kind":"kanji","level":"N5","character":"午","meaning":"Buổi trưa","hanviet":"Ngọ","onReadings":["ゴ"],"kunReadings":["-"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"午前","reading":"ごぜん","meaning":"Sáng/ am","vocabKey":"v:午前"},{"compound":"午後","reading":"ごご","meaning":"Chiều/ pm","vocabKey":"v:午後"}],"lessonIds":[4],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 午 là chữ tượng hình — hình cái chày giã gạo. Hán-Việt: NGỌ (giờ ngọ = buổi trưa). Mẹo nhớ: Kim đồng hồ chỉ thẳng 12h trưa — 'ngọ' là buổi trưa ☀️🕛. 4 nét. Âm ゴ (go) trong 午前 (gozen - sáng AM), 午後 (gogo - chiều PM). Liên kết: 午前 (sáng), 午後 (chiều). ⚠️ 午 (ngọ) vs 牛 (ngưu/bò) — khác 1 nét, dễ nhầm!","example":"**午**後3時に会いましょう。 / gogo sanji ni aimashou. (Gặp nhau lúc 3 giờ chiều nhé.)","examples":[{"ja":"午後3時に会いましょう。","vi":"Gặp nhau lúc 3 giờ chiều nhé.","romaji":"gogo 3ji ni ai masho u."},{"ja":"午前中に届く","vi":"Giao trong buổi sáng","romaji":"gozenchuu ni todoku"},{"ja":"午後三時に会う","vi":"Gặp lúc 3 giờ chiều","romaji":"Gogo sanji ni au"},{"ja":"会議は午前ですか、午後ですか。","vi":"Cuộc họp buổi sáng hay buổi chiều?","romaji":"kaigi wa gozen desu ka, gogo desu ka."}]},{"key":"k:毎","kind":"kanji","level":"N5","character":"毎","meaning":"Mỗi, mọi","hanviet":"Mỗi","onReadings":["マイ"],"kunReadings":["-"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"毎日","reading":"まいにち","meaning":"Mỗi ngày","vocabKey":"v:毎日"},{"compound":"毎年","reading":"まいとし","meaning":"Mỗi năm","vocabKey":"v:毎年"}],"lessonIds":[4,35,36],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 母 (mẹ) biến thể. Hán-Việt: MỖI. Mẹo nhớ: Mẹ (母) ngày nào cũng dậy sớm — 'mỗi' ngày đều đặn 📅. 6 nét. Âm マイ (mai) trong 毎日 (mainichi - mỗi ngày), 毎年 (maitoshi - mỗi năm). Liên kết: 毎日 (mỗi ngày), 毎週 (mỗi tuần). ⚠️ 毎 vs 海 (biển) — 毎 thêm 氵= 海.","example":"**毎**日日本語を勉強します。 / mainichi nihongo wo benkyou shimasu. (Mỗi ngày tôi đều học tiếng Nhật.)","examples":[{"ja":"毎日日本語を勉強します。","vi":"Mỗi ngày tôi đều học tiếng Nhật.","romaji":"mainichi nihongo wo benkyou shimasu."},{"ja":"毎朝走る","vi":"Chạy mỗi sáng","romaji":"Maiasa hashiru"},{"ja":"毎晩勉強する","vi":"Học mỗi tối","romaji":"maiban benkyou suru"},{"ja":"毎日勉強する","vi":"Học mỗi ngày","romaji":"mainichi benkyou suru"}]},{"key":"k:何","kind":"kanji","level":"N5","character":"何","meaning":"Cái gì","hanviet":"Hà","onReadings":["カ"],"kunReadings":["なに","なん"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"何","reading":"なに","meaning":"Cái gì","vocabKey":"v:何"},{"compound":"何人","reading":"なんにん","meaning":"Mấy người"}],"lessonIds":[1,2,3,4,5,6,13,19,26,37],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 亻(người) + 可 (khả/có thể). Hán-Việt: HÀ. Mẹo nhớ: Người (亻) hỏi 'có thể' (可) là gì — 'hà' là cái gì, sao ❓. 7 nét. Âm カ (ka), なに (nani) = cái gì, なん (nan). Liên kết: 何 (nani - cái gì), 何人 (nannin - mấy người). ⚠️ Đọc なに hay なん tùy ngữ cảnh — trước ですか đọc なん.","example":"あれは**何**ですか。 / are wa nan desu ka. (Kia là cái gì?)","examples":[{"ja":"あれは何ですか。","vi":"Kia là cái gì?","romaji":"are wa nani desu ka."},{"ja":"何を食べますか","vi":"Ăn gì?","romaji":"Nani wo tabemasu ka"},{"ja":"お仕事は何ですか。","vi":"Công việc của bạn là gì?","romaji":"o shigoto wa nani desu ka."},{"ja":"今何時ですか。……7時10分です。","vi":"Bây giờ là mấy giờ? ... 7 giờ 10 phút.","romaji":"ima nanji desu ka....... 7ji 10fun desu."}]},{"key":"k:本","kind":"kanji","level":"N5","character":"本","meaning":"Sách, cội nguồn","hanviet":"Bản","onReadings":["ホン"],"kunReadings":["もと"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"本","reading":"ほん","meaning":"Sách","vocabKey":"v:本"},{"compound":"日本","reading":"にほん","meaning":"Nhật Bản","vocabKey":"v:日本"}],"lessonIds":[2,27,31,37,40,41],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 木 (cây) + 一 (nhất/gốc). Hán-Việt: BẢN. Mẹo nhớ: Gạch ngang (一) ở gốc cây (木) — 'bản' là gốc, cội nguồn, sách 📚. 5 nét. Âm ホン (hon) trong 本 (hon - quyển sách), 日本 (nihon - Nhật Bản), もと (moto) = gốc. Liên kết: 日本 (Nhật Bản), 本屋 (hiệu sách). ⚠️ 本 vừa là 'sách' vừa là bộ đếm cho vật dài (鉛筆一本).","example":"面白い**本**を読みました。 / omoshiroi hon wo yomimashita. (Tôi đã đọc một quyển sách thú vị.)","examples":[{"ja":"面白い本を読みました。","vi":"Tôi đã đọc một quyển sách thú vị.","romaji":"omoshiroi hon wo yomimashita."},{"ja":"日本語を勉強する","vi":"Học tiếng Nhật","romaji":"nihongo o benkyou suru"},{"ja":"日本に行く","vi":"Đi Nhật","romaji":"nippon ni iku"},{"ja":"ペンを二本買った","vi":"Mua 2 cây bút","romaji":"pen o nihon katsuta"}]},{"key":"k:名","kind":"kanji","level":"N5","character":"名","meaning":"Tên gọi","hanviet":"Danh","onReadings":["メイ","ミョウ"],"kunReadings":["な"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"名前","reading":"なまえ","meaning":"Tên gọi","vocabKey":"v:名前"},{"compound":"有名","reading":"ゆうめい","meaning":"Nổi tiếng"}],"lessonIds":[2,8,14],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 夕 (chiều tối) + 口 (miệng). Hán-Việt: DANH. Mẹo nhớ: Buổi tối (夕) gọi tên (口) ai đó — 'danh' là tên gọi 📛. 6 nét. Âm メイ (mei) trong 名前 (namae - tên), 有名 (yuumei - nổi tiếng), な (na). Liên kết: 名前 (tên), 有名 (nổi tiếng). ⚠️ 名前 (namae) = tên — cặp từ cơ bản nhất trong tiếng Nhật.","example":"お**名**前は何ですか。 / onamae wa nan desu ka. (Tên bạn là gì?)","examples":[{"ja":"お名前は何ですか。","vi":"Tên bạn là gì?","romaji":"o namae wa nani desu ka."},{"ja":"有名な人","vi":"Người nổi tiếng","romaji":"yuumei na hito"},{"ja":"名前を書く","vi":"Viết tên","romaji":"Namae wo kaku"},{"ja":"名刺を交換する","vi":"Trao đổi danh thiếp","romaji":"meishi o koukan suru"}]},{"key":"k:安","kind":"kanji","level":"N5","character":"安","meaning":"Rẻ, an toàn","hanviet":"An","onReadings":["アン"],"kunReadings":["やす"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"安い","reading":"やすい","meaning":"Rẻ","vocabKey":"v:安い"},{"compound":"安心","reading":"あんしん","meaning":"An tâm","vocabKey":"v:安心"}],"lessonIds":[8,39,44],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + 女 (nữ). Hán-Việt: AN. Mẹo nhớ: Phụ nữ (女) dưới mái nhà (宀) — 'an' là yên ổn, rẻ 🏠💰. 6 nét. Âm アン (an) trong 安心 (anshin - an tâm), やすい (yasui) = rẻ. Liên kết: 安い (rẻ), 安心 (an tâm). ⚠️ 安い (yasui-rẻ) vs 易い (yasui-dễ) — khác kanji, đọc giống!","example":"このカメラはとても**安**いです。 / kono kamera wa totemo yasui desu. (Cái máy ảnh này rất rẻ.)","examples":[{"ja":"このカメラはとても安いです。","vi":"Cái máy ảnh này rất rẻ.","romaji":"kono kamera wa totemo yasui desu."},{"ja":"結果を聞いて安心する","vi":"Nghe kết quả mà yên tâm","romaji":"Kekka wo kiite anshinsuru"},{"ja":"この店は安い","vi":"Quán này rẻ","romaji":"Kono mise wa yasui"},{"ja":"この道は安全だ","vi":"Con đường này an toàn","romaji":"Kono michi wa anzen da"}]},{"key":"k:休","kind":"kanji","level":"N5","character":"休","meaning":"Nghỉ ngơi","hanviet":"Hưu","onReadings":["キュウ"],"kunReadings":["やす"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"休む","reading":"やすむ","meaning":"Nghỉ ngơi","vocabKey":"v:休む"},{"compound":"昼休み","reading":"ひるやすみ","meaning":"Nghỉ trưa","vocabKey":"v:昼休み"}],"lessonIds":[4,11,31],"topicTags":[],"sectionId":19,"sectionName":"KANJI N5 BỔ TRỢ (CẦN ĐỂ GHÉP TỪ N4)","mnemonic":"Bộ/thành phần: 亻 (người) + 木 (cây). Mẹo nhớ: người tựa vào gốc cây để nghỉ ngơi, nên mang nghĩa 'nghỉ'.","example":"日曜日は学校が**休**みです。 / nichiyoubi wa gakkou ga yasumi desu. (Chủ nhật trường học nghỉ.)","examples":[{"ja":"日曜日は学校が休みです。","vi":"Chủ nhật trường học nghỉ.","romaji":"nichiyoubi wa gakkou ga yasumi desu."},{"ja":"今日は休む","vi":"Hôm nay nghỉ","romaji":"kyou wa yasumu"},{"ja":"ゴールデンウィークは長い連休です","vi":"Golden Week là kỳ nghỉ dài","romaji":"gooruden'uiiku wa nagai renkyuu desu"},{"ja":"昼休みに食事する","vi":"Ăn trưa giờ nghỉ","romaji":"Hiruyasumi ni shokuji suru"}]},{"key":"k:間","kind":"kanji","level":"N5","character":"間","meaning":"Khoảng cách, khoảng thời gian","hanviet":"Gian","onReadings":["カン","ケン"],"kunReadings":["あいだ","ま"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"時間","reading":"じかん","meaning":"Thời gian","vocabKey":"v:時間"},{"compound":"人間","reading":"にんげん","meaning":"Con người"},{"compound":"間に合う","reading":"まにあう","meaning":"Kịp","vocabKey":"v:間に合う"}],"lessonIds":[9,10,11,20,26,27,37,41,48],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 門 (cổng) + 日 (mặt trời). Hán-Việt: GIAN. Mẹo nhớ: Mặt trời (日) lọt qua khe cổng (門) — 'gian' là khoảng cách, khoảng thời gian ⏰. 12 nét. Âm カン (kan) trong 時間 (jikan - thời gian), あいだ (aida) = giữa. Liên kết: 時間 (thời gian), 人間 (con người), 間に合う (kịp). ⚠️ 間 đọc あいだ (giữa) hoặc ま (khoảng trống) — tùy ngữ cảnh.","example":"東京まで3**時間**かかります。 / toukyou made sanjikan kakarimasu. (Mất 3 tiếng đến Tokyo)","examples":[{"ja":"東京まで3時間かかります。","vi":"Mất 3 tiếng đến Tokyo","romaji":"toukyou made 3jikan kakarimasu."},{"ja":"電車に間に合う","vi":"Kịp tàu","romaji":"Densha ni maniau"},{"ja":"道を間違える","vi":"Nhầm đường","romaji":"Michi wo machigaeru"},{"ja":"クラスの仲間と旅行する","vi":"Đi du lịch với bạn cùng lớp","romaji":"kurasu no nakama to ryokou suru"}]},{"key":"k:自","kind":"kanji","level":"N4","character":"自","meaning":"Tự mình, bản thân","hanviet":"Tự","onReadings":["ジ","シ"],"kunReadings":["みずか"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"自分","reading":"じぶん","meaning":"Bản thân","vocabKey":"v:自分"},{"compound":"自動車","reading":"じどうしゃ","meaning":"Ô tô"},{"compound":"自由","reading":"じゆう","meaning":"Tự do"}],"lessonIds":[3,5,24,27,28,31,36,42,48],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 自 là chữ tượng hình — hình cái mũi (chỉ vào bản thân). Hán-Việt: TỰ. Mẹo nhớ: Người Nhật chỉ vào mũi khi nói 'tôi' — 'tự' là bản thân 👃. 6 nét. Âm ジ (ji) trong 自分 (jibun - bản thân), 自動車 (jidousha - ô tô). Liên kết: 自分 (bản thân), 自由 (tự do). ⚠️ 自 là bộ thủ — xuất hiện trong 臭 (thối), 息 (hơi thở).","example":"**自**分で料理を作ります。 / jibun de ryouri wo tsukurimasu. (Tôi tự nấu ăn)","examples":[{"ja":"自分で料理を作ります。","vi":"Tôi tự nấu ăn","romaji":"jibun de ryouri wo tsukurimasu."},{"ja":"自由な生活","vi":"Cuộc sống tự do","romaji":"jiyuu na seikatsu"},{"ja":"自然環境を守る","vi":"Bảo vệ môi trường tự nhiên","romaji":"shizen kankyou o mamoru"},{"ja":"自転車で通う","vi":"Đi bằng xe đạp","romaji":"jitensha de kayou"}]},{"key":"k:通","kind":"kanji","level":"N4","character":"通","meaning":"Đi qua, thông, đến","hanviet":"Thông","onReadings":["ツウ"],"kunReadings":["とお","かよ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"交通","reading":"こうつう","meaning":"Giao thông","vocabKey":"v:交通"},{"compound":"通る","reading":"とおる","meaning":"Đi qua","vocabKey":"v:通る"},{"compound":"通う","reading":"かよう","meaning":"Qua lại","vocabKey":"v:通う"}],"lessonIds":[5,21,27,28,39,48],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 甬 (dũng/ống) + 辶 (đi). Hán-Việt: THÔNG. Mẹo nhớ: Đi (辶) qua ống (甬) — 'thông' là đi qua, thông suốt 🛤️. 10 nét. Âm ツウ (tsuu), とおる (tooru) = đi qua, かよう (kayou) = qua lại. Liên kết: 交通 (giao thông), 通る (đi qua). ⚠️ 通る (tooru-đi qua chỗ) vs 通う (kayou-đi lại thường xuyên) — khác nghĩa.","example":"この道を**通**って学校に行きます。 / kono michi wo tootte gakkou ni ikimasu. (Tôi đi qua con đường này đến trường)","examples":[{"ja":"この道を通って学校に行きます。","vi":"Tôi đi qua con đường này đến trường","romaji":"kono michi o tootsute gakkou ni ikimasu."},{"ja":"学校に通う","vi":"Đi học hàng ngày","romaji":"gakkou ni kayou"},{"ja":"この道を通ってください","vi":"Hãy đi qua con đường này","romaji":"kono michi o tootsute kudasai"},{"ja":"普通の生活がしたい","vi":"Muốn sống bình thường","romaji":"futsuu no seikatsu ga shitai"}]},{"key":"k:真","kind":"kanji","level":"N4","character":"真","meaning":"Thật, chân thật","hanviet":"Chân","onReadings":["シン"],"kunReadings":["ま"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"写真","reading":"しゃしん","meaning":"Ảnh","vocabKey":"v:写真"},{"compound":"真ん中","reading":"まんなか","meaning":"Chính giữa","vocabKey":"v:真ん中"}],"lessonIds":[6,30,41],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 十 (thập) + 具 (cụ/dụng cụ) biến thể. Hán-Việt: CHÂN. Mẹo nhớ: Đặt dụng cụ (具) lên bàn (十) kiểm tra — 'chân' là thật, chân thật 📸. 10 nét. Âm シン (shin) trong 写真 (shashin - ảnh), ま (ma) trong 真ん中 (mannaka - chính giữa). Liên kết: 写真 (ảnh), 真ん中 (chính giữa). ⚠️ 写真 = chụp ảnh — cặp từ rất phổ biến.","example":"きれいな**写真**を撮りました。 / kireina shashin wo torimashita. (Tôi đã chụp ảnh đẹp)","examples":[{"ja":"きれいな写真を撮りました。","vi":"Tôi đã chụp ảnh đẹp","romaji":"kireina shashin wo torimashita."},{"ja":"真面目な学生","vi":"Học sinh nghiêm túc","romaji":"Majime na gakusei"},{"ja":"写真を撮る","vi":"Chụp ảnh","romaji":"Shashin wo toru"},{"ja":"机の上に写真があります。","vi":"Ở trên bàn có bức ảnh.","romaji":"tsukue no ue ni shashin ga arimasu."}]},{"key":"k:黄","kind":"kanji","level":"N4","character":"黄","meaning":"Màu vàng","hanviet":"Hoàng","onReadings":["オウ","コウ"],"kunReadings":["き","こ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"黄色","reading":"きいろ","meaning":"Màu vàng","vocabKey":"v:黄色"},{"compound":"黄色い","reading":"きいろい","meaning":"Vàng (tính từ)","vocabKey":"v:黄色い"}],"lessonIds":[34],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 廿 (biến thể) + 由 (do/từ) + 八 (tám). Hán-Việt: HOÀNG. Mẹo nhớ: Ruộng lúa (由) chín vàng tỏa ra (八) — 'hoàng' là màu vàng 🟡. 11 nét. Âm オウ (ou), き (ki) trong 黄色 (kiiro - màu vàng). Liên kết: 黄色 (màu vàng), 黄色い (vàng - tính từ). ⚠️ 黄 nét nhiều (11) — nhớ theo cấu trúc trên xuống.","example":"**黄**色い花が咲いています。 / kiiroi hana ga saite imasu. (Hoa màu vàng đang nở)","examples":[{"ja":"黄色い花が咲いています。","vi":"Hoa màu vàng đang nở","romaji":"kiiroi hana ga saite imasu."},{"ja":"黄色い花","vi":"Hoa vàng","romaji":"Kiiroi hana"},{"ja":"黄色","vi":"màu vàng (danh từ)","romaji":"kiiro"}]},{"key":"k:最","kind":"kanji","level":"N4","character":"最","meaning":"Nhất, tối (cùng)","hanviet":"Tối","onReadings":["サイ"],"kunReadings":["もっと"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"最近","reading":"さいきん","meaning":"Gần đây","vocabKey":"v:最近"},{"compound":"最後","reading":"さいご","meaning":"Cuối cùng","vocabKey":"v:最後"},{"compound":"最初","reading":"さいしょ","meaning":"Đầu tiên","vocabKey":"v:最初"}],"lessonIds":[21],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 取 (lấy). Hán-Việt: TỐI. Mẹo nhớ: Lấy (取) cái tốt nhất dưới mặt trời (日) — 'tối' là nhất, tối cao ⭐. 12 nét. Âm サイ (sai) trong 最近 (saikin - gần đây), 最後 (saigo - cuối cùng), もっとも (mottomo). Liên kết: 最近 (gần đây), 最後 (cuối cùng), 最初 (đầu tiên). ⚠️ 最 + 近/後/初 = gần đây/cuối/đầu — rất phổ biến.","example":"**最**近、日本語がうまくなりました。 / saikin, nihongo ga umaku narimashita. (Gần đây tiếng Nhật đã khá hơn)","examples":[{"ja":"最近、日本語がうまくなりました。","vi":"Gần đây tiếng Nhật đã khá hơn","romaji":"saikin, nihongo ga umaku narimashita."},{"ja":"最近忙しい","vi":"Gần đây bận","romaji":"Saikin'isogashi i"},{"ja":"今日の最高気温は三十度です","vi":"Nhiệt độ cao nhất hôm nay là 30 độ","romaji":"kyou no saikou kion wa san juudo desu"},{"ja":"明日の最低気温は五度です","vi":"Nhiệt độ thấp nhất ngày mai là 5 độ","romaji":"Ashita no saitei kion wa godo de su"}]},{"key":"k:園","kind":"kanji","level":"N4","character":"園","meaning":"Vườn, công viên","hanviet":"Viên","onReadings":["エン"],"kunReadings":["その"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"公園","reading":"こうえん","meaning":"Công viên","vocabKey":"v:公園"},{"compound":"動物園","reading":"どうぶつえん","meaning":"Sở thú","vocabKey":"v:動物園"},{"compound":"幼稚園","reading":"ようちえん","meaning":"Mẫu giáo","vocabKey":"v:幼稚園"}],"lessonIds":[10,12,31,41],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 囗 (bao quanh) + 袁 (viên). Hán-Việt: VIÊN. Mẹo nhớ: Hàng rào (囗) bao quanh khu đất — 'viên' là vườn, công viên 🌳. 13 nét. Âm エン (en) trong 公園 (kouen - công viên), 動物園 (doubutsuen - sở thú). Liên kết: 公園 (công viên), 動物園 (sở thú). ⚠️ 園 (en-vườn) vs 円 (en-yên) — đọc giống nhau, khác nghĩa.","example":"**動物園**に行きたいです。 / doubutsuen ni ikitai desu. (Tôi muốn đi sở thú)","examples":[{"ja":"動物園に行きたいです。","vi":"Tôi muốn đi sở thú","romaji":"doubutsuen ni ikitai desu."},{"ja":"公園を散歩する","vi":"Đi dạo ở công viên","romaji":"kouen o sanpo suru"},{"ja":"動物園に行く","vi":"Đi sở thú","romaji":"doubutsuen ni iku"},{"ja":"公園を散歩します。","vi":"Đi dạo trong công viên.","romaji":"kouen o sanpo shimasu."}]},{"key":"k:野","kind":"kanji","level":"N4","character":"野","meaning":"Đồng, cánh đồng, hoang dã","hanviet":"Dã","onReadings":["ヤ"],"kunReadings":["の"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"野菜","reading":"やさい","meaning":"Rau","vocabKey":"v:野菜"},{"compound":"野球","reading":"やきゅう","meaning":"Bóng chày","vocabKey":"v:野球"}],"lessonIds":[6,9],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 里 (làng) + 予 (dự). Hán-Việt: DÃ. Mẹo nhớ: Ngoài làng (里) là đồng dã — 'dã' là cánh đồng, hoang dã 🌾. 11 nét. Âm ヤ (ya) trong 野菜 (yasai - rau), 野球 (yakyuu - bóng chày), の (no). Liên kết: 野菜 (rau), 野球 (bóng chày). ⚠️ 野菜 = dã thái = rau — từ rất phổ biến trong đời sống.","example":"**野**菜をたくさん食べてください。 / yasai wo takusan tabete kudasai. (Hãy ăn nhiều rau)","examples":[{"ja":"野菜をたくさん食べてください。","vi":"Hãy ăn nhiều rau","romaji":"yasai wo takusan tabete kudasai."},{"ja":"野菜を食べる","vi":"Ăn rau","romaji":"Yasai wo taberu"},{"ja":"野球を見る","vi":"Xem bóng chày","romaji":"yakyuu o miru"},{"ja":"得意な分野について話す","vi":"Nói về lĩnh vực mình giỏi","romaji":"Tokui na bunya ni tsuite hanasu"}]},{"key":"k:供","kind":"kanji","level":"N4","character":"供","meaning":"Cung cấp, trẻ con (trong từ ghép)","hanviet":"Cung","onReadings":["キョウ","ク"],"kunReadings":["とも","そな"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"子供","reading":"こども","meaning":"Trẻ con","vocabKey":"v:子供"},{"compound":"供える","reading":"そなえる","meaning":"Cúng"}],"lessonIds":[],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 亻(người) + 共 (cộng/cùng). Hán-Việt: CUNG. Mẹo nhớ: Người (亻) cùng (共) phục vụ — 'cung' là cung cấp, trẻ con (子供) 👦. 8 nét. Âm キョウ (kyou), とも (tomo). Liên kết: 子供 (kodomo - trẻ con), 供える (cúng). ⚠️ 子供 đọc こども (kodomo) — 供 đọc đặc biệt trong từ này.","example":"**子供**たちが元気に遊んでいます。 / kodomo-tachi ga genki ni asonde imasu. (Bọn trẻ đang vui vẻ chơi đùa)","examples":[{"ja":"子供たちが元気に遊んでいます。","vi":"Bọn trẻ đang vui vẻ chơi đùa","romaji":"kodomo-tachi ga genki ni asonde imasu."},{"ja":"子供が遊ぶ","vi":"Trẻ con chơi","romaji":"Kodomo ga asobu"},{"ja":"10歳未満の子供は無料です","vi":"Trẻ dưới 10 tuổi miễn phí","romaji":"10saimiman no kodomo wa muryou desu"},{"ja":"子供のとき、よく遊びました。(こどものとき、よく あそびました)","vi":"Khi còn nhỏ, tôi hay chơi."}]},{"key":"k:遊","kind":"kanji","level":"N4","character":"遊","meaning":"Chơi, du ngoạn","hanviet":"Du","onReadings":["ユウ"],"kunReadings":["あそ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"遊ぶ","reading":"あそぶ","meaning":"Chơi","vocabKey":"v:遊ぶ"},{"compound":"遊び","reading":"あそび","meaning":"Trò chơi"}],"lessonIds":[13],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 斿 (du/cờ) + 辶 (đi). Hán-Việt: DU. Mẹo nhớ: Đi (辶) chơi với cờ phất phới — 'du' là chơi, du ngoạn 🎮. 12 nét. Âm ユウ (yuu), あそぶ (asobu) = chơi. Liên kết: 遊ぶ (chơi), 遊び (trò chơi). ⚠️ 遊ぶ (asobu) — động từ nhóm 1 (godan), て形 là 遊んで.","example":"日曜日に友達と**遊**びます。 / nichiyoubi ni tomodachi to asobimasu. (Chủ nhật tôi chơi với bạn)","examples":[{"ja":"日曜日に友達と遊びます。","vi":"Chủ nhật tôi chơi với bạn","romaji":"nichiyoubi ni tomodachi to asobimasu."},{"ja":"公園で遊ぶ","vi":"Chơi ở công viên","romaji":"kouen de asobu"},{"ja":"読みます、飲みます、遊びます は Nhóm I です。","vi":"Đọc, uống, chơi là động từ Nhóm I.","romaji":"yomimasu, nomimasu, asobimasu wa nhom i desu."},{"ja":"ぜひ遊びに来てください。","vi":"Nhất định hãy đến chơi nhé.","romaji":"zehi asobi ni kite kudasai."}]},{"key":"k:活","kind":"kanji","level":"N4","character":"活","meaning":"Sống, hoạt động","hanviet":"Hoạt","onReadings":["カツ"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"生活","reading":"せいかつ","meaning":"Cuộc sống","vocabKey":"v:生活"},{"compound":"活動","reading":"かつどう","meaning":"Hoạt động"}],"lessonIds":[8],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 氵(nước) + 舌 (lưỡi/thiệt). Hán-Việt: HOẠT. Mẹo nhớ: Nước (氵) chảy qua lưỡi (舌) — tràn đầy sức 'hoạt' động, sinh sống 💧. 9 nét. Âm カツ (katsu) trong 生活 (seikatsu - cuộc sống), 活動 (katsudou - hoạt động). Liên kết: 生活 (cuộc sống), 活動 (hoạt động). ⚠️ 生活 = sinh hoạt = cuộc sống — từ ghép quan trọng.","example":"日本での**生活**は楽しいです。 / nihon de no seikatsu wa tanoshii desu. (Cuộc sống ở Nhật vui)","examples":[{"ja":"日本での生活は楽しいです。","vi":"Cuộc sống ở Nhật vui","romaji":"nippon de no seikatsu wa tanoshii desu."},{"ja":"一人で生活する","vi":"Sống một mình","romaji":"ichinin de seikatsu suru"},{"ja":"日本の生活に慣れる","vi":"Quen cuộc sống Nhật","romaji":"Nippon no seikatsu ni nareru"},{"ja":"生活費が高い","vi":"Chi phí sinh hoạt cao","romaji":"Seikatsuhi ga takai"}]},{"key":"k:様","kind":"kanji","level":"N4","character":"様","meaning":"Dạng, kiểu, kính ngữ (Mr./ mrs.)","hanviet":"Dạng","onReadings":["ヨウ"],"kunReadings":["さま"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"様","reading":"～さま","meaning":"Ngài","vocabKey":"v:様"},{"compound":"お客様","reading":"おきゃくさま","meaning":"Quý khách","vocabKey":"v:お客様"},{"compound":"様子","reading":"ようす","meaning":"Tình hình"}],"lessonIds":[26,36,37,39,41,46,49],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 木 (cây) + 羊 (dê) + 水 biến thể. Hán-Việt: DẠNG. Mẹo nhớ: Cây (木) đủ dạng vẻ — 'dạng' là kiểu, kính ngữ (～様) 🎩. 14 nét. Âm ヨウ (you) trong 様子 (yousu - tình hình), さま (sama) = ngài. Liên kết: ～様 (sama - ngài), お客様 (quý khách). ⚠️ ～様 (sama) là kính ngữ cao — lịch sự hơn ～さん.","example":"お客**様**、こちらへどうぞ。 / okyaku-sama, kochira e douzo. (Thưa quý khách, mời đi lối này)","examples":[{"ja":"お客様、こちらへどうぞ。","vi":"Thưa quý khách, mời đi lối này","romaji":"okyaku-sama, kochira e douzo."},{"ja":"田中さん、今日もお疲れ様です。","vi":"Anh Tanaka, hôm nay cũng vất vả rồi.","romaji":"tanaka san, kyou mo o tsukare sama desu."},{"ja":"ご馳走様でした。とてもおいしかったです。","vi":"Cảm ơn vì bữa ăn, món ăn rất ngon.","romaji":"gochisousama deshita. totemo oishikatsuta desu."},{"ja":"一般のお客様","vi":"Khách hàng thông thường","romaji":"Ippanno o kyakusama"}]},{"key":"k:信","kind":"kanji","level":"N4","character":"信","meaning":"Tin, tín","hanviet":"Tín","onReadings":["シン"],"kunReadings":["—"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"信じる","reading":"しんじる","meaning":"Tin","vocabKey":"v:信じる"},{"compound":"信号","reading":"しんごう","meaning":"Đèn giao thông","vocabKey":"v:信号"}],"lessonIds":[23,27,45],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 亻 (người) + 言 (lời nói). Mẹo nhớ: lời nói của con người tạo nên niềm tin, nên nhớ nghĩa 'tin'.","example":"**信**号が赤の時は止まってください。 / shingou ga aka no toki wa tomatte kudasai. (Khi đèn đỏ hãy dừng lại)","examples":[{"ja":"信号が赤の時は止まってください。","vi":"Khi đèn đỏ hãy dừng lại","romaji":"shingou ga aka no toki wa tomatsute kudasai."},{"ja":"友達を信じる","vi":"Tin tưởng bạn","romaji":"Tomodachi wo shinjiru"},{"ja":"信号が赤い","vi":"Đèn đỏ","romaji":"shingou ga akai"},{"ja":"信号機が青になった","vi":"Đèn giao thông chuyển xanh","romaji":"shingouki ga ao ni natsuta"}]},{"key":"k:取","kind":"kanji","level":"N4","character":"取","meaning":"Lấy, cầm","hanviet":"Thủ","onReadings":["シュ"],"kunReadings":["と"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"取る","reading":"とる","meaning":"Lấy","vocabKey":"v:取る"},{"compound":"取り消す","reading":"とりけす","meaning":"Hủy bỏ"}],"lessonIds":[14,25,29,31],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 耳 (tai) + 又 (tay/hữu). Hán-Việt: THỦ. Mẹo nhớ: Tay (又) nắm tai (耳) kéo lại — 'thủ' là lấy, cầm ✊. 8 nét. Âm シュ (shu), とる (toru) = lấy. Liên kết: 取る (lấy), 取り消す (hủy bỏ). ⚠️ 取る (toru-lấy) vs 撮る (toru-chụp ảnh) vs 採る (toru-thu hoạch) — 3 chữ đọc giống.","example":"棚から本を**取**ってください。 / tana kara hon wo totte kudasai. (Hãy lấy sách từ kệ xuống)","examples":[{"ja":"棚から本を取ってください。","vi":"Hãy lấy sách từ kệ xuống","romaji":"tana kara hon o totsute kudasai."},{"ja":"写真を取る","vi":"Chụp ảnh","romaji":"Shashin wo toru"},{"ja":"荷物を受け取る","vi":"Nhận hàng","romaji":"Nimotsu wo uketoru"},{"ja":"取扱説明書をよく読んでください","vi":"Hãy đọc kỹ hướng dẫn sử dụng","romaji":"Toriatsukaisetsumeisho wo yoku yonde kudasai"}]},{"key":"k:返","kind":"kanji","level":"N4","character":"返","meaning":"Trả lại","hanviet":"Phản","onReadings":["ヘン"],"kunReadings":["かえ","かえ"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"返す","reading":"かえす","meaning":"Trả lại","vocabKey":"v:返す"},{"compound":"返事","reading":"へんじ","meaning":"Trả lời","vocabKey":"v:返事"}],"lessonIds":[9,17,18,27,28,29,38,40],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 反 (phản/ngược) + 辶 (đi). Hán-Việt: PHẢN (trả lại). Mẹo nhớ: Đi (辶) ngược lại (反) — 'phản' là trả lại, quay về 🔄. 7 nét. Âm ヘン (hen) trong 返事 (henji - trả lời), かえす (kaesu) = trả lại. Liên kết: 返す (trả lại), 返事 (trả lời). ⚠️ 返す (kaesu-trả) vs 帰る (kaeru-về nhà) — khác nghĩa.","example":"借りた本を**返**しました。 / karita hon wo kaeshimashita. (Tôi đã trả sách đã mượn)","examples":[{"ja":"借りた本を返しました。","vi":"Tôi đã trả sách đã mượn","romaji":"karita hon wo kaeshimashita."},{"ja":"本を返す","vi":"Trả sách","romaji":"Hon wo kaesu"},{"ja":"すぐに返事する","vi":"Trả lời ngay","romaji":"Suguni henji suru"},{"ja":"返事をする","vi":"Trả lời","romaji":"Henji wo suru"}]},{"key":"k:配","kind":"kanji","level":"N4","character":"配","meaning":"Phân phối, lo lắng","hanviet":"Phối","onReadings":["ハイ"],"kunReadings":["くば"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"心配","reading":"しんぱい","meaning":"Lo lắng"},{"compound":"配る","reading":"くばる","meaning":"Phát"},{"compound":"配達","reading":"はいたつ","meaning":"Giao hàng","vocabKey":"v:配達"}],"lessonIds":[17,46],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 酉 (rượu/dậu) + 己 (kỷ/mình). Hán-Việt: PHỐI. Mẹo nhớ: Chia rượu (酉) cho mình (己) — 'phối' là phân phối, chia, lo lắng 📦. 10 nét. Âm ハイ (hai) trong 心配 (shinpai - lo lắng), くばる (kubaru) = phát. Liên kết: 心配 (lo lắng), 配る (phát), 配達 (giao hàng). ⚠️ 心配 = tâm phối = lo lắng — từ rất phổ biến.","example":"母はいつも**心配**しています。 / haha wa itsumo shinpai shite imasu. (Mẹ lúc nào cũng lo lắng)","examples":[{"ja":"母はいつも心配しています。","vi":"Mẹ lúc nào cũng lo lắng","romaji":"haha wa itsumo shinpai shite imasu."},{"ja":"子供を心配する","vi":"Lo lắng cho con","romaji":"Kodomo wo shinpai suru"},{"ja":"新聞の配達を頼む","vi":"Nhờ giao báo","romaji":"Shinbun no haitatsu wo tanomu"},{"ja":"何か心配なことがあるんですか。","vi":"Bạn có điều gì lo lắng à?","romaji":"nani ka shinpai na koto ga aru n desu ka."}]},{"key":"k:覚","kind":"kanji","level":"N4","character":"覚","meaning":"Nhớ, ghi nhớ, thức tỉnh","hanviet":"Giác","onReadings":["カク"],"kunReadings":["おぼ","さ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"覚える","reading":"おぼえる","meaning":"Nhớ/ học thuộc","vocabKey":"v:覚える"},{"compound":"覚ます","reading":"さます","meaning":"Đánh thức"}],"lessonIds":[17,29,30,45],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 学 biến thể (冖+⺍) + 見 (nhìn). Hán-Việt: GIÁC. Mẹo nhớ: Học (学) bằng cách nhìn (見) — 'giác' là nhớ, thức tỉnh 💡. 12 nét. Âm カク (kaku), おぼえる (oboeru) = nhớ/học thuộc. Liên kết: 覚える (nhớ), 覚ます (đánh thức). ⚠️ 覚える (oboeru-nhớ) vs 教える (oshieru-dạy) — thường đi cặp.","example":"新しい漢字を**覚**えました。 / atarashii kanji wo oboemashita. (Tôi đã nhớ được kanji mới)","examples":[{"ja":"新しい漢字を覚えました。","vi":"Tôi đã nhớ được kanji mới","romaji":"atarashii kanji wo oboemashita."},{"ja":"漢字を覚える","vi":"Nhớ Kanji","romaji":"Kanji wo oboeru"},{"ja":"日本の都道府県を覚える","vi":"Học các tỉnh thành của Nhật","romaji":"nippon no todoufuken o oboeru"},{"ja":"なかなか覚えられません。","vi":"Mãi không nhớ được.","romaji":"nakanaka oboe raremasen."}]},{"key":"k:号","kind":"kanji","level":"N4","character":"号","meaning":"Số, tín hiệu","hanviet":"Hiệu","onReadings":["ゴウ"],"kunReadings":["—"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"番号","reading":"ばんごう","meaning":"Số","vocabKey":"v:番号"},{"compound":"信号","reading":"しんごう","meaning":"Đèn tín hiệu","vocabKey":"v:信号"}],"lessonIds":[23,31,39,40],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 口 (miệng) + 丂 (biến thể). Hán-Việt: HIỆU. Mẹo nhớ: Miệng (口) hô to tín hiệu — 'hiệu' là số, tín hiệu 📯. 5 nét. Âm ゴウ (gou) trong 番号 (bangou - số), 信号 (shingou - đèn tín hiệu). Liên kết: 番号 (số), 信号 (đèn giao thông). ⚠️ 番号 = phiên hiệu = số — dùng cho số điện thoại, phòng.","example":"電話**番号**を教えてもらえませんか。 / denwa bangou wo oshiete moraemasen ka. (Bạn có thể cho tôi biết số điện thoại không?)","examples":[{"ja":"電話番号を教えてもらえませんか。","vi":"Bạn có thể cho tôi biết số điện thoại không?","romaji":"denwa bangou wo oshiete moraemasen ka."},{"ja":"信号が赤い","vi":"Đèn đỏ","romaji":"shingou ga akai"},{"ja":"信号機が青になった","vi":"Đèn giao thông chuyển xanh","romaji":"shingouki ga ao ni natsuta"},{"ja":"電話番号を教えてください","vi":"Cho tôi số điện thoại","romaji":"denwa bangou o oshiete kudasai"}]},{"key":"k:宿","kind":"kanji","level":"N4","character":"宿","meaning":"Nhà trọ, ở trọ","hanviet":"Túc","onReadings":["シュク"],"kunReadings":["やど"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"宿題","reading":"しゅくだい","meaning":"Bài tập về nhà","vocabKey":"v:宿題"},{"compound":"宿","reading":"やど","meaning":"Nhà trọ"}],"lessonIds":[6],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + 亻(người) + 百 (trăm). Hán-Việt: TÚC. Mẹo nhớ: Trăm (百) người (亻) dưới mái nhà (宀) — 'túc' là nhà trọ, ở trọ 🏨. 11 nét. Âm シュク (shuku) trong 宿題 (shukudai - bài tập về nhà), やど (yado) = nhà trọ. Liên kết: 宿題 (bài tập về nhà), 宿 (nhà trọ). ⚠️ 宿題 = túc đề = bài tập VỀ NHÀ — không phải bài tập ở trường.","example":"**宿**題を忘れないでください。 / shukudai wo wasurenaide kudasai. (Đừng quên bài tập về nhà.)","examples":[{"ja":"宿題を忘れないでください。","vi":"Đừng quên bài tập về nhà.","romaji":"shukudai wo wasurenaide kudasai."},{"ja":"宿題をする","vi":"Làm bài tập","romaji":"Shukudai wo suru"},{"ja":"宿題をします。","vi":"Làm bài tập về nhà.","romaji":"shukudai o shimasu."},{"ja":"もう宿題をしましたか。…はい、もうしました。","vi":"Đã làm bài tập chưa? …Vâng, làm rồi.","romaji":"mou shukudai o shimashita ka.... hai, moushimashita."}]},{"key":"k:利","kind":"kanji","level":"N4","character":"利","meaning":"Lợi, có ích","hanviet":"Lợi","onReadings":["リ"],"kunReadings":["き"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"便利","reading":"べんり","meaning":"Tiện lợi"},{"compound":"利用","reading":"りよう","meaning":"Sử dụng"}],"lessonIds":[8,36],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 禾 (lúa) + 刂 (dao). Hán-Việt: LỢI. Mẹo nhớ: Dùng dao (刂) cắt lúa (禾) thu hoạch — 'lợi' là có ích, lợi ích 🌾. 7 nét. Âm リ (ri) trong 便利 (benri - tiện lợi), 利用 (riyou - sử dụng). Liên kết: 便利 (tiện lợi), 利用 (sử dụng). ⚠️ 便利 = tiện lợi — tính từ -na rất hay dùng.","example":"この辞書はとても**便利**です。 / kono jisho wa totemo benri desu. (Quyển từ điển này rất tiện lợi)","examples":[{"ja":"この辞書はとても便利です。","vi":"Quyển từ điển này rất tiện lợi","romaji":"kono jisho wa totemo benri desu."},{"ja":"図書館を利用する","vi":"Sử dụng thư viện","romaji":"toshokan o riyou suru"},{"ja":"便利な道具","vi":"Công cụ tiện lợi","romaji":"benri na dougu"},{"ja":"この条件は有利です","vi":"Điều kiện này có lợi","romaji":"kono jouken wa yuuri desu"}]},{"key":"k:記","kind":"kanji","level":"N4","character":"記","meaning":"Ghi chép, ký","hanviet":"Ký","onReadings":["キ"],"kunReadings":["しる"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"日記","reading":"にっき","meaning":"Nhật ký","vocabKey":"v:日記"},{"compound":"暗記","reading":"あんき","meaning":"Thuộc lòng"},{"compound":"記事","reading":"きじ","meaning":"Bài báo","vocabKey":"v:記事"}],"lessonIds":[18],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 言 (lời nói) + 己 (kỷ/mình). Hán-Việt: KÝ. Mẹo nhớ: Lời (言) của mình (己) ghi lại — 'ký' là ghi chép ✍️. 10 nét. Âm キ (ki) trong 日記 (nikki - nhật ký), 暗記 (anki - thuộc lòng). Liên kết: 日記 (nhật ký), 暗記 (thuộc lòng). ⚠️ 記 vs 紀 — cùng đọc キ (ki) nhưng khác nghĩa: 記 = ghi, 紀 = kỷ nguyên.","example":"毎日**日記**を書いています。 / mainichi nikki wo kaite imasu. (Tôi viết nhật ký mỗi ngày)","examples":[{"ja":"毎日日記を書いています。","vi":"Tôi viết nhật ký mỗi ngày","romaji":"mainichi nikki wo kaite imasu."},{"ja":"毎日日記を書く","vi":"Viết nhật ký mỗi ngày","romaji":"Mainichi nikki wo kaku"},{"ja":"記事を書く","vi":"Viết bài báo","romaji":"Kiji wo kaku"},{"ja":"使用目的を明記する","vi":"Ghi rõ mục đích sử dụng","romaji":"shiyou mokuteki o meiki suru"}]},{"key":"k:卒","kind":"kanji","level":"N4","character":"卒","meaning":"Tốt nghiệp","hanviet":"Tốt","onReadings":["ソツ"],"kunReadings":["—"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"卒業","reading":"そつぎょう","meaning":"Tốt nghiệp","vocabKey":"v:卒業"}],"lessonIds":[31,46],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 亠 (đầu) + 从 (theo) + 十 (thập). Hán-Việt: TỐT (tốt nghiệp). Mẹo nhớ: Người theo (从) học đến cuối (十) — 'tốt' nghiệp, hoàn thành 🎓. 8 nét. Âm ソツ (sotsu) trong 卒業 (sotsugyou - tốt nghiệp). Liên kết: 卒業 (tốt nghiệp). ⚠️ 卒業 = tốt nghiệp — gần như chỉ dùng trong từ này.","example":"来年大学を**卒**業します。 / rainen daigaku wo sotsugyou shimasu. (Năm sau tôi tốt nghiệp đại học)","examples":[{"ja":"来年大学を卒業します。","vi":"Năm sau tôi tốt nghiệp đại học","romaji":"rainen daigaku wo sotsugyou shimasu."},{"ja":"大学を卒業する","vi":"Tốt nghiệp đại học","romaji":"daigaku o sotsugyou suru"},{"ja":"大学の卒業式","vi":"Lễ tốt nghiệp đại học","romaji":"daigaku no sotsugyoushiki"},{"ja":"卒業したら国へ帰ろうと思っています。","vi":"Sau khi tốt nghiệp, tôi định sẽ về nước.","romaji":"sotsugyou shi tara kuni e kaero u to omotsute imasu."}]},{"key":"k:授","kind":"kanji","level":"N4","character":"授","meaning":"Ban cho, dạy","hanviet":"Thụ","onReadings":["ジュ"],"kunReadings":["さず"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"授業","reading":"じゅぎょう","meaning":"Tiết học","vocabKey":"v:授業"},{"compound":"教授","reading":"きょうじゅ","meaning":"Giáo sư"}],"lessonIds":[30],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 扁(tay) + 受 (nhận). Hán-Việt: THỤ. Mẹo nhớ: Tay (扁) trao cho người nhận (受) — 'thụ' là ban cho, dạy 🤲. 11 nét. Âm ジュ (ju) trong 授業 (jugyou - tiết học), 教授 (kyouju - giáo sư). Liên kết: 授業 (tiết học), 教授 (giáo sư). ⚠️ 授 (thụ-ban cho) vs 受 (thụ-nhận) — cặp đôi trao/nhận.","example":"**授**業は9時に始まります。 / jugyou wa kuji ni hajimarimasu. (Tiết học bắt đầu lúc 9 giờ)","examples":[{"ja":"授業は9時に始まります。","vi":"Tiết học bắt đầu lúc 9 giờ","romaji":"jugyou wa 9ji ni hajimarimasu."},{"ja":"授業が始まる","vi":"Tiết học bắt đầu","romaji":"jugyou ga hajimaru"},{"ja":"授業を欠席した理由を書く","vi":"Viết lý do vắng buổi học","romaji":"jugyou o kesseki shita riyuu o kaku"},{"ja":"電車が遅れました。それで、授業に遅刻しました。","vi":"Tàu bị trễ. Vì thế, tôi đến lớp muộn.","romaji":"densha ga okuremashita. sorede, jugyou ni chikoku shimashita."}]},{"key":"k:要","kind":"kanji","level":"N4","character":"要","meaning":"Cần thiết, quan trọng","hanviet":"Yếu","onReadings":["ヨウ"],"kunReadings":["い"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"必要","reading":"ひつよう","meaning":"Cần thiết"},{"compound":"重要","reading":"じゅうよう","meaning":"Quan trọng"}],"lessonIds":[20,35,40],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 覀 (tay che mắt) + 女 (nữ). Hán-Việt: YẾU. Mẹo nhớ: Phụ nữ (女) che mắt (覀) tìm điều cần — 'yếu' là cần thiết, quan trọng ⚡. 9 nét. Âm ヨウ (you) trong 必要 (hitsuyou - cần thiết), 重要 (juuyou - quan trọng), いる (iru) = cần. Liên kết: 必要 (cần thiết), 重要 (quan trọng). ⚠️ 要る (iru-cần) vs いる (iru-có) — đọc giống nhau.","example":"このレポートはとても**重要**です。 / kono repooto wa totemo juuyou desu. (Bản báo cáo này rất quan trọng)","examples":[{"ja":"このレポートはとても重要です。","vi":"Bản báo cáo này rất quan trọng","romaji":"kono repooto wa totemo juuyou desu."},{"ja":"お金が要る","vi":"Cần tiền","romaji":"Okane ga iru"},{"ja":"必要な書類","vi":"Tài liệu cần thiết","romaji":"hitsuyou na shorui"},{"ja":"図書館で本を借りるとき、カードが要ります。","vi":"Khi mượn sách ở thư viện thì cần phải có thẻ.","romaji":"toshokan de hon o kariru toki, kaado ga irimasu."}]},{"key":"k:死","kind":"kanji","level":"N4","character":"死","meaning":"Chết","hanviet":"Tử","onReadings":["シ"],"kunReadings":["し"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"死ぬ","reading":"しぬ","meaning":"Chết","vocabKey":"v:死ぬ"},{"compound":"必死","reading":"ひっし","meaning":"Liều mạng"}],"lessonIds":[39],"topicTags":[],"sectionId":20,"sectionName":"THIẾU SÓT QUAN TRỌNG CHO N4","mnemonic":"Bộ/thành phần: 歹 (chết/xương) + 匕 (thìa/biến thể). Hán-Việt: TỬ. Mẹo nhớ: Xương tàn (歹) với người gục xuống (匕) — 'tử' là chết ☠️. 6 nét. Âm シ (shi), しぬ (shinu) = chết. Liên kết: 死ぬ (chết), 必死 (hisshi - liều mạng). ⚠️ 死ぬ là động từ nhóm 1 duy nhất kết thúc bằng ～ぬ.","example":"この花は水がないと**死**んでしまいます。 / kono hana wa mizu ga naito shinde shimaimasu. (Bông hoa này không có nước sẽ chết mất)","examples":[{"ja":"この花は水がないと死んでしまいます。","vi":"Bông hoa này không có nước sẽ chết mất","romaji":"kono hana wa mizu ga naito shinde shimaimasu."},{"ja":"犬が死んでしまった","vi":"Con chó đã chết mất","romaji":"inu ga shinde shimatsuta"},{"ja":"死にます","vi":"chết","romaji":"shinimasu"}]},{"key":"k:太","kind":"kanji","level":"N4","character":"太","meaning":"To, béo, dày","hanviet":"Thái","onReadings":["タイ","タ"],"kunReadings":["ふと"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"太い","reading":"ふとい","meaning":"To","vocabKey":"v:太い"},{"compound":"太陽","reading":"たいよう","meaning":"Mặt trời","vocabKey":"v:太陽"},{"compound":"丈夫","reading":"じょうぶ","meaning":"Chắc chắn"}],"lessonIds":[32,39,41,44],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 大 (lớn) + 丶 (nét chấm). Hán-Việt: THÁI. Mẹo nhớ: Lớn (大) thêm chấm (丶) — to hơn, 'thái' là to, béo, dày 🐷. 4 nét. Âm タイ (tai) trong 太陽 (taiyou - mặt trời), ふとい (futoi) = to/béo. Liên kết: 太い (to/béo), 太陽 (mặt trời). ⚠️ 太 (thái-to) vs 大 (đại-lớn) — khác 1 chấm!","example":"この木は**太**いです。 / kono ki wa futoi desu. (Cái cây này to.)","examples":[{"ja":"この木は太いです。","vi":"Cái cây này to.","romaji":"kono ki wa futoi desu."},{"ja":"最近太った","vi":"Gần đây béo lên","romaji":"Saikin futotsuta"},{"ja":"木が太い","vi":"Cây to","romaji":"Ki ga futoi"},{"ja":"太陽が出る","vi":"Mặt trời mọc","romaji":"taiyou ga deru"}]},{"key":"k:細","kind":"kanji","level":"N4","character":"細","meaning":"Nhỏ, mảnh, chi tiết","hanviet":"Tế","onReadings":["サイ"],"kunReadings":["ほそ","こま"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"細い","reading":"ほそい","meaning":"Mảnh","vocabKey":"v:細い"},{"compound":"細かい","reading":"こまかい","meaning":"Chi tiết"}],"lessonIds":[9,44,49],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 糸 (sợi tơ) + 田 (ruộng). Hán-Việt: TẾ. Mẹo nhớ: Sợi tơ (糸) mảnh trong ruộng (田) — 'tế' là nhỏ, mảnh, chi tiết 🧵. 11 nét. Âm サイ (sai), ほそい (hosoi) = mảnh/gầy, こまかい (komakai) = chi tiết. Liên kết: 細い (mảnh), 細かい (chi tiết). ⚠️ 細い (hosoi-mảnh) vs 小さい (chiisai-nhỏ) — khác nghĩa.","example":"この道は**細**いです。 / kono michi wa hosoi desu. (Con đường này hẹp.)","examples":[{"ja":"この道は細いです。","vi":"Con đường này hẹp.","romaji":"kono michi wa hosoi desu."},{"ja":"細い道","vi":"Đường hẹp","romaji":"Hosoi michi"},{"ja":"このコップは細すぎて、洗いにくいです。","vi":"Cái cốc này quá nhỏ và dài nên khó rửa.","romaji":"kono koppu wa hoso sugite, arai nikui desu."},{"ja":"細かい お金","vi":"tiền lẻ","romaji":"komakai okane"}]},{"key":"k:暖","kind":"kanji","level":"N4","character":"暖","meaning":"Ấm áp","hanviet":"Noãn","onReadings":["ダン"],"kunReadings":["あたた","あたた"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"暖かい","reading":"あたたかい","meaning":"Ấm áp","vocabKey":"v:暖かい"},{"compound":"暖房","reading":"だんぼう","meaning":"Sưởi ấm","vocabKey":"v:暖房"}],"lessonIds":[12,41],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 爰 (viện/biến thể). Hán-Việt: NOÃN. Mẹo nhớ: Mặt trời (日) sưởi ấm — 'noãn' là ấm áp ☀️🧣. 13 nét. Âm ダン (dan) trong 暖房 (danbou - sưởi ấm), あたたかい (atatakai) = ấm áp. Liên kết: 暖かい (ấm áp), 暖房 (sưởi ấm). ⚠️ 暖かい vs 温かい — cùng đọc あたたかい nhưng: 暖 = ấm thời tiết, 温 = ấm nước/tình cảm.","example":"今日は**暖**かいですね。 / kyou wa atatakai desu ne. (Hôm nay ấm nhỉ.)","examples":[{"ja":"今日は暖かいですね。","vi":"Hôm nay ấm nhỉ.","romaji":"kyou wa atatakai desu ne."},{"ja":"今日は暖かい","vi":"Hôm nay ấm áp","romaji":"kyou wa atatakai"},{"ja":"風邪を引かないように、暖かい服を着てください。","vi":"Để không bị cảm, hãy mặc áo ấm.","romaji":"kaze o hikanai you ni, atatakai fuku o kite kudasai."},{"ja":"春と秋、どちらの暖かさが好きですか。","vi":"Mùa xuân và mùa thu, bạn thích sự ấm áp của mùa nào?","romaji":"haru to aki, dochira no atatakasa ga suki desu ka."}]},{"key":"k:涼","kind":"kanji","level":"N4","character":"涼","meaning":"Mát mẻ","hanviet":"Lương","onReadings":["リョウ"],"kunReadings":["すず"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"涼しい","reading":"すずしい","meaning":"Mát mẻ","vocabKey":"v:涼しい"}],"lessonIds":[12],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 氵(nước) + 京 (kinh/kinh đô). Hán-Việt: LƯƠNG. Mẹo nhớ: Nước (氵) mát từ kinh đô (京) — 'lương' là mát mẻ 🌬️. 11 nét. Âm リョウ (ryou), すずしい (suzushii) = mát mẻ. Liên kết: 涼しい (mát mẻ). ⚠️ 涼しい (suzushii-mát) — chỉ dùng cho thời tiết/không gian.","example":"秋は**涼**しくて気持ちいいです。 / aki wa suzushikute kimochi ii desu. (Mùa thu mát mẻ rất dễ chịu.)","examples":[{"ja":"秋は涼しくて気持ちいいです。","vi":"Mùa thu mát mẻ rất dễ chịu.","romaji":"aki wa suzushikute kimochi ii desu."},{"ja":"秋は涼しい","vi":"Mùa thu mát","romaji":"Aki wa suzushii"}]},{"key":"k:痛","kind":"kanji","level":"N4","character":"痛","meaning":"Đau","hanviet":"Thống","onReadings":["ツウ"],"kunReadings":["いた","いた"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"痛い","reading":"いたい","meaning":"Đau","vocabKey":"v:痛い"},{"compound":"頭痛","reading":"ずつう","meaning":"Đau đầu","vocabKey":"v:頭痛"},{"compound":"腹痛","reading":"ふくつう","meaning":"Đau bụng"}],"lessonIds":[17],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 疒 (bệnh) + 甬 (dũng). Hán-Việt: THỐNG. Mẹo nhớ: Bị bệnh (疒) đau nhức — 'thống' là đau 🤕. 12 nét. Âm ツウ (tsuu), いたい (itai) = đau. Liên kết: 痛い (đau), 頭痛 (đau đầu), 腹痛 (đau bụng). ⚠️ 疒 (bệnh) là bộ thủ — xuất hiện trong nhiều kanji bệnh: 病, 痛, 症.","example":"お腹が**痛**いので、薬を飲みました。 / onaka ga itai node, kusuri wo nomimashita. (Vì đau bụng nên tôi đã uống thuốc.)","examples":[{"ja":"お腹が痛いので、薬を飲みました。","vi":"Vì đau bụng nên tôi đã uống thuốc.","romaji":"onaka ga itai node, kusuri wo nomimashita."},{"ja":"頭が痛い","vi":"Đau đầu","romaji":"Atama ga itai"},{"ja":"頭痛がする","vi":"Bị đau đầu","romaji":"zutsuu ga suru"},{"ja":"頭が痛いんです。","vi":"Tôi bị đau đầu.","romaji":"atama ga itai n desu."}]},{"key":"k:首","kind":"kanji","level":"N4","character":"首","meaning":"Cổ, đầu","hanviet":"Thủ","onReadings":["シュ"],"kunReadings":["くび"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"首","reading":"くび","meaning":"Cổ","vocabKey":"v:首"},{"compound":"首相","reading":"しゅしょう","meaning":"Thủ tướng","vocabKey":"v:首相"}],"lessonIds":[21,39],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 首 là chữ tượng hình — hình cái đầu với tóc phía trên. Hán-Việt: THỦ. Mẹo nhớ: Đầu người với mái tóc — 'thủ' là cổ, đầu 🦒. 9 nét. Âm シュ (shu) trong 首相 (shushou - thủ tướng), くび (kubi) = cổ. Liên kết: 首 (cổ), 首相 (thủ tướng). ⚠️ 首 vừa là 'cổ' (kun) vừa là 'đầu/thủ' (on).","example":"昨日から**首**が痛くて、右を向きにくいです。 / kinou kara kubi ga itakute, migi wo mukinikui desu. (Từ hôm qua cổ tôi đau nên khó quay sang phải.)","examples":[{"ja":"昨日から首が痛くて、右を向きにくいです。","vi":"Từ hôm qua cổ tôi đau nên khó quay sang phải.","romaji":"kinou kara kubi ga itakute, migi wo mukinikui desu."},{"ja":"首が痛い","vi":"Đau cổ","romaji":"Kubi ga itai"},{"ja":"首相","vi":"thủ tướng","romaji":"shushou"}]},{"key":"k:歯","kind":"kanji","level":"N4","character":"歯","meaning":"Răng","hanviet":"Xỉ","onReadings":["シ"],"kunReadings":["は"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"歯","reading":"は","meaning":"Răng","vocabKey":"v:歯"},{"compound":"歯医者","reading":"はいしゃ","meaning":"Nha sĩ","vocabKey":"v:歯医者"},{"compound":"虫歯","reading":"むしば","meaning":"Sâu răng"}],"lessonIds":[15,16,35],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 止 (dừng) + 米 (gạo) biến thể trong 凵 (khung). Hán-Việt: XỈ. Mẹo nhớ: Răng dùng để nghiền gạo (米) — 'xỉ' là răng 🦷. 12 nét. Âm シ (shi), は (ha) = răng. Liên kết: 歯 (răng), 歯医者 (haisha - nha sĩ), 虫歯 (mushiba - sâu răng). ⚠️ 歯医者 (haisha) = nha sĩ — từ ghép quan trọng.","example":"寝る前に必ず**歯**を磨いてから寝ます。 / neru mae ni kanarazu ha wo migaite kara nemasu. (Trước khi ngủ tôi luôn đánh răng rồi mới đi ngủ.)","examples":[{"ja":"寝る前に必ず歯を磨いてから寝ます。","vi":"Trước khi ngủ tôi luôn đánh răng rồi mới đi ngủ.","romaji":"neru mae ni kanarazu ha wo migaite kara nemasu."},{"ja":"歯ブラシで磨く","vi":"Đánh răng bằng bàn chải","romaji":"Haburashi de migaku"},{"ja":"歯を磨く","vi":"Đánh răng","romaji":"Ha wo migaku"},{"ja":"歯医者に行く","vi":"Đi nha sĩ","romaji":"Haisha ni iku"}]},{"key":"k:違","kind":"kanji","level":"N4","character":"違","meaning":"Khác, sai","hanviet":"Vi","onReadings":["イ"],"kunReadings":["ちが","ちが"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"違う","reading":"ちがう","meaning":"Khác nhau","vocabKey":"v:違う"},{"compound":"違い","reading":"ちがい","meaning":"Sự khác biệt"},{"compound":"間違い","reading":"まちがい","meaning":"Lỗi sai"}],"lessonIds":[26,28,33,36],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 辶 (đi) + 韋 (vi/da thuộc). Hán-Việt: VI (trái, sai). Mẹo nhớ: Đi (辶) sai đường, trái (韋) — 'vi' là khác, sai ❌. 13 nét. Âm イ (i), ちがう (chigau) = khác nhau. Liên kết: 違う (khác), 違い (sự khác biệt), 間違い (lỗi sai). ⚠️ 間違い (machigai) = lỗi sai — từ rất phổ biến.","example":"その説明は少し**違**うと思います。もう一度確認しましょう。 / sono setsumei wa sukoshi chigau to omoimasu. mou ichido kakunin shimashou. (Tôi nghĩ phần giải thích đó hơi sai, mình kiểm tra lại một lần nữa nhé.)","examples":[{"ja":"その説明は少し違うと思います。もう一度確認しましょう。","vi":"Tôi nghĩ phần giải thích đó hơi sai, mình kiểm tra lại một lần nữa nhé.","romaji":"sono setsumei wa sukoshi chigau to omoimasu. mou ichido kakunin shimashou."},{"ja":"答えが違う","vi":"Đáp án sai","romaji":"Kotae ga chigau"},{"ja":"道を間違える","vi":"Nhầm đường","romaji":"Michi wo machigaeru"},{"ja":"理想と現実は違う","vi":"Lý tưởng và hiện thực khác nhau","romaji":"risou to genjitsu wa chigau"}]},{"key":"k:渡","kind":"kanji","level":"N4","character":"渡","meaning":"Đi qua, đưa cho","hanviet":"Độ","onReadings":["ト"],"kunReadings":["わた","わた"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"渡る","reading":"わたる","meaning":"Qua (sông / đường)","vocabKey":"v:渡る"},{"compound":"渡す","reading":"わたす","meaning":"Đưa cho","vocabKey":"v:渡す"}],"lessonIds":[23,46],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 氵(nước) + 度 (độ/mức). Hán-Việt: ĐỘ. Mẹo nhớ: Qua nước (氵) từng mức (度) — 'độ' là đi qua, đưa cho 🚶‍♂️🌊. 12 nét. Âm ト (to), わたる (wataru) = qua sông/đường, わたす (watasu) = đưa cho. Liên kết: 渡る (qua), 渡す (đưa cho). ⚠️ 渡る (wataru-qua) vs 渡す (watasu-đưa) — tự/tha động từ.","example":"青信号になってから道を**渡**ってください。 / ao shingou ni natte kara michi wo watatte kudasai. (Hãy sang đường sau khi đèn chuyển xanh.)","examples":[{"ja":"青信号になってから道を渡ってください。","vi":"Hãy sang đường sau khi đèn chuyển xanh.","romaji":"aoshingou ni natsute kara michi o watatsute kudasai."},{"ja":"手紙を渡す","vi":"Đưa thư","romaji":"Tegami wo watasu"},{"ja":"橋を渡る","vi":"Qua cầu","romaji":"Hashi wo wataru"},{"ja":"渡ります [橋を~]","vi":"qua, đi qua [cầu]","romaji":"watarimasu [kyou o ~]"}]},{"key":"k:落","kind":"kanji","level":"N4","character":"落","meaning":"Rơi, rớt","hanviet":"Lạc","onReadings":["ラク"],"kunReadings":["お","お"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"落ちる","reading":"おちる","meaning":"Rơi","vocabKey":"v:落ちる"},{"compound":"落とす","reading":"おとす","meaning":"Làm rơi","vocabKey":"v:落とす"}],"lessonIds":[29,43],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 艹 (cỏ) + 洛 (lạc). Hán-Việt: LẠC. Mẹo nhớ: Cỏ (艹) rơi xuống nước (洛) — 'lạc' là rơi, rớt 🍂. 12 nét. Âm ラク (raku), おちる (ochiru) = rơi, おとす (otosu) = làm rơi. Liên kết: 落ちる (rơi), 落とす (làm rơi). ⚠️ 落ちる (ochiru-tự rơi) vs 落とす (otosu-làm rơi) — cặp tự/tha.","example":"駅で財布を**落**としてしまって、とても困りました。 / eki de saifu wo otoshite shimatte, totemo komarimashita. (Tôi làm rơi ví ở ga nên rất bối rối.)","examples":[{"ja":"駅で財布を落としてしまって、とても困りました。","vi":"Tôi làm rơi ví ở ga nên rất bối rối.","romaji":"eki de saifu o otoshite shimatsute, totemo komarimashita."},{"ja":"財布を落とす","vi":"Làm rơi ví","romaji":"Saifu wo otosu"},{"ja":"木から落ちる","vi":"Rơi từ cây","romaji":"Ki kara ochiru"},{"ja":"りんごがテーブルから落ちました。 私が財布を落としました。","vi":"Quả táo đã rơi khỏi bàn. Tôi đã đánh rơi ví.","romaji":"ringo ga teeburu kara ochimashita. watashi ga saifu o otoshimashita."}]},{"key":"k:押","kind":"kanji","level":"N4","character":"押","meaning":"Đẩy, nhấn","hanviet":"Áp","onReadings":["オウ"],"kunReadings":["お"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"押す","reading":"おす","meaning":"Nhấn","vocabKey":"v:押す"},{"compound":"押し入れ","reading":"おしいれ","meaning":"Tủ âm tường","vocabKey":"v:押し入れ"}],"lessonIds":[16,22],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 扁(tay) + 甲 (giáp). Hán-Việt: ÁP. Mẹo nhớ: Tay (扁) đè lên giáp (甲) — 'áp' là đẩy, nhấn 👋. 8 nét. Âm オウ (ou), おす (osu) = nhấn/đẩy. Liên kết: 押す (nhấn), 押し入れ (oshiire - tủ âm tường). ⚠️ 押す (osu-nhấn) vs 引く (hiku-kéo) — cặp đối lập.","example":"ドアが開かない時は、このボタンを**押**してください。 / doa ga akanai toki wa, kono botan wo oshite kudasai. (Khi cửa không mở, hãy nhấn nút này.)","examples":[{"ja":"ドアが開かない時は、このボタンを押してください。","vi":"Khi cửa không mở, hãy nhấn nút này.","romaji":"doa ga hirakanai toki wa, kono botan o oshite kudasai."},{"ja":"ボタンを押す","vi":"Nhấn nút","romaji":"Botan wo osu"},{"ja":"布団を押入れにしまう","vi":"Cất nệm vào tủ","romaji":"futon o oshiire ni shimau"},{"ja":"このボタンを押すと、お釣りが出ます。","vi":"Hễ bấm nút này thì tiền thừa sẽ chạy ra.","romaji":"kono botan o osu to, otsuri ga demasu."}]},{"key":"k:捨","kind":"kanji","level":"N4","character":"捨","meaning":"Vứt bỏ","hanviet":"Xả","onReadings":["シャ"],"kunReadings":["す"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"捨てる","reading":"すてる","meaning":"Vứt bỏ","vocabKey":"v:捨てる"}],"lessonIds":[18],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 扁(tay) + 舍 (xá/nhà). Hán-Việt: XẢ. Mẹo nhớ: Tay (扁) ném ra khỏi nhà (舍) — 'xả' là vứt bỏ 🗑️. 11 nét. Âm シャ (sha), すてる (suteru) = vứt bỏ. Liên kết: 捨てる (vứt bỏ). ⚠️ 捨てる là ichidan (nhóm 2) — て形: 捨てて.","example":"分別してから、ゴミをここに**捨**ててください。 / bunbetsu shite kara, gomi wo koko ni sutete kudasai. (Hãy phân loại rồi mới vứt rác vào đây.)","examples":[{"ja":"分別してから、ゴミをここに捨ててください。","vi":"Hãy phân loại rồi mới vứt rác vào đây.","romaji":"funbetsu shite kara, gomi o koko ni sutete kudasai."},{"ja":"ゴミを捨てる","vi":"Vứt rác","romaji":"Gomi wo suteru"},{"ja":"捨てます","vi":"vứt, bỏ","romaji":"sutemasu"}]},{"key":"k:拾","kind":"kanji","level":"N4","character":"拾","meaning":"Nhặt lên","hanviet":"Thập","onReadings":["シュウ","ジュウ"],"kunReadings":["ひろ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"拾う","reading":"ひろう","meaning":"Nhặt lên","vocabKey":"v:拾う"}],"lessonIds":[26],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 扁(tay) + 合 (hợp/gặp). Hán-Việt: THẬP. Mẹo nhớ: Tay (扁) gom lại (合) — 'thập' là nhặt lên 🤲. 9 nét. Âm シュウ (shuu), ひろう (hirou) = nhặt lên. Liên kết: 拾う (nhặt lên). ⚠️ 拾う (hirou) vs 捨てる (suteru) — cặp đối lập: nhặt lên/vứt đi.","example":"道で財布を**拾**ったので、交番に届けました。 / michi de saifu wo hirotta node, kouban ni todokemashita. (Tôi nhặt được ví trên đường nên đã mang đến đồn cảnh sát.)","examples":[{"ja":"道で財布を拾ったので、交番に届けました。","vi":"Tôi nhặt được ví trên đường nên đã mang đến đồn cảnh sát.","romaji":"michi de saifu o hirotsuta node, kouban ni todokemashita."},{"ja":"ゴミを拾う","vi":"Nhặt rác","romaji":"gomi o hirou"},{"ja":"拾います","vi":"nhặt, lượm","romaji":"hiroimasu"}]},{"key":"k:育","kind":"kanji","level":"N4","character":"育","meaning":"Nuôi dưỡng, phát triển","hanviet":"Dục","onReadings":["イク"],"kunReadings":["そだ","そだ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"教育","reading":"きょういく","meaning":"Giáo dục","vocabKey":"v:教育"},{"compound":"育てる","reading":"そだてる","meaning":"Nuôi dưỡng","vocabKey":"v:育てる"}],"lessonIds":[28,38,42],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 月 (thịt/cơ thể) + 子 biến thể (trên). Hán-Việt: DỤC. Mẹo nhớ: Con (子) lớn lên bằng thể xác (月) — 'dục' là nuôi dưỡng, phát triển 🌱. 8 nét. Âm イク (iku) trong 教育 (kyouiku - giáo dục), そだてる (sodateru) = nuôi dưỡng. Liên kết: 教育 (giáo dục), 育てる (nuôi dưỡng). ⚠️ 教育 = giáo dục — từ ghép quan trọng.","example":"母はベランダでハーブを**育**てるのが好きです。 / haha wa beranda de haabu wo sodateru no ga suki desu. (Mẹ tôi thích trồng thảo mộc ở ban công.)","examples":[{"ja":"母はベランダでハーブを育てるのが好きです。","vi":"Mẹ tôi thích trồng thảo mộc ở ban công.","romaji":"haha wa beranda de haabu wo sodateru no ga suki desu."},{"ja":"この子はすくすく育っています","vi":"Đứa trẻ đang lớn lên","romaji":"Kono ko wa sukusuku sodatsuteimasu"},{"ja":"子供を育てる","vi":"Nuôi con","romaji":"Kodomo wo sodateru"},{"ja":"子育ては大変だ","vi":"Nuôi con rất vất vả","romaji":"Kosodate wa taihen da"}]},{"key":"k:伝","kind":"kanji","level":"N4","character":"伝","meaning":"Truyền đạt","hanviet":"Truyền","onReadings":["デン"],"kunReadings":["つた","つた"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"伝える","reading":"つたえる","meaning":"Truyền đạt","vocabKey":"v:伝える"},{"compound":"手伝う","reading":"てつだう","meaning":"Giúp đỡ","vocabKey":"v:手伝う"}],"lessonIds":[14,33,37,49],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 亻(người) + 云 (vân/nói). Hán-Việt: TRUYỀN. Mẹo nhớ: Người (亻) nói (云) truyền miệng — 'truyền' là truyền đạt 📢. 6 nét. Âm デン (den), つたえる (tsutaeru) = truyền đạt. Liên kết: 伝える (truyền đạt), 手伝う (tetsudau - giúp đỡ). ⚠️ 手伝う (tetsudau-giúp đỡ) — đọc đặc biệt, cần nhớ.","example":"会議の時間が変わったことを、みんなに**伝**えてください。 / kaigi no jikan ga kawatta koto wo, minna ni tsutaete kudasai. (Hãy thông báo cho mọi người rằng giờ họp đã thay đổi.)","examples":[{"ja":"会議の時間が変わったことを、みんなに伝えてください。","vi":"Hãy thông báo cho mọi người rằng giờ họp đã thay đổi.","romaji":"kaigi no jikan ga kawatsuta koto o, minna ni tsutaete kudasai."},{"ja":"母を手伝う","vi":"Phụ giúp mẹ","romaji":"Haha wo tetsudau"},{"ja":"気持ちを伝える","vi":"Truyền đạt tâm trạng","romaji":"Kimochi wo tsutaeru"},{"ja":"日本の伝統文化を学ぶ","vi":"Học văn hóa truyền thống Nhật","romaji":"nippon no dentou bunka o manabu"}]},{"key":"k:絵","kind":"kanji","level":"N4","character":"絵","meaning":"Bức tranh, hình vẽ","hanviet":"Hội","onReadings":["カイ","エ"],"kunReadings":["—"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"絵","reading":"え","meaning":"Bức tranh","vocabKey":"v:絵"},{"compound":"絵本","reading":"えほん","meaning":"Sách tranh","vocabKey":"v:絵本"}],"lessonIds":[9,41],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 糸 (sợi tơ) + 会 (hội/gặp). Hán-Việt: HỘI. Mẹo nhớ: Tơ (糸) dệt thành hình khi gặp (会) — 'hội' là bức tranh 🎨. 12 nét. Âm カイ (kai), エ (e) = tranh. Liên kết: 絵 (tranh), 絵本 (ehon - sách tranh). ⚠️ 絵 thường dùng âm え (e) — 絵を描く (e wo kaku - vẽ tranh).","example":"子どもが動物の**絵**を楽しそうに描いています。 / kodomo ga doubutsu no e wo tanoshisou ni kaite imasu. (Đứa trẻ đang vui vẻ vẽ tranh con vật.)","examples":[{"ja":"子どもが動物の絵を楽しそうに描いています。","vi":"Đứa trẻ đang vui vẻ vẽ tranh con vật.","romaji":"kodomo ga doubutsu no e o tanoshisou ni egaite imasu."},{"ja":"絵を描く","vi":"Vẽ tranh","romaji":"E wo egaku"},{"ja":"田中さんは絵は上手です。","vi":"Anh Tanaka vẽ giỏi.","romaji":"tanaka san wa e wa jouzu desu."},{"ja":"私は絵を描くのが好きです。","vi":"Tôi thích vẽ tranh.","romaji":"watashi wa e o egaku no ga suki desu."}]},{"key":"k:窓","kind":"kanji","level":"N4","character":"窓","meaning":"Cửa sổ","hanviet":"Song","onReadings":["ソウ"],"kunReadings":["まど"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"窓","reading":"まど","meaning":"Cửa sổ","vocabKey":"v:窓"},{"compound":"窓口","reading":"まどぐち","meaning":"Quầy giao dịch","vocabKey":"v:窓口"}],"lessonIds":[10],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 穴 (lỗ/hang) + 心 (tim) + 厶 (tư). Hán-Việt: SONG. Mẹo nhớ: Lỗ (穴) trên tường cho tâm hồn (心) nhìn ra — 'song' là cửa sổ 🪟. 11 nét. Âm ソウ (sou), まど (mado) = cửa sổ. Liên kết: 窓 (cửa sổ), 窓口 (madoguchi - quầy giao dịch). ⚠️ 窓口 = cửa sổ + miệng = quầy giao dịch — nghĩa mở rộng.","example":"暑いので、少し**窓**を開けてもいいですか。 / atsui node, sukoshi mado wo aketemo ii desu ka. (Vì nóng nên tôi mở cửa sổ một chút được không?)","examples":[{"ja":"暑いので、少し窓を開けてもいいですか。","vi":"Vì nóng nên tôi mở cửa sổ một chút được không?","romaji":"atsui node, sukoshi mado wo aketemo ii desu ka."},{"ja":"窓口で切符を買う","vi":"Mua vé ở quầy","romaji":"Madoguchi de kippu wo kau"},{"ja":"窓を開ける","vi":"Mở cửa sổ","romaji":"Mado wo akeru"},{"ja":"暑いですから、窓を開けてください。","vi":"Vì nóng nên hãy mở cửa sổ.","romaji":"atsui desu kara, mado o akete kudasai."}]},{"key":"k:彼","kind":"kanji","level":"N4","character":"彼","meaning":"Anh ấy, đó","hanviet":"Bỉ","onReadings":["ヒ"],"kunReadings":["かれ","かの"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"彼","reading":"かれ","meaning":"Anh ấy","vocabKey":"v:彼"},{"compound":"彼女","reading":"かのじょ","meaning":"Cô ấy","vocabKey":"v:彼女"}],"lessonIds":[5],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 彳 (bước đi) + 皮 (da/bì). Hán-Việt: BỈ. Mẹo nhớ: Người bước đi (彳) khoác da (皮) — 'bỉ' là anh ấy, người đó 👤. 8 nét. Âm ヒ (hi), かれ (kare) = anh ấy. Liên kết: 彼 (anh ấy), 彼女 (kanojo - cô ấy/bạn gái). ⚠️ 彼女 đọc かのじょ (kanojo) = cô ấy HOẶC bạn gái.","example":"**彼**は困っている人を見ると、すぐに助けてくれます。 / kare wa komatte iru hito wo miru to, sugu ni tasukete kuremasu. (Anh ấy thấy ai gặp khó khăn là giúp ngay.)","examples":[{"ja":"彼は困っている人を見ると、すぐに助けてくれます。","vi":"Anh ấy thấy ai gặp khó khăn là giúp ngay.","romaji":"kare wa komatsute iru hito o miru to, sugu ni tasukete kuremasu."},{"ja":"彼は日本人だ","vi":"Anh ấy là người Nhật","romaji":"kare wa nipponjin da"},{"ja":"彼女は学生だ","vi":"Cô ấy là sinh viên","romaji":"Kanojo wa gakusei da"},{"ja":"彼女はピアノは上手ですが、歌は下手です。","vi":"Cô ấy đàn piano giỏi nhưng hát thì dở.","romaji":"kanojo wa piano wa jouzu desu ga, uta wa heta desu."}]},{"key":"k:指","kind":"kanji","level":"N4","character":"指","meaning":"Ngón tay, chỉ","hanviet":"Chỉ","onReadings":["シ"],"kunReadings":["ゆび","さ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"指","reading":"ゆび","meaning":"Ngón tay","vocabKey":"v:指"},{"compound":"指輪","reading":"ゆびわ","meaning":"Nhẫn","vocabKey":"v:指輪"}],"lessonIds":[29,38,49],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 扁(tay) + 旨 (chỉ/mục đích). Hán-Việt: CHỈ. Mẹo nhớ: Tay (扁) chỉ đến mục đích (旨) — 'chỉ' là ngón tay, chỉ ☝️. 9 nét. Âm シ (shi), ゆび (yubi) = ngón tay, さす (sasu) = chỉ. Liên kết: 指 (ngón tay), 指輪 (yubiwa - nhẫn). ⚠️ 指輪 = chỉ luân = nhẫn đeo tay.","example":"料理中に包丁で**指**を切ってしまいました。 / ryourichuu ni houchou de yubi wo kitte shimaimashita. (Lúc nấu ăn tôi lỡ cắt vào ngón tay.)","examples":[{"ja":"料理中に包丁で指を切ってしまいました。","vi":"Lúc nấu ăn tôi lỡ cắt vào ngón tay.","romaji":"ryourichuu ni houchou de yubi o kitsute shimaimashita."},{"ja":"指輪をはめる","vi":"Đeo nhẫn","romaji":"yubiwa o hameru"},{"ja":"指を切った","vi":"Bị cắt ngón tay","romaji":"yubi o kitsuta"},{"ja":"指します","vi":"chỉ","romaji":"sashimasu"}]},{"key":"k:末","kind":"kanji","level":"N4","character":"末","meaning":"Cuối cùng","hanviet":"Mạt","onReadings":["マツ","バツ"],"kunReadings":["すえ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"週末","reading":"しゅうまつ","meaning":"Cuối tuần","vocabKey":"v:週末"},{"compound":"月末","reading":"げつまつ","meaning":"Cuối tháng"},{"compound":"年末","reading":"ねんまつ","meaning":"Cuối năm","vocabKey":"v:年末"}],"lessonIds":[13],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 木 (cây) + 一 (nhất) trên ngọn. Hán-Việt: MẠT. Mẹo nhớ: Ngọn cây (木) với gạch trên (一) — 'mạt' là cuối cùng, chót 📅. 5 nét. Âm マツ (matsu) trong 週末 (shuumatsu - cuối tuần), すえ (sue) = cuối. Liên kết: 週末 (cuối tuần), 月末 (cuối tháng), 年末 (cuối năm). ⚠️ 末 vs 未 — 末 nét ngang trên DÀI hơn = cuối; 未 nét ngang trên NGẮN hơn = chưa.","example":"**週末**は図書館で勉強してから、友達と映画を見ます。 / shuumatsu wa toshokan de benkyou shite kara, tomodachi to eiga wo mimasu. (Cuối tuần tôi học ở thư viện rồi đi xem phim với bạn.)","examples":[{"ja":"週末は図書館で勉強してから、友達と映画を見ます。","vi":"Cuối tuần tôi học ở thư viện rồi đi xem phim với bạn.","romaji":"shuumatsu wa toshokan de benkyou shite kara, tomodachi to eiga wo mimasu."},{"ja":"年末はいつも忙しい","vi":"Cuối năm lúc nào cũng bận","romaji":"Nenmatsu wa itsumo isogashii"},{"ja":"週末何をしますか。","vi":"Cuối tuần bạn làm gì?","romaji":"shuumatsu nani o shimasu ka."},{"ja":"週末は買い物したり、料理したりします。","vi":"Cuối tuần tôi mua sắm, nấu ăn v.v.","romaji":"shuumatsu wa kaimono shi tari, ryouri shi tari shimasu."}]},{"key":"k:当","kind":"kanji","level":"N4","character":"当","meaning":"Trúng, đúng, phải","hanviet":"Đương","onReadings":["トウ"],"kunReadings":["あ","あ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"本当","reading":"ほんとう","meaning":"Thật sự"},{"compound":"当たる","reading":"あたる","meaning":"Trúng"}],"lessonIds":[22,32,34],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: biến thể của 尚. Hán-Việt: ĐƯƠNG. Mẹo nhớ: Chỉ đúng mục tiêu — 'đương' là trúng, đúng, phải 🎯. 6 nét. Âm トウ (tou) trong 本当 (hontou - thật sự), あたる (ataru) = trúng. Liên kết: 本当 (thật sự), 当たる (trúng). ⚠️ 本当 (hontou) = thật sự — cực kỳ phổ biến trong hội thoại.","example":"それは**本当**ですか。もう一度確認してもいいですか。 / sore wa hontou desu ka. mou ichido kakunin shite mo ii desu ka. (Điều đó có thật không? Tôi xác nhận lại một lần nữa được chứ?)","examples":[{"ja":"それは本当ですか。もう一度確認してもいいですか。","vi":"Điều đó có thật không? Tôi xác nhận lại một lần nữa được chứ?","romaji":"sore wa hontou desu ka. mou ichido kakunin shite mo ii desu ka."},{"ja":"適当な答え","vi":"Câu trả lời phù hợp","romaji":"tekitou na kotae"},{"ja":"弁当を作る","vi":"Làm cơm hộp","romaji":"bentou o tsukuru"},{"ja":"お弁当を作る","vi":"Làm cơm hộp","romaji":"o bentou o tsukuru"}]},{"key":"k:港","kind":"kanji","level":"N4","character":"港","meaning":"Bến cảng","hanviet":"Cảng","onReadings":["コウ"],"kunReadings":["みなと"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"港","reading":"みなと","meaning":"Bến cảng","vocabKey":"v:港"},{"compound":"空港","reading":"くうこう","meaning":"Sân bay","vocabKey":"v:空港"}],"lessonIds":[12,35],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 氵(nước) + 巷 (hạng/ngõ). Hán-Việt: CẢNG. Mẹo nhớ: Nước (氵) chảy qua ngõ (巷) tạo bến — 'cảng' là bến cảng ⚓. 12 nét. Âm コウ (kou), みなと (minato) = bến cảng. Liên kết: 港 (bến cảng), 空港 (kuukou - sân bay). ⚠️ 空港 = không cảng = SÂN BAY — từ ghép hay gặp.","example":"**空港**まで車で1時間かかります。 / kuukou made kuruma de ichijikan kakarimasu. (Mất 1 tiếng đi xe đến sân bay.)","examples":[{"ja":"空港まで車で1時間かかります。","vi":"Mất 1 tiếng đi xe đến sân bay.","romaji":"kuukou made kuruma de 1jikan kakarimasu."},{"ja":"港に船がある","vi":"Có tàu ở cảng","romaji":"Minato ni fune ga aru"},{"ja":"空港に行く","vi":"Đi sân bay","romaji":"kuukou ni iku"},{"ja":"新しい空港は きれいだと 思います。","vi":"Tôi nghĩ sân bay mới đẹp.","romaji":"atarashii kuukou wa kirei da to omoimasu."}]},{"key":"k:助","kind":"kanji","level":"N4","character":"助","meaning":"Giúp đỡ","hanviet":"Trợ","onReadings":["ジョ"],"kunReadings":["たす","たす"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"助ける","reading":"たすける","meaning":"Giúp đỡ","vocabKey":"v:助ける"},{"compound":"助かる","reading":"たすかる","meaning":"Được cứu"}],"lessonIds":[33,41],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 且 (thả/hơn nữa) + 力 (lực). Hán-Việt: TRỢ. Mẹo nhớ: Thêm sức (力) giúp đỡ — 'trợ' là giúp đỡ 🤝. 7 nét. Âm ジョ (jo), たすける (tasukeru) = giúp đỡ, たすかる (tasukaru) = được cứu. Liên kết: 助ける (giúp), 助かる (được cứu). ⚠️ 助ける (tasukeru-giúp) vs 助かる (tasukaru-được cứu) — cặp tự/tha.","example":"困っている人を**助**けましょう。 / komatte iru hito wo tasukemashou. (Hãy giúp đỡ người đang gặp khó khăn.)","examples":[{"ja":"困っている人を助けましょう。","vi":"Hãy giúp đỡ người đang gặp khó khăn.","romaji":"komatsute iru hito o tasuke masho u."},{"ja":"人を助ける","vi":"Giúp người","romaji":"hito o tasukeru"},{"ja":"助け合います","vi":"giúp đỡ lẫn nhau","romaji":"tasukeaimasu"},{"ja":"助けます","vi":"cứu, giúp đỡ","romaji":"tasukemasu"}]},{"key":"k:相","kind":"kanji","level":"N4","character":"相","meaning":"Lẫn nhau, tướng mạo","hanviet":"Tương","onReadings":["ソウ"],"kunReadings":["あい"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"相手","reading":"あいて","meaning":"Đối phương","vocabKey":"v:相手"},{"compound":"相談","reading":"そうだん","meaning":"Trao đổi"}],"lessonIds":[19,21,30,33,39,47],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 木 (cây) + 目 (mắt). Hán-Việt: TƯƠNG. Mẹo nhớ: Mắt (目) nhìn cây (木) — nhìn lẫn nhau, 'tương' là lẫn nhau 👀. 9 nét. Âm ソウ (sou) trong 相談 (soudan - trao đổi), あい (ai) trong 相手 (aite - đối phương). Liên kết: 相手 (đối phương), 相談 (trao đổi). ⚠️ 相談 = tương đàm = trao đổi — từ quan trọng.","example":"先生に**相**談しました。 / sensei ni soudan shimashita. (Tôi đã trao đổi với giáo viên.)","examples":[{"ja":"先生に相談しました。","vi":"Tôi đã trao đổi với giáo viên.","romaji":"sensei ni soudan shimashita."},{"ja":"先生に相談する","vi":"Trao đổi với thầy","romaji":"sensei ni soudan suru"},{"ja":"相手の話を聞く","vi":"Nghe đối phương nói","romaji":"Aite no hanashi wo kiku"},{"ja":"彼は相変わらず元気ですね","vi":"Anh ấy vẫn khỏe như thường nhỉ","romaji":"Kare wa aikawarazu genki de sune"}]},{"key":"k:比","kind":"kanji","level":"N4","character":"比","meaning":"So sánh","hanviet":"Tỷ","onReadings":["ヒ"],"kunReadings":["くら"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"比べる","reading":"くらべる","meaning":"So sánh","vocabKey":"v:比べる"},{"compound":"比較","reading":"ひかく","meaning":"So sánh"}],"lessonIds":[47],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 比 là chữ tượng hình — hình hai người đứng cạnh nhau so sánh. Hán-Việt: TỶ. Mẹo nhớ: Hai người đứng cạnh nhau — 'tỷ' là so sánh ⚖️. 4 nét. Âm ヒ (hi), くらべる (kuraberu) = so sánh. Liên kết: 比べる (so sánh), 比較 (hikaku - so sánh). ⚠️ 比べる (kuraberu) — ichidan (nhóm 2).","example":"二つの答えを**比**べてください。 / futatsu no kotae wo kurabete kudasai. (Hãy so sánh hai đáp án.)","examples":[{"ja":"二つの答えを比べてください。","vi":"Hãy so sánh hai đáp án.","romaji":"futatsu no kotae wo kurabete kudasai."},{"ja":"値段を比べる","vi":"So sánh giá","romaji":"Nedan wo kuraberu"},{"ja":"二つの案を比較する","vi":"So sánh hai phương án","romaji":"Futatsu no an wo hikaku suru"},{"ja":"日本とベトナムの暗さを比べてみました。","vi":"Tôi đã thử so sánh độ nóng của Nhật và Việt Nam.","romaji":"nippon to betonamu no kurasa o kurabete mimashita."}]},{"key":"k:申","kind":"kanji","level":"N4","character":"申","meaning":"Thưa, xin (khiêm nhường)","hanviet":"Thân","onReadings":["シン"],"kunReadings":["もう"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"申す","reading":"もうす","meaning":"Nói (khiêm nhường)","vocabKey":"v:申す"},{"compound":"申し込む","reading":"もうしこむ","meaning":"Đăng ký","vocabKey":"v:申し込む"}],"lessonIds":[31,40,46,50],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 申 là chữ tượng hình — hình tia sét xuyên qua. Hán-Việt: THÂN. Mẹo nhớ: Tia sét xuyên qua — thưa gửi, trình bày (khiêm nhường) 🙇. 5 nét. Âm シン (shin), もうす (mousu) = nói (khiêm nhường). Liên kết: 申す (nói khiêm nhường), 申し込む (moushikomu - đăng ký). ⚠️ 申す = nói (khiêm nhường) — dùng thay cho 言う khi lịch sự.","example":"田中と**申**します。 / tanaka to moushimasu. (Tôi tên là Tanaka.)","examples":[{"ja":"田中と申します。","vi":"Tôi tên là Tanaka.","romaji":"tanaka to moushimasu."},{"ja":"コースに申し込む","vi":"Đăng ký khóa học","romaji":"koosu ni moushikomu"},{"ja":"田中と申します","vi":"Tôi tên là Tanaka","romaji":"tanaka to moushimasu"},{"ja":"申込書を書いてください","vi":"Hãy viết đơn đăng ký","romaji":"moushikomisho o kaite kudasai"}]},{"key":"k:参","kind":"kanji","level":"N4","character":"参","meaning":"Đi, đến (khiêm nhường), tham gia","hanviet":"Tham","onReadings":["サン"],"kunReadings":["まい"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"参る","reading":"まいる","meaning":"Đi (khiêm nhường)","vocabKey":"v:参る"},{"compound":"参加","reading":"さんか","meaning":"Tham gia"}],"lessonIds":[28,38,50],"topicTags":[],"sectionId":21,"sectionName":"HOÀN THIỆN N4","mnemonic":"Bộ/thành phần: 厶 (tư) + 大 (lớn) + 彡 (lông/vân). Hán-Việt: THAM. Mẹo nhớ: Người lớn (大) đi tham gia với vẻ trang nghiêm (彡) — 'tham' là đi, tham gia 🏃. 8 nét. Âm サン (san) trong 参加 (sanka - tham gia), まいる (mairu) = đi (khiêm nhường). Liên kết: 参加 (tham gia), 参る (đi khiêm nhường). ⚠️ 参る = まいる = đi (khiêm nhường) — thay cho 行く khi lịch sự.","example":"お祭りに**参**加しました。 / omatsuri ni sanka shimashita. (Tôi đã tham gia lễ hội.)","examples":[{"ja":"お祭りに参加しました。","vi":"Tôi đã tham gia lễ hội.","romaji":"omatsuri ni sanka shimashita."},{"ja":"パーティーに参加する","vi":"Tham gia tiệc","romaji":"paateii ni sanka suru"},{"ja":"明日参ります","vi":"Ngày mai tôi sẽ đến","romaji":"Ashita mairimasu"},{"ja":"参加者は全部で三十人です","vi":"Tổng cộng có 30 người tham gia","romaji":"sankasha wa zenbu de san juunin desu"}]},{"key":"k:晴","kind":"kanji","level":"N4","character":"晴","meaning":"Trời quang, nắng","hanviet":"Tình","onReadings":["セイ"],"kunReadings":["は","は"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"晴れる","reading":"はれる","meaning":"Trời nắng","vocabKey":"v:晴れる"},{"compound":"晴天","reading":"せいてん","meaning":"Trời quang"}],"lessonIds":[32],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 青 (xanh). Hán-Việt: TÌNH. Mẹo nhớ: Mặt trời (日) trên bầu trời xanh (青) — 'tình' là trời quang, nắng đẹp ☀️. 12 nét. Âm セイ (sei) trong 晴天 (seiten - trời quang), はれる (hareru) = trời nắng. Liên kết: 晴れる (trời nắng), 晴天 (trời quang). ⚠️ 晴れ (hare) = trời tạnh/nắng — thường dùng trong dự báo thời tiết.","example":"明日は**晴**れるそうです。 / ashita wa hareru sou desu. (Nghe nói ngày mai trời sẽ nắng.)","examples":[{"ja":"明日は晴れるそうです。","vi":"Nghe nói ngày mai trời sẽ nắng.","romaji":"ashita wa hareru sou desu."},{"ja":"天気が晴れる","vi":"Trời quang","romaji":"Tenki ga hareru"},{"ja":"今日の演奏は素晴らしかった","vi":"Buổi biểu diễn tuyệt vời","romaji":"kyou no ensou wa subarashikatsuta"},{"ja":"明日は晴れると思います。","vi":"Tôi nghĩ ngày mai trời nắng.","romaji":"ashita wa hareru to omoimasu."}]},{"key":"k:曇","kind":"kanji","level":"N4","character":"曇","meaning":"Trời nhiều mây, u ám","hanviet":"Đàm","onReadings":["ドン"],"kunReadings":["くも"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"曇る","reading":"くもる","meaning":"Âm u","vocabKey":"v:曇る"},{"compound":"曇り","reading":"くもり","meaning":"Trời nhiều mây","vocabKey":"v:曇り"}],"lessonIds":[12,32],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 雲 (mây). Hán-Việt: ĐÀM. Mẹo nhớ: Mây (雲) che khuất mặt trời (日) — 'đàm' là trời nhiều mây, u ám ☁️. 16 nét. Âm ドン (don), くもる (kumoru) = trời âm u. Liên kết: 曇る (trời âm u), 曇り (trời mây). ⚠️ Thời tiết: 晴れ (nắng) → 曇り (mây) → 雨 (mưa) — nắm 3 từ cùng lúc.","example":"今日は朝から**曇**っています。 / kyou wa asa kara kumotte imasu. (Hôm nay từ sáng trời đã nhiều mây.)","examples":[{"ja":"今日は朝から曇っています。","vi":"Hôm nay từ sáng trời đã nhiều mây.","romaji":"kyou wa asa kara kumotsute imasu."},{"ja":"空が曇る","vi":"Trời âm u","romaji":"Sora ga kumoru"},{"ja":"曇り","vi":"có mây","romaji":"kumori"},{"ja":"曇ります","vi":"có mây","romaji":"kumorimasu"}]},{"key":"k:温","kind":"kanji","level":"N4","character":"温","meaning":"Ấm, nhiệt độ","hanviet":"Ôn","onReadings":["オン"],"kunReadings":["あたた","あたた"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"温かい","reading":"あたたかい","meaning":"Ấm"},{"compound":"温度","reading":"おんど","meaning":"Nhiệt độ","vocabKey":"v:温度"}],"lessonIds":[12,31,41,42],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 氵(nước) + 昷 (ôn — 日+皿). Hán-Việt: ÔN. Mẹo nhớ: Nước (氵) được mặt trời (日) sưởi trong bát (皿) — 'ôn' là ấm 🌡️. 12 nét. Âm オン (on) trong 温度 (ondo - nhiệt độ), あたたかい (atatakai) = ấm. Liên kết: 温かい (ấm áp), 温度 (nhiệt độ). ⚠️ 温かい (atatakai-ấm) vs 暖かい (atatakai-ấm áp khí hậu) — 温 dùng cho đồ ăn/nước, 暖 dùng cho thời tiết.","example":"このスープはまだ**温**かいです。 / kono suupu wa mada atatakai desu. (Món súp này vẫn còn ấm.)","examples":[{"ja":"このスープはまだ温かいです。","vi":"Món súp này vẫn còn ấm.","romaji":"kono suupu wa mada atatakai desu."},{"ja":"ご飯を温める","vi":"Hâm nóng cơm","romaji":"Gohan wo atatameru"},{"ja":"部屋の温度を下げる","vi":"Giảm nhiệt độ phòng","romaji":"Heya no ondo wo sageru"},{"ja":"今日の気温は何度ですか","vi":"Nhiệt độ hôm nay là bao nhiêu độ?","romaji":"kyou no kion wa nando desu ka"}]},{"key":"k:冷","kind":"kanji","level":"N4","character":"冷","meaning":"Lạnh, làm lạnh","hanviet":"Lãnh","onReadings":["レイ"],"kunReadings":["つめ","ひ","ひ"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"冷たい","reading":"つめたい","meaning":"Lạnh","vocabKey":"v:冷たい"},{"compound":"冷蔵庫","reading":"れいぞうこ","meaning":"Tủ lạnh","vocabKey":"v:冷蔵庫"}],"lessonIds":[8,10,32,41],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 冫(băng) + 令 (lệnh). Hán-Việt: LÃNH. Mẹo nhớ: Băng (冫) với mệnh lệnh (令) — 'lãnh' là lạnh buốt 🧊. 7 nét. Âm レイ (rei) trong 冷蔵庫 (reizouko - tủ lạnh), つめたい (tsumetai) = lạnh. Liên kết: 冷たい (lạnh), 冷蔵庫 (tủ lạnh). ⚠️ 冷たい (tsumetai-lạnh chạm vào) vs 寒い (samui-lạnh thời tiết) — 冷 dùng cho vật, 寒 dùng cho không khí.","example":"**冷**たい水をください。 / tsumetai mizu wo kudasai. (Làm ơn cho tôi nước lạnh.)","examples":[{"ja":"冷たい水をください。","vi":"Làm ơn cho tôi nước lạnh.","romaji":"tsumetai mizu wo kudasai."},{"ja":"体が冷える","vi":"Cơ thể lạnh đi","romaji":"Karada ga hieru"},{"ja":"スープが冷める","vi":"Súp nguội","romaji":"suupu ga sameru"},{"ja":"水が冷たい","vi":"Nước lạnh","romaji":"Mizu ga tsumetai"}]},{"key":"k:熱","kind":"kanji","level":"N4","character":"熱","meaning":"Nhiệt, sốt","hanviet":"Nhiệt","onReadings":["ネツ"],"kunReadings":["あつ"],"strokeCount":15,"radicals":[],"components":[],"compounds":[{"compound":"熱","reading":"ねつ","meaning":"Sốt","vocabKey":"v:熱"},{"compound":"熱い","reading":"あつい","meaning":"Nóng (đồ vật)","vocabKey":"v:熱い"}],"lessonIds":[8,17,28],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 埶 (nghệ) + 灬 (lửa). Hán-Việt: NHIỆT. Mẹo nhớ: Lửa (灬) đốt bên dưới — 'nhiệt' là nóng, sốt 🔥. 15 nét. Âm ネツ (netsu) trong 熱 (netsu - sốt), あつい (atsui) = nóng. Liên kết: 熱い (nóng), 熱 (sốt). ⚠️ 熱い (atsui-nóng chạm vào) vs 暑い (atsui-nóng thời tiết) — đồng âm nhưng khác nghĩa.","example":"子どもが**熱**を出しました。 / kodomo ga netsu wo dashimashita. (Đứa trẻ đã bị sốt.)","examples":[{"ja":"子どもが熱を出しました。","vi":"Đứa trẻ đã bị sốt.","romaji":"kodomo ga netsu wo dashimashita."},{"ja":"コーヒーが熱い","vi":"Cà phê nóng","romaji":"koohii ga atsui"},{"ja":"熱心な先生","vi":"Thầy nhiệt tình","romaji":"Nesshin na sensei"},{"ja":"熱がある","vi":"Bị sốt","romaji":"Netsu ga aru"}]},{"key":"k:消","kind":"kanji","level":"N4","character":"消","meaning":"Biến mất, xóa, tắt","hanviet":"Tiêu","onReadings":["ショウ"],"kunReadings":["き","け"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"消える","reading":"きえる","meaning":"Tắt/ biến mất","vocabKey":"v:消える"},{"compound":"消す","reading":"けす","meaning":"Tắt/ xóa","vocabKey":"v:消す"}],"lessonIds":[7,14,29],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 氵(nước) + 肖 (tiêu). Hán-Việt: TIÊU. Mẹo nhớ: Nước (氵) dập tắt, biến mất — 'tiêu' là tắt, xóa, biến mất 💨. 10 nét. Âm ショウ (shou), きえる (kieru) = tắt/biến mất, けす (kesu) = tắt/xóa. Liên kết: 消える (tắt/biến mất), 消す (tắt/xóa). ⚠️ 消える (kieru-tự tắt) vs 消す (kesu-tắt đi) — cặp tự/tha động từ.","example":"寝る前に電気を**消**してください。 / neru mae ni denki wo keshite kudasai. (Trước khi ngủ hãy tắt điện.)","examples":[{"ja":"寝る前に電気を消してください。","vi":"Trước khi ngủ hãy tắt điện.","romaji":"neru mae ni denki wo keshite kudasai."},{"ja":"電気を消してください","vi":"Hãy tắt đèn","romaji":"Denki wo keshitekudasai"},{"ja":"電気が消える","vi":"Đèn tắt","romaji":"Denki ga kieru"},{"ja":"消しゴムで消す","vi":"Xóa bằng tẩy","romaji":"Keshigomu de kesu"}]},{"key":"k:残","kind":"kanji","level":"N4","character":"残","meaning":"Còn lại, để lại","hanviet":"Tàn","onReadings":["ザン"],"kunReadings":["のこ","のこ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"残る","reading":"のこる","meaning":"Còn lại","vocabKey":"v:残る"},{"compound":"残す","reading":"のこす","meaning":"Chừa lại"}],"lessonIds":[9,17,31],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 歹 (xương/chết) + 戋 (tiền nhỏ). Hán-Việt: TÀN. Mẹo nhớ: Xương (歹) còn sót lại — 'tàn' là còn lại, để lại 🦴. 10 nét. Âm ザン (zan), のこる (nokoru) = còn lại, のこす (nokosu) = chừa lại. Liên kết: 残る (còn lại), 残す (chừa lại). ⚠️ 残る (nokoru-tự còn) vs 残す (nokosu-chừa lại) — cặp tự/tha động từ.","example":"料理が少し**残**っています。 / ryouri ga sukoshi nokotte imasu. (Món ăn vẫn còn lại một ít.)","examples":[{"ja":"料理が少し残っています。","vi":"Món ăn vẫn còn lại một ít.","romaji":"ryouri ga sukoshi nokotsute imasu."},{"ja":"食べ物が残る","vi":"Đồ ăn còn lại","romaji":"Tabemono ga nokoru"},{"ja":"残念な結果","vi":"Kết quả đáng tiếc","romaji":"Zannen na kekka"},{"ja":"残業が多い","vi":"Nhiều OT","romaji":"zangyou ga ooi"}]},{"key":"k:無","kind":"kanji","level":"N4","character":"無","meaning":"Không có, vô","hanviet":"Vô","onReadings":["ム","ブ"],"kunReadings":["な"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"無理","reading":"むり","meaning":"Quá sức"},{"compound":"無料","reading":"むりょう","meaning":"Miễn phí","vocabKey":"v:無料"}],"lessonIds":[19,28,32,33,45],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: hình gốc — múa (舞) bỏ bớt. Hán-Việt: VÔ. Mẹo nhớ: 'Vô' là không có gì — từ gốc người múa nhưng mất nghĩa gốc 🚫. 12 nét. Âm ム (mu) trong 無理 (muri - quá sức), ブ (bu) trong 無事 (buji - bình an). Liên kết: 無理 (quá sức), 無料 (miễn phí). ⚠️ 無理 (muri) = vô lý = quá sức — cực phổ biến; 無料 = vô liệu = miễn phí.","example":"今日は**無**理をしないでください。 / kyou wa muri wo shinaide kudasai. (Hôm nay đừng cố quá sức.)","examples":[{"ja":"今日は無理をしないでください。","vi":"Hôm nay đừng cố quá sức.","romaji":"kyou wa muri wo shinaide kudasai."},{"ja":"鍵を無くす","vi":"Làm mất chìa khóa","romaji":"Kagi wo nakusu"},{"ja":"お金が無くなる","vi":"Hết tiền","romaji":"Okane ga nakunaru"},{"ja":"無理なお願い","vi":"Yêu cầu vô lý","romaji":"Muri nao negai"}]},{"key":"k:緑","kind":"kanji","level":"N4","character":"緑","meaning":"Màu xanh lá","hanviet":"Lục","onReadings":["リョク"],"kunReadings":["みどり"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"緑","reading":"みどり","meaning":"Màu xanh lá","vocabKey":"v:緑"},{"compound":"緑色","reading":"みどりいろ","meaning":"Màu xanh lá"}],"lessonIds":[16],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 糸 (tơ/sợi) + 录 (lục). Hán-Việt: LỤC. Mẹo nhớ: Sợi tơ (糸) màu xanh lá — 'lục' là xanh lá cây 🌿. 14 nét. Âm リョク (ryoku), みどり (midori) = xanh lá. Liên kết: 緑 (xanh lá), 緑色 (midoriiro - màu xanh lá). ⚠️ 緑茶 (ryokucha) = lục trà = trà xanh — từ ghép quen thuộc.","example":"この公園は**緑**が多いです。 / kono kouen wa midori ga ooi desu. (Công viên này có nhiều cây xanh.)","examples":[{"ja":"この公園は緑が多いです。","vi":"Công viên này có nhiều cây xanh.","romaji":"kono kouen wa midori ga ooi desu."},{"ja":"緑のペン","vi":"Bút xanh lá","romaji":"Midori no pen"},{"ja":"緑","vi":"màu xanh lá cây","romaji":"midori"}]},{"key":"k:船","kind":"kanji","level":"N4","character":"船","meaning":"Thuyền, tàu","hanviet":"Thuyền","onReadings":["セン"],"kunReadings":["ふね"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"船","reading":"ふね","meaning":"Thuyền","vocabKey":"v:船"},{"compound":"船便","reading":"ふなびん","meaning":"Gửi hàng đường biển","vocabKey":"v:船便"}],"lessonIds":[5,11,26,36],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 舟 (thuyền) + 㕣 (八+口). Hán-Việt: THUYỀN. Mẹo nhớ: Chiếc thuyền (舟) với miệng (口) gọi bến — 'thuyền' là tàu, thuyền ⛵. 11 nét. Âm セン (sen), ふね (fune) = thuyền. Liên kết: 船 (thuyền), 船便 (funabin - đường biển). ⚠️ 船 vs 舟 — 船 là thuyền lớn/tàu (dùng phổ biến), 舟 là thuyền nhỏ (ít dùng).","example":"島まで**船**で行きました。 / shima made fune de ikimashita. (Tôi đã đi bằng thuyền tới đảo.)","examples":[{"ja":"島まで船で行きました。","vi":"Tôi đã đi bằng thuyền tới đảo.","romaji":"shima made fune de ikimashita."},{"ja":"船に乗る","vi":"Đi tàu thủy","romaji":"Fune ni noru"},{"ja":"船便","vi":"Gửi bằng đường biển","romaji":"funabin"},{"ja":"宇宙船","vi":"tàu vũ trụ","romaji":"uchuusen"}]},{"key":"k:泳","kind":"kanji","level":"N4","character":"泳","meaning":"Bơi","hanviet":"Vịnh","onReadings":["エイ"],"kunReadings":["およ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"泳ぐ","reading":"およぐ","meaning":"Bơi","vocabKey":"v:泳ぐ"},{"compound":"水泳","reading":"すいえい","meaning":"Môn bơi","vocabKey":"v:水泳"}],"lessonIds":[13,36],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 氵(nước) + 永 (vĩnh/mãi). Hán-Việt: VỊNH. Mẹo nhớ: Trong nước (氵) mãi (永) di chuyển — 'vịnh' là bơi 🏊. 8 nét. Âm エイ (ei) trong 水泳 (suiei - môn bơi), およぐ (oyogu) = bơi. Liên kết: 泳ぐ (bơi), 水泳 (môn bơi). ⚠️ Âm エイ (ei) giống 永 (vĩnh), dễ nhớ qua 永 = forever, trong nước mãi = bơi.","example":"夏に海で**泳**ぎたいです。 / natsu ni umi de oyogitai desu. (Mùa hè tôi muốn bơi ở biển.)","examples":[{"ja":"夏に海で泳ぎたいです。","vi":"Mùa hè tôi muốn bơi ở biển.","romaji":"natsu ni umi de oyogitai desu."},{"ja":"プールで泳ぐ","vi":"Bơi ở hồ bơi","romaji":"puuru de oyogu"},{"ja":"水泳が得意です","vi":"Giỏi bơi lội","romaji":"Suiei ga tokui de su"},{"ja":"書く、見る、泳ぐ","vi":"viết, xem, bơi (thể từ điển)","romaji":"kaku, miru, oyogu"}]},{"key":"k:寺","kind":"kanji","level":"N4","character":"寺","meaning":"Chùa","hanviet":"Tự","onReadings":["ジ"],"kunReadings":["てら"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"寺","reading":"てら","meaning":"Chùa"},{"compound":"お寺","reading":"おてら","meaning":"Ngôi chùa","vocabKey":"v:お寺"}],"lessonIds":[16],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 土 (đất) + 寸 (tấc/đo). Hán-Việt: TỰ. Mẹo nhớ: Đất (土) được đo (寸) để xây — 'tự' là chùa, đền 🏯. 6 nét. Âm ジ (ji), てら (tera) = chùa. Liên kết: お寺 (ngôi chùa), 寺 (chùa). ⚠️ 寺 (tera-chùa Phật) vs 神社 (jinja-đền Thần đạo) — hai loại đền thờ khác nhau ở Nhật.","example":"京都の有名な**寺**を見学しました。 / kyouto no yuumei na tera wo kengaku shimashita. (Tôi đã tham quan ngôi chùa nổi tiếng ở Kyoto.)","examples":[{"ja":"京都の有名な寺を見学しました。","vi":"Tôi đã tham quan ngôi chùa nổi tiếng ở Kyoto.","romaji":"kyouto no yuumei na tera wo kengaku shimashita."},{"ja":"お寺を見学する","vi":"Tham quan chùa","romaji":"O tera wo kengaku suru"},{"ja":"この寺は400年前に有名な僧侶によって建てられました。","vi":"Ngôi chùa này được một nhà sư nổi tiếng xây cách đây 400 năm.","romaji":"kono tera wa 400nen mae ni yuumei na souryo niyotte tate raremashita."},{"ja":"お寺","vi":"chùa","romaji":"otera"}]},{"key":"k:神","kind":"kanji","level":"N4","character":"神","meaning":"Thần linh","hanviet":"Thần","onReadings":["シン","ジン"],"kunReadings":["かみ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"神社","reading":"じんじゃ","meaning":"Đền thần đạo","vocabKey":"v:神社"},{"compound":"神","reading":"かみ","meaning":"Thần"}],"lessonIds":[16,31],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 礻(bộ thị/thần) + 申 (thân/thưa). Hán-Việt: THẦN. Mẹo nhớ: Bộ thần (礻) với thưa gửi (申) — 'thần' là thần linh, thần thánh ⛩️. 9 nét. Âm シン (shin), ジン (jin) trong 神社 (jinja - đền thần đạo), かみ (kami) = thần. Liên kết: 神社 (đền thần đạo), 神 (thần). ⚠️ 神社 (jinja) = thần xã = đền thần đạo — khác 寺 (tera-chùa Phật).","example":"旅行で**神**社にお参りしました。 / ryokou de jinja ni omairi shimashita. (Trong chuyến đi tôi đã tới viếng đền.)","examples":[{"ja":"旅行で神社にお参りしました。","vi":"Trong chuyến đi tôi đã tới viếng đền.","romaji":"ryokou de jinja ni omairi shimashita."},{"ja":"神社にお参りする","vi":"Đi lễ ở đền","romaji":"Jinja ni o mairi suru"},{"ja":"神戸へ インド料理を 食べに 行きます。","vi":"Tôi đi Kobe để ăn món Ấn Độ.","romaji":"koube e indo ryouri o tabe ni ikimasu."},{"ja":"神社","vi":"đền thờ thần đạo","romaji":"jinja"}]},{"key":"k:橋","kind":"kanji","level":"N4","character":"橋","meaning":"Cây cầu","hanviet":"Kiều","onReadings":["キョウ"],"kunReadings":["はし"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"橋","reading":"はし","meaning":"Cây cầu","vocabKey":"v:橋"},{"compound":"歩道橋","reading":"ほどうきょう","meaning":"Cầu vượt đi bộ"}],"lessonIds":[23],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 木 (gỗ) + 喬 (kiều/cao). Hán-Việt: KIỀU. Mẹo nhớ: Gỗ (木) bắc cao (喬) qua sông — 'kiều' là cầu 🌉. 16 nét. Âm キョウ (kyou), はし (hashi) = cầu. Liên kết: 橋 (cầu), 歩道橋 (hodoukyou - cầu vượt đi bộ). ⚠️ はし có 3 nghĩa: 橋 (cầu), 箸 (đũa), 端 (đầu mút) — phân biệt qua kanji.","example":"あの**橋**を渡ると駅があります。 / ano hashi wo wataru to eki ga arimasu. (Qua cây cầu đó sẽ tới ga.)","examples":[{"ja":"あの橋を渡ると駅があります。","vi":"Qua cây cầu đó sẽ tới ga.","romaji":"ano hashi wo wataru to eki ga arimasu."},{"ja":"橋を渡る","vi":"Qua cầu","romaji":"Hashi wo wataru"},{"ja":"あの橋は石で作られました。","vi":"Cây cầu kia được làm bằng đá.","romaji":"ano hashi wa ishi de tsukura remashita."},{"ja":"この橋の長さは500メートルです。","vi":"Cây cầu này dài 500 mét.","romaji":"kono hashi no nagasa wa 500meetoru desu."}]},{"key":"k:荷","kind":"kanji","level":"N4","character":"荷","meaning":"Hành lý, hàng hóa","hanviet":"Hà","onReadings":["カ"],"kunReadings":["に"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"荷物","reading":"にもつ","meaning":"Hành lý","vocabKey":"v:荷物"},{"compound":"入荷","reading":"にゅうか","meaning":"Nhập hàng"}],"lessonIds":[7],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 艹 (cỏ) + 何 (cái gì). Hán-Việt: HÀ. Mẹo nhớ: Gánh cỏ (艹) mang cái gì (何) — 'hà' là hành lý, gánh vác 🧳. 10 nét. Âm カ (ka), に (ni) trong 荷物 (nimotsu - hành lý). Liên kết: 荷物 (hành lý), 入荷 (nyuuka - nhập hàng). ⚠️ 荷物 (nimotsu) = hà vật = hành lý — từ rất thực dụng khi du lịch.","example":"**荷**物が重いので手伝ってください。 / nimotsu ga omoi node tetsudatte kudasai. (Hành lý nặng nên hãy giúp tôi.)","examples":[{"ja":"荷物が重いので手伝ってください。","vi":"Hành lý nặng nên hãy giúp tôi.","romaji":"nimotsu ga omoi node tetsudatsute kudasai."},{"ja":"荷物を運ぶ","vi":"Mang hành lý","romaji":"Nimotsu wo hakobu"},{"ja":"荷物の重さを量る","vi":"Cân trọng lượng hành lý","romaji":"Nimotsu no omosa wo hakaru"},{"ja":"もう荷物を送りましたか。……はい、もう送りました。","vi":"Anh/Chị đã gửi đồ chưa? Rồi, tôi đã gửi rồi.","romaji":"mou nimotsu o okurimashita ka....... hai, mou okurimashita."}]},{"key":"k:側","kind":"kanji","level":"N4","character":"側","meaning":"Bên, phía","hanviet":"Trắc","onReadings":["ソク"],"kunReadings":["がわ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"側","reading":"がわ","meaning":"Phía bên"},{"compound":"内側","reading":"うちがわ","meaning":"Mặt trong"}],"lessonIds":[29],"topicTags":[],"sectionId":22,"sectionName":"N4 CÒN THIẾU THỰC DỤNG","mnemonic":"Bộ/thành phần: 亻(người) + 則 (tắc/quy tắc). Hán-Việt: TRẮC. Mẹo nhớ: Người (亻) đứng bên cạnh theo quy tắc (則) — 'trắc' là bên, phía 👈👉. 11 nét. Âm ソク (soku), がわ (gawa) = bên/phía. Liên kết: 右側 (migigawa - bên phải), 内側 (uchigawa - mặt trong). ⚠️ 〜側 (-gawa) = bên ~ — thêm sau 右/左/外/内 để chỉ phía.","example":"駅の右**側**に銀行があります。 / eki no migigawa ni ginkou ga arimasu. (Ở bên phải ga có ngân hàng.)","examples":[{"ja":"駅の右側に銀行があります。","vi":"Ở bên phải ga có ngân hàng.","romaji":"eki no migigawa ni ginkou ga arimasu."},{"ja":"～側","vi":"phía ~, bên ~","romaji":"gawa"}]},{"key":"k:議","kind":"kanji","level":"N4","character":"議","meaning":"Thảo luận, nghị luận","hanviet":"Nghị","onReadings":["ギ"],"kunReadings":["-"],"strokeCount":20,"radicals":[],"components":[],"compounds":[{"compound":"会議","reading":"かいぎ","meaning":"Cuộc họp","vocabKey":"v:会議"},{"compound":"議員","reading":"ぎいん","meaning":"Nghị viên"}],"lessonIds":[3,4,13,26,27],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 言 (lời nói) + 義 (nghĩa). Mẹo nhớ: lời nói có lý lẽ tạo thành thảo luận.","example":"明日の会**議**で新しい計画を話します。 / ashita no kaigi de atarashii keikaku wo hanashimasu. (Ngày mai chúng tôi sẽ bàn kế hoạch mới trong cuộc họp.)","examples":[{"ja":"明日の会議で新しい計画を話します。","vi":"Ngày mai chúng tôi sẽ bàn kế hoạch mới trong cuộc họp.","romaji":"ashita no kaigi de atarashii keikaku wo hanashimasu."},{"ja":"不思議な話","vi":"Câu chuyện bí ẩn","romaji":"Fushigi na hanashi"},{"ja":"会議に出る","vi":"Tham dự cuộc họp","romaji":"Kaigi ni deru"},{"ja":"会議室を予約する","vi":"Đặt phòng họp","romaji":"Kaigishitsu wo yoyaku suru"}]},{"key":"k:辞","kind":"kanji","level":"N4","character":"辞","meaning":"Từ ngữ, từ chức, từ điển","hanviet":"Từ","onReadings":["ジ"],"kunReadings":["や"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"辞書","reading":"じしょ","meaning":"Từ điển","vocabKey":"v:辞書"},{"compound":"辞める","reading":"やめる","meaning":"Nghỉ"}],"lessonIds":[2],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 舌 (lưỡi) + 辛 (cay). Hán-Việt: TỪ. Mẹo nhớ: Lưỡi (舌) nếm vị cay (辛) — nói lời 'từ' biệt, từ chức 📖. 13 nét. Âm ジ (ji), やめる (yameru) = nghỉ việc. Liên kết: 辞書 (jisho - từ điển), 辞める (yameru - nghỉ/thôi). ⚠️ 辞書 (jisho) = từ thư = từ điển — từ quan trọng cho người học.","example":"新しい漢字はまず**辞**書で調べます。 / atarashii kanji wa mazu jisho de shirabemasu. (Khi gặp kanji mới tôi tra từ điển trước.)","examples":[{"ja":"新しい漢字はまず辞書で調べます。","vi":"Khi gặp kanji mới tôi tra từ điển trước.","romaji":"atarashii kanji wa mazu jisho de shirabemasu."},{"ja":"辞書で調べる","vi":"Tra từ điển","romaji":"Jisho de shiraberu"},{"ja":"あれは辞書じゃありません。","vi":"Kia không phải là từ điển.","romaji":"are wa jisho ja arimasen."},{"ja":"それは辞書ですか。","vi":"Đó có phải là quyển từ điển không?","romaji":"sore wa jisho desu ka."}]},{"key":"k:柔","kind":"kanji","level":"N4","character":"柔","meaning":"Mềm, dẻo","hanviet":"Nhu","onReadings":["ジュウ","ニュウ"],"kunReadings":["やわ"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"柔道","reading":"じゅうどう","meaning":"Nhu đạo","vocabKey":"v:柔道"},{"compound":"柔らかい","reading":"やわらかい","meaning":"Mềm","vocabKey":"v:柔らかい"}],"lessonIds":[36],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 矛 (giáo) + 木 (cây). Hán-Việt: NHU. Mẹo nhớ: Cây (木) mềm uốn cong như giáo (矛) — 'nhu' là mềm, dẻo 🤸. 9 nét. Âm ジュウ (juu) trong 柔道 (juudou - nhu đạo), やわらかい (yawarakai) = mềm. Liên kết: 柔道 (nhu đạo), 柔らかい (mềm). ⚠️ 柔道 = nhu đạo — môn võ nổi tiếng Nhật Bản.","example":"このパンはとても**柔**らかくておいしいです。 / kono pan wa totemo yawarakakute oishii desu. (Bánh mì này rất mềm và ngon.)","examples":[{"ja":"このパンはとても柔らかくておいしいです。","vi":"Bánh mì này rất mềm và ngon.","romaji":"kono pan wa totemo yawarakakute oishii desu."},{"ja":"パンが柔らかい","vi":"Bánh mì mềm","romaji":"Pan ga yawarakai"},{"ja":"柔道を習う","vi":"Học judo","romaji":"juudou o narau"},{"ja":"柔道","vi":"nhu đạo","romaji":"juudou"}]},{"key":"k:駐","kind":"kanji","level":"N4","character":"駐","meaning":"Đỗ, dừng (xe)","hanviet":"Trú","onReadings":["チュウ"],"kunReadings":["-"],"strokeCount":15,"radicals":[],"components":[],"compounds":[{"compound":"駐車","reading":"ちゅうしゃ","meaning":"Đỗ xe"},{"compound":"駐車場","reading":"ちゅうしゃじょう","meaning":"Bãi đỗ xe","vocabKey":"v:駐車場"}],"lessonIds":[23,33],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 馬 (ngựa) + 主 (chủ). Hán-Việt: TRÚ. Mẹo nhớ: Ngựa (馬) dừng lại ở chỗ chủ (主) — 'trú' là đỗ, dừng lại 🅿️. 15 nét. Âm チュウ (chuu) trong 駐車場 (chuushajou - bãi đỗ xe). Liên kết: 駐車 (đỗ xe), 駐車場 (bãi đỗ xe). ⚠️ 駐車場 = trú xa trường = bãi đỗ xe — từ quan trọng khi du lịch.","example":"ここに車を**駐**車してはいけません。 / koko ni kuruma wo chuusha shite wa ikemasen. (Không được đỗ xe ở đây.)","examples":[{"ja":"ここに車を駐車してはいけません。","vi":"Không được đỗ xe ở đây.","romaji":"koko ni kuruma wo chuusha shite wa ikemasen."},{"ja":"駐車場に車を止める","vi":"Đỗ xe ở bãi","romaji":"chuushajou ni kuruma o tomeru"},{"ja":"看板に「駐車禁止」と書いてあります。","vi":"Trên biển có ghi \\"Cấm đỗ xe\\".","romaji":"kanban ni\\" chuusha kinshi\\" to kaite arimasu."},{"ja":"駐車場","vi":"bãi đỗ xe","romaji":"chuushajou"}]},{"key":"k:帽","kind":"kanji","level":"N4","character":"帽","meaning":"Mũ","hanviet":"Mạo","onReadings":["ボウ"],"kunReadings":["-"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"帽子","reading":"ぼうし","meaning":"Cái mũ","vocabKey":"v:帽子"}],"lessonIds":[22],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 巾 (vải/khăn) + 冒 (mạo hiểm). Hán-Việt: MẠO. Mẹo nhớ: Vải (巾) che trên đầu — 'mạo' là mũ, nón 🧢. 12 nét. Âm ボウ (bou) trong 帽子 (boushi - cái mũ). Liên kết: 帽子 (cái mũ). ⚠️ 帽子 (boushi) = mạo tử = cái mũ — từ sinh hoạt quan trọng.","example":"日差しが強いので**帽**子をかぶります。 / hizashi ga tsuyoi node boushi wo kaburimasu. (Vì nắng gắt nên tôi đội mũ.)","examples":[{"ja":"日差しが強いので帽子をかぶります。","vi":"Vì nắng gắt nên tôi đội mũ.","romaji":"hizashi ga tsuyoi node boushi wo kaburimasu."},{"ja":"帽子をかぶる","vi":"Đội mũ","romaji":"boushi o kaburu"},{"ja":"帽子をかぶって出かけました。","vi":"Đội mũ rồi đi ra ngoài.","romaji":"boushi o kabutsute dekakemashita."},{"ja":"かぶります [帽子を～]","vi":"đội [mũ, v.v.]","romaji":"kaburimasu [ boushi o ~]"}]},{"key":"k:湯","kind":"kanji","level":"N4","character":"湯","meaning":"Nước nóng","hanviet":"Thang","onReadings":["トウ"],"kunReadings":["ゆ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"お湯","reading":"おゆ","meaning":"Nước nóng","vocabKey":"v:お湯"},{"compound":"銭湯","reading":"せんとう","meaning":"Nhà tắm công cộng"}],"lessonIds":[],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 氵(nước) + 昜 (dương). Hán-Việt: THANG. Mẹo nhớ: Nước (氵) được nắng (昜) đun nóng — 'thang' là nước nóng ♨️. 12 nét. Âm トウ (tou), ゆ (yu) = nước nóng. Liên kết: お湯 (nước nóng), 銭湯 (sentou - nhà tắm công cộng). ⚠️ お湯 (oyu) = nước nóng — đừng nhầm 湯 (nước nóng) với 水 (mizu - nước lạnh).","example":"カップに**湯**を入れてください。 / kappu ni yu wo irete kudasai. (Hãy rót nước nóng vào cốc.)","examples":[{"ja":"カップに湯を入れてください。","vi":"Hãy rót nước nóng vào cốc.","romaji":"kappu ni yu wo irete kudasai."},{"ja":"お湯を沸かす","vi":"Đun nước sôi","romaji":"Oyu wo wakasu"}]},{"key":"k:横","kind":"kanji","level":"N4","character":"横","meaning":"Ngang, bên cạnh","hanviet":"Hoành","onReadings":["オウ"],"kunReadings":["よこ"],"strokeCount":15,"radicals":[],"components":[],"compounds":[{"compound":"横","reading":"よこ","meaning":"Ngang/bên cạnh","vocabKey":"v:横"},{"compound":"横断歩道","reading":"おうだんほどう","meaning":"Vạch qua đường","vocabKey":"v:横断歩道"}],"lessonIds":[26],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 木 (cây) + 黄 (vàng). Mẹo nhớ: nét trải ngang tạo cảm giác chiều ngang.","example":"駅の**横**にコンビニがあります。 / eki no yoko ni konbini ga arimasu. (Bên cạnh ga có cửa hàng tiện lợi.)","examples":[{"ja":"駅の横にコンビニがあります。","vi":"Bên cạnh ga có cửa hàng tiện lợi.","romaji":"eki no yoko ni konbini ga arimasu."},{"ja":"横に座る","vi":"Ngồi bên cạnh","romaji":"Yoko ni suwaru"},{"ja":"横断歩道を渡る","vi":"Băng qua vạch qua đường","romaji":"oudan hodou o wataru"},{"ja":"横","vi":"bên cạnh","romaji":"yoko"}]},{"key":"k:欲","kind":"kanji","level":"N4","character":"欲","meaning":"Muốn, ham muốn","hanviet":"Dục","onReadings":["ヨク"],"kunReadings":["ほ","ほっ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"欲しい","reading":"ほしい","meaning":"Muốn","vocabKey":"v:欲しい"},{"compound":"食欲","reading":"しょくよく","meaning":"Sự thèm ăn"}],"lessonIds":[13],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 谷 (thung lũng) + 欠 (thiếu/há miệng). Hán-Việt: DỤC. Mẹo nhớ: Thung lũng trống (谷) + há miệng thèm (欠) — 'dục' là ham muốn 🤤. 11 nét. Âm ヨク (yoku), ほしい (hoshii) = muốn. Liên kết: 欲しい (muốn), 食欲 (shokuyoku - thèm ăn). ⚠️ ～が欲しい (ga hoshii) = muốn ~ — mẫu câu quan trọng N4.","example":"新しい辞書が**欲**しいです。 / atarashii jisho ga hoshii desu. (Tôi muốn một cuốn từ điển mới.)","examples":[{"ja":"新しい辞書が欲しいです。","vi":"Tôi muốn một cuốn từ điển mới.","romaji":"atarashii jisho ga hoshii desu."},{"ja":"新しい車が欲しい","vi":"Muốn xe mới","romaji":"Atarashii kuruma ga hoshii"},{"ja":"欲しい","vi":"muốn có","romaji":"hoshii"},{"ja":"弟は新しいゲームを 欲しがっています。","vi":"Em trai tỏ ra muốn có game mới."}]},{"key":"k:景","kind":"kanji","level":"N4","character":"景","meaning":"Cảnh, phong cảnh","hanviet":"Cảnh","onReadings":["ケイ"],"kunReadings":["-"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"景色","reading":"けしき","meaning":"Phong cảnh","vocabKey":"v:景色"},{"compound":"景気","reading":"けいき","meaning":"Tình hình kinh tế","vocabKey":"v:景気"}],"lessonIds":[27],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 京. Mẹo nhớ: ánh sáng mặt trời làm cảnh vật hiện rõ.","example":"山の**景**色がとてもきれいです。 / yama no keshiki ga totemo kirei desu. (Phong cảnh núi rất đẹp.)","examples":[{"ja":"山の景色がとてもきれいです。","vi":"Phong cảnh núi rất đẹp.","romaji":"yama no keshiki ga totemo kirei desu."},{"ja":"景色がきれいだ","vi":"Phong cảnh đẹp","romaji":"Keshiki gakireida"},{"ja":"景気が悪くなった","vi":"Kinh tế trở nên xấu đi","romaji":"keiki ga waruku natsuta"},{"ja":"景色","vi":"phong cảnh","romaji":"keshiki"}]},{"key":"k:具","kind":"kanji","level":"N4","character":"具","meaning":"Dụng cụ, trang bị","hanviet":"Cụ","onReadings":["グ"],"kunReadings":["そな"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"道具","reading":"どうぐ","meaning":"Dụng cụ","vocabKey":"v:道具"},{"compound":"文房具","reading":"ぶんぼうぐ","meaning":"Văn phòng phẩm"}],"lessonIds":[27,46],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 目 (mắt) + 一 + 八. Hán-Việt: CỤ. Mẹo nhớ: Nhìn (目) đếm đủ tám (八) món — 'cụ' là dụng cụ, đồ dùng 🔧. 8 nét. Âm グ (gu), そなえる (sonaeru) = trang bị. Liên kết: 道具 (dougu - dụng cụ), 文房具 (bunbougu - văn phòng phẩm). ⚠️ 道具 (dougu) = đạo cụ = dụng cụ — từ thực dụng hay gặp.","example":"料理の道**具**をそろえました。 / ryouri no dougu wo soroemashita. (Tôi đã chuẩn bị đủ dụng cụ nấu ăn.)","examples":[{"ja":"料理の道具をそろえました。","vi":"Tôi đã chuẩn bị đủ dụng cụ nấu ăn.","romaji":"ryouri no dougu wo soroemashita."},{"ja":"道具を使う","vi":"Dùng dụng cụ","romaji":"dougu o tsukau"},{"ja":"道具","vi":"dụng cụ, công cụ","romaji":"dougu"},{"ja":"家具","vi":"đồ gỗ, đồ đạc trong nhà","romaji":"kagu"}]},{"key":"k:昔","kind":"kanji","level":"N4","character":"昔","meaning":"Ngày xưa","hanviet":"Tích","onReadings":["セキ","シャク"],"kunReadings":["むかし"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"昔","reading":"むかし","meaning":"Ngày xưa","vocabKey":"v:昔"},{"compound":"昔話","reading":"むかしばなし","meaning":"Truyện cổ","vocabKey":"v:昔話"}],"lessonIds":[27,35,41],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 共 biến thể (trên) + 日 (mặt trời). Hán-Việt: TÍCH. Mẹo nhớ: Nhiều ngày (日) đã qua — 'tích' là ngày xưa, xưa kia 📜. 8 nét. Âm セキ (seki), むかし (mukashi) = ngày xưa. Liên kết: 昔 (ngày xưa), 昔話 (mukashibanashi - truyện cổ). ⚠️ むかし (mukashi) = ngày xưa — thường mở đầu truyện cổ tích.","example":"**昔**、この町には大きい川がありました。 / mukashi, kono machi ni wa ookii kawa ga arimashita. (Ngày xưa thị trấn này có một con sông lớn.)","examples":[{"ja":"昔、この町には大きい川がありました。","vi":"Ngày xưa thị trấn này có một con sông lớn.","romaji":"mukashi, kono machi ni wa ookii kawa ga arimashita."},{"ja":"昔の日本の家は木で作られました。","vi":"Nhà Nhật ngày xưa được làm bằng gỗ.","romaji":"mukashi no nippon no ie wa ki de tsukura remashita."},{"ja":"昔","vi":"ngày xưa","romaji":"mukashi"},{"ja":"昔話","vi":"truyện cổ tích","romaji":"mukashibanashi"}]},{"key":"k:夢","kind":"kanji","level":"N4","character":"夢","meaning":"Giấc mơ","hanviet":"Mộng","onReadings":["ム"],"kunReadings":["ゆめ"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"夢","reading":"ゆめ","meaning":"Giấc mơ","vocabKey":"v:夢"},{"compound":"夢中","reading":"むちゅう","meaning":"Mải mê"}],"lessonIds":[],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 艹 + 冖 + 夕 + 䒑 (phân tích học tập). Mẹo nhớ: hình ảnh mơ hồ ban đêm gợi giấc mơ.","example":"将来の**夢**は日本で働くことです。 / shourai no yume wa nihon de hataraku koto desu. (Ước mơ tương lai của tôi là làm việc ở Nhật.)","examples":[{"ja":"将来の夢は日本で働くことです。","vi":"Ước mơ tương lai của tôi là làm việc ở Nhật.","romaji":"shourai no yume wa nippon de hataraku koto desu."},{"ja":"夢がある","vi":"Có ước mơ","romaji":"Yume ga aru"},{"ja":"いつか夢がかなうといいですね","vi":"Hy vọng một ngày nào đó ước mơ sẽ thành hiện thực.","romaji":"Itsuka yume ga kanau to ii desu ne"},{"ja":"まるで夢の ような 話です。","vi":"Câu chuyện giống như mơ."}]},{"key":"k:役","kind":"kanji","level":"N4","character":"役","meaning":"Vai trò, nhiệm vụ","hanviet":"Dịch","onReadings":["ヤク","エキ"],"kunReadings":["-"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"役所","reading":"やくしょ","meaning":"Cơ quan hành chính"},{"compound":"役に立つ","reading":"やくにたつ","meaning":"Có ích","vocabKey":"v:役に立つ"}],"lessonIds":[13,21],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 彳 (bước đi) + 殳 (gậy/vũ khí). Hán-Việt: DỊCH. Mẹo nhớ: Bước đi (彳) cầm vũ khí (殳) — 'dịch' là vai trò, nhiệm vụ 🎭. 7 nét. Âm ヤク (yaku) trong 役に立つ (yakunitatsu - có ích). Liên kết: 役所 (yakusho - ủy ban), 役に立つ (có ích). ⚠️ 役に立つ (yakunitatsu) = có ích — thành ngữ cực phổ biến.","example":"この説明は学習に**役**に立ちます。 / kono setsumei wa gakushuu ni yakunitachimasu. (Phần giải thích này hữu ích cho việc học.)","examples":[{"ja":"この説明は学習に役に立ちます。","vi":"Phần giải thích này hữu ích cho việc học.","romaji":"kono setsumei wa gakushuu ni yakunitachimasu."},{"ja":"この本は役に立つ","vi":"Cuốn sách này có ích","romaji":"Kono hon wa yaku ni tatsu"},{"ja":"市役所で住所変更の手続きをする","vi":"Làm thủ tục đổi địa chỉ ở tòa thị chính","romaji":"shiyakusho de juusho henkou no tetsuzuki o suru"},{"ja":"区役所で住民票をもらう","vi":"Lấy giấy cư trú ở ủy ban quận","romaji":"kuyakusho de juuminhyou o morau"}]},{"key":"k:形","kind":"kanji","level":"N4","character":"形","meaning":"Hình dạng","hanviet":"Hình","onReadings":["ケイ","ギョウ"],"kunReadings":["かたち"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"形","reading":"かたち","meaning":"Hình dạng","vocabKey":"v:形"},{"compound":"人形","reading":"にんぎょう","meaning":"Búp bê","vocabKey":"v:人形"}],"lessonIds":[27,28,30],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 开 (mở) + 彡 (lông/nét trang trí). Hán-Việt: HÌNH. Mẹo nhớ: Đường nét (彡) tạo ra dáng — 'hình' là hình dạng, hình thù 🔷. 7 nét. Âm ケイ (kei), かたち (katachi) = hình dạng. Liên kết: 形 (hình dạng), 人形 (ningyou - búp bê). ⚠️ 人形 (ningyou) = nhân hình = búp bê — đọc đặc biệt.","example":"このコップは丸い**形**をしています。 / kono koppu wa marui katachi wo shite imasu. (Cái cốc này có hình tròn.)","examples":[{"ja":"このコップは丸い形をしています。","vi":"Cái cốc này có hình tròn.","romaji":"kono koppu wa marui katachi wo shite imasu."},{"ja":"変な形","vi":"Hình dạng lạ","romaji":"Henna katachi"},{"ja":"人形を作る","vi":"Làm búp bê","romaji":"ningyou o tsukuru"},{"ja":"この漢字は形が似ていて、覚えにくいです。","vi":"Chữ Hán này có hình giống chữ khác nên khó nhớ.","romaji":"kono kanji wa katachi ga nite ite, oboe nikui desu."}]},{"key":"k:慣","kind":"kanji","level":"N4","character":"慣","meaning":"Quen, quen thuộc","hanviet":"Quán","onReadings":["カン"],"kunReadings":["な","な"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"慣れる","reading":"なれる","meaning":"Quen","vocabKey":"v:慣れる"},{"compound":"習慣","reading":"しゅうかん","meaning":"Thói quen","vocabKey":"v:習慣"}],"lessonIds":[28,36,38],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 忄 (tâm) + 貫. Mẹo nhớ: lặp lại trong lòng nhiều lần sẽ thành thói quen.","example":"日本の生活にだんだん**慣**れてきました。 / nihon no seikatsu ni dandan narete kimashita. (Tôi đã dần quen với cuộc sống ở Nhật.)","examples":[{"ja":"日本の生活にだんだん慣れてきました。","vi":"Tôi đã dần quen với cuộc sống ở Nhật.","romaji":"nippon no seikatsu ni dandan narete kimashita."},{"ja":"生活に慣れる","vi":"Quen với cuộc sống","romaji":"Seikatsu ni nareru"},{"ja":"いい習慣","vi":"Thói quen tốt","romaji":"ii shuukan"},{"ja":"大学を卒業したばかりで、まだ仕事に慣れていません。","vi":"Vì tôi mới tốt nghiệp đại học nên vẫn chưa quen công việc.","romaji":"daigaku o sotsugyou shita bakari de, mada shigoto ni narete imasen."}]},{"key":"k:将","kind":"kanji","level":"N4","character":"将","meaning":"Sẽ, tương lai, tướng","hanviet":"Tướng","onReadings":["ショウ"],"kunReadings":["まさ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"将来","reading":"しょうらい","meaning":"Tương lai","vocabKey":"v:将来"},{"compound":"大将","reading":"たいしょう","meaning":"Đội trưởng/chủ quán"}],"lessonIds":[28],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 寸 + 丬 + 夕 (phân tích học tập). Mẹo nhớ: chỉ điều sắp tới, hướng về tương lai.","example":"**将**来は教師になりたいです。 / shourai wa kyoushi ni naritai desu. (Tương lai tôi muốn trở thành giáo viên.)","examples":[{"ja":"将来は教師になりたいです。","vi":"Tương lai tôi muốn trở thành giáo viên.","romaji":"shourai wa kyoushi ni naritai desu."},{"ja":"将来の夢","vi":"Ước mơ tương lai","romaji":"shourai no yume"},{"ja":"将来","vi":"tương lai","romaji":"shourai"},{"ja":"親は子どもの将来を心配します","vi":"Cha mẹ lo lắng cho tương lai của con cái.","romaji":"Oya wa kodomo no shourai o shinpai shimasu"}]},{"key":"k:眠","kind":"kanji","level":"N4","character":"眠","meaning":"Ngủ, buồn ngủ","hanviet":"Miên","onReadings":["ミン"],"kunReadings":["ねむ","ねむ"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"眠る","reading":"ねむる","meaning":"Ngủ"},{"compound":"眠い","reading":"ねむい","meaning":"Buồn ngủ","vocabKey":"v:眠い"}],"lessonIds":[19,37,44],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 目 (mắt) + 民 (dân). Hán-Việt: MIÊN. Mẹo nhớ: Mắt (目) của dân (民) nhắm lại — 'miên' là ngủ 😴. 10 nét. Âm ミン (min), ねむる (nemuru) = ngủ, ねむい (nemui) = buồn ngủ. Liên kết: 眠る (ngủ), 眠い (buồn ngủ). ⚠️ 眠い (nemui-buồn ngủ) vs 寝る (neru-ngủ/nằm) — 眠 tập trung vào trạng thái, 寝 chỉ hành động.","example":"ゆうべあまり**眠**れませんでした。 / yuube amari nemuremasen deshita. (Tối qua tôi không ngủ được nhiều.)","examples":[{"ja":"ゆうべあまり眠れませんでした。","vi":"Tối qua tôi không ngủ được nhiều.","romaji":"yuube amari nemuremasen deshita."},{"ja":"とても眠い","vi":"Rất buồn ngủ","romaji":"Totemo nemui"},{"ja":"疲れたし、眠いし、もう帰ります。","vi":"Mệt rồi, lại buồn ngủ nữa, nên tôi về đây.","romaji":"tsukareta shi, nemui shi, mou kaerimasu."},{"ja":"この薬を飲めば、よく眠れるようになります。","vi":"Nếu uống thuốc này thì sẽ ngủ ngon được.","romaji":"kono kusuri o nome ba, yoku nemureru you ni narimasu."}]},{"key":"k:優","kind":"kanji","level":"N4","character":"優","meaning":"Ưu tú, dịu dàng","hanviet":"Ưu","onReadings":["ユウ"],"kunReadings":["やさ","すぐ"],"strokeCount":17,"radicals":[],"components":[],"compounds":[{"compound":"優しい","reading":"やさしい","meaning":"Dịu dàng","vocabKey":"v:優しい"},{"compound":"優勝","reading":"ゆうしょう","meaning":"Vô địch"}],"lessonIds":[28,41,43,45],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 亻 (người) + 憂. Mẹo nhớ: người có phẩm chất tốt, vừa giỏi vừa tử tế.","example":"彼はとても**優**しい先生です。 / kare wa totemo yasashii sensei desu. (Thầy ấy là một giáo viên rất hiền.)","examples":[{"ja":"彼はとても優しい先生です。","vi":"Thầy ấy là một giáo viên rất hiền.","romaji":"kare wa totemo yasashii sensei desu."},{"ja":"先生が優しい","vi":"Thầy hiền","romaji":"Sensei ga yasashii"},{"ja":"優しい","vi":"hiền lành, dịu dàng","romaji":"yasashii"},{"ja":"山田さんはだれにでも優しいです","vi":"Anh Yamada tốt bụng với mọi người.","romaji":"Yamada-san wa dare ni demo yasashii desu"}]},{"key":"k:選","kind":"kanji","level":"N4","character":"選","meaning":"Chọn, tuyển chọn","hanviet":"Tuyển","onReadings":["セン"],"kunReadings":["えら"],"strokeCount":15,"radicals":[],"components":[],"compounds":[{"compound":"選ぶ","reading":"えらぶ","meaning":"Chọn","vocabKey":"v:選ぶ"},{"compound":"選手","reading":"せんしゅ","meaning":"Vận động viên"}],"lessonIds":[28,40],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 辶 (đi/chọn hướng) + 巽. Mẹo nhớ: đi qua nhiều lựa chọn để chọn ra phương án đúng.","example":"自分に合うコースを**選**んでください。 / jibun ni au koosu wo erande kudasai. (Hãy chọn khóa học phù hợp với bạn.)","examples":[{"ja":"自分に合うコースを選んでください。","vi":"Hãy chọn khóa học phù hợp với bạn.","romaji":"jibun ni au koosu wo erande kudasai."},{"ja":"プレゼントを選ぶ","vi":"Chọn quà","romaji":"Purezento wo erabu"},{"ja":"交通手段を選ぶ","vi":"Chọn phương tiện giao thông","romaji":"koutsuu shudan o erabu"},{"ja":"子どもに好きなお菓子を選ばせました。","vi":"Tôi đã cho con chọn bánh kẹo mình thích.","romaji":"kodomo ni suki na okashi o eraba semashita."}]},{"key":"k:経","kind":"kanji","level":"N4","character":"経","meaning":"Trải qua, kinh, kinh tế","hanviet":"Kinh","onReadings":["ケイ","キョウ"],"kunReadings":["へ"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"経つ","reading":"たつ","meaning":"Trôi qua"},{"compound":"経験","reading":"けいけん","meaning":"Kinh nghiệm","vocabKey":"v:経験"},{"compound":"経済","reading":"けいざい","meaning":"Kinh tế","vocabKey":"v:経済"}],"lessonIds":[13,28,49],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 糸 (sợi) + 圣. Mẹo nhớ: sợi chỉ chạy xuyên qua như dòng thời gian trôi qua.","example":"日本に来て一年が**経**ちました。 / nihon ni kite ichinen ga tachimashita. (Đã một năm trôi qua kể từ khi tôi đến Nhật.)","examples":[{"ja":"日本に来て一年が経ちました。","vi":"Đã một năm trôi qua kể từ khi tôi đến Nhật.","romaji":"nippon ni kite ichinen ga tachimashita."},{"ja":"いろいろ経験する","vi":"Trải qua nhiều thứ","romaji":"Iroiro keiken suru"},{"ja":"大阪経由で福岡に行く","vi":"Đi Fukuoka qua Osaka","romaji":"oosaka keiyu de fukuoka ni iku"},{"ja":"経済が発展する","vi":"Kinh tế phát triển","romaji":"Keizai ga hatten suru"}]},{"key":"k:喫","kind":"kanji","level":"N4","character":"喫","meaning":"Uống (trà/cafe), thưởng thức","hanviet":"Cật","onReadings":["キツ"],"kunReadings":["-"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"喫茶店","reading":"きっさてん","meaning":"Quán cafe","vocabKey":"v:喫茶店"},{"compound":"喫煙","reading":"きつえん","meaning":"Hút thuốc"}],"lessonIds":[10],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 口 (miệng) + 契 (khế/hợp đồng). Hán-Việt: CẬT. Mẹo nhớ: Miệng (口) thưởng thức — 'cật' là uống, ăn 🍵. 12 nét. Âm キツ (kitsu) trong 喫茶店 (kissaten - quán trà/cafe). Liên kết: 喫茶店 (quán trà). ⚠️ 喫茶店 (kissaten) = cật trà điếm = quán trà — từ văn hóa Nhật Bản.","example":"駅前の**喫**茶店でコーヒーを飲みました。 / ekimae no kissaten de koohii wo nomimashita. (Tôi uống cafe ở quán cafe trước ga.)","examples":[{"ja":"駅前の喫茶店でコーヒーを飲みました。","vi":"Tôi uống cafe ở quán cafe trước ga.","romaji":"ekimae no kissaten de koohii wo nomimashita."},{"ja":"この近くに静かな喫茶店はありませんか。","vi":"Gần đây có quán cà phê yên tĩnh nào không?","romaji":"kono chikaku ni shizuka na kissaten wa arimasen ka."},{"ja":"喫茶店","vi":"quán giải khát, quán cà-phê","romaji":"kissaten"}]},{"key":"k:辺","kind":"kanji","level":"N4","character":"辺","meaning":"Vùng, quanh, bên","hanviet":"Biên","onReadings":["ヘン"],"kunReadings":["あた","べ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"この辺","reading":"このへん","meaning":"Khu vực này"},{"compound":"周辺","reading":"しゅうへん","meaning":"Vùng lân cận","vocabKey":"v:周辺"}],"lessonIds":[29],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 辶 (đi/chuyển động) + 刀 (biến thể). Mẹo nhớ: chỉ khu vực xung quanh một điểm.","example":"この**辺**は静かで住みやすいです。 / kono hen wa shizuka de sumiyasui desu. (Khu này yên tĩnh và dễ sống.)","examples":[{"ja":"この辺は静かで住みやすいです。","vi":"Khu này yên tĩnh và dễ sống.","romaji":"kono atari wa shizuka de sumi yasui desu."},{"ja":"駅の周辺を散歩する","vi":"Đi dạo quanh ga","romaji":"eki no shuuhen o sanpo suru"},{"ja":"この辺にはコンビニしかありません。","vi":"Quanh đây chỉ có cửa hàng tiện lợi thôi.","romaji":"kono atari ni wa konbini shika arimasen."},{"ja":"～辺り","vi":"chỗ ~, vùng xung quanh ~","romaji":"atari"}]},{"key":"k:汚","kind":"kanji","level":"N4","character":"汚","meaning":"Bẩn, dơ","hanviet":"Ô","onReadings":["オ"],"kunReadings":["よご","よご","きたな"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"汚い","reading":"きたない","meaning":"Bẩn","vocabKey":"v:汚い"},{"compound":"汚す","reading":"よごす","meaning":"Làm bẩn","vocabKey":"v:汚す"},{"compound":"汚れる","reading":"よごれる","meaning":"Bị bẩn","vocabKey":"v:汚れる"}],"lessonIds":[37,39],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 氵(nước) + 亏. Hán-Việt: Ô. Mẹo nhớ: Nước (氵) đục bẩn — 'ô' là bẩn, dơ 🤢. 6 nét. Âm オ (o), きたない (kitanai) = bẩn, よごす (yogosu) = làm bẩn. Liên kết: 汚い (bẩn), 汚す (làm bẩn). ⚠️ 汚い (kitanai-bẩn) vs 汚す (yogosu-làm bẩn) vs 汚れる (yogoreru-bị bẩn) — 3 cách dùng.","example":"靴が**汚**れたので洗いました。 / kutsu ga yogoreta node araimashita. (Giày bị bẩn nên tôi đã rửa.)","examples":[{"ja":"靴が汚れたので洗いました。","vi":"Giày bị bẩn nên tôi đã rửa.","romaji":"kutsu ga yogoreta node araimashita."},{"ja":"服を汚す","vi":"Làm bẩn quần áo","romaji":"fuku o kegasu"},{"ja":"服が汚れる","vi":"Quần áo bẩn","romaji":"Fuku ga yogoreru"},{"ja":"部屋が汚い","vi":"Phòng bẩn","romaji":"Heya ga kitanai"}]},{"key":"k:割","kind":"kanji","level":"N4","character":"割","meaning":"Chia, vỡ, tỷ lệ","hanviet":"Cát","onReadings":["カツ"],"kunReadings":["わ","わ","わり"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"割る","reading":"わる","meaning":"Chia/đập vỡ","vocabKey":"v:割る"},{"compound":"割引","reading":"わりびき","meaning":"Giảm giá","vocabKey":"v:割引"},{"compound":"割合","reading":"わりあい","meaning":"Tỷ lệ"}],"lessonIds":[29,33],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 害 (hại) + 刂 (đao). Hán-Việt: CÁT. Mẹo nhớ: Đao (刂) cắt chia — 'cát' là chia, cắt, tỷ lệ ✂️. 12 nét. Âm カツ (katsu), わる (waru) = chia/vỡ, わり (wari) = tỷ lệ. Liên kết: 割る (chia/vỡ), 割引 (waribiki - giảm giá). ⚠️ 割引 (waribiki) = cát dẫn = giảm giá — từ hay gặp khi mua sắm.","example":"お皿を落として**割**ってしまいました。 / osara wo otoshite watte shimaimashita. (Tôi lỡ làm rơi đĩa và vỡ mất.)","examples":[{"ja":"お皿を落として割ってしまいました。","vi":"Tôi lỡ làm rơi đĩa và vỡ mất.","romaji":"o sara o otoshite watsute shimaimashita."},{"ja":"コップを割る","vi":"Làm vỡ cốc","romaji":"koppu o wareru"},{"ja":"ガラスが割れる","vi":"Kính vỡ","romaji":"Garasu ga wareru"},{"ja":"自分の役割を果たす","vi":"Hoàn thành vai trò của mình","romaji":"Jibun no yakuwari wo hata su"}]},{"key":"k:皿","kind":"kanji","level":"N4","character":"皿","meaning":"Đĩa, cái đĩa","hanviet":"Mãnh","onReadings":["ベイ"],"kunReadings":["さら"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"皿","reading":"さら","meaning":"Cái đĩa","vocabKey":"v:皿"},{"compound":"灰皿","reading":"はいざら","meaning":"Gạt tàn"}],"lessonIds":[29],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — hình cái đĩa 🍽️. Hán-Việt: MÃNH. Mẹo nhớ: Nét ngang dài là mặt đĩa, hai bên là thành đĩa — 'mãnh' là cái đĩa. 5 nét. Âm ベイ (bei), さら (sara) = đĩa. Liên kết: 皿 (đĩa), 灰皿 (haizara - gạt tàn). ⚠️ 皿 là bộ thủ quan trọng: 温 (ôn), 監 (giám) đều chứa 皿.","example":"テーブルの上に**皿**が五枚あります。 / teeburu no ue ni sara ga gomai arimasu. (Trên bàn có 5 cái đĩa.)","examples":[{"ja":"テーブルの上に皿が五枚あります。","vi":"Trên bàn có 5 cái đĩa.","romaji":"teeburu no ue ni sara ga gomai arimasu."},{"ja":"お皿を洗う","vi":"Rửa đĩa","romaji":"O sara wo arau"},{"ja":"皿を洗う","vi":"Rửa đĩa","romaji":"Sara wo arau"},{"ja":"お皿が割れています。","vi":"Đĩa bị vỡ.","romaji":"o sara ga warete imasu."}]},{"key":"k:隅","kind":"kanji","level":"N4","character":"隅","meaning":"Góc, xó","hanviet":"Ngung","onReadings":["グウ"],"kunReadings":["すみ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"隅","reading":"すみ","meaning":"Góc/xó","vocabKey":"v:隅"},{"compound":"片隅","reading":"かたすみ","meaning":"Một góc nhỏ"}],"lessonIds":[30],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 阝(gò đất) + 禺 (ngung). Hán-Việt: NGUNG. Mẹo nhớ: Gò đất (阝) ở góc khuất — 'ngung' là góc, xó 📐. 12 nét. Âm グウ (guu), すみ (sumi) = góc. Liên kết: 隅 (góc), 片隅 (katasumi - góc nhỏ). ⚠️ 隅 (sumi-góc phòng) vs 角 (kado-góc đường) — hai từ 'góc' khác nhau.","example":"部屋の**隅**にほこりがたまっています。 / heya no sumi ni hokori ga tamatte imasu. (Bụi tích tụ ở góc phòng.)","examples":[{"ja":"部屋の隅にほこりがたまっています。","vi":"Bụi tích tụ ở góc phòng.","romaji":"heya no sumi ni hokori ga tamatsute imasu."},{"ja":"隅","vi":"góc","romaji":"sumi"}]},{"key":"k:机","kind":"kanji","level":"N4","character":"机","meaning":"Cái bàn","hanviet":"Cơ","onReadings":["キ"],"kunReadings":["つくえ"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"机","reading":"つくえ","meaning":"Cái bàn","vocabKey":"v:机"},{"compound":"机の上","reading":"つくえのうえ","meaning":"Trên bàn"}],"lessonIds":[2],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 木 (gỗ) + 几 (cái kỷ/bàn thấp). Hán-Việt: CƠ. Mẹo nhớ: Gỗ (木) đóng thành bàn thấp (几) — 'cơ' là cái bàn 📝. 6 nét. Âm キ (ki), つくえ (tsukue) = cái bàn. Liên kết: 机 (cái bàn). ⚠️ 机 (tsukue-bàn học) vs テーブル (teeburu-bàn ăn) — 机 thường chỉ bàn học/làm việc.","example":"**机**の上に本が置いてあります。 / tsukue no ue ni hon ga oite arimasu. (Trên bàn có đặt sách.)","examples":[{"ja":"机の上に本が置いてあります。","vi":"Trên bàn có đặt sách.","romaji":"tsukue no ue ni hon ga oite arimasu."},{"ja":"わたしの部屋に机があります。","vi":"Ở phòng của tôi có cái bàn.","romaji":"watashi no heya ni tsukue ga arimasu."},{"ja":"机の上に写真があります。","vi":"Ở trên bàn có bức ảnh.","romaji":"tsukue no ue ni shashin ga arimasu."},{"ja":"机の上にメモが置いてあります。","vi":"Trên bàn có để sẵn mẩu ghi chú.","romaji":"tsukue no ue ni memo ga oite arimasu."}]},{"key":"k:箱","kind":"kanji","level":"N4","character":"箱","meaning":"Hộp, thùng","hanviet":"Tương","onReadings":["ソウ"],"kunReadings":["はこ"],"strokeCount":15,"radicals":[],"components":[],"compounds":[{"compound":"箱","reading":"はこ","meaning":"Cái hộp","vocabKey":"v:箱"},{"compound":"ゴミ箱","reading":"ごみばこ","meaning":"Thùng rác"},{"compound":"本箱","reading":"ほんばこ","meaning":"Kệ sách"}],"lessonIds":[10,30,35],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: ⺮ (tre) + 相 (tương). Hán-Việt: TƯƠNG. Mẹo nhớ: Hộp bằng tre (⺮) đựng đồ — 'tương' là hộp, thùng 📦. 15 nét. Âm ソウ (sou), はこ (hako) = hộp. Liên kết: 箱 (hộp), ゴミ箱 (gomibako - thùng rác). ⚠️ ゴミ箱 (gomibako) = thùng rác — từ sinh hoạt quan trọng.","example":"この**箱**の中に何が入っていますか。 / kono hako no naka ni nani ga haitte imasu ka. (Bên trong hộp này có gì?)","examples":[{"ja":"この箱の中に何が入っていますか。","vi":"Bên trong hộp này có gì?","romaji":"kono hako no naka ni nani ga haitsute imasu ka."},{"ja":"箱を開ける","vi":"Mở hộp","romaji":"Hako wo akeru"},{"ja":"ごみ箱に捨てる","vi":"Bỏ vào thùng rác","romaji":"Gomibako ni suteru"},{"ja":"箱の中に手紙や写真があります。","vi":"Trong hộp có thư và ảnh.","romaji":"hako no naka ni tegami ya shashin ga arimasu."}]},{"key":"k:定","kind":"kanji","level":"N4","character":"定","meaning":"Quyết định, cố định","hanviet":"Định","onReadings":["テイ","ジョウ"],"kunReadings":["さだ"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"予定","reading":"よてい","meaning":"Dự định","vocabKey":"v:予定"},{"compound":"定食","reading":"ていしょく","meaning":"Suất ăn cố định","vocabKey":"v:定食"},{"compound":"決定","reading":"けってい","meaning":"Quyết định"}],"lessonIds":[13,30],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 宀 (mái nhà) + 疋. Mẹo nhớ: dưới mái nhà mọi thứ được sắp xếp cố định.","example":"来週の**定**休日は水曜日です。 / raishuu no teikyuubi wa suiyoubi desu. (Ngày nghỉ cố định tuần tới là thứ Tư.)","examples":[{"ja":"来週の定休日は水曜日です。","vi":"Ngày nghỉ cố định tuần tới là thứ Tư.","romaji":"raishuu no teikyuubi wa suiyoubi desu."},{"ja":"定食を注文する","vi":"Gọi suất ăn","romaji":"teishoku o chuumon suru"},{"ja":"定期券を更新する","vi":"Gia hạn vé tháng","romaji":"teikiken o koushin suru"},{"ja":"到着予定は明日の午前です","vi":"Dự kiến đến vào sáng mai","romaji":"touchaku yotei wa ashita no gozen desu"}]},{"key":"k:置","kind":"kanji","level":"N4","character":"置","meaning":"Đặt, để","hanviet":"Trí","onReadings":["チ"],"kunReadings":["お"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"置く","reading":"おく","meaning":"Đặt","vocabKey":"v:置く"},{"compound":"位置","reading":"いち","meaning":"Vị trí"}],"lessonIds":[15,26],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 罒 (lưới) + 直 (thẳng). Hán-Việt: TRÍ. Mẹo nhớ: Để thẳng (直) vào vị trí — 'trí' là đặt, để 📌. 13 nét. Âm チ (chi), おく (oku) = đặt/để. Liên kết: 置く (đặt), 位置 (ichi - vị trí). ⚠️ 置く (oku) = đặt — động từ cơ bản; 〜ておく (te oku) = làm sẵn trước.","example":"鍵をテーブルの上に**置**いてください。 / kagi wo teeburu no ue ni oite kudasai. (Hãy đặt chìa khóa lên bàn.)","examples":[{"ja":"鍵をテーブルの上に置いてください。","vi":"Hãy đặt chìa khóa lên bàn.","romaji":"kagi wo teeburu no ue ni oite kudasai."},{"ja":"机の上に置く","vi":"Đặt trên bàn","romaji":"Tsukue no ue ni oku"},{"ja":"物置に箱を入れる","vi":"Cho hộp vào kho","romaji":"monooki ni hako o ireru"},{"ja":"棚に本を置きます。","vi":"Đặt sách lên giá.","romaji":"tana ni hon o okimasu."}]},{"key":"k:掛","kind":"kanji","level":"N4","character":"掛","meaning":"Treo, mắc","hanviet":"Quải","onReadings":["カイ"],"kunReadings":["か","か"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"掛ける","reading":"かける","meaning":"Treo","vocabKey":"v:掛ける"},{"compound":"腰掛ける","reading":"こしかける","meaning":"Ngồi ghế"}],"lessonIds":[29,30,38,50],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 扌(tay) + 卦 (quải). Hán-Việt: QUẢI. Mẹo nhớ: Tay (扌) treo đồ lên — 'quải' là treo, mắc 🪝. 11 nét. Âm カ (ka), かける (kakeru) = treo/mắc, かかる (kakaru) = bị treo/tốn. Liên kết: 掛ける (treo), 時計を掛ける (treo đồng hồ). ⚠️ 掛かる (kakaru-tốn) vs 掛ける (kakeru-treo) — cặp tự/tha.","example":"壁に絵を**掛**けました。 / kabe ni e wo kakemashita. (Tôi đã treo tranh lên tường.)","examples":[{"ja":"壁に絵を掛けました。","vi":"Tôi đã treo tranh lên tường.","romaji":"kabe ni e wo kakemashita."},{"ja":"電話を掛ける","vi":"Gọi điện","romaji":"Denwa wo kakeru"},{"ja":"こちらにお掛けください。","vi":"Xin mời ngồi đây.","romaji":"kochira ni o kake kudasai."},{"ja":"掛かります","vi":"đóng, khóa","romaji":"kakarimasu"}]},{"key":"k:片","kind":"kanji","level":"N4","character":"片","meaning":"Mảnh, một bên","hanviet":"Phiến","onReadings":["ヘン"],"kunReadings":["かた"],"strokeCount":4,"radicals":[],"components":[],"compounds":[{"compound":"片付ける","reading":"かたづける","meaning":"Dọn dẹp","vocabKey":"v:片付ける"},{"compound":"片道","reading":"かたみち","meaning":"Một chiều","vocabKey":"v:片道"}],"lessonIds":[26,29,30],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — nửa phần cây chẻ đôi. Hán-Việt: PHIẾN. Mẹo nhớ: Nửa cây chẻ ra — 'phiến' là mảnh, một bên 🪵. 4 nét. Âm ヘン (hen), かた (kata) = một bên. Liên kết: 片付ける (katazukeru - dọn dẹp), 片道 (katamichi - một chiều). ⚠️ 片付ける (katazukeru) = dọn dẹp — từ hay gặp hàng ngày.","example":"部屋を**片**付けてから出かけます。 / heya wo katadukete kara dekakemasu. (Tôi dọn phòng xong rồi mới ra ngoài.)","examples":[{"ja":"部屋を片付けてから出かけます。","vi":"Tôi dọn phòng xong rồi mới ra ngoài.","romaji":"heya o katazukete kara dekakemasu."},{"ja":"部屋が片付いた","vi":"Phòng đã gọn","romaji":"Heya ga katazuita"},{"ja":"部屋を片付けなさい","vi":"Dọn phòng đi","romaji":"Heya wo katazuke nasai"},{"ja":"部屋を片づける","vi":"Dọn phòng","romaji":"Heya wo katazukeru"}]},{"key":"k:復","kind":"kanji","level":"N4","character":"復","meaning":"Phục hồi, lại","hanviet":"Phục","onReadings":["フク"],"kunReadings":["ー"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"復習","reading":"ふくしゅう","meaning":"Ôn tập","vocabKey":"v:復習"},{"compound":"回復","reading":"かいふく","meaning":"Hồi phục"}],"lessonIds":[30],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 彳 (bước đi) + 复 (phục/lặp). Hán-Việt: PHỤC. Mẹo nhớ: Bước đi (彳) quay lại — 'phục' là phục hồi, lại 🔄. 12 nét. Âm フク (fuku) trong 復習 (fukushuu - ôn tập). Liên kết: 復習 (ôn tập), 回復 (kaifuku - hồi phục). ⚠️ 復習 (fukushuu) = phục tập = ôn tập — quan trọng cho người học.","example":"テストの前に**復**習しなければなりません。 / tesuto no mae ni fukushuu shinakereba narimasen. (Trước khi thi phải ôn tập.)","examples":[{"ja":"テストの前に復習しなければなりません。","vi":"Trước khi thi phải ôn tập.","romaji":"tesuto no mae ni fukushuu shinakereba narimasen."},{"ja":"授業の後で復習する","vi":"Ôn lại sau giờ học","romaji":"jugyou no nochi de fukushuu suru"},{"ja":"授業の復習をする","vi":"Ôn lại bài học","romaji":"jugyou no fukushuu o suru"},{"ja":"往復切符のほうが安いです","vi":"Vé khứ hồi rẻ hơn","romaji":"oufuku kippu no hou ga yasui desu"}]},{"key":"k:務","kind":"kanji","level":"N4","character":"務","meaning":"Nhiệm vụ, công vụ","hanviet":"Vụ","onReadings":["ム"],"kunReadings":["つと"],"strokeCount":11,"radicals":[],"components":[],"compounds":[{"compound":"事務所","reading":"じむしょ","meaning":"Văn phòng","vocabKey":"v:事務所"},{"compound":"公務員","reading":"こうむいん","meaning":"Công chức"}],"lessonIds":[3],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 矛 (giáo) + 攵 + 力 (sức). Hán-Việt: VỤ. Mẹo nhớ: Dồn sức (力) làm việc — 'vụ' là nhiệm vụ, công vụ 💼. 11 nét. Âm ム (mu) trong 事務所 (jimusho - văn phòng). Liên kết: 事務所 (văn phòng), 公務員 (koumuin - công chức). ⚠️ 事務所 (jimusho) = sự vụ sở = văn phòng — từ thực dụng.","example":"**務**め先は駅の近くにあります。 / tsutomesaki wa eki no chikaku ni arimasu. (Nơi làm việc ở gần ga.)","examples":[{"ja":"務め先は駅の近くにあります。","vi":"Nơi làm việc ở gần ga.","romaji":"tsutomesaki wa eki no chikaku ni arimasu."},{"ja":"事務所で働く","vi":"Làm việc ở văn phòng","romaji":"Jimusho de hataraku"},{"ja":"山田さんは事務所です。","vi":"Anh Yamada ở văn phòng.","romaji":"yamada san wa jimusho desu."},{"ja":"ミラーさんはどこにいますか。……事務所にいます。","vi":"Anh Miller ở đâu? Ở văn phòng.","romaji":"miraa san wa doko ni imasu ka....... jimusho ni imasu."}]},{"key":"k:飛","kind":"kanji","level":"N4","character":"飛","meaning":"Bay","hanviet":"Phi","onReadings":["ヒ"],"kunReadings":["と","と"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"飛ぶ","reading":"とぶ","meaning":"Bay","vocabKey":"v:飛ぶ"},{"compound":"飛行機","reading":"ひこうき","meaning":"Máy bay","vocabKey":"v:飛行機"}],"lessonIds":[5,26,27],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — hình chim xòe cánh bay. Hán-Việt: PHI. Mẹo nhớ: Đôi cánh mở rộng bay lên — 'phi' là bay ✈️. 9 nét. Âm ヒ (hi), とぶ (tobu) = bay. Liên kết: 飛ぶ (bay), 飛行機 (hikouki - máy bay). ⚠️ 飛行機 (hikouki) = phi hành cơ = máy bay — từ ghép quan trọng.","example":"**飛**行機で大阪へ行きます。 / hikouki de oosaka e ikimasu. (Tôi đi Osaka bằng máy bay.)","examples":[{"ja":"飛行機で大阪へ行きます。","vi":"Tôi đi Osaka bằng máy bay.","romaji":"hikouki de oosaka e ikimasu."},{"ja":"鳥が飛ぶ","vi":"Chim bay","romaji":"Tori ga tobu"},{"ja":"飛行機で行く","vi":"Đi bằng máy bay","romaji":"hikouki de iku"},{"ja":"飛行機は午後2時に着く予定です。","vi":"Máy bay dự kiến đến lúc 2 giờ chiều.","romaji":"hikouki wa gogo 2ji ni tsuku yotei desu."}]},{"key":"k:機","kind":"kanji","level":"N4","character":"機","meaning":"Máy, cơ hội","hanviet":"Cơ","onReadings":["キ"],"kunReadings":["はた"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"飛行機","reading":"ひこうき","meaning":"Máy bay","vocabKey":"v:飛行機"},{"compound":"機会","reading":"きかい","meaning":"Cơ hội","vocabKey":"v:機会"},{"compound":"洗濯機","reading":"せんたくき","meaning":"Máy giặt","vocabKey":"v:洗濯機"}],"lessonIds":[3,5,23,27,28,35],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 木 (gỗ) + 幾 (mấy/cơ hội). Hán-Việt: CƠ. Mẹo nhớ: Máy gỗ (木) tinh vi — 'cơ' là máy, cơ hội ⚙️. 16 nét. Âm キ (ki) trong 飛行機 (hikouki - máy bay). Liên kết: 機会 (kikai - cơ hội), 飛行機 (máy bay). ⚠️ 机 (tsukue-bàn, 6 nét) vs 機 (ki-máy, 16 nét) — cùng âm CƠ nhưng khác nghĩa!","example":"この洗濯**機**は新しくて使いやすいです。 / kono sentakuki wa atarashikute tsukaiyasui desu. (Máy giặt này mới và dễ dùng.)","examples":[{"ja":"この洗濯機は新しくて使いやすいです。","vi":"Máy giặt này mới và dễ dùng.","romaji":"kono sentakuki wa atarashikute tsukaiyasui desu."},{"ja":"機械が壊れた","vi":"Máy hỏng","romaji":"Kikai ga kowareta"},{"ja":"飛行機で行く","vi":"Đi bằng máy bay","romaji":"hikouki de iku"},{"ja":"信号機が青になった","vi":"Đèn giao thông chuyển xanh","romaji":"shingouki ga ao ni natsuta"}]},{"key":"k:普","kind":"kanji","level":"N4","character":"普","meaning":"Phổ biến, thông thường","hanviet":"Phổ","onReadings":["フ"],"kunReadings":["ー"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"普通","reading":"ふつう","meaning":"Bình thường","vocabKey":"v:普通"},{"compound":"普段","reading":"ふだん","meaning":"Thường ngày"}],"lessonIds":[5,48],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 並 + 日. Mẹo nhớ: giống như mặt trời mọc hàng ngày, điều bình thường.","example":"**普**通は電車で会社に行きます。 / futsuu wa densha de kaisha ni ikimasu. (Thường thì tôi đi tàu đến công ty.)","examples":[{"ja":"普通は電車で会社に行きます。","vi":"Thường thì tôi đi tàu đến công ty.","romaji":"futsuu wa densha de kaisha ni ikimasu."},{"ja":"普通の生活がしたい","vi":"Muốn sống bình thường","romaji":"futsuu no seikatsu ga shitai"},{"ja":"次の「普通」ですよ。","vi":"Chuyến tàu thường tiếp theo mới đi cơ.","romaji":"tsugi no\\" futsuu\\" desu yo."},{"ja":"普通","vi":"tàu thường","romaji":"futsuu"}]},{"key":"k:式","kind":"kanji","level":"N4","character":"式","meaning":"Nghi lễ, kiểu cách","hanviet":"Thức","onReadings":["シキ"],"kunReadings":["ー"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"結婚式","reading":"けっこんしき","meaning":"Lễ cưới","vocabKey":"v:結婚式"},{"compound":"卒業式","reading":"そつぎょうしき","meaning":"Lễ tốt nghiệp"},{"compound":"方式","reading":"ほうしき","meaning":"Phương thức"}],"lessonIds":[31],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 弋 (dặc/cọc) + 工 (công). Hán-Việt: THỨC. Mẹo nhớ: Dựng cọc (弋) kiểu cách — 'thức' là nghi lễ, kiểu cách 🎓. 6 nét. Âm シキ (shiki) trong 卒業式 (sotsugyoushiki - lễ tốt nghiệp). Liên kết: 結婚式 (kekkonshiki - lễ cưới), 卒業式 (lễ tốt nghiệp). ⚠️ 〜式 (-shiki) = lễ ~ — hậu tố nghi lễ phổ biến.","example":"来月友達の結婚**式**に出席します。 / raigetsu tomodachi no kekkonshiki ni shusseki shimasu. (Tháng tới tôi dự lễ cưới của bạn.)","examples":[{"ja":"来月友達の結婚式に出席します。","vi":"Tháng tới tôi dự lễ cưới của bạn.","romaji":"raigetsu tomodachi no kekkonshiki ni shusseki shimasu."},{"ja":"結婚式に出る","vi":"Tham dự lễ cưới","romaji":"Kekkonshiki ni deru"},{"ja":"結婚式に招待された","vi":"Được mời dự đám cưới","romaji":"kekkonshiki ni shoutai sa reta"},{"ja":"『源氏物語』は紫式部によって書かれました。","vi":"'Truyện Genji' được Murasaki Shikibu viết.","romaji":"\\" genjimonogatari\\" wa murasakishikibu niyotte kaka remashita."}]},{"key":"k:連","kind":"kanji","level":"N4","character":"連","meaning":"Liên tiếp, dẫn theo","hanviet":"Liên","onReadings":["レン"],"kunReadings":["つ","つら"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"連れる","reading":"つれる","meaning":"Dẫn theo","vocabKey":"v:連れる"},{"compound":"連絡","reading":"れんらく","meaning":"Liên lạc","vocabKey":"v:連絡"},{"compound":"連休","reading":"れんきゅう","meaning":"Ngày nghỉ liên tiếp","vocabKey":"v:連休"}],"lessonIds":[24,26,31,42],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 辶 (di chuyển) + 車 (xe). Hán-Việt: LIÊN. Mẹo nhớ: Xe (車) nối nhau di chuyển (辶) — 'liên' là liên tiếp, dẫn theo 🔗. 10 nét. Âm レン (ren), つれる (tsureru) = dẫn theo. Liên kết: 連れる (dẫn theo), 連絡 (renraku - liên lạc). ⚠️ 連絡 (renraku) = liên lạc — từ giao tiếp cực quan trọng.","example":"犬を**連**れて公園を散歩しました。 / inu wo tsurete kouen wo sanpo shimashita. (Tôi dắt chó đi dạo công viên.)","examples":[{"ja":"犬を連れて公園を散歩しました。","vi":"Tôi dắt chó đi dạo công viên.","romaji":"inu wo tsurete kouen wo sanpo shimashita."},{"ja":"子供を連れる","vi":"Dẫn con","romaji":"Kodomo wo tsureru"},{"ja":"電話で連絡する","vi":"Liên lạc bằng điện thoại","romaji":"Denwa de renraku suru"},{"ja":"ゴールデンウィークは長い連休です","vi":"Golden Week là kỳ nghỉ dài","romaji":"gooruden'uiiku wa nagai renkyuu desu"}]},{"key":"k:星","kind":"kanji","level":"N4","character":"星","meaning":"Ngôi sao","hanviet":"Tinh","onReadings":["セイ"],"kunReadings":["ほし"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"星","reading":"ほし","meaning":"Ngôi sao","vocabKey":"v:星"},{"compound":"星座","reading":"せいざ","meaning":"Chòm sao"}],"lessonIds":[26,32],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 日 (mặt trời) + 生 (sống). Mẹo nhớ: ánh sáng sống trên bầu trời đêm là ngôi sao.","example":"今夜は**星**がたくさん見えます。 / konya wa hoshi ga takusan miemasu. (Tối nay nhìn thấy nhiều sao.)","examples":[{"ja":"今夜は星がたくさん見えます。","vi":"Tối nay nhìn thấy nhiều sao.","romaji":"konya wa hoshi ga takusan miemasu."},{"ja":"星が見える","vi":"Nhìn thấy sao","romaji":"Hoshi ga mieru"},{"ja":"星空を見上げる","vi":"Ngước nhìn bầu trời đầy sao","romaji":"Hoshizora wo miageru"},{"ja":"星出彰彦","vi":"nhà du hành vũ trụ người Nhật Bản","romaji":"hoshi izuru akihiko"}]},{"key":"k:乳","kind":"kanji","level":"N4","character":"乳","meaning":"Sữa","hanviet":"Nhũ","onReadings":["ニュウ"],"kunReadings":["ちち","ち"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"牛乳","reading":"ぎゅうにゅう","meaning":"Sữa bò","vocabKey":"v:牛乳"},{"compound":"乳製品","reading":"にゅうせいひん","meaning":"Sản phẩm từ sữa"}],"lessonIds":[6],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 孚 (ấp/ôm) biến thể. Hán-Việt: NHŨ. Mẹo nhớ: Hình ảnh bà mẹ cho con bú — 'nhũ' là sữa 🍼. 8 nét. Âm ニュウ (nyuu), ちち (chichi) = sữa. Liên kết: 牛乳 (gyuunyuu - sữa bò). ⚠️ 牛乳 (gyuunyuu) = ngưu nhũ = sữa bò — cách nói trang trọng hơn ミルク.","example":"毎朝**乳**を飲みます。 / maiasa gyuunyuu wo nomimasu. (Mỗi sáng tôi uống sữa.)","examples":[{"ja":"毎朝乳を飲みます。","vi":"Mỗi sáng tôi uống sữa.","romaji":"maiasa chichi o nomimasu."},{"ja":"牛乳を飲む","vi":"Uống sữa","romaji":"gyuunyuu o nomu"},{"ja":"バターは牛乳から作られます。","vi":"Bơ được làm từ sữa bò.","romaji":"bataa wa gyuunyuu kara tsukura remasu."},{"ja":"母は子どもに毎朝牛乳を飲ませます。","vi":"Mẹ cho con uống sữa mỗi sáng.","romaji":"haha wa kodomo ni maiasa gyuunyuu o noma semasu."}]},{"key":"k:勝","kind":"kanji","level":"N4","character":"勝","meaning":"Thắng","hanviet":"Thắng","onReadings":["ショウ"],"kunReadings":["か","まさ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"勝つ","reading":"かつ","meaning":"Thắng","vocabKey":"v:勝つ"},{"compound":"優勝","reading":"ゆうしょう","meaning":"Vô địch"},{"compound":"勝負","reading":"しょうぶ","meaning":"Thắng thua"}],"lessonIds":[4,11,21,45],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 月 (thịt) + 力 (sức) + phần trên. Hán-Việt: THẮNG. Mẹo nhớ: Dùng sức (力) để chiến — 'thắng' là thắng, giành chiến thắng 🏆. 12 nét. Âm ショウ (shou), かつ (katsu) = thắng. Liên kết: 勝つ (thắng), 優勝 (yuushou - vô địch). ⚠️ 勝つ (katsu-thắng) vs 負ける (makeru-thua) — cặp từ đối lập.","example":"サッカーの試合に**勝**ちました。 / sakkaa no shiai ni kachimashita. (Chúng tôi đã thắng trận bóng đá.)","examples":[{"ja":"サッカーの試合に勝ちました。","vi":"Chúng tôi đã thắng trận bóng đá.","romaji":"sakkaa no shiai ni kachimashita."},{"ja":"試合に勝つ","vi":"Thắng trận đấu","romaji":"Shiai ni katsu"},{"ja":"勝ちます","vi":"thắng","romaji":"kachimasu"},{"ja":"今年こそ優勝したいです","vi":"Năm nay tôi rất muốn giành chức vô địch.","romaji":"Kotoshi koso yuushou shitai desu"}]},{"key":"k:負","kind":"kanji","level":"N4","character":"負","meaning":"Thua, gánh chịu","hanviet":"Phụ","onReadings":["フ"],"kunReadings":["ま","お"],"strokeCount":9,"radicals":[],"components":[],"compounds":[{"compound":"負ける","reading":"まける","meaning":"Thua","vocabKey":"v:負ける"},{"compound":"勝負","reading":"しょうぶ","meaning":"Thắng thua"},{"compound":"負担","reading":"ふたん","meaning":"Gánh nặng"}],"lessonIds":[21],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: gốc từ người (人) cõng tiền (貝). Hán-Việt: PHỤ. Mẹo nhớ: Gánh nặng quá lớn — 'phụ' là thua, gánh chịu 😞. 9 nét. Âm フ (fu), まける (makeru) = thua. Liên kết: 負ける (thua), 勝負 (shoubu - thắng thua). ⚠️ 負ける (makeru-thua) vs 勝つ (katsu-thắng); 勝負 = thắng phụ = cuộc thi đấu.","example":"試合に**負**けて悔しかったです。 / shiai ni makete kuyashikatta desu. (Thua trận rất tiếc.)","examples":[{"ja":"試合に負けて悔しかったです。","vi":"Thua trận rất tiếc.","romaji":"shiai ni makete kuyashikatsuta desu."},{"ja":"試合に負ける","vi":"Thua trận đấu","romaji":"Shiai ni makeru"},{"ja":"負けます","vi":"thua","romaji":"makemasu"}]},{"key":"k:続","kind":"kanji","level":"N4","character":"続","meaning":"Tiếp tục","hanviet":"Tục","onReadings":["ゾク"],"kunReadings":["つづ","つづ"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"続ける","reading":"つづける","meaning":"Tiếp tục","vocabKey":"v:続ける"},{"compound":"続く","reading":"つづく","meaning":"Kéo dài","vocabKey":"v:続く"},{"compound":"手続き","reading":"てつづき","meaning":"Thủ tục","vocabKey":"v:手続き"}],"lessonIds":[31,32],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 糸 (tơ) + 売 biến thể. Hán-Việt: TỤC. Mẹo nhớ: Sợi tơ (糸) kéo dài không đứt — 'tục' là tiếp tục ➡️. 13 nét. Âm ゾク (zoku), つづく (tsuzuku) = tiếp tục, つづける (tsuzukeru) = tiếp tục làm. Liên kết: 続く (tiếp tục), 続ける (tiếp tục làm). ⚠️ 続く (tsuzuku-tự tiếp) vs 続ける (tsuzukeru-làm tiếp) — cặp tự/tha.","example":"日本語の勉強を**続**けています。 / nihongo no benkyou wo tsudukete imasu. (Tôi đang tiếp tục học tiếng Nhật.)","examples":[{"ja":"日本語の勉強を続けています。","vi":"Tôi đang tiếp tục học tiếng Nhật.","romaji":"nihongo no benkyou o tsuzukete imasu."},{"ja":"雨が続く","vi":"Mưa tiếp tục","romaji":"Ame ga tsuzuku"},{"ja":"勉強を続ける","vi":"Tiếp tục học","romaji":"benkyou o tsuzukeru"},{"ja":"入学の手続きをする","vi":"Làm thủ tục nhập học","romaji":"nyuugaku no tetsuzuki o suru"}]},{"key":"k:直","kind":"kanji","level":"N4","character":"直","meaning":"Thẳng, sửa","hanviet":"Trực","onReadings":["チョク","ジキ"],"kunReadings":["なお","なお"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"直す","reading":"なおす","meaning":"Sửa","vocabKey":"v:直す"},{"compound":"直る","reading":"なおる","meaning":"Được sửa","vocabKey":"v:直る"},{"compound":"直接","reading":"ちょくせつ","meaning":"Trực tiếp","vocabKey":"v:直接"}],"lessonIds":[20,26,35],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 十 + 目 + 𠃊. Mẹo nhớ: nhìn thẳng không lệch, cái gì sai thì sửa lại cho thẳng.","example":"壊れた時計を**直**してもらいました。 / kowareta tokei wo naoshite moraimashita. (Tôi đã nhờ sửa đồng hồ bị hỏng.)","examples":[{"ja":"壊れた時計を直してもらいました。","vi":"Tôi đã nhờ sửa đồng hồ bị hỏng.","romaji":"kowareta tokei wo naoshite moraimashita."},{"ja":"車を直す","vi":"Sửa xe","romaji":"Kuruma wo naosu"},{"ja":"風邪が直る","vi":"Khỏi cảm","romaji":"Kaze ga naoru"},{"ja":"欠点も正直に話す","vi":"Nói thật cả khuyết điểm","romaji":"ketten mo shoujiki ni hanasu"}]},{"key":"k:治","kind":"kanji","level":"N4","character":"治","meaning":"Chữa trị, cai trị","hanviet":"Trị","onReadings":["チ","ジ"],"kunReadings":["なお","なお"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"治す","reading":"なおす","meaning":"Chữa trị"},{"compound":"治る","reading":"なおる","meaning":"Khỏi bệnh"},{"compound":"政治","reading":"せいじ","meaning":"Chính trị","vocabKey":"v:政治"}],"lessonIds":[21,35,42],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 氵(nước) + 台 (đài). Hán-Việt: TRỊ. Mẹo nhớ: Nước (氵) chảy đúng hướng — 'trị' là chữa trị, cai trị 🏥. 8 nét. Âm ジ、チ (ji, chi), なおる (naoru) = khỏi bệnh, なおす (naosu) = chữa. Liên kết: 治る (khỏi bệnh), 政治 (seiji - chính trị). ⚠️ 治る (naoru-khỏi) vs 直る (naoru-sửa được) — đồng âm khác kanji.","example":"風邪が早く**治**るといいですね。 / kaze ga hayaku naoru to ii desu ne. (Mong bạn sớm khỏi cảm.)","examples":[{"ja":"風邪が早く治るといいですね。","vi":"Mong bạn sớm khỏi cảm.","romaji":"kaze ga hayaku naoru to ii desu ne."},{"ja":"政治に興味がある","vi":"Quan tâm chính trị","romaji":"seiji ni kyoumi ga aru"},{"ja":"政治","vi":"chính trị","romaji":"seiji"},{"ja":"治ります、直ります","vi":"khỏi, được sửa xong","romaji":"naorimasu, naorimasu"}]},{"key":"k:登","kind":"kanji","level":"N4","character":"登","meaning":"Leo, đăng ký","hanviet":"Đăng","onReadings":["トウ","ト"],"kunReadings":["のぼ"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"登る","reading":"のぼる","meaning":"Leo","vocabKey":"v:登る"},{"compound":"登山","reading":"とざん","meaning":"Leo núi","vocabKey":"v:登山"},{"compound":"登録","reading":"とうろく","meaning":"Đăng ký","vocabKey":"v:登録"}],"lessonIds":[13,19,35],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 癶 (hai chân bước) + 豆 (đậu). Hán-Việt: ĐĂNG. Mẹo nhớ: Hai chân (癶) bước lên cao — 'đăng' là leo, đăng ký ⛰️. 12 nét. Âm トウ、ト (tou, to), のぼる (noboru) = leo. Liên kết: 登る (leo), 登山 (tozan - leo núi). ⚠️ 登る (noboru-leo) vs 上る (noboru-lên) — 登 nhấn mạnh leo trèo.","example":"去年の夏、富士山に**登**りました。 / kyonen no natsu, fujisan ni noborimashita. (Mùa hè năm ngoái tôi đã leo núi Phú Sĩ.)","examples":[{"ja":"去年の夏、富士山に登りました。","vi":"Mùa hè năm ngoái tôi đã leo núi Phú Sĩ.","romaji":"kyonen no natsu, fujisan ni noborimashita."},{"ja":"山に登る","vi":"Leo núi","romaji":"Yama ni noboru"},{"ja":"登山が趣味です","vi":"Sở thích là leo núi","romaji":"Tozan ga shumi de su"},{"ja":"一度富士山に登ってみたいです。","vi":"Tôi muốn thử leo núi Phú Sĩ một lần.","romaji":"ichido fujisan ni nobotsute mitai desu."}]},{"key":"k:戻","kind":"kanji","level":"N4","character":"戻","meaning":"Quay về, trả lại","hanviet":"Lệ","onReadings":["レイ"],"kunReadings":["もど","もど"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"戻る","reading":"もどる","meaning":"Quay về","vocabKey":"v:戻る"},{"compound":"戻す","reading":"もどす","meaning":"Trả lại","vocabKey":"v:戻す"}],"lessonIds":[30,33],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 戸 (cửa) + 大 (lớn). Hán-Việt: LỆ. Mẹo nhớ: Quay về qua cửa (戸) lớn (大) — 'lệ' là quay về, trả lại 🔙. 7 nét. Âm レイ (rei), もどる (modoru) = quay về, もどす (modosu) = trả lại. Liên kết: 戻る (quay về), 戻す (trả lại). ⚠️ 戻る (modoru-tự về) vs 戻す (modosu-trả lại) — cặp tự/tha động từ.","example":"忘れ物を取りに家に**戻**りました。 / wasuremono wo tori ni ie ni modorimashita. (Tôi quay về nhà lấy đồ bỏ quên.)","examples":[{"ja":"忘れ物を取りに家に戻りました。","vi":"Tôi quay về nhà lấy đồ bỏ quên.","romaji":"wasuremono wo tori ni ie ni modorimashita."},{"ja":"家に戻る","vi":"Quay về nhà","romaji":"Ie ni modoru"},{"ja":"本を棚に戻す","vi":"Trả sách lên kệ","romaji":"Hon wo tana ni modosu"},{"ja":"はさみを使ったら、元の所に戻しておいてください。","vi":"Sau khi dùng xong kéo, hãy cất lại chỗ cũ.","romaji":"hasami o tsukatsu tara, moto no tokoro ni modoshite oite kudasai."}]},{"key":"k:付","kind":"kanji","level":"N4","character":"付","meaning":"Gắn, dán","hanviet":"Phụ","onReadings":["フ"],"kunReadings":["つ","つ"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"付ける","reading":"つける","meaning":"Gắn","vocabKey":"v:付ける"},{"compound":"受付","reading":"うけつけ","meaning":"Quầy lễ tân","vocabKey":"v:受付"},{"compound":"気付く","reading":"きづく","meaning":"Nhận ra"}],"lessonIds":[3,27,34,35],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 亻(người) + 寸 (tấc). Hán-Việt: PHỤ. Mẹo nhớ: Người (亻) đưa tay (寸) gắn vào — 'phụ' là gắn, dán 📎. 5 nét. Âm フ (fu), つける (tsukeru) = gắn, つく (tsuku) = dính. Liên kết: 付ける (gắn), 気を付ける (ki wo tsukeru - cẩn thận). ⚠️ 気を付けて (ki wo tsukete) = cẩn thận nhé — câu chào phổ biến.","example":"名前のシールを荷物に**付**けてください。 / namae no shiiru wo nimotsu ni tsukete kudasai. (Hãy dán nhãn tên lên hành lý.)","examples":[{"ja":"名前のシールを荷物に付けてください。","vi":"Hãy dán nhãn tên lên hành lý.","romaji":"namae no shiiru wo nimotsu ni tsukete kudasai."},{"ja":"部屋が片付いた","vi":"Phòng đã gọn","romaji":"Heya ga katazuita"},{"ja":"服に泥が付く","vi":"Bùn dính vào quần áo","romaji":"Fuku ni doro ga tsuku"},{"ja":"部屋を片付けなさい","vi":"Dọn phòng đi","romaji":"Heya wo katazuke nasai"}]},{"key":"k:角","kind":"kanji","level":"N4","character":"角","meaning":"Góc, sừng","hanviet":"Giác","onReadings":["カク"],"kunReadings":["かど","つの"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"角","reading":"かど","meaning":"Góc","vocabKey":"v:角"},{"compound":"三角","reading":"さんかく","meaning":"Tam giác"},{"compound":"角度","reading":"かくど","meaning":"Góc độ"}],"lessonIds":[23],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — hình cái sừng thú. Hán-Việt: GIÁC. Mẹo nhớ: Hình sừng nhọn — 'giác' là góc, sừng 🦌. 7 nét. Âm カク (kaku), かど (kado) = góc đường. Liên kết: 角 (góc), 三角 (sankaku - tam giác). ⚠️ 角 (kado-góc đường) vs 隅 (sumi-góc phòng) — hai loại 'góc' khác nhau.","example":"あの**角**を右に曲がってください。 / ano kado wo migi ni magatte kudasai. (Hãy rẽ phải ở góc kia.)","examples":[{"ja":"あの角を右に曲がってください。","vi":"Hãy rẽ phải ở góc kia.","romaji":"ano kaku o migi ni magatsute kudasai."},{"ja":"角を曲がる","vi":"Rẽ ở góc","romaji":"kaku o magaru"},{"ja":"角","vi":"góc","romaji":"kaku"}]},{"key":"k:席","kind":"kanji","level":"N4","character":"席","meaning":"Chỗ ngồi, buổi tiệc","hanviet":"Tịch","onReadings":["セキ"],"kunReadings":["ー"],"strokeCount":10,"radicals":[],"components":[],"compounds":[{"compound":"席","reading":"せき","meaning":"Chỗ ngồi","vocabKey":"v:席"},{"compound":"出席","reading":"しゅっせき","meaning":"Có mặt"},{"compound":"欠席","reading":"けっせき","meaning":"Vắng mặt"}],"lessonIds":[33],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 广 (mái nhà) + 席. Mẹo nhớ: vị trí dưới mái nhà dành cho người ngồi.","example":"授業に**席**がまだ空いています。 / jugyou ni seki ga mada aite imasu. (Vẫn còn chỗ trống trong lớp học.)","examples":[{"ja":"授業に席がまだ空いています。","vi":"Vẫn còn chỗ trống trong lớp học.","romaji":"jugyou ni seki ga mada aite imasu."},{"ja":"会議に出席する","vi":"Tham dự cuộc họp","romaji":"Kaigi ni shusseki suru"},{"ja":"授業を欠席する","vi":"Vắng tiết học","romaji":"jugyou o kesseki suru"},{"ja":"席に座る","vi":"Ngồi vào ghế","romaji":"Seki ni suwaru"}]},{"key":"k:触","kind":"kanji","level":"N4","character":"触","meaning":"Chạm, sờ","hanviet":"Xúc","onReadings":["ショク"],"kunReadings":["さわ","ふ"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"触る","reading":"さわる","meaning":"Chạm","vocabKey":"v:触る"},{"compound":"触れる","reading":"ふれる","meaning":"Tiếp xúc"}],"lessonIds":[23],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 角 (sừng) + 虫 (côn trùng). Hán-Việt: XÚC. Mẹo nhớ: Sừng (角) côn trùng (虫) chạm vào — 'xúc' là chạm, sờ 👆. 13 nét. Âm ショク (shoku), さわる (sawaru) = chạm. Liên kết: 触る (chạm), 触れる (fureru - tiếp xúc). ⚠️ 触らないでください (sawaranaide kudasai) = xin đừng chạm — biển cấm phổ biến.","example":"展示品に**触**らないでください。 / tenjishin ni sawaranaide kudasai. (Xin đừng chạm vào vật trưng bày.)","examples":[{"ja":"展示品に触らないでください。","vi":"Xin đừng chạm vào vật trưng bày.","romaji":"tenjihin ni sawaranaide kudasai."},{"ja":"壁に触る","vi":"Sờ tường","romaji":"Kabe ni sawaru"},{"ja":"触ります [ドアに~]","vi":"sờ, chạm vào [cửa]","romaji":"sawarimasu [ doa ni ~]"},{"ja":"危ない から、触らないでください。(あぶない から、さわらないでください)","vi":"Vì nguy hiểm, xin đừng sờ."}]},{"key":"k:吸","kind":"kanji","level":"N4","character":"吸","meaning":"Hít, hút","hanviet":"Hấp","onReadings":["キュウ"],"kunReadings":["す"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"吸う","reading":"すう","meaning":"Hít/hút"},{"compound":"呼吸","reading":"こきゅう","meaning":"Hơi thở"}],"lessonIds":[6],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 口 (miệng) + 及 (kịp/đến). Hán-Việt: HẤP. Mẹo nhớ: Miệng (口) hít vào — 'hấp' là hít, hút 💨. 6 nét. Âm キュウ (kyuu), すう (suu) = hít. Liên kết: 吸う (hít), 呼吸 (kokyuu - hô hấp). ⚠️ 吸う (suu) = hít/hút — dùng cho cả thuốc lá và không khí.","example":"タバコを**吸**わないでください。 / tabako wo suwanaide kudasai. (Xin đừng hút thuốc.)","examples":[{"ja":"タバコを吸わないでください。","vi":"Xin đừng hút thuốc.","romaji":"tabako wo suwanaide kudasai."},{"ja":"ここで タバコを 吸っては いけません。","vi":"Không được hút thuốc lá ở đây.","romaji":"koko de tabako o sutsute wa ikemasen."},{"ja":"ここでたばこを吸ってはいけません。","vi":"Không được hút thuốc ở đây.","romaji":"koko de tabako o sutsute wa ikemasen."},{"ja":"明日からはたばこを吸わないつもりです。","vi":"Tôi quyết định từ ngày mai sẽ không hút thuốc nữa.","romaji":"ashita kara wa tabako o suwanai tsumori desu."}]},{"key":"k:投","kind":"kanji","level":"N4","character":"投","meaning":"Ném, quăng","hanviet":"Đầu","onReadings":["トウ"],"kunReadings":["な"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"投げる","reading":"なげる","meaning":"Ném","vocabKey":"v:投げる"},{"compound":"投票","reading":"とうひょう","meaning":"Bỏ phiếu"}],"lessonIds":[33],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 扌(tay) + 殳 (gậy). Hán-Việt: ĐẦU. Mẹo nhớ: Tay (扌) ném gậy (殳) — 'đầu' là ném, quăng ⚾. 7 nét. Âm トウ (tou), なげる (nageru) = ném. Liên kết: 投げる (ném), 投票 (touhyou - bỏ phiếu). ⚠️ 投げる (nageru) = ném — dùng nhiều trong thể thao.","example":"ボールを**投**げてください。 / booru wo nagete kudasai. (Hãy ném bóng.)","examples":[{"ja":"ボールを投げてください。","vi":"Hãy ném bóng.","romaji":"booru wo nagete kudasai."},{"ja":"ボールを投げる","vi":"Ném bóng","romaji":"booru o nageru"},{"ja":"投げます","vi":"ném","romaji":"nagemasu"}]},{"key":"k:曲","kind":"kanji","level":"N4","character":"曲","meaning":"Bài hát, cong","hanviet":"Khúc","onReadings":["キョク"],"kunReadings":["ま","ま"],"strokeCount":6,"radicals":[],"components":[],"compounds":[{"compound":"曲","reading":"きょく","meaning":"Bài hát","vocabKey":"v:曲"},{"compound":"曲がる","reading":"まがる","meaning":"Rẽ/cong","vocabKey":"v:曲がる"},{"compound":"作曲","reading":"さっきょく","meaning":"Sáng tác nhạc"}],"lessonIds":[14,36],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — hình vật uốn cong. Hán-Việt: KHÚC. Mẹo nhớ: Đường cong uốn — 'khúc' là bài hát, cong 🎵. 6 nét. Âm キョク (kyoku), まがる (magaru) = rẽ/cong, まげる (mageru) = bẻ cong. Liên kết: 曲 (bài hát), 曲がる (rẽ). ⚠️ 曲がる (magaru-rẽ) — あの角を曲がって (rẽ ở góc đó) — chỉ đường phổ biến.","example":"次の**曲**がりを左に曲がってください。 / tsugi no magari wo hidari ni magatte kudasai. (Hãy rẽ trái ở chỗ rẽ tiếp theo.)","examples":[{"ja":"次の曲がりを左に曲がってください。","vi":"Hãy rẽ trái ở chỗ rẽ tiếp theo.","romaji":"tsugi no magari o hidari ni magatsute kudasai."},{"ja":"角を右に曲がる","vi":"Rẽ phải ở góc","romaji":"Kaku wo migi ni magaru"},{"ja":"交差点を右へ曲がります。","vi":"Rẽ phải ở ngã tư.","romaji":"kousaten o migi e magarimasu."},{"ja":"右に曲がる","vi":"Rẽ phải","romaji":"Migi ni magaru"}]},{"key":"k:塩","kind":"kanji","level":"N4","character":"塩","meaning":"Muối","hanviet":"Diêm","onReadings":["エン"],"kunReadings":["しお"],"strokeCount":13,"radicals":[],"components":[],"compounds":[{"compound":"塩","reading":"しお","meaning":"Muối","vocabKey":"v:塩"},{"compound":"塩辛い","reading":"しおからい","meaning":"Mặn"}],"lessonIds":[14],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 土 (đất) + 鹵 (muối/khoáng chất mặn). Hán-Việt: DIÊM. Mẹo nhớ: khoáng chất mặn kết tinh từ đất và biển tạo nên muối, nên nhớ nghĩa 'diêm/muối' 🧂. 13 nét. Âm kun しお (shio) = muối dùng hàng ngày. Âm on エン (en) gặp trong 食塩 (shokuen - muối ăn). Liên kết: 塩 (muối), 塩辛い (mặn), 食塩 (muối ăn). ⚠️ Dễ nhầm với 潮 (しお - thủy triều): cùng có cách đọc しお nhưng 塩 là muối, 潮 là nước triều.","example":"スープに**塩**を少し入れてください。 / suupu ni shio wo sukoshi irete kudasai. (Hãy cho ít muối vào súp.)","examples":[{"ja":"スープに塩を少し入れてください。","vi":"Hãy cho ít muối vào súp.","romaji":"suupu ni shio wo sukoshi irete kudasai."},{"ja":"塩を入れる","vi":"Cho muối","romaji":"Shio wo ireru"},{"ja":"すみませんが、塩を 取って ください。","vi":"Xin lỗi, làm ơn lấy giúp tôi muối.","romaji":"sumimasen ga, shio o totsute kudasai."},{"ja":"そのスープは塩が多すぎます。","vi":"Món súp đó nhiều muối quá.","romaji":"sono suupu wa shio ga oo sugimasu."}]},{"key":"k:甘","kind":"kanji","level":"N4","character":"甘","meaning":"Ngọt","hanviet":"Cam","onReadings":["カン"],"kunReadings":["あま"],"strokeCount":5,"radicals":[],"components":[],"compounds":[{"compound":"甘い","reading":"あまい","meaning":"Ngọt","vocabKey":"v:甘い"},{"compound":"甘える","reading":"あまえる","meaning":"Nũng nịu"}],"lessonIds":[12],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — miệng (口) ngậm vật ngọt. Hán-Việt: CAM. Mẹo nhớ: Miệng có vật ngọt bên trong — 'cam' là ngọt 🍬. 5 nét. Âm カン (kan), あまい (amai) = ngọt. Liên kết: 甘い (ngọt), 甘える (amaeru - làm nũng). ⚠️ 甘い (amai) vừa nghĩa 'ngọt' vừa nghĩa 'nuông chiều/dễ dãi'.","example":"このケーキはちょっと**甘**すぎます。 / kono keeki wa chotto amasugimasu. (Cái bánh này hơi ngọt quá.)","examples":[{"ja":"このケーキはちょっと甘すぎます。","vi":"Cái bánh này hơi ngọt quá.","romaji":"kono keeki wa chotto amasugimasu."},{"ja":"ケーキが甘い","vi":"Bánh ngọt","romaji":"keeki ga amai"},{"ja":"もう甘いものは食べないつもりです。","vi":"Tôi quyết không ăn đồ ngọt nữa.","romaji":"mou amai mono wa tabenai tsumori desu."},{"ja":"医者に甘いものを食べないように言われました。","vi":"Bác sĩ dặn tôi không ăn đồ ngọt.","romaji":"isha ni amai mono o tabenai you ni iwa remashita."}]},{"key":"k:辛","kind":"kanji","level":"N4","character":"辛","meaning":"Cay","hanviet":"Tân","onReadings":["シン"],"kunReadings":["から"],"strokeCount":7,"radicals":[],"components":[],"compounds":[{"compound":"辛い","reading":"からい","meaning":"Cay","vocabKey":"v:辛い"},{"compound":"辛口","reading":"からくち","meaning":"Vị cay/khô"}],"lessonIds":[12],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: Chữ tượng hình — hình cây kim/dụng cụ nhọn. Hán-Việt: TÂN. Mẹo nhớ: Kim châm đau — vị cay xé 🌶️. 7 nét. Âm シン (shin), からい (karai) = cay. Liên kết: 辛い (cay), 辛い (tsurai - khổ sở). ⚠️ 辛い có 2 cách đọc: からい (karai-cay) vs つらい (tsurai-khổ) — phân biệt theo ngữ cảnh.","example":"韓国料理は**辛**いものが多いです。 / kankoku ryouri wa karai mono ga ooi desu. (Món Hàn Quốc có nhiều đồ cay.)","examples":[{"ja":"韓国料理は辛いものが多いです。","vi":"Món Hàn Quốc có nhiều đồ cay.","romaji":"kankoku ryouri wa tsurai mono ga ooi desu."},{"ja":"カレーが辛い","vi":"Cà ri cay","romaji":"karee ga tsurai"},{"ja":"その カレー、おいしい？……うん、辛いけど、おいしい。","vi":"Món cà ri đó ngon không? Ừ, cay nhưng mà ngon.","romaji":"sono karee, oishii?...... un, tsurai kedo, oishii."},{"ja":"辛い料理は食べられません。","vi":"Tôi không ăn được đồ cay.","romaji":"tsurai ryouri wa tabe raremasen."}]},{"key":"k:苦","kind":"kanji","level":"N4","character":"苦","meaning":"Đắng, khổ","hanviet":"Khổ","onReadings":["ク"],"kunReadings":["くる","にが"],"strokeCount":8,"radicals":[],"components":[],"compounds":[{"compound":"苦い","reading":"にがい","meaning":"Đắng","vocabKey":"v:苦い"},{"compound":"苦手","reading":"にがて","meaning":"Không giỏi"},{"compound":"苦しい","reading":"くるしい","meaning":"Đau khổ","vocabKey":"v:苦しい"}],"lessonIds":[30,34],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 艹 (cỏ) + 古 (cũ). Hán-Việt: KHỔ. Mẹo nhớ: Cỏ (艹) cũ (古) đắng — 'khổ' là đắng, khổ sở 😣. 8 nét. Âm ク (ku), にがい (nigai) = đắng, くるしい (kurushii) = đau khổ. Liên kết: 苦い (đắng), 苦しい (đau khổ). ⚠️ 苦い (nigai-đắng) vs 苦しい (kurushii-đau khổ) vs 苦手 (nigate-yếu) — 3 cách dùng.","example":"この薬は**苦**いですが、よく効きます。 / kono kusuri wa nigai desu ga, yoku kikimasu. (Thuốc này đắng nhưng hiệu quả tốt.)","examples":[{"ja":"この薬は苦いですが、よく効きます。","vi":"Thuốc này đắng nhưng hiệu quả tốt.","romaji":"kono kusuri wa nigai desu ga, yoku kikimasu."},{"ja":"息が苦しい","vi":"Khó thở","romaji":"Iki ga kurushii"},{"ja":"この薬は苦い","vi":"Thuốc này đắng","romaji":"Kono kusuri wa nigai"},{"ja":"料理が苦手です","vi":"Dở nấu ăn","romaji":"ryouri ga nigate desu"}]},{"key":"k:踊","kind":"kanji","level":"N4","character":"踊","meaning":"Nhảy múa","hanviet":"Dũng","onReadings":["ヨウ"],"kunReadings":["おど"],"strokeCount":14,"radicals":[],"components":[],"compounds":[{"compound":"踊る","reading":"おどる","meaning":"Nhảy/múa","vocabKey":"v:踊る"},{"compound":"踊り","reading":"おどり","meaning":"Điệu nhảy"},{"compound":"盆踊り","reading":"ぼんおどり","meaning":"Múa Bon","vocabKey":"v:盆踊り"}],"lessonIds":[11,26,28],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: ⻊ (chân) + 甬 (dũng). Hán-Việt: DŨNG. Mẹo nhớ: Chân (⻊) nhún nhảy — 'dũng' là nhảy múa 💃. 14 nét. Âm ヨウ (you), おどる (odoru) = nhảy múa. Liên kết: 踊る (nhảy múa), 踊り (odori - điệu múa). ⚠️ 踊る (odoru) = nhảy múa — 盆踊り (bon odori) là điệu múa truyền thống mùa hè.","example":"お祭りで皆で**踊**りました。 / omatsuri de mina de odorimashita. (Mọi người cùng nhảy múa trong lễ hội.)","examples":[{"ja":"お祭りで皆で踊りました。","vi":"Mọi người cùng nhảy múa trong lễ hội.","romaji":"omatsuri de mina de odorimashita."},{"ja":"ダンスを踊る","vi":"Nhảy múa","romaji":"Dansu wo odoru"},{"ja":"その踊りはとてもきれいでした。","vi":"Điệu nhảy đó rất đẹp.","romaji":"sono odori wa totemo kirei deshita."},{"ja":"盆踊り","vi":"múa Bon","romaji":"bon'odori"}]},{"key":"k:磨","kind":"kanji","level":"N4","character":"磨","meaning":"Đánh bóng, chải","hanviet":"Ma","onReadings":["マ"],"kunReadings":["みが"],"strokeCount":16,"radicals":[],"components":[],"compounds":[{"compound":"磨く","reading":"みがく","meaning":"Đánh bóng/chải","vocabKey":"v:磨く"},{"compound":"歯磨き","reading":"はみがき","meaning":"Đánh răng"}],"lessonIds":[34],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 麻 (gai/tê) + 石 (đá). Hán-Việt: MA. Mẹo nhớ: Mài đá (石) cho bóng — 'ma' là đánh bóng, chải ✨. 16 nét. Âm マ (ma), みがく (migaku) = đánh bóng/chải. Liên kết: 磨く (đánh bóng), 歯を磨く (ha wo migaku - đánh răng). ⚠️ 歯を磨く (đánh răng) — thành ngữ sinh hoạt dùng hàng ngày.","example":"毎日寝る前に歯を**磨**きます。 / mainichi neru mae ni ha wo migakimasu. (Mỗi ngày trước khi ngủ tôi đánh răng.)","examples":[{"ja":"毎日寝る前に歯を磨きます。","vi":"Mỗi ngày trước khi ngủ tôi đánh răng.","romaji":"mainichi neru mae ni ha wo migakimasu."},{"ja":"歯を磨く","vi":"Đánh răng","romaji":"Ha wo migaku"},{"ja":"寝る前に歯を磨きます。","vi":"Trước khi ngủ tôi đánh răng.","romaji":"neru mae ni ha o migakimasu."},{"ja":"磨きます","vi":"đánh, đánh (giày)","romaji":"migakimasu"}]},{"key":"k:換","kind":"kanji","level":"N4","character":"換","meaning":"Đổi, trao đổi","hanviet":"Hoán","onReadings":["カン"],"kunReadings":["か","か"],"strokeCount":12,"radicals":[],"components":[],"compounds":[{"compound":"換える","reading":"かえる","meaning":"Đổi"},{"compound":"交換","reading":"こうかん","meaning":"Trao đổi"},{"compound":"乗り換える","reading":"のりかえる","meaning":"Chuyển tàu/xe","vocabKey":"v:乗り換える"}],"lessonIds":[16,18],"topicTags":[],"sectionId":23,"sectionName":"ÔN TẬP TẬP TRUNG - JLPT N4","mnemonic":"Bộ/thành phần: 扌(tay) + 奐 (hoán). Hán-Việt: HOÁN. Mẹo nhớ: Tay (扌) đổi lại — 'hoán' là đổi, trao đổi 🔀. 12 nét. Âm カン (kan), かえる (kaeru) = đổi, かわる (kawaru) = bị đổi. Liên kết: 換える (đổi), 交換 (koukan - trao đổi). ⚠️ 乗り換える (norikaeru) = đổi tàu/xe — từ giao thông quan trọng.","example":"次の駅で電車を乗り**換**えてください。 / tsugi no eki de densha wo norikaete kudasai. (Hãy đổi tàu ở ga tiếp theo.)","examples":[{"ja":"次の駅で電車を乗り換えてください。","vi":"Hãy đổi tàu ở ga tiếp theo.","romaji":"tsugi no eki de densha wo norikaete kudasai."},{"ja":"ここで乗り換える","vi":"Chuyển ở đây","romaji":"Kokode norikaeru"},{"ja":"電話番号を交換する","vi":"Trao đổi số điện thoại","romaji":"denwa bangou o koukan suru"},{"ja":"東京駅で乗り換えが必要です","vi":"Cần chuyển tuyến ở ga Tokyo","romaji":"toukyoueki de norikae ga hitsuyou desu"}]}]`);
